/// Parses a bare YouTube ID or an official YouTube video URL.
///
/// Non-URL text returns `Ok(None)` and remains an ordinary search query.
/// YouTube-looking but malformed input returns an error so look-alike hosts and
/// broken identifiers are not sent to search accidentally.
///
/// # Errors
///
/// Returns a short validation message for malformed or non-video YouTube URLs.
pub fn parse_direct_youtube_input(raw: &str) -> Result<Option<DirectVideoInput>, &'static str> {
    let input = raw.trim();
    if input.is_empty() {
        return Ok(None);
    }
    if validate_youtube_video_id(input).is_ok() {
        return Ok(Some(DirectVideoInput {
            video_id: input.to_owned(),
            start_seconds: None,
        }));
    }

    let lower = input.to_ascii_lowercase();
    let looks_like_youtube = lower.contains("youtube.") || lower.contains("youtu.be");
    if !looks_like_youtube {
        return Ok(None);
    }
    let normalized = if lower.starts_with("youtube.")
        || lower.starts_with("www.youtube.")
        || lower.starts_with("music.youtube.")
        || lower.starts_with("m.youtube.")
        || lower.starts_with("youtu.be")
    {
        format!("https://{input}")
    } else {
        input.to_owned()
    };
    let url = url::Url::parse(&normalized).map_err(|_| "invalid YouTube URL")?;
    let Some(LinkTarget::YouTubeVideo {
        video_id,
        start_seconds,
    }) = parse_youtube_url(&url)
    else {
        return Err("input is not a valid YouTube video URL");
    };
    Ok(Some(DirectVideoInput {
        video_id,
        start_seconds,
    }))
}

/// Parses a direct non-YouTube source URL.
///
/// Known hosts receive a first-class source identity. Other credential-free
/// HTTP(S) links use the generic yt-dlp route, whose installed extractor list
/// determines whether playback is supported.
///
/// # Errors
///
/// Returns an error for credential-bearing, non-HTTP, or malformed URL-like
/// input. Ordinary free text returns `Ok(None)`.
pub fn parse_direct_source_input(raw: &str) -> Result<Option<DirectSourceInput>, &'static str> {
    let input = raw.trim();
    if input.is_empty() || input.chars().any(char::is_whitespace) {
        return Ok(None);
    }
    let lower = input.to_ascii_lowercase();
    let normalized = if lower.starts_with("http://") || lower.starts_with("https://") {
        input.to_owned()
    } else if looks_like_bare_host_path(input) {
        format!("https://{input}")
    } else {
        return Ok(None);
    };
    let url = url::Url::parse(&normalized).map_err(|_| "invalid source URL")?;
    if !matches!(url.scheme(), "http" | "https")
        || !url.username().is_empty()
        || url.password().is_some()
        || url.host_str().is_none()
    {
        return Err("source URL must be credential-free HTTP or HTTPS");
    }
    if parse_youtube_url(&url).is_some()
        || url
            .host_str()
            .is_some_and(|host| host.ends_with("youtube.com") || host.ends_with("youtu.be"))
    {
        return Err("input is not a valid YouTube video URL");
    }
    let host = url.host_str().unwrap_or_default().to_ascii_lowercase();
    let source = classify_known_host(&host, url.path());
    Ok(Some(DirectSourceInput { url, source }))
}

fn looks_like_bare_host_path(input: &str) -> bool {
    let authority = input.split('/').next().unwrap_or_default();
    authority.contains('.')
        && !authority.starts_with('.')
        && !authority.ends_with('.')
        && !authority.contains('@')
}

fn host_matches(host: &str, domain: &str) -> bool {
    host == domain
        || host
            .strip_suffix(domain)
            .is_some_and(|prefix| prefix.ends_with('.'))
}

fn classify_known_host(host: &str, path: &str) -> SourceKind {
    if is_supported_media_path(path) {
        SourceKind::RemoteFiles
    } else if host_matches(host, "podcasts.apple.com") {
        SourceKind::ApplePodcasts
    } else if host_matches(host, "soundcloud.com") {
        SourceKind::SoundCloud
    } else if host_matches(host, "jamendo.com") || host_matches(host, "jamen.do") {
        SourceKind::Jamendo
    } else if host_matches(host, "soundstream.media") {
        SourceKind::SoundStream
    } else if host_matches(host, "litres.ru") {
        SourceKind::LitRes
    } else if host_matches(host, "vimeo.com") {
        SourceKind::Vimeo
    } else if host_matches(host, "rutube.ru") {
        SourceKind::RuTube
    } else if host_matches(host, "bandcamp.com") {
        SourceKind::Bandcamp
    } else if host_matches(host, "odysee.com") {
        SourceKind::Odysee
    } else if host_matches(host, "rumble.com") {
        SourceKind::Rumble
    } else if host_matches(host, "bilibili.com") || host == "b23.tv" {
        SourceKind::Bilibili
    } else if host_matches(host, "vk.com") {
        SourceKind::Vk
    } else if host_matches(host, "archive.org") {
        SourceKind::ArchiveOrg
    } else if host_matches(host, "librivox.org") {
        SourceKind::LibriVox
    } else if host == "commons.wikimedia.org" {
        SourceKind::WikimediaCommons
    } else if host_matches(host, "music.yandex.ru") {
        SourceKind::YandexMusic
    } else if host_matches(host, "bbc.co.uk") || host_matches(host, "bbc.com") {
        SourceKind::BbcRadio
    } else if host_matches(host, "modarchive.org")
        || host_matches(host, "scene.org")
        || host_matches(host, "aminet.net")
        || host_matches(host, "modland.com")
        || host_matches(host, "dascene.net")
        || host_matches(host, "demozoo.org")
        || host_matches(host, "modules.pl")
        || host_matches(host, "mirsoft.info")
    {
        SourceKind::ModArchive
    } else {
        SourceKind::GenericYtDlp
    }
}

fn is_supported_media_path(path: &str) -> bool {
    let extension = Path::new(path)
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or_default();
    matches!(
        extension.to_ascii_lowercase().as_str(),
        "opus"
            | "m4a"
            | "aac"
            | "flac"
            | "wav"
            | "mp3"
            | "ogg"
            | "oga"
            | "mka"
            | "webm"
            | "mkv"
            | "mp4"
            | "m4v"
            | "mov"
            | "avi"
            | "mod"
            | "xm"
            | "it"
            | "s3m"
            | "mptm"
            | "stm"
            | "mtm"
            | "669"
    )
}

/// Selects a libavformat filename extension compatible with an advertised Radio codec.
///
/// mpv implements `stream-record` through libavformat and selects its output
/// container from the filename extension. A codec-matched extension lets mpv
/// copy original encoded packets; forcing `.mka` can fail for otherwise
/// playable streams. BBC uses its cached resolved-manifest codec when present;
/// only genuinely unknown streams retain `.mka` as the general fallback, and
/// mpv reports a clear backend error when it cannot mux that stream.
#[cfg(feature = "radio")]
fn radio_recording_extension(codec: Option<RadioCodec>, stream: &str) -> &'static str {
    match codec {
        Some(RadioCodec::Flac) => "flac",
        Some(RadioCodec::Mp3) => "mp3",
        Some(RadioCodec::Aac) => "aac",
        Some(RadioCodec::Opus) => "opus",
        Some(RadioCodec::Vorbis) => "ogg",
        Some(RadioCodec::Pcm) => "wav",
        None => radio_stream_extension(stream).unwrap_or("mka"),
    }
}

/// Extracts a known audio-container extension from a trusted built-in stream URL.
#[cfg(feature = "radio")]
fn radio_stream_extension(stream: &str) -> Option<&'static str> {
    let url = url::Url::parse(stream).ok()?;
    let path = url.path();
    match Path::new(path)
        .extension()
        .and_then(|extension| extension.to_str())?
        .to_ascii_lowercase()
        .as_str()
    {
        "flac" => Some("flac"),
        "mp3" => Some("mp3"),
        "aac" => Some("aac"),
        "opus" => Some("opus"),
        "ogg" | "oga" => Some("ogg"),
        "wav" => Some("wav"),
        "mka" => Some("mka"),
        _ => None,
    }
}

/// Converts the trusted codec label obtained from a BBC manifest into an output extension.
#[cfg(feature = "bbc-radio")]
fn radio_recording_extension_from_bbc_codec(codec: &str) -> Option<&'static str> {
    match codec.trim().to_ascii_lowercase().as_str() {
        "flac" => Some("flac"),
        "mp3" | "mpeg audio layer 3" => Some("mp3"),
        "aac" | "aac-lc" | "he-aac" => Some("aac"),
        "opus" => Some("opus"),
        "vorbis" => Some("ogg"),
        "pcm" | "pcm_s16le" | "pcm_s24le" => Some("wav"),
        _ => None,
    }
}

/// Creates a restricted runtime child and returns one unused extension-bearing path.
#[cfg(feature = "radio")]
fn prepare_radio_recording_staging_path(
    config: &Config,
    extension: &str,
) -> Result<PathBuf, String> {
    config
        .ensure_directories()
        .map_err(|error| format!("cannot prepare Youta directories: {error}"))?;
    let directory = config.runtime_dir().join("radio-recordings");
    std::fs::create_dir_all(&directory)
        .map_err(|error| format!("cannot create private recording directory: {error}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;

        std::fs::set_permissions(&directory, std::fs::Permissions::from_mode(0o700))
            .map_err(|error| format!("cannot secure private recording directory: {error}"))?;
    }
    let sequence = RADIO_RECORDING_SEQUENCE.fetch_add(1, AtomicOrdering::Relaxed);
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    for retry in 0..1024_u32 {
        let path = directory.join(format!(".radio-{timestamp}-{sequence}-{retry}.{extension}"));
        match std::fs::symlink_metadata(&path) {
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(path),
            Ok(_) => continue,
            Err(error) => {
                return Err(format!("cannot inspect private recording path: {error}"));
            }
        }
    }
    Err("could not reserve a private Radio recording path".to_owned())
}

/// Publishes a closed regular staging file without exposing an in-progress file in Downloaded.
#[cfg(feature = "radio")]
fn publish_radio_recording(
    config: &Config,
    recording: &ActiveRadioRecording,
) -> Result<PathBuf, String> {
    let metadata = std::fs::symlink_metadata(&recording.staging_path)
        .map_err(|error| format!("recording output is unavailable: {error}"))?;
    if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
        return Err("recording output is not a regular private file".to_owned());
    }
    if metadata.len() == 0 {
        return Err("recording output is empty".to_owned());
    }
    let downloads = config.downloads_dir();
    let station = sanitized_radio_recording_station_name(&recording.station_name);
    let timestamp = recording.started_at.format("%Y-%m-%d %H-%M-%S");
    let base = format!("{station} — {timestamp}");

    for collision in 0..10_000_u32 {
        let suffix = if collision == 0 {
            String::new()
        } else {
            format!(" ({})", collision.saturating_add(1))
        };
        let destination = downloads.join(format!("{base}{suffix}.{}", recording.extension));
        match publish_file_without_replacement(&recording.staging_path, &destination) {
            Ok(()) => {
                // The destination link is durable enough to discover only after
                // the complete output has been closed. A stale private source is
                // harmless and never appears in Downloaded.
                let _ = std::fs::remove_file(&recording.staging_path);
                return Ok(destination);
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) if error.kind() == std::io::ErrorKind::CrossesDevices => {
                return publish_radio_recording_via_download_staging(
                    &recording.staging_path,
                    &destination,
                )
                .map(|()| destination)
                .map_err(|error| format!("cannot publish recording safely: {error}"));
            }
            Err(error) => return Err(format!("cannot publish recording safely: {error}")),
        }
    }
    Err("too many existing recordings share this station and second".to_owned())
}

/// Links one complete file into its final name; hard links provide no-replace publication.
#[cfg(feature = "radio")]
fn publish_file_without_replacement(source: &Path, destination: &Path) -> std::io::Result<()> {
    std::fs::hard_link(source, destination)?;
    std::fs::File::open(destination)?.sync_all()
}

/// Copies across filesystems into a hidden Downloaded staging file before final publication.
#[cfg(feature = "radio")]
fn publish_radio_recording_via_download_staging(
    source: &Path,
    destination: &Path,
) -> std::io::Result<()> {
    use std::io::Write;

    let parent = destination
        .parent()
        .ok_or_else(|| std::io::Error::other("recording destination has no parent"))?;
    let sequence = RADIO_RECORDING_SEQUENCE.fetch_add(1, AtomicOrdering::Relaxed);
    let staging = parent.join(format!(".youta-radio-recording-{sequence}.part"));
    let result = (|| {
        let mut input = std::fs::File::open(source)?;
        let mut output = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&staging)?;
        std::io::copy(&mut input, &mut output)?;
        output.flush()?;
        output.sync_all()?;
        publish_file_without_replacement(&staging, destination)
    })();
    let _ = std::fs::remove_file(&staging);
    if result.is_ok() {
        // A successful cross-filesystem copy has made the complete public
        // destination authoritative. The private source is no longer needed;
        // cleanup remains best-effort because a complete Downloaded item must
        // not be reported as failed solely due to a stale private runtime file.
        remove_radio_recording_file(source);
    }
    result
}

/// Replaces path separators and control bytes while preserving a readable station label.
#[cfg(feature = "radio")]
fn sanitized_radio_recording_station_name(name: &str) -> String {
    let sanitized = name
        .chars()
        .map(|character| {
            if character.is_control() || matches!(character, '/' | '\\' | ':' | '\0') {
                ' '
            } else {
                character
            }
        })
        .collect::<String>();
    let sanitized = sanitized.split_whitespace().collect::<Vec<_>>().join(" ");
    if sanitized.is_empty() || sanitized == "." || sanitized == ".." {
        "Radio station".to_owned()
    } else {
        sanitized
    }
}

/// Best-effort removal used only for unpublished private staging paths.
#[cfg(feature = "radio")]
fn remove_radio_recording_file(path: &Path) {
    match std::fs::remove_file(path) {
        Ok(()) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(_) => {}
    }
}

/// Returns the deliberately narrow search route for a screen.
///
/// The normal search screen never fans a query out to every configured service.
/// This makes YouTube-only search the default and avoids surprise network use.
#[must_use]
pub const fn search_route(screen: Screen) -> SearchRoute {
    match screen {
        Screen::Search => SearchRoute::YouTube,
        Screen::YouTubeMusic => SearchRoute::YouTubeMusic,
        Screen::Bandcamp => SearchRoute::Bandcamp,
        Screen::ApplePodcasts => SearchRoute::ApplePodcasts,
        Screen::TrackerMusic => SearchRoute::TrackerArchives,
        Screen::Radio
        | Screen::Subscriptions
        | Screen::Local
        | Screen::Downloaded
        | Screen::History
        | Screen::Playlists
        | Screen::Statistics => SearchRoute::None,
    }
}

