    /// Returns cached selected-file metadata and promotes its LRU entry.
    fn cached_local_media_item(&mut self, path: &Path, size_bytes: u64) -> Option<LocalMediaItem> {
        let current_identity = local_file_identity(path)?;
        let cached = self.local_media_cache.get(path).cloned();
        if current_identity.length != size_bytes
            || cached
                .as_ref()
                .is_some_and(|cached| cached.identity != current_identity)
        {
            self.local_media_cache.remove(path);
            self.local_media_cache_order
                .retain(|cached_path| cached_path != path);
            return None;
        }
        if cached.is_some() {
            self.local_media_cache_order
                .retain(|cached_path| cached_path != path);
            self.local_media_cache_order.push_back(path.to_owned());
        }
        cached.map(|cached| cached.item)
    }

    /// Returns a midpoint target derived from current identity-bound metadata.
    ///
    /// The Boolean result asks the caller to schedule the asynchronous metadata
    /// probe. Persisted History and playlist durations are deliberately ignored:
    /// a file may have been replaced at the same path since either row was
    /// written.
    fn cached_local_video_thumbnail(
        &mut self,
        path: &Path,
    ) -> (Option<LocalVideoThumbnailView>, bool) {
        #[cfg(all(feature = "images", feature = "local-video-thumbnails"))]
        {
            if crate::local_browser::classify_local_file(path)
                != Some(crate::local_browser::LocalEntryKind::Video)
            {
                return (None, false);
            }
            let Ok(metadata) = std::fs::metadata(path) else {
                return (None, false);
            };
            let Some(item) = self.cached_local_media_item(path, metadata.len()) else {
                return (None, true);
            };
            (
                local_video_thumbnail_view(&item.path, item.duration_seconds),
                !item.technical_metadata_probed,
            )
        }
        #[cfg(not(all(feature = "images", feature = "local-video-thumbnails")))]
        {
            let _ = path;
            (None, false)
        }
    }

    /// Inserts one complete selected-file record into the bounded RAM LRU.
    fn cache_local_media_item(&mut self, identity: LocalFileIdentity, item: LocalMediaItem) {
        let path = item.path.clone();
        self.local_media_cache.remove(&path);
        self.local_media_cache_order
            .retain(|cached_path| cached_path != &path);
        while self.local_media_cache.len() >= MAX_CACHED_LOCAL_MEDIA_ITEMS {
            let Some(oldest) = self.local_media_cache_order.pop_front() else {
                break;
            };
            self.local_media_cache.remove(&oldest);
        }
        self.local_media_cache
            .insert(path.clone(), CachedLocalMediaItem { identity, item });
        self.local_media_cache_order.push_back(path);
    }

    /// Starts at most one lazy metadata read without blocking terminal input.
    fn request_local_media_metadata(&mut self, path: PathBuf) {
        if self.local_media_cache.contains_key(&path) || self.pending_local_media_metadata.is_some()
        {
            return;
        }
        self.pending_local_media_metadata = Some(path.clone());
        let loader = Arc::clone(&self.local_media_loader);
        let responses = self.local_media_metadata_sender.clone();
        let worker_path = path.clone();
        if thread::Builder::new()
            .name("youta-local-metadata".to_owned())
            .spawn(move || {
                let result = local_file_identity(&worker_path).and_then(|before| {
                    let item = loader.load(worker_path.clone());
                    (local_file_identity(&worker_path).as_ref() == Some(&before))
                        .then_some((before, item))
                });
                let _ = responses.send(LocalMediaMetadataResponse {
                    path: worker_path,
                    result,
                });
            })
            .is_err()
        {
            self.pending_local_media_metadata = None;
        }
    }

    /// Returns the regular local file currently owning the visible Details panel.
    fn selected_local_metadata_path(&self) -> Option<PathBuf> {
        match self.view.screen {
            Screen::Local => self.selected_local_regular_file(),
            Screen::Search | Screen::Downloaded => self
                .view
                .rows
                .get(self.view.selected)
                .and_then(|row| row.media_id.as_ref())
                .filter(|media_id| media_id.source == SourceKind::Local)
                .map(|media_id| PathBuf::from(&media_id.external_id)),
            Screen::History => self
                .history_entries
                .get(self.view.selected)
                .filter(|history| !history.local_removed)
                .and_then(|history| history_replay_target(&history.entry).ok())
                .and_then(|target| match target {
                    HistoryReplayTarget::Local(path) => Some(path),
                    HistoryReplayTarget::Remote(_) => None,
                })
                .filter(|path| path.is_file()),
            Screen::Playlists => self
                .active_playlist
                .as_ref()
                .and_then(|playlist| playlist.entries.get(self.view.selected))
                .filter(|entry| {
                    entry.media.id.source == SourceKind::Local
                        && entry.media.kind == MediaKind::Video
                })
                .map(|entry| PathBuf::from(&entry.media.replay_locator))
                .filter(|path| path.is_file()),
            Screen::YouTubeMusic
            | Screen::Bandcamp
            | Screen::ApplePodcasts
            | Screen::Radio
            | Screen::Subscriptions
            | Screen::TrackerMusic
            | Screen::Statistics => None,
        }
    }

    /// Applies completed lazy metadata and immediately schedules the latest row.
    fn drain_local_media_metadata_responses(&mut self) {
        while let Ok(LocalMediaMetadataResponse { path, result }) =
            self.local_media_metadata_responses.try_recv()
        {
            if self.pending_local_media_metadata.as_ref() == Some(&path) {
                self.pending_local_media_metadata = None;
            }
            let Some((identity, item)) = result
                .filter(|(identity, _)| local_file_identity(&path).as_ref() == Some(identity))
            else {
                if self
                    .selected_local_metadata_path()
                    .as_deref()
                    .is_some_and(|selected| selected != path)
                {
                    match self.view.screen {
                        Screen::Local => self.update_local_browser_detail(),
                        Screen::Search => self.update_non_youtube_detail(),
                        Screen::Downloaded => self.update_downloaded_detail(),
                        Screen::History => self.update_history_detail(),
                        Screen::Playlists => self.update_playlist_detail(),
                        Screen::YouTubeMusic
                        | Screen::Bandcamp
                        | Screen::ApplePodcasts
                        | Screen::Radio
                        | Screen::Subscriptions
                        | Screen::TrackerMusic
                        | Screen::Statistics => {}
                    }
                }
                continue;
            };
            self.cache_local_media_item(identity, item.clone());
            if let Some(index) = self
                .local_results
                .iter()
                .position(|candidate| candidate.path == path)
            {
                self.local_results[index] = item;
                if self.view.screen == Screen::Search
                    && let Some(row) = self.view.rows.get_mut(index)
                    && row.media_id.as_ref().is_some_and(|media_id| {
                        media_id.source == SourceKind::Local
                            && Path::new(&media_id.external_id) == path
                    })
                {
                    row.subtitle = local_media_subtitle(&self.local_results[index]);
                }
            }
            match self.view.screen {
                Screen::Local => self.update_local_browser_detail(),
                Screen::Search => self.update_non_youtube_detail(),
                Screen::Downloaded => self.update_downloaded_detail(),
                Screen::History => self.update_history_detail(),
                Screen::Playlists => self.update_playlist_detail(),
                Screen::YouTubeMusic
                | Screen::Bandcamp
                | Screen::ApplePodcasts
                | Screen::Radio
                | Screen::Subscriptions
                | Screen::TrackerMusic
                | Screen::Statistics => {}
            }
        }
    }

    /// Loads one lazily selected recursive-scan result and refreshes its row.
    fn ensure_local_result_technical_metadata(&mut self, index: usize) {
        let Some(item) = self.local_results.get(index) else {
            return;
        };
        if item.technical_metadata_probed {
            return;
        }
        let path = item.path.clone();
        let size_bytes = item.size_bytes;
        if let Some(item) = self.cached_local_media_item(&path, size_bytes) {
            if let Some(row) = self.view.rows.get_mut(index) {
                row.subtitle = local_media_subtitle(&item);
            }
            self.local_results[index] = item;
        } else {
            self.request_local_media_metadata(path);
        }
    }

    /// Starts one lazy artwork lookup for selected Local media or a folder.
    #[cfg(all(feature = "local-artwork", feature = "images"))]
    fn request_selected_local_artwork(&mut self) {
        let selected = if self.view.screen == Screen::Local {
            self.local_entry_index()
                .and_then(|index| self.local_listing.as_ref()?.entries.get(index))
                .and_then(|entry| match entry.kind {
                    crate::local_browser::LocalEntryKind::Directory => {
                        Some((entry.path.clone(), LocalArtworkKind::FolderCover))
                    }
                    crate::local_browser::LocalEntryKind::Audio
                    | crate::local_browser::LocalEntryKind::TrackerModule => {
                        Some((entry.path.clone(), LocalArtworkKind::EmbeddedMedia))
                    }
                    crate::local_browser::LocalEntryKind::Video => {
                        (!cfg!(feature = "local-video-thumbnails"))
                            .then_some((entry.path.clone(), LocalArtworkKind::EmbeddedMedia))
                    }
                    crate::local_browser::LocalEntryKind::Image => None,
                })
        } else {
            self.view
                .details
                .as_ref()
                .and_then(|details| details.media_id.as_ref())
                .filter(|media_id| media_id.source == SourceKind::Local)
                .and_then(|media_id| {
                    let path = PathBuf::from(&media_id.external_id);
                    (cfg!(not(feature = "local-video-thumbnails"))
                        || crate::local_browser::classify_local_file(&path)
                            != Some(crate::local_browser::LocalEntryKind::Video))
                    .then_some((path, LocalArtworkKind::EmbeddedMedia))
                })
        };
        let Some((path, kind)) = selected else {
            if self.pending_local_artwork.is_none() {
                self.view.local_artwork_pending = false;
            }
            return;
        };
        if self.local_artwork_cache.contains_key(&path) {
            self.apply_cached_local_artwork(&path);
            if self.pending_local_artwork.is_none() {
                self.view.local_artwork_pending = false;
            }
            return;
        }
        if self.pending_local_artwork.is_some() {
            self.view.local_artwork_pending = true;
            return;
        }
        let Some(sender) = self.provider_requests.as_ref() else {
            self.view.local_artwork_pending = false;
            return;
        };
        self.local_artwork_generation = self.local_artwork_generation.wrapping_add(1);
        let generation = self.local_artwork_generation;
        let request = ProviderRequest::LocalArtwork {
            generation,
            path: path.clone(),
            cache_directory: self.config.thumbnail_cache_dir(),
            kind,
        };
        if sender.send(request).is_ok() {
            self.pending_local_artwork = Some((generation, path));
            self.view.local_artwork_pending = true;
        } else {
            self.view.local_artwork_pending = false;
        }
    }

    /// Stores one process-local artwork result with deterministic FIFO eviction.
    #[cfg(all(feature = "local-artwork", feature = "images"))]
    fn cache_local_artwork(&mut self, path: PathBuf, artwork: Option<url::Url>) {
        self.local_artwork_cache.insert(path.clone(), artwork);
        self.local_artwork_cache_order
            .retain(|cached_path| cached_path != &path);
        self.local_artwork_cache_order.push_back(path);
        while self.local_artwork_cache.len() > MAX_CACHED_LOCAL_ARTWORK {
            let Some(oldest) = self.local_artwork_cache_order.pop_front() else {
                break;
            };
            self.local_artwork_cache.remove(&oldest);
        }
    }

    /// Applies a cached cover only when the same Local path still owns Details.
    #[cfg(all(feature = "local-artwork", feature = "images"))]
    fn apply_cached_local_artwork(&mut self, path: &Path) {
        let Some(artwork) = self.local_artwork_cache.get(path) else {
            return;
        };
        let selected_local_path_matches = self.selected_local_path().as_deref() == Some(path);
        let Some(details) = self.view.details.as_mut() else {
            return;
        };
        let selected_matches = selected_local_path_matches
            || details.media_id.as_ref().is_some_and(|media_id| {
                media_id.source == SourceKind::Local && Path::new(&media_id.external_id) == path
            });
        if selected_matches {
            details.thumbnail_url.clone_from(artwork);
        }
    }

    fn browse_local_directory(&mut self, directory: PathBuf) {
        self.browse_local_directory_with_reselection(directory, None);
    }

    /// Applies one isolated Local worker result only when its owner is current.
    fn handle_local_browse_response(&mut self, response: LocalBrowseResponse) {
        match response {
            LocalBrowseResponse::Browse { generation, result } => {
                self.handle_local_directory_response(generation, result);
            }
            #[cfg(feature = "local-move")]
            LocalBrowseResponse::MoveDestinations { generation, result } => {
                self.handle_local_move_destinations_response(generation, result);
            }
            #[cfg(feature = "local-move")]
            LocalBrowseResponse::Move {
                generation,
                planned,
                result,
            } => {
                self.handle_local_move_response(generation, &planned, result);
            }
        }
    }

    /// Applies one isolated Local listing only when its route is still current.
    fn handle_local_directory_response(
        &mut self,
        generation: u64,
        result: Result<crate::local_browser::LocalDirectoryListing, String>,
    ) {
        if generation != self.local_generation {
            return;
        }
        self.view.local_browse_pending = false;
        match result {
            Ok(listing) => {
                let truncated = listing.truncated;
                let path = listing.path.display().to_string();
                let reselected_path = self
                    .pending_local_reselection
                    .take()
                    .filter(|(pending_generation, _)| *pending_generation == generation)
                    .map(|(_, child)| child);
                self.local_listing = Some(listing);
                self.sort_local_listing();
                self.view.selected = 0;
                self.select_local_path(reselected_path.as_deref());
                #[cfg(feature = "local-move")]
                {
                    let visible_paths = self
                        .local_listing
                        .as_ref()
                        .map(|listing| {
                            listing
                                .entries
                                .iter()
                                .map(|entry| entry.path.clone())
                                .collect::<HashSet<_>>()
                        })
                        .unwrap_or_default();
                    self.local_move_marks
                        .retain(|marked| visible_paths.contains(marked));
                }
                self.hydrate_local_progress_cache();
                self.refresh_local_browser_rows();
                self.schedule_local_folder_sizes();
                self.view.status_line = if truncated {
                    format!("Showing a bounded partial listing of {path}")
                } else {
                    format!("Local folder: {path}")
                };
                self.refresh_selected_playlist_state();
            }
            Err(error) => {
                self.pending_local_reselection = None;
                self.view.rows.clear();
                self.view.selected = 0;
                self.show_error_message("Local folder could not be opened", error);
            }
        }
    }

    /// Starts one directory load and optionally remembers a direct child that
    /// should be selected when the response arrives.
    fn browse_local_directory_with_reselection(
        &mut self,
        directory: PathBuf,
        reselect_child: Option<PathBuf>,
    ) {
        #[cfg(feature = "local-move")]
        {
            let leaves_current_directory = self
                .local_listing
                .as_ref()
                .is_some_and(|listing| listing.path != directory);
            if leaves_current_directory {
                self.local_move_marks.clear();
            }
        }
        let keep_noninteractive_rows = self.view.screen == Screen::Local
            && self.local_listing.is_some()
            && !self.view.rows.is_empty();
        self.local_generation = self.local_generation.wrapping_add(1);
        self.invalidate_local_folder_sizes();
        self.pending_local_reselection = reselect_child
            .clone()
            .map(|child| (self.local_generation, child));
        self.local_listing = None;
        if !keep_noninteractive_rows {
            self.view.rows.clear();
            self.view.selected = 0;
        }
        self.view.details = None;
        self.view.local_path = directory.display().to_string();
        let status_line = format!("Reading {}…", directory.display());
        self.view.local_browse_pending = false;
        if self.send_local_browse_request(
            LocalBrowseRequest::Browse {
                generation: self.local_generation,
                directory,
                preferred_child: reselect_child,
            },
            "Could not open the local folder",
        ) {
            self.view.local_browse_pending = true;
            self.view.status_line = status_line;
        } else {
            self.pending_local_reselection = None;
        }
    }

    /// Cancels older recursive work without discarding bounded RAM cache data.
    fn invalidate_local_folder_sizes(&mut self) {
        self.local_folder_size_generation
            .fetch_add(1, AtomicOrdering::Relaxed);
        self.local_folder_size_queue.clear();
        self.local_folder_size_pending = None;
    }

    /// Queues one rotating, fixed-size batch of current child directories.
    fn schedule_local_folder_sizes(&mut self) {
        if self.view.screen != Screen::Local || !self.config.ui.show_local_folder_sizes {
            return;
        }
        if self.local_folder_size_pending.is_some() || !self.local_folder_size_queue.is_empty() {
            return;
        }
        let Some(listing) = self.local_listing.as_ref() else {
            return;
        };
        let listing_path = listing.path.clone();
        let directories = listing
            .entries
            .iter()
            .filter(|entry| entry.is_directory())
            .map(|entry| (entry.path.clone(), entry.directory_identity.clone()))
            .collect::<Vec<_>>();
        if directories.is_empty() {
            return;
        }
        let generation = self
            .local_folder_size_generation
            .load(AtomicOrdering::Relaxed);
        let now = Instant::now();
        let mut reused_complete_size = false;

        for (path, identity) in &directories {
            let complete_is_fresh = self
                .local_folder_size_cache
                .get(path)
                .is_some_and(|cached| {
                    identity.as_ref() == Some(&cached.identity)
                        && now.saturating_duration_since(cached.measured_at)
                            <= LOCAL_FOLDER_SIZE_CACHE_TTL
                });
            if complete_is_fresh {
                if let Some(cached) = self.local_folder_size_cache.get_mut(path) {
                    cached.validated_generation = generation;
                }
                reused_complete_size = true;
                self.local_folder_size_cache_order
                    .retain(|cached_path| cached_path != path);
                self.local_folder_size_cache_order.push_back(path.clone());
            } else if self.local_folder_size_cache.remove(path).is_some() {
                self.local_folder_size_cache_order
                    .retain(|cached_path| cached_path != path);
            }

            let failure_is_fresh =
                self.local_folder_size_failures
                    .get(path)
                    .is_some_and(|failure| {
                        failure.identity.as_ref() == identity.as_ref()
                            && now.saturating_duration_since(failure.failed_at)
                                <= LOCAL_FOLDER_SIZE_FAILURE_TTL
                    });
            if !failure_is_fresh && self.local_folder_size_failures.remove(path).is_some() {
                self.local_folder_size_failure_order
                    .retain(|failed_path| failed_path != path);
            }
        }

        let start = self
            .local_folder_size_batch_cursors
            .get(&listing_path)
            .copied()
            .unwrap_or_default()
            % directories.len();
        let mut next_cursor = start;
        for offset in 0..directories.len() {
            let index = start.saturating_add(offset) % directories.len();
            next_cursor = index.saturating_add(1) % directories.len();
            let (path, _) = &directories[index];
            let complete = self
                .local_folder_size_cache
                .get(path)
                .is_some_and(|cached| cached.validated_generation == generation);
            if complete || self.local_folder_size_failures.contains_key(path) {
                continue;
            }
            self.local_folder_size_queue.push_back(path.clone());
            if self.local_folder_size_queue.len() >= MAX_LAZY_LOCAL_FOLDER_SIZES {
                break;
            }
        }
        self.local_folder_size_batch_cursors
            .insert(listing_path.clone(), next_cursor);
        self.local_folder_size_batch_cursor_order
            .retain(|path| path != &listing_path);
        self.local_folder_size_batch_cursor_order
            .push_back(listing_path);
        while self.local_folder_size_batch_cursors.len() > MAX_LOCAL_FOLDER_SIZE_BATCH_CURSORS {
            let Some(oldest) = self.local_folder_size_batch_cursor_order.pop_front() else {
                break;
            };
            self.local_folder_size_batch_cursors.remove(&oldest);
        }
        if reused_complete_size {
            let selected_path = self.selected_local_path();
            self.sort_local_listing();
            self.select_local_path(selected_path.as_deref());
            self.refresh_local_browser_rows_without_detail();
        }
        self.request_next_local_folder_size();
    }

    /// Dispatches at most one lazy folder-size request at a time.
    fn request_next_local_folder_size(&mut self) {
        if !self.config.ui.show_local_folder_sizes || self.local_folder_size_pending.is_some() {
            return;
        }
        let Some(path) = self.local_folder_size_queue.pop_front() else {
            return;
        };
        let generation = self
            .local_folder_size_generation
            .load(AtomicOrdering::Relaxed);
        let now = Instant::now();
        let cached = self
            .local_folder_size_cache
            .get(&path)
            .filter(|cached| {
                now.saturating_duration_since(cached.measured_at) <= LOCAL_FOLDER_SIZE_CACHE_TTL
            })
            .map(|cached| crate::local_browser::LocalFolderSizeMeasurement {
                bytes: cached.bytes,
                identity: cached.identity.clone(),
            });
        if self.send_provider_request(
            ProviderRequest::LocalFolderSize {
                generation,
                path: path.clone(),
                cancellation: Arc::clone(&self.local_folder_size_generation),
                cached,
            },
            "Could not measure the local folder",
        ) {
            self.local_folder_size_pending = Some(path);
        }
    }

    /// Returns a complete current-generation size for one Local entry.
    fn known_local_entry_size(&self, entry: &crate::local_browser::LocalEntry) -> Option<u64> {
        if !entry.is_directory() {
            return entry.size_bytes;
        }
        if !self.config.ui.show_local_folder_sizes {
            return None;
        }
        let generation = self
            .local_folder_size_generation
            .load(AtomicOrdering::Relaxed);
        let now = Instant::now();
        self.local_folder_size_cache
            .get(&entry.path)
            .filter(|cached| {
                cached.validated_generation == generation
                    && now.saturating_duration_since(cached.measured_at)
                        <= LOCAL_FOLDER_SIZE_CACHE_TTL
            })
            .map(|cached| cached.bytes)
    }

    /// Stores one worker-validated size and enforces the global RAM bound.
    fn store_local_folder_size(
        &mut self,
        path: &Path,
        generation: u64,
        result: LocalFolderSizeWorkerResult,
    ) -> bool {
        let now = Instant::now();
        if result.reused {
            let Some(cached) = self.local_folder_size_cache.get_mut(path) else {
                return false;
            };
            if cached.identity != result.measurement.identity
                || now.saturating_duration_since(cached.measured_at) > LOCAL_FOLDER_SIZE_CACHE_TTL
            {
                self.local_folder_size_cache.remove(path);
                self.local_folder_size_cache_order
                    .retain(|cached_path| cached_path != path);
                return false;
            }
            cached.bytes = result.measurement.bytes;
            cached.validated_generation = generation;
        } else {
            self.local_folder_size_cache.insert(
                path.to_owned(),
                CachedLocalFolderSize {
                    identity: result.measurement.identity,
                    bytes: result.measurement.bytes,
                    measured_at: now,
                    validated_generation: generation,
                },
            );
        }

        self.local_folder_size_cache_order
            .retain(|cached_path| cached_path != path);
        self.local_folder_size_cache_order
            .push_back(path.to_owned());
        self.local_folder_size_failures.remove(path);
        self.local_folder_size_failure_order
            .retain(|failed_path| failed_path != path);
        while self.local_folder_size_cache.len() > MAX_CACHED_LOCAL_FOLDER_SIZES {
            let Some(oldest) = self.local_folder_size_cache_order.pop_front() else {
                break;
            };
            self.local_folder_size_cache.remove(&oldest);
        }
        true
    }

    /// Caches one bounded failure so navigation does not hammer the same tree.
    fn store_local_folder_size_failure(&mut self, path: PathBuf) {
        let identity = self.local_listing.as_ref().and_then(|listing| {
            listing
                .entries
                .iter()
                .find(|entry| entry.path == path)
                .and_then(|entry| entry.directory_identity.clone())
        });
        self.local_folder_size_failures.insert(
            path.clone(),
            CachedLocalFolderSizeFailure {
                identity,
                failed_at: Instant::now(),
            },
        );
        self.local_folder_size_failure_order
            .retain(|failed_path| failed_path != &path);
        self.local_folder_size_failure_order.push_back(path);
        while self.local_folder_size_failures.len() > MAX_CACHED_LOCAL_FOLDER_SIZES {
            let Some(oldest) = self.local_folder_size_failure_order.pop_front() else {
                break;
            };
            self.local_folder_size_failures.remove(&oldest);
        }
    }

    /// Returns the path represented by the selected Local row.
    fn selected_local_path(&self) -> Option<PathBuf> {
        let listing = self.local_listing.as_ref()?;
        if listing.parent.is_some() && self.view.selected == 0 {
            return listing.parent.clone();
        }
        self.local_entry_index()
            .and_then(|index| listing.entries.get(index))
            .map(|entry| entry.path.clone())
    }

    /// Restores one exact Local path after lazy size sorting reorders rows.
    fn select_local_path(&mut self, selected_path: Option<&Path>) {
        let Some(selected_path) = selected_path else {
            return;
        };
        let Some(listing) = self.local_listing.as_ref() else {
            return;
        };
        if listing
            .parent
            .as_deref()
            .is_some_and(|parent| parent == selected_path)
        {
            self.view.selected = 0;
            return;
        }
        if let Some(index) = listing
            .entries
            .iter()
            .position(|entry| entry.path == selected_path)
        {
            self.view.selected = index.saturating_add(usize::from(listing.parent.is_some()));
        }
    }

    /// Applies the selected deterministic Local ordering to the listing.
    fn sort_local_listing(&mut self) {
        let sizes_enabled = self.config.ui.show_local_folder_sizes;
        let mode = if sizes_enabled {
            self.view.local_size_sort
        } else {
            LocalSizeSort::Off
        };
        let generation = self
            .local_folder_size_generation
            .load(AtomicOrdering::Relaxed);
        let now = Instant::now();
        let cache = &self.local_folder_size_cache;
        let Some(listing) = self.local_listing.as_mut() else {
            return;
        };
        listing.entries.sort_by(|left, right| {
            if mode == LocalSizeSort::Off {
                return right
                    .is_directory()
                    .cmp(&left.is_directory())
                    .then_with(|| left.name.cmp(&right.name));
            }
            let known_size = |entry: &crate::local_browser::LocalEntry| {
                if entry.is_directory() {
                    sizes_enabled
                        .then(|| cache.get(&entry.path))
                        .flatten()
                        .filter(|cached| {
                            cached.validated_generation == generation
                                && now.saturating_duration_since(cached.measured_at)
                                    <= LOCAL_FOLDER_SIZE_CACHE_TTL
                        })
                        .map(|cached| cached.bytes)
                } else {
                    entry.size_bytes
                }
            };
            match (known_size(left), known_size(right)) {
                (Some(left_size), Some(right_size)) => {
                    let size_order = match mode {
                        LocalSizeSort::Ascending => left_size.cmp(&right_size),
                        LocalSizeSort::Descending => right_size.cmp(&left_size),
                        LocalSizeSort::Off => std::cmp::Ordering::Equal,
                    };
                    size_order.then_with(|| left.name.cmp(&right.name))
                }
                (Some(_), None) => std::cmp::Ordering::Less,
                (None, Some(_)) => std::cmp::Ordering::Greater,
                (None, None) => left.name.cmp(&right.name),
            }
        });
    }

    /// Rebuilds visible Local rows and refreshes the selected entry's metadata.
    fn refresh_local_browser_rows(&mut self) {
        self.rebuild_local_browser_rows();
        self.update_local_browser_detail();
    }

    /// Rebuilds Local rows while retaining details for the same selected path.
    ///
    /// Lazy folder-size responses may arrive hundreds of times for one
    /// listing. They update row subtitles and ordering but must not repeatedly
    /// reopen a selected media file to parse its tags.
    fn refresh_local_browser_rows_without_detail(&mut self) {
        self.rebuild_local_browser_rows();
    }

    /// Hydrates watched row states once for the accepted Local listing.
    fn hydrate_local_progress_cache(&mut self) {
        self.local_progress_cache.clear();
        let Some(listing) = self.local_listing.as_ref() else {
            return;
        };
        let progress_ids = listing
            .entries
            .iter()
            .filter(|entry| entry.kind.is_playable())
            .map(|entry| MediaId::new(SourceKind::Local, entry.path.display().to_string()))
            .collect::<Vec<_>>();
        self.local_progress_cache.extend(
            progress_ids
                .iter()
                .cloned()
                .map(|media_id| (media_id, PlaybackRowState::default())),
        );
        let Ok(progress) = self.store.progress_for_media_ids(&progress_ids) else {
            return;
        };
        self.local_progress_cache
            .extend(progress.into_iter().map(|(media_id, progress)| {
                (media_id, PlaybackRowState::from_progress(Some(&progress)))
            }));
    }

    /// Updates one visible progress marker without rebuilding its source list.
    ///
    /// Local rows additionally retain the state in their listing-scoped
    /// RAM cache. Subscription videos use a separate row collection, so both
    /// visible collections must follow the same durable checkpoint.
    fn update_visible_progress_view(&mut self, media_id: &MediaId, state: PlaybackRowState) {
        if media_id.source == SourceKind::Local {
            let visible = self
                .view
                .rows
                .iter()
                .any(|row| row.media_id.as_ref() == Some(media_id));
            if self.local_progress_cache.contains_key(media_id) || visible {
                self.local_progress_cache.insert(media_id.clone(), state);
            }
        }
        for row in &mut self.view.rows {
            if !row.hide_watched_marker && row.media_id.as_ref() == Some(media_id) {
                row.watched_percent = state.watched_percent;
                row.playback_started = state.playback_started;
            }
        }
        for row in &mut self.view.subscriptions.items {
            if !row.hide_watched_marker && row.media_id.as_ref() == Some(media_id) {
                row.watched_percent = state.watched_percent;
                row.playback_started = state.playback_started;
            }
        }
    }

    /// Mirrors an actively playing backend position into the current Local row.
    ///
    /// A backend may temporarily omit the duration while replacing or opening
    /// media. Such a status cannot produce a trustworthy percentage and must
    /// not erase a previously hydrated marker.
    fn update_live_local_progress_view(&mut self) {
        let Some(media_id) = self
            .current_media
            .as_ref()
            .filter(|media_id| media_id.source == SourceKind::Local)
            .cloned()
        else {
            return;
        };
        let Some(duration) = self
            .view
            .playback
            .duration
            .map(|value| value.as_secs())
            .filter(|duration| *duration > 0)
        else {
            return;
        };
        let now = unix_time();
        let mut progress = PlaybackProgress::new(media_id.clone(), Some(duration), now);
        progress.record_position(self.view.playback.position.as_secs(), now);
        if let Some(current) = self
            .current_playback_progress
            .as_ref()
            .filter(|current| current.media_id == media_id)
        {
            progress.played_override = current.played_override;
        }
        self.update_visible_progress_view(
            &media_id,
            PlaybackRowState::from_progress(Some(&progress)),
        );
    }

    /// Rebuilds the Local row model from listing-scoped RAM state.
    fn rebuild_local_browser_rows(&mut self) {
        use crate::local_browser::LocalEntryKind;

        let Some(listing) = self.local_listing.as_ref() else {
            self.view.rows.clear();
            return;
        };
        self.view.local_path = listing.path.display().to_string();
        let mut rows = Vec::with_capacity(
            listing
                .entries
                .len()
                .saturating_add(usize::from(listing.parent.is_some())),
        );
        if listing.parent.is_some() {
            rows.push(RowView {
                title: "..".to_owned(),
                subtitle: String::new(),
                source: "Local folder".to_owned(),
                compact: true,
                ..RowView::default()
            });
        }
        rows.extend(listing.entries.iter().map(|entry| {
            let source = match entry.kind {
                LocalEntryKind::Directory => "Local folder",
                LocalEntryKind::Audio => "Local audio",
                LocalEntryKind::Video => "Local video (audio playback)",
                LocalEntryKind::TrackerModule => "Local tracker module",
                LocalEntryKind::Image => "Local image",
            };
            let media_id = entry
                .kind
                .is_playable()
                .then(|| MediaId::new(SourceKind::Local, entry.path.display().to_string()));
            let playback = media_id
                .as_ref()
                .and_then(|id| self.local_progress_cache.get(id))
                .copied()
                .unwrap_or_default();
            #[cfg(feature = "local-move")]
            let local_marked = self.local_move_marks.contains(&entry.path);
            #[cfg(not(feature = "local-move"))]
            let local_marked = false;
            let subtitle = match entry.kind {
                LocalEntryKind::Directory => self
                    .known_local_entry_size(entry)
                    .map_or_else(String::new, human_bytes),
                LocalEntryKind::Image => entry.image_dimensions.map_or_else(
                    || entry.size_bytes.map_or_else(String::new, human_bytes),
                    |dimensions| {
                        format!(
                            "{}×{} · {}",
                            dimensions.width,
                            dimensions.height,
                            human_bytes(entry.size_bytes.unwrap_or_default())
                        )
                    },
                ),
                _ => entry.size_bytes.map_or_else(String::new, human_bytes),
            };
            RowView {
                media_id,
                title: entry.display_name().into_owned(),
                subtitle,
                source: source.to_owned(),
                watched_percent: playback.watched_percent,
                playback_started: playback.playback_started,
                thumbnail_url: (entry.kind == LocalEntryKind::Image)
                    .then(|| url::Url::from_file_path(&entry.path).ok())
                    .flatten(),
                compact: true,
                local_marked,
                ..RowView::default()
            }
        }));
        self.view.rows = rows;
        self.view.selected = self
            .view
            .selected
            .min(self.view.rows.len().saturating_sub(1));
    }

    fn local_entry_index(&self) -> Option<usize> {
        let listing = self.local_listing.as_ref()?;
        self.view
            .selected
            .checked_sub(usize::from(listing.parent.is_some()))
            .filter(|index| *index < listing.entries.len())
    }

    fn update_local_browser_detail(&mut self) {
        use crate::local_browser::LocalEntryKind;

        let Some(listing) = self.local_listing.as_ref() else {
            self.view.details = None;
            return;
        };
        if self.view.selected == 0
            && let Some(parent) = listing.parent.as_ref()
        {
            self.view.details = Some(DetailView {
                title: "..".to_owned(),
                source: "Local folder".to_owned(),
                description: format!("Full path: {}", parent.display()),
                ..DetailView::default()
            });
            return;
        }
        let Some(index) = self.local_entry_index() else {
            self.view.details = None;
            return;
        };
        let entry = listing.entries[index].clone();
        if entry.kind.is_playable() {
            let size_bytes = entry.size_bytes.unwrap_or_default();
            let item = self
                .cached_local_media_item(&entry.path, size_bytes)
                .unwrap_or_else(|| local_media_item_stub(entry.path.clone(), Some(size_bytes)));
            let metadata_pending = !item.technical_metadata_probed;
            self.view.details = Some(DetailView {
                media_id: Some(MediaId::new(
                    SourceKind::Local,
                    entry.path.display().to_string(),
                )),
                title: item.title.clone(),
                source: match entry.kind {
                    LocalEntryKind::Video => "Local video (audio playback)",
                    LocalEntryKind::TrackerModule => "Local tracker module",
                    _ => "Local audio",
                }
                .to_owned(),
                length: item
                    .duration_seconds
                    .map_or_else(|| "unknown".to_owned(), format_seconds),
                description: local_media_description(&item),
                local_video_thumbnail: local_video_thumbnail_view(
                    &item.path,
                    item.duration_seconds,
                ),
                local_renamable: cfg!(feature = "local-rename"),
                local_movable: cfg!(feature = "local-move"),
                local_trashable: cfg!(feature = "local-trash"),
                ..DetailView::default()
            });
            if metadata_pending {
                self.request_local_media_metadata(entry.path);
            }
        } else {
            let is_directory = entry.kind == LocalEntryKind::Directory;
            let known_size = (!is_directory)
                .then(|| self.known_local_entry_size(&entry))
                .flatten();
            self.view.details = Some(DetailView {
                title: entry.display_name().into_owned(),
                source: if entry.kind == LocalEntryKind::Image {
                    "Local image"
                } else {
                    "Local folder"
                }
                .to_owned(),
                description: format!(
                    "Full path: {}{}{}",
                    entry.path.display(),
                    known_size
                        .map_or_else(String::new, |size| format!("\nSize: {}", human_bytes(size))),
                    entry
                        .image_dimensions
                        .map_or_else(String::new, |dimensions| {
                            format!("\nDimensions: {}×{}", dimensions.width, dimensions.height)
                        })
                ),
                thumbnail_url: (entry.kind == LocalEntryKind::Image)
                    .then(|| url::Url::from_file_path(&entry.path).ok())
                    .flatten(),
                local_renamable: cfg!(feature = "local-rename") && !is_directory,
                local_movable: cfg!(feature = "local-move"),
                local_trashable: cfg!(feature = "local-trash"),
                ..DetailView::default()
            });
        }
        #[cfg(all(feature = "local-artwork", feature = "images"))]
        self.request_selected_local_artwork();
    }

    fn refresh_tracker_rows(&mut self) {
        self.view.rows =
            self.tracker_results
                .iter()
                .map(|item| RowView {
                    media_id: item.prepared_path.as_ref().map(|_| {
                        MediaId::new(SourceKind::ModArchive, item.webpage_url.to_string())
                    }),
                    title: item.title.clone(),
                    subtitle: item.subtitle.clone(),
                    source: item.source.clone(),
                    ..RowView::default()
                })
                .collect();
        hydrate_row_playback_progress(&self.store, &mut self.view.rows);
        self.view.selected = self
            .view
            .selected
            .min(self.view.rows.len().saturating_sub(1));
        self.update_non_youtube_detail();
    }

    #[cfg(feature = "tracker-music")]
    fn finish_tracker_preparation(
        &mut self,
        item_key: &str,
        modules: Vec<crate::tracker_media::PreparedTrackerModule>,
        owner: TrackerPreparationOwner,
    ) {
        let autoplay_origin = match &owner {
            TrackerPreparationOwner::Autoplay(origin) if self.config.playback.autoplay => {
                Some(origin.clone())
            }
            _ => None,
        };
        let Some(index) = self
            .tracker_results
            .iter()
            .position(|item| item.webpage_url.as_str() == item_key)
        else {
            if let Some(origin) = autoplay_origin {
                self.continue_autoplay(origin);
            } else if owner == TrackerPreparationOwner::Manual {
                self.show_error_message(
                    "Tracker module preparation failed",
                    "the prepared result no longer exists in the current tracker search",
                );
            }
            return;
        };
        let template = self.tracker_results[index].clone();
        let mut prepared = modules
            .into_iter()
            .map(|module| {
                let mut item = template.clone();
                item.title = module.display_name;
                item.expected_format = Some(module.format.clone());
                item.subtitle = format!(
                    "{} · {}",
                    module.format.to_ascii_uppercase(),
                    human_bytes(module.size_bytes)
                );
                item.prepared_path = Some(module.path);
                item.access = TrackerAccess::DirectModule;
                item
            })
            .collect::<Vec<_>>();
        if prepared.is_empty() {
            if let Some(origin) = autoplay_origin {
                self.view.status_line =
                    "Autoplay skipped a payload with no supported tracker module".to_owned();
                self.continue_autoplay(origin);
            } else if owner == TrackerPreparationOwner::Manual {
                self.show_error_message(
                    "Tracker module preparation failed",
                    "the selected payload contained no supported tracker module",
                );
            } else {
                self.view.status_line =
                    "Canceled tracker preparation contained no playable module".to_owned();
            }
            return;
        }
        let prepared_count = prepared.len();
        self.tracker_results
            .splice(index..=index, prepared.drain(..));
        self.view.selected = index;
        self.tracker_selected = index;
        if self.view.screen == Screen::TrackerMusic {
            self.refresh_tracker_rows();
        }
        if owner == TrackerPreparationOwner::CanceledAutoplay
            || (matches!(&owner, TrackerPreparationOwner::Autoplay(_))
                && !self.config.playback.autoplay)
        {
            self.view.status_line =
                format!("Prepared {prepared_count} tracker module(s); autoplay remains off");
            return;
        }
        if prepared_count > 1 && owner == TrackerPreparationOwner::Manual {
            self.view.status_line =
                format!("Prepared {prepared_count} modules; select the extracted entry to play");
            return;
        }
        let item = match queue_item_from_tracker(&self.tracker_results[index]) {
            Ok(item) => item,
            Err(error) => {
                self.show_error_message("Tracker module preparation failed", error);
                return;
            }
        };
        match owner {
            TrackerPreparationOwner::Autoplay(_) => self.play_queue_item_with_origin(
                item,
                false,
                Some(AutoplayOrigin::Tracker {
                    generation: self.search_generation,
                    index,
                }),
            ),
            TrackerPreparationOwner::Manual => self.play_queue_item(item, false),
            TrackerPreparationOwner::CanceledAutoplay => {
                unreachable!("canceled preparation returned before queue activation")
            }
        }
    }

    fn update_non_youtube_detail(&mut self) {
        match self.view.screen {
            Screen::Local => {
                self.update_local_browser_detail();
                return;
            }
            Screen::History => {
                self.update_history_detail();
                return;
            }
            Screen::Downloaded => {
                self.update_downloaded_detail();
                return;
            }
            Screen::Bandcamp => {
                #[cfg(feature = "bandcamp")]
                self.update_bandcamp_detail();
                #[cfg(not(feature = "bandcamp"))]
                {
                    self.view.details = None;
                }
                return;
            }
            Screen::ApplePodcasts => {
                match self.apple_podcasts_route {
                    ApplePodcastsRoute::Shows => self.update_apple_podcasts_detail(),
                    ApplePodcastsRoute::Episodes => self.update_apple_podcast_episode_detail(),
                    ApplePodcastsRoute::Direct => self.refresh_apple_direct_view(),
                }
                return;
            }
            Screen::Radio => {
                self.update_radio_detail();
                return;
            }
            Screen::Search | Screen::TrackerMusic => {}
            Screen::YouTubeMusic
            | Screen::Subscriptions
            | Screen::Playlists
            | Screen::Statistics => {
                self.view.details = None;
                return;
            }
        }
        if self.view.screen == Screen::Search {
            self.ensure_local_result_technical_metadata(self.view.selected);
        }
        if self.view.screen == Screen::Search
            && let Some(item) = self.local_results.get(self.view.selected)
        {
            self.view.details = Some(DetailView {
                media_id: Some(MediaId::new(
                    SourceKind::Local,
                    item.path.display().to_string(),
                )),
                title: item.title.clone(),
                source: "Local".to_owned(),
                length: item
                    .duration_seconds
                    .map_or_else(|| "unknown".to_owned(), format_seconds),
                description: local_media_description(item),
                license: "local file".to_owned(),
                wikidata: "not applicable".to_owned(),
                thumbnail_url: None,
                local_video_thumbnail: local_video_thumbnail_view(
                    &item.path,
                    item.duration_seconds,
                ),
                ..DetailView::default()
            });
            #[cfg(all(feature = "local-artwork", feature = "images"))]
            self.request_selected_local_artwork();
        } else if self.view.screen == Screen::TrackerMusic
            && let Some(item) = self.tracker_results.get(self.view.selected)
        {
            self.view.details = Some(DetailView {
                title: item.title.clone(),
                source: item.source.clone(),
                description: format!(
                    "{}\n{}",
                    item.subtitle,
                    if item.insecure_transport {
                        "Warning: this result uses plaintext HTTP."
                    } else {
                        item.webpage_url.as_str()
                    }
                ),
                license: "check source metadata".to_owned(),
                wikidata: "not loaded".to_owned(),
                ..DetailView::default()
            });
        }
    }

    /// Rebuilds History Details exclusively from the selected persisted row.
    ///
    /// History must not index into stale Local-search or tracker-search arrays:
    /// those arrays can retain unrelated URLs after the user changes screens.
    fn update_history_detail(&mut self) {
        let local_path = self
            .history_entries
            .get(self.view.selected)
            .filter(|history| !history.local_removed)
            .and_then(|history| {
                let HistoryReplayTarget::Local(path) =
                    history_replay_target(&history.entry).ok()?
                else {
                    return None;
                };
                path.is_file().then_some(path)
            });
        let (local_video_thumbnail, metadata_pending) = local_path
            .as_deref()
            .map(|path| self.cached_local_video_thumbnail(path))
            .unwrap_or((None, false));
        let Some(row) = self.view.rows.get(self.view.selected).cloned() else {
            self.view.details = None;
            return;
        };
        self.view.details = Some(DetailView {
            media_id: row.media_id,
            title: row.title,
            source: row.source,
            description: row.subtitle,
            local_video_thumbnail,
            ..DetailView::default()
        });
        if metadata_pending && let Some(path) = local_path {
            self.request_local_media_metadata(path);
        }
    }

    fn move_selection(&mut self, delta: i32) {
        if self.view.screen == Screen::Subscriptions {
            match (
                self.view.subscriptions.layout,
                self.view.subscriptions.route,
                self.view.subscriptions.focus,
            ) {
                (SubscriptionsLayout::DrillDown, SubscriptionRoute::Sources, _)
                | (SubscriptionsLayout::Split, _, SubscriptionPane::Sources) => {
                    let Some(index) = moved_index(
                        self.view.subscriptions.selected_source,
                        self.subscription_entries.len(),
                        delta,
                    ) else {
                        return;
                    };
                    self.select_subscription_source(index);
                }
                _ => {
                    let Some(index) = moved_index(
                        self.view.subscriptions.selected_item,
                        self.view.subscriptions.items.len(),
                        delta,
                    ) else {
                        return;
                    };
                    self.select_subscription_item(index);
                }
            }
            return;
        }
        if self.view.rows.is_empty() {
            return;
        }
        let last = self.view.rows.len().saturating_sub(1);
        self.view.selected = if delta.is_negative() {
            self.view
                .selected
                .saturating_sub(delta.unsigned_abs() as usize)
        } else {
            self.view.selected.saturating_add(delta as usize).min(last)
        };
        if matches!(self.view.screen, Screen::Search | Screen::YouTubeMusic) {
            let youtube_list_active = self.view.screen == Screen::YouTubeMusic
                || (self.local_results.is_empty()
                    && self.direct_item.is_none()
                    && self.resolved_direct.is_none());
            if youtube_list_active {
                self.request_selected_details();
            } else {
                self.update_non_youtube_detail();
            }
            if self.view.screen == Screen::Search
                && self.local_results.is_empty()
                && self.direct_item.is_none()
                && self.view.selected.saturating_add(2) >= self.view.rows.len()
                && let Some(page) = self.next_youtube_page
            {
                self.submit_youtube_search(page);
            }
        } else if self.view.screen == Screen::Bandcamp {
            #[cfg(feature = "bandcamp")]
            {
                self.bandcamp_selected = self.view.selected;
                self.cancel_pending_bandcamp_resolution();
                self.update_bandcamp_detail();
                if delta.is_positive() {
                    self.load_next_bandcamp_page_if_needed();
                }
            }
        } else if self.view.screen == Screen::ApplePodcasts {
            match self.apple_podcasts_route {
                ApplePodcastsRoute::Shows => {
                    self.apple_podcasts_selected = self.view.selected;
                    self.update_apple_podcasts_detail();
                }
                ApplePodcastsRoute::Episodes => {
                    self.apple_podcast_episode_selected = self.view.selected;
                    self.update_apple_podcast_episode_detail();
                }
                ApplePodcastsRoute::Direct => self.refresh_apple_direct_view(),
            }
        } else if self.view.screen == Screen::Radio {
            self.update_radio_detail();
        } else if self.view.screen == Screen::Playlists {
            match self.playlists_route {
                PlaylistsRoute::Index => self.playlist_selected = self.view.selected,
                PlaylistsRoute::Entries { .. } => {
                    self.playlist_entry_selected = self.view.selected;
                }
            }
            self.update_playlist_detail();
        } else if matches!(
            self.view.screen,
            Screen::TrackerMusic | Screen::Local | Screen::Downloaded | Screen::History
        ) {
            self.update_non_youtube_detail();
        }
        self.refresh_selected_playlist_state();
    }

    fn select_row(&mut self, row: usize) {
        if row >= self.view.rows.len() {
            return;
        }
        self.view.selected = row;
        let youtube_list_active = self.view.screen == Screen::YouTubeMusic
            || (self.view.screen == Screen::Search
                && self.local_results.is_empty()
                && self.direct_item.is_none());
        if youtube_list_active {
            self.request_selected_details();
        } else if self.view.screen == Screen::Bandcamp {
            #[cfg(feature = "bandcamp")]
            {
                self.bandcamp_selected = self.view.selected;
                self.cancel_pending_bandcamp_resolution();
                self.update_bandcamp_detail();
                self.load_next_bandcamp_page_if_needed();
            }
        } else if self.view.screen == Screen::ApplePodcasts {
            match self.apple_podcasts_route {
                ApplePodcastsRoute::Shows => {
                    self.apple_podcasts_selected = self.view.selected;
                    self.update_apple_podcasts_detail();
                }
                ApplePodcastsRoute::Episodes => {
                    self.apple_podcast_episode_selected = self.view.selected;
                    self.update_apple_podcast_episode_detail();
                }
                ApplePodcastsRoute::Direct => self.refresh_apple_direct_view(),
            }
        } else if self.view.screen == Screen::Radio {
            self.update_radio_detail();
        } else if self.view.screen == Screen::Playlists {
            match self.playlists_route {
                PlaylistsRoute::Index => self.playlist_selected = self.view.selected,
                PlaylistsRoute::Entries { .. } => {
                    self.playlist_entry_selected = self.view.selected;
                }
            }
            self.update_playlist_detail();
        } else {
            self.update_non_youtube_detail();
        }
        self.refresh_selected_playlist_state();
    }

    /// Builds a queue entry using full visible description chapters when ready.
    fn selected_video_queue_item(
        &self,
        video: &VideoSummary,
        start_at_seconds: Option<u64>,
    ) -> QueueItem {
        let mut item = queue_item_from_video(video, start_at_seconds);
        let media_id = MediaId::new(SourceKind::YouTube, &video.video_id);
        if let Some(details) = self
            .view
            .details
            .as_ref()
            .filter(|details| details.media_id.as_ref() == Some(&media_id))
        {
            item.media.chapters =
                description_chapters(&details.description, video.duration_seconds);
        }
        item
    }

    fn selected_queue_item(&self) -> Result<QueueItem, String> {
        if self.view.screen == Screen::Downloaded {
            return queue_item_from_local(&local_media_item(self.selected_downloaded_path()?));
        }
        if self.view.screen == Screen::Radio {
            #[cfg(feature = "radio")]
            {
                let station = self
                    .selected_radio_station()
                    .ok_or_else(|| "No radio station is selected".to_owned())?;
                return queue_item_from_radio_station(&station);
            }
            #[cfg(not(feature = "radio"))]
            {
                return Err("This build omits Radio support".to_owned());
            }
        }
        if self.view.screen == Screen::TrackerMusic {
            let item = self
                .tracker_results
                .get(self.view.selected)
                .ok_or_else(|| "No tracker item is selected".to_owned())?;
            return queue_item_from_tracker(item);
        }
        if self.view.screen == Screen::Subscriptions {
            let video_is_active = match self.view.subscriptions.layout {
                SubscriptionsLayout::DrillDown => {
                    self.view.subscriptions.route == SubscriptionRoute::Items
                }
                SubscriptionsLayout::Split => {
                    self.view.subscriptions.focus == SubscriptionPane::Items
                        || self.view.subscriptions.description_expanded
                }
            };
            if !video_is_active {
                return Err("Focus a subscription video before using queue actions".to_owned());
            }
            return match self.selected_subscription_item() {
                Some(SearchItem::Video(video)) => {
                    Ok(self.selected_video_queue_item(video, self.selected_start_override))
                }
                Some(SearchItem::Channel(_)) => Err("YouTube channels cannot be queued".to_owned()),
                Some(SearchItem::PodcastEpisode(episode)) => {
                    #[cfg(feature = "rss")]
                    {
                        queue_item_from_podcast_episode(episode)
                    }
                    #[cfg(not(feature = "rss"))]
                    {
                        let _ = episode;
                        Err("This build omits RSS subscription support".to_owned())
                    }
                }
                None => Err("No subscription item is selected".to_owned()),
            };
        }
        if !matches!(self.view.screen, Screen::Search | Screen::YouTubeMusic) {
            return Err("Queue actions are available for playable search results".to_owned());
        }
        if self.view.screen == Screen::YouTubeMusic {
            return match self.youtube_music_results.get(self.view.selected) {
                Some(SearchItem::Video(video)) => {
                    Ok(self.selected_video_queue_item(video, self.youtube_music_start_override))
                }
                Some(SearchItem::Channel(_)) => {
                    Err("YouTube Music channels cannot be queued".to_owned())
                }
                Some(SearchItem::PodcastEpisode(_)) => {
                    Err("Podcast episodes are not YouTube Music results".to_owned())
                }
                None => Err("No playable YouTube Music track is selected".to_owned()),
            };
        }
        if let Some(item) = self.local_results.get(self.view.selected) {
            return queue_item_from_local(item);
        }
        if let Some(media) = &self.resolved_direct {
            return queue_item_from_resolved(media);
        }
        if let Some(direct) = &self.direct_item {
            if requires_first_class_direct_resolution(&direct.source)
                || direct.source == SourceKind::ApplePodcasts
            {
                return Err(format!(
                    "{} metadata must resolve before it can be queued",
                    direct_source_label(&direct.source)
                ));
            }
            return Ok(queue_item_from_direct(direct));
        }
        match self.youtube_results.get(self.view.selected) {
            Some(SearchItem::Video(video)) => {
                Ok(self.selected_video_queue_item(video, self.selected_start_override))
            }
            Some(SearchItem::Channel(_)) => Err("YouTube channels cannot be queued".to_owned()),
            Some(SearchItem::PodcastEpisode(_)) => {
                Err("Podcast episodes are not YouTube search results".to_owned())
            }
            None => Err("No playable item is selected".to_owned()),
        }
    }

    /// Captures the selected playable item without retaining transient media URLs.
    ///
    /// Provider pages and local paths remain canonical so the resulting
    /// snapshot can be persisted and resolved again after a restart.
    fn selected_playlist_snapshot(&self) -> Result<PlaylistMediaSnapshot, String> {
        if self.view.screen == Screen::Playlists {
            if !matches!(self.playlists_route, PlaylistsRoute::Entries { .. }) {
                return Err("Open a playlist and select one of its items".to_owned());
            }
            let snapshot = self
                .active_playlist
                .as_ref()
                .and_then(|playlist| playlist.entries.get(self.view.selected))
                .map(|entry| entry.media.clone())
                .ok_or_else(|| "No playlist item is selected".to_owned())?;
            ensure_playlist_snapshot_available(&snapshot)?;
            return Ok(snapshot);
        }

        if self.view.screen == Screen::Local {
            let listing = self
                .local_listing
                .as_ref()
                .ok_or_else(|| "No local folder is loaded".to_owned())?;
            let index = self
                .local_entry_index()
                .ok_or_else(|| "Select a local audio, video, or tracker file".to_owned())?;
            let entry = listing
                .entries
                .get(index)
                .filter(|entry| entry.kind.is_playable() && entry.path.is_file())
                .ok_or_else(|| {
                    "Only available local audio, video, or tracker files can be added to a media playlist"
                        .to_owned()
                })?;
            return playlist_snapshot_from_queue_item(&queue_item_from_local(&local_media_item(
                entry.path.clone(),
            ))?);
        }

        if self.view.screen == Screen::Bandcamp {
            #[cfg(feature = "bandcamp")]
            {
                let release = self
                    .bandcamp_results
                    .get(self.view.selected)
                    .ok_or_else(|| "No Bandcamp release is selected".to_owned())?;
                if release.kind != BandcampReleaseKind::Track {
                    return Err(
                        "Select a Bandcamp track; albums are containers, not playlist items"
                            .to_owned(),
                    );
                }
                return Ok(PlaylistMediaSnapshot {
                    id: release.id.clone(),
                    kind: MediaKind::Audio,
                    title: release.title.clone(),
                    creator: release.artist.clone(),
                    webpage_url: release.webpage_url.clone(),
                    thumbnail_url: release.artwork_url.clone(),
                    duration_seconds: None,
                    replay_locator: release.webpage_url.to_string(),
                });
            }
            #[cfg(not(feature = "bandcamp"))]
            {
                return Err("This build omits Bandcamp support".to_owned());
            }
        }

        if self.view.screen == Screen::ApplePodcasts {
            #[cfg(feature = "apple-podcasts")]
            {
                if self.apple_podcasts_route == ApplePodcastsRoute::Direct {
                    let media = self
                        .resolved_direct
                        .as_ref()
                        .filter(|media| {
                            media.source == SourceKind::ApplePodcasts
                                && media.playback_url.is_some()
                        })
                        .ok_or_else(|| {
                            "Open an Apple Podcast episode before using playlists".to_owned()
                        })?;
                    return playlist_snapshot_from_queue_item(&queue_item_from_resolved(media)?);
                }
                if self.apple_podcasts_route != ApplePodcastsRoute::Episodes {
                    return Err("Open an Apple Podcast episode before using playlists".to_owned());
                }
                let episode = self
                    .apple_podcast_episodes
                    .get(self.view.selected)
                    .ok_or_else(|| "No Apple Podcast episode is selected".to_owned())?;
                let item = queue_item_from_apple_episode(
                    episode,
                    self.active_apple_podcast_show.as_ref(),
                )?;
                return playlist_snapshot_from_queue_item(&item);
            }
            #[cfg(not(feature = "apple-podcasts"))]
            {
                return Err("This build omits Apple Podcasts support".to_owned());
            }
        }

        if self.view.screen == Screen::History {
            let history = self
                .history_entries
                .get(self.view.selected)
                .ok_or_else(|| "No History item is selected".to_owned())?;
            if history.local_removed {
                return Err("The local History file was removed or moved".to_owned());
            }
            let entry = &history.entry;
            let target = history_replay_target(entry)?;
            return playlist_snapshot_from_queue_item(&queue_item_from_history(entry, &target)?);
        }

        playlist_snapshot_from_queue_item(&self.selected_queue_item()?)
    }

    /// Rejects Local playlist writes while an identity move is not durable.
    ///
    /// Remote entries have stable provider identities and remain safe to edit.
    /// Local entries wait until both the in-memory remap queue and crash
    /// recovery journal are empty, preventing a new membership from being
    /// written under an identity that the pending move may replace.
    fn ensure_playlist_mutation_ready(
        &self,
        snapshot: &PlaylistMediaSnapshot,
    ) -> Result<(), String> {
        ensure_playlist_snapshot_available(snapshot)?;
        #[cfg(any(feature = "local-rename", feature = "local-move"))]
        if snapshot.id.source == SourceKind::Local
            && (!self.local_move_persistence_queue.is_empty()
                || self.local_move_journal_pending
                || self.local_move_is_executing())
        {
            return Err(
                "Finish or recover the pending Local move before changing playlists".to_owned(),
            );
        }
        Ok(())
    }

    /// Returns the selected supported downloaded file after revalidating it.
    fn selected_downloaded_path(&self) -> Result<PathBuf, String> {
        let row = self
            .view
            .rows
            .get(self.view.selected)
            .ok_or_else(|| "No downloaded item is selected".to_owned())?;
        let media_id = row
            .media_id
            .as_ref()
            .filter(|media_id| media_id.source == SourceKind::Local)
            .ok_or_else(|| "The selected download has no local media identity".to_owned())?;
        let path = PathBuf::from(&media_id.external_id);
        if !path.is_absolute()
            || !path.is_file()
            || !is_supported_media_path(&path.to_string_lossy())
        {
            return Err("The selected downloaded media is unavailable or unsupported".to_owned());
        }
        Ok(path)
    }

    /// Returns the selected download and its authoritative containing directory.
    ///
    /// The system-Trash operation performs a second canonical containment and
    /// file-type validation immediately before mutation.
    #[cfg(feature = "local-trash")]
    fn selected_downloaded_trash_target(&self) -> Result<(PathBuf, PathBuf), String> {
        if self.view.screen != Screen::Downloaded {
            return Err("Open Downloaded before removing an offline item".to_owned());
        }
        Ok((
            self.config.downloads_dir(),
            self.selected_downloaded_path()?,
        ))
    }

    /// Returns the selected playable identity without opening media metadata.
    ///
    /// This cheap path is used while navigating so Details membership never
    /// causes a second FLAC tag read or a provider request.
    fn selected_playlist_identity(&self) -> Option<(MediaId, String)> {
        if self.view.screen == Screen::Subscriptions {
            let video_is_active = match self.view.subscriptions.layout {
                SubscriptionsLayout::DrillDown => {
                    self.view.subscriptions.route == SubscriptionRoute::Items
                }
                SubscriptionsLayout::Split => {
                    self.view.subscriptions.focus == SubscriptionPane::Items
                        || self.view.subscriptions.description_expanded
                }
            };
            if !video_is_active {
                return None;
            }
            return match self.selected_subscription_item()? {
                SearchItem::Video(video) => Some((
                    MediaId::new(SourceKind::YouTube, &video.video_id),
                    video.title.clone(),
                )),
                SearchItem::PodcastEpisode(episode) => {
                    subscription_item_media_id(self.selected_subscription_item()?)
                        .map(|media_id| (media_id, episode.title.clone()))
                }
                SearchItem::Channel(_) => None,
            };
        }

        if self.view.screen == Screen::Bandcamp {
            #[cfg(feature = "bandcamp")]
            {
                let release = self.bandcamp_results.get(self.view.selected)?;
                return (release.kind == BandcampReleaseKind::Track)
                    .then(|| (release.id.clone(), release.title.clone()));
            }
            #[cfg(not(feature = "bandcamp"))]
            {
                return None;
            }
        }

        if self.view.screen == Screen::ApplePodcasts {
            #[cfg(feature = "apple-podcasts")]
            {
                if self.apple_podcasts_route == ApplePodcastsRoute::Direct {
                    let media = self.resolved_direct.as_ref().filter(|media| {
                        media.source == SourceKind::ApplePodcasts
                            && media.playback_url.is_some()
                            && media.webpage_url.as_ref().is_some_and(|url| {
                                stable_history_remote_url(&SourceKind::ApplePodcasts, url).is_some()
                            })
                    })?;
                    return Some((
                        MediaId::new(SourceKind::ApplePodcasts, media.external_id.clone()),
                        media.title.clone(),
                    ));
                }
                if self.apple_podcasts_route != ApplePodcastsRoute::Episodes {
                    return None;
                }
                let episode = self.apple_podcast_episodes.get(self.view.selected)?;
                return queue_item_from_apple_episode(
                    episode,
                    self.active_apple_podcast_show.as_ref(),
                )
                .ok()
                .map(|item| (item.media.id, item.media.title));
            }
            #[cfg(not(feature = "apple-podcasts"))]
            {
                return None;
            }
        }

        if self.view.screen == Screen::Local {
            let listing = self.local_listing.as_ref()?;
            let entry = listing.entries.get(self.local_entry_index()?)?;
            return (entry.kind.is_playable() && entry.path.is_file()).then(|| {
                (
                    MediaId::new(SourceKind::Local, entry.path.display().to_string()),
                    entry.display_name().into_owned(),
                )
            });
        }

        if self.view.screen == Screen::History {
            let history = self.history_entries.get(self.view.selected)?;
            if history.local_removed || history_replay_target(&history.entry).is_err() {
                return None;
            }
            return Some((history.entry.media_id.clone(), history.entry.title.clone()));
        }

        if self.view.screen == Screen::TrackerMusic {
            // Prepared tracker payloads live in the process cache and cannot
            // be reconstructed from a stable provider page after restart.
            return None;
        }

        if self.view.screen == Screen::Playlists {
            if !matches!(self.playlists_route, PlaylistsRoute::Entries { .. }) {
                return None;
            }
            let entry = self
                .active_playlist
                .as_ref()?
                .entries
                .get(self.view.selected)?;
            if ensure_playlist_snapshot_available(&entry.media).is_err() {
                return None;
            }
            return Some((entry.media.id.clone(), entry.media.title.clone()));
        }

        if self.view.screen == Screen::Search
            && self.direct_item.is_some()
            && self.resolved_direct.is_none()
        {
            return self
                .selected_playlist_snapshot()
                .ok()
                .map(|snapshot| (snapshot.id, snapshot.title));
        }

        let row = self.view.rows.get(self.view.selected)?;
        row.media_id
            .as_ref()
            .cloned()
            .map(|media_id| (media_id, row.title.clone()))
    }

    /// Rehydrates quick-action state and the right-panel playlist membership.
    fn refresh_selected_playlist_state(&mut self) {
        self.refresh_selected_private_note_state();
        self.view.playlist_item = None;
        self.view.playlist_edit_available = self.view.screen == Screen::Playlists
            && matches!(self.playlists_route, PlaylistsRoute::Index)
            && self.playlist_summaries.get(self.view.selected).is_some();
        self.view.playlist_back_available = self.view.screen == Screen::Playlists
            && matches!(self.playlists_route, PlaylistsRoute::Entries { .. });
        if let Some(details) = self.view.details.as_mut() {
            details.playlist_names.clear();
        }
        let Some((media_id, title)) = self.selected_playlist_identity() else {
            return;
        };
        let memberships = match self.store.playlist_memberships_with_names(&media_id) {
            Ok(memberships) => memberships,
            Err(error) => {
                self.show_error("Could not read playlist membership", &error);
                return;
            }
        };
        let names = memberships
            .iter()
            .map(|membership| membership.playlist_name.clone())
            .collect::<Vec<_>>();
        let in_todo = memberships
            .iter()
            .any(|membership| membership.playlist_id == TODO_PLAYLIST_ID);
        self.view.playlist_item = Some(PlaylistItemView {
            media_id: media_id.clone(),
            title,
            in_todo,
        });
        if let Some(details) = self
            .view
            .details
            .as_mut()
            .filter(|details| details.media_id.as_ref() == Some(&media_id))
        {
            details.playlist_names = names;
        }
    }

    /// Resolves the active route to one exact media or source note target.
    ///
    /// Provider-qualified identities keep equal-looking titles from colliding,
    /// while source targets let channels and podcast shows retain notes
    /// independently from their individual uploads or episodes.
    fn selected_private_note_target(&self) -> Option<PrivateNoteSelection> {
        if self.view.right_panel_mode == RightPanelMode::Channel {
            let details = self.view.details.as_ref()?;
            if !details.channel_id.is_empty() {
                return Some(PrivateNoteSelection {
                    target: CommentTarget::Source {
                        source_id: MediaId::new(SourceKind::YouTube, &details.channel_id),
                    },
                    label: if details.channel_name.is_empty() {
                        details.title.clone()
                    } else {
                        details.channel_name.clone()
                    },
                });
            }
        }

        match self.view.screen {
            Screen::Subscriptions => {
                let item_is_active = match self.view.subscriptions.layout {
                    SubscriptionsLayout::DrillDown => {
                        self.view.subscriptions.route == SubscriptionRoute::Items
                    }
                    SubscriptionsLayout::Split => {
                        self.view.subscriptions.focus == SubscriptionPane::Items
                            || self.view.subscriptions.description_expanded
                    }
                };
                if item_is_active {
                    return match self.selected_subscription_item()? {
                        SearchItem::Video(video) => Some(PrivateNoteSelection {
                            target: CommentTarget::Media {
                                media_id: MediaId::new(SourceKind::YouTube, &video.video_id),
                            },
                            label: video.title.clone(),
                        }),
                        SearchItem::Channel(channel) => Some(PrivateNoteSelection {
                            target: CommentTarget::Source {
                                source_id: MediaId::new(SourceKind::YouTube, &channel.channel_id),
                            },
                            label: channel.name.clone(),
                        }),
                        SearchItem::PodcastEpisode(episode) => subscription_item_media_id(
                            self.selected_subscription_item()?,
                        )
                        .map(|media_id| PrivateNoteSelection {
                            target: CommentTarget::Media { media_id },
                            label: episode.title.clone(),
                        }),
                    };
                }
                let subscription = &self
                    .subscription_entries
                    .get(self.view.subscriptions.selected_source)?
                    .subscription;
                let source_id = if let Some(channel_id) = subscription.youtube_channel_id() {
                    MediaId::new(SourceKind::YouTube, channel_id)
                } else {
                    let source = match subscription.kind {
                        SubscriptionKind::Rss => SourceKind::Rss,
                        SubscriptionKind::YouTube => SourceKind::YouTube,
                        SubscriptionKind::Other => SourceKind::Other("subscription".to_owned()),
                    };
                    MediaId::new(source, subscription.url.to_string())
                };
                Some(PrivateNoteSelection {
                    target: CommentTarget::Source { source_id },
                    label: subscription.title.clone(),
                })
            }
            Screen::ApplePodcasts => {
                #[cfg(feature = "apple-podcasts")]
                {
                    match self.apple_podcasts_route {
                        ApplePodcastsRoute::Shows => {
                            let show = self.apple_podcasts_results.get(self.view.selected)?;
                            Some(PrivateNoteSelection {
                                target: CommentTarget::Source {
                                    source_id: show.id.clone(),
                                },
                                label: show.title.clone(),
                            })
                        }
                        ApplePodcastsRoute::Episodes => {
                            let episode = self.apple_podcast_episodes.get(self.view.selected)?;
                            Some(PrivateNoteSelection {
                                target: CommentTarget::Media {
                                    media_id: MediaId::new(
                                        SourceKind::ApplePodcasts,
                                        episode.episode_id.to_string(),
                                    ),
                                },
                                label: episode.title.clone(),
                            })
                        }
                        ApplePodcastsRoute::Direct => {
                            let media = self.resolved_direct.as_ref()?;
                            let id = MediaId::new(SourceKind::ApplePodcasts, &media.external_id);
                            Some(PrivateNoteSelection {
                                target: if media.playback_url.is_some() {
                                    CommentTarget::Media { media_id: id }
                                } else {
                                    CommentTarget::Source { source_id: id }
                                },
                                label: media.title.clone(),
                            })
                        }
                    }
                }
                #[cfg(not(feature = "apple-podcasts"))]
                {
                    None
                }
            }
            Screen::Bandcamp => {
                #[cfg(feature = "bandcamp")]
                {
                    let release = self.bandcamp_results.get(self.view.selected)?;
                    Some(PrivateNoteSelection {
                        target: if release.kind == BandcampReleaseKind::Track {
                            CommentTarget::Media {
                                media_id: release.id.clone(),
                            }
                        } else {
                            CommentTarget::Source {
                                source_id: release.id.clone(),
                            }
                        },
                        label: release.title.clone(),
                    })
                }
                #[cfg(not(feature = "bandcamp"))]
                {
                    None
                }
            }
            Screen::TrackerMusic => {
                let item = self.tracker_results.get(self.view.selected)?;
                Some(PrivateNoteSelection {
                    target: CommentTarget::Media {
                        media_id: MediaId::new(
                            SourceKind::ModArchive,
                            item.webpage_url.to_string(),
                        ),
                    },
                    label: item.title.clone(),
                })
            }
            Screen::Radio => {
                #[cfg(feature = "radio")]
                {
                    let station = self.selected_radio_station()?;
                    Some(PrivateNoteSelection {
                        target: CommentTarget::Source {
                            source_id: MediaId::new(SourceKind::Radio, station.id),
                        },
                        label: station.name.to_owned(),
                    })
                }
                #[cfg(not(feature = "radio"))]
                {
                    None
                }
            }
            Screen::Playlists => {
                if !matches!(self.playlists_route, PlaylistsRoute::Entries { .. }) {
                    return None;
                }
                let entry = self
                    .active_playlist
                    .as_ref()?
                    .entries
                    .get(self.view.selected)?;
                Some(PrivateNoteSelection {
                    target: if entry.media.id.source == SourceKind::Radio {
                        CommentTarget::Source {
                            source_id: entry.media.id.clone(),
                        }
                    } else {
                        CommentTarget::Media {
                            media_id: entry.media.id.clone(),
                        }
                    },
                    label: entry.media.title.clone(),
                })
            }
            Screen::Local | Screen::Downloaded | Screen::History => {
                let details = self.view.details.as_ref()?;
                let media_id = details.media_id.clone()?;
                Some(PrivateNoteSelection {
                    target: if media_id.source == SourceKind::Radio {
                        CommentTarget::Source {
                            source_id: media_id,
                        }
                    } else {
                        CommentTarget::Media { media_id }
                    },
                    label: details.title.clone(),
                })
            }
            Screen::Search | Screen::YouTubeMusic => {
                if let Some(item) = self.selected_youtube_item() {
                    return match item {
                        SearchItem::Video(video) => Some(PrivateNoteSelection {
                            target: CommentTarget::Media {
                                media_id: MediaId::new(SourceKind::YouTube, &video.video_id),
                            },
                            label: video.title.clone(),
                        }),
                        SearchItem::Channel(channel) => Some(PrivateNoteSelection {
                            target: CommentTarget::Source {
                                source_id: MediaId::new(SourceKind::YouTube, &channel.channel_id),
                            },
                            label: channel.name.clone(),
                        }),
                        SearchItem::PodcastEpisode(_) => None,
                    };
                }
                let details = self.view.details.as_ref()?;
                Some(PrivateNoteSelection {
                    target: CommentTarget::Media {
                        media_id: details.media_id.clone()?,
                    },
                    label: details.title.clone(),
                })
            }
            Screen::Statistics => None,
        }
    }

    /// Refreshes only the non-sensitive note indicator for the active Details.
    fn refresh_selected_private_note_state(&mut self) {
        self.view.private_note_available = false;
        if let Some(details) = self.view.details.as_mut() {
            details.has_private_note = false;
        }
        let Some(selection) = self.selected_private_note_target() else {
            return;
        };
        self.view.private_note_available = true;
        match self.store.private_note(&selection.target) {
            Ok(note) => {
                if let Some(details) = self.view.details.as_mut() {
                    details.has_private_note = note.is_some();
                }
            }
            Err(error) => self.show_error("Could not read private note", &error),
        }
    }

    /// Opens the multiline private-note editor for the active exact target.
    fn open_private_note_popup(&mut self) {
        let Some(selection) = self.selected_private_note_target() else {
            self.view.status_line =
                "Select a media item, channel, or podcast show before adding a note".to_owned();
            return;
        };
        let existing = match self.store.private_note(&selection.target) {
            Ok(existing) => existing,
            Err(error) => {
                self.show_error("Could not read private note", &error);
                return;
            }
        };
        let is_existing = existing.is_some();
        let body = existing.map_or_else(String::new, |comment| comment.body);
        let storage_path = match self.config.persistence.backend {
            PersistenceBackend::Files => self.config.state_dir().join("notes.toml"),
            PersistenceBackend::Sqlite => self.config.database_file(),
        };
        self.private_note_editor = Some(PrivateNoteEditor {
            target: selection.target,
        });
        self.view.private_note_popup = Some(PrivateNotePopupView {
            target_label: selection.label,
            cursor_byte: body.len(),
            body,
            follow_cursor: true,
            existing: is_existing,
            storage_path: storage_path.display().to_string(),
            ..PrivateNotePopupView::default()
        });
    }

    /// Inserts one character if it fits the documented UTF-8 byte limit.
    fn append_private_note_character(&mut self, character: char) {
        let Some(popup) = self.view.private_note_popup.as_mut() else {
            return;
        };
        if popup.body.len().saturating_add(character.len_utf8()) > MAX_PRIVATE_NOTE_BYTES {
            popup.validation_error = Some(format!(
                "A private note is limited to {MAX_PRIVATE_NOTE_BYTES} UTF-8 bytes"
            ));
            return;
        }
        let cursor = private_note_cursor_boundary(&popup.body, popup.cursor_byte);
        popup.body.insert(cursor, character);
        popup.cursor_byte = cursor.saturating_add(character.len_utf8());
        popup.follow_cursor = true;
        popup.confirming_delete = false;
        popup.validation_error = None;
    }

    /// Inserts one line break into the private-note draft.
    fn insert_private_note_newline(&mut self) {
        self.append_private_note_character('\n');
    }

    /// Removes one complete grapheme cluster before the note cursor.
    fn delete_private_note_character(&mut self) {
        let Some(popup) = self.view.private_note_popup.as_mut() else {
            return;
        };
        let cursor = private_note_cursor_boundary(&popup.body, popup.cursor_byte);
        let Some(start) = popup.body[..cursor]
            .grapheme_indices(true)
            .next_back()
            .map(|(index, _)| index)
        else {
            return;
        };
        popup.body.replace_range(start..cursor, "");
        popup.cursor_byte = start;
        popup.follow_cursor = true;
        popup.confirming_delete = false;
        popup.validation_error = None;
    }

    /// Deletes one Vim-style word before the private-note cursor.
    fn delete_private_note_word(&mut self) {
        let Some(popup) = self.view.private_note_popup.as_mut() else {
            return;
        };
        if delete_previous_editor_word(&mut popup.body, &mut popup.cursor_byte) {
            popup.follow_cursor = true;
            popup.confirming_delete = false;
            popup.validation_error = None;
        }
    }

    /// Moves the private-note insertion point without splitting a grapheme.
    fn move_private_note_cursor(&mut self, motion: PrivateNoteCursorMotion) {
        let Some(popup) = self.view.private_note_popup.as_mut() else {
            return;
        };
        popup.cursor_byte = moved_private_note_cursor(&popup.body, popup.cursor_byte, motion);
        popup.follow_cursor = true;
        popup.confirming_delete = false;
    }

    /// Scrolls the private-note viewport without forcing it back to the cursor.
    fn set_private_note_scroll(&mut self, offset: usize) {
        let Some(popup) = self.view.private_note_popup.as_mut() else {
            return;
        };
        popup.scroll_offset = offset;
        popup.follow_cursor = false;
    }

    /// Creates or edits the sole user-facing note for an exact target.
    fn save_private_note(&mut self) {
        let Some(editor) = self.private_note_editor.as_ref() else {
            return;
        };
        let Some(popup) = self.view.private_note_popup.as_ref() else {
            return;
        };
        if popup.body.trim().is_empty() {
            if let Some(popup) = self.view.private_note_popup.as_mut() {
                popup.validation_error =
                    Some("A note cannot be empty; use Delete to remove it".to_owned());
            }
            return;
        }
        if popup.body.len() > MAX_PRIVATE_NOTE_BYTES {
            if let Some(popup) = self.view.private_note_popup.as_mut() {
                popup.validation_error = Some(format!(
                    "A private note is limited to {MAX_PRIVATE_NOTE_BYTES} UTF-8 bytes"
                ));
            }
            return;
        }
        let target = editor.target.clone();
        let body = popup.body.clone();
        match self.store.upsert_private_note(&target, &body, unix_time()) {
            Ok(_) => {}
            Err(error) => {
                if let Some(popup) = self.view.private_note_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
                return;
            }
        }
        let label = self
            .view
            .private_note_popup
            .as_ref()
            .map_or("item", |popup| popup.target_label.as_str())
            .to_owned();
        self.dismiss_private_note_popup();
        self.refresh_selected_private_note_state();
        self.view.status_line = format!("Saved private note for {label}");
    }

    /// Starts deletion confirmation, then removes every legacy row at target.
    fn request_private_note_delete(&mut self) {
        let Some(popup) = self.view.private_note_popup.as_mut() else {
            return;
        };
        if !popup.existing {
            popup.validation_error = Some("This target has no saved note to delete".to_owned());
            return;
        }
        if !popup.confirming_delete {
            popup.confirming_delete = true;
            popup.validation_error = None;
            return;
        }
        let Some(editor) = self.private_note_editor.as_ref() else {
            return;
        };
        match self.store.delete_private_note(&editor.target) {
            Ok(_) => {}
            Err(error) => {
                if let Some(popup) = self.view.private_note_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
                return;
            }
        }
        let label = popup.target_label.clone();
        self.dismiss_private_note_popup();
        self.refresh_selected_private_note_state();
        self.view.status_line = format!("Deleted private note for {label}");
    }

    /// Closes the private-note editor and drops its unsaved body.
    fn dismiss_private_note_popup(&mut self) {
        self.view.private_note_popup = None;
        self.private_note_editor = None;
    }

    /// Toggles the selected item in the fixed Watch Later-style playlist.
    fn toggle_selected_todo(&mut self) {
        let snapshot = match self.selected_playlist_snapshot() {
            Ok(snapshot) => snapshot,
            Err(error) => {
                self.view.status_line = error;
                return;
            }
        };
        if let Err(error) = self.ensure_playlist_mutation_ready(&snapshot) {
            self.view.status_line = error;
            return;
        }
        match self.store.toggle_todo(&snapshot, unix_time()) {
            Ok(PlaylistToggleOutcome::Added) => {
                self.view.status_line = format!("Added {} to todo", snapshot.title);
            }
            Ok(PlaylistToggleOutcome::Removed) => {
                self.view.status_line = format!("Removed {} from todo", snapshot.title);
            }
            Err(error) => {
                self.show_error("Could not update todo", &error);
                return;
            }
        }
        self.refresh_playlists_after_mutation(Some(&snapshot.id));
    }

    /// Opens a bounded membership chooser for the selected playable item.
    fn open_playlist_popup(&mut self) {
        let snapshot = match self.selected_playlist_snapshot() {
            Ok(snapshot) => snapshot,
            Err(error) => {
                self.view.status_line = error;
                return;
            }
        };
        if let Err(error) = self.ensure_playlist_mutation_ready(&snapshot) {
            self.view.status_line = error;
            return;
        }
        let summaries = match self.store.playlists() {
            Ok(summaries) => summaries,
            Err(error) => {
                self.show_error("Could not load playlists", &error);
                return;
            }
        };
        let memberships = match self.store.playlist_memberships(&snapshot.id) {
            Ok(memberships) => memberships.into_iter().collect::<HashSet<_>>(),
            Err(error) => {
                self.show_error("Could not load playlist membership", &error);
                return;
            }
        };
        let playlists = summaries
            .into_iter()
            .map(|summary| PlaylistChoiceView {
                contains_item: memberships.contains(&summary.id),
                playlist_id: summary.id,
                name: summary.name,
            })
            .collect();
        self.playlist_popup_item = Some(snapshot.clone());
        self.view.playlist_popup = Some(PlaylistPopupView {
            item_title: snapshot.title,
            playlists,
            ..PlaylistPopupView::default()
        });
    }

    /// Rebuilds chooser rows after a membership or metadata mutation.
    fn refresh_open_playlist_popup(&mut self) {
        let Some(snapshot) = self.playlist_popup_item.as_ref() else {
            return;
        };
        let summaries = match self.store.playlists() {
            Ok(summaries) => summaries,
            Err(error) => {
                self.show_error("Could not reload playlists", &error);
                return;
            }
        };
        let memberships = match self.store.playlist_memberships(&snapshot.id) {
            Ok(memberships) => memberships.into_iter().collect::<HashSet<_>>(),
            Err(error) => {
                self.show_error("Could not reload playlist membership", &error);
                return;
            }
        };
        let Some(popup) = self.view.playlist_popup.as_mut() else {
            return;
        };
        let selected_id = popup
            .playlists
            .get(popup.selected)
            .map(|playlist| playlist.playlist_id.clone());
        popup.playlists = summaries
            .into_iter()
            .map(|summary| PlaylistChoiceView {
                contains_item: memberships.contains(&summary.id),
                playlist_id: summary.id,
                name: summary.name,
            })
            .collect();
        popup.selected = selected_id
            .and_then(|selected_id| {
                popup
                    .playlists
                    .iter()
                    .position(|playlist| playlist.playlist_id == selected_id)
            })
            .unwrap_or_default()
            .min(popup.playlists.len().saturating_sub(1));
        popup.validation_error = None;
    }

    /// Toggles membership in the chooser's selected playlist in place.
    fn toggle_selected_playlist_membership(&mut self) {
        let Some(snapshot) = self.playlist_popup_item.as_ref().cloned() else {
            self.view.playlist_popup = None;
            self.view.status_line = "The selected playlist item is no longer available".to_owned();
            return;
        };
        if let Err(error) = self.ensure_playlist_mutation_ready(&snapshot) {
            if let Some(popup) = self.view.playlist_popup.as_mut() {
                popup.validation_error = Some(error);
            }
            return;
        }
        let Some(playlist) = self
            .view
            .playlist_popup
            .as_ref()
            .and_then(|popup| popup.playlists.get(popup.selected))
            .cloned()
        else {
            if let Some(popup) = self.view.playlist_popup.as_mut() {
                popup.validation_error =
                    Some("Create a playlist before changing membership".to_owned());
            }
            return;
        };
        match self
            .store
            .toggle_playlist_entry(&playlist.playlist_id, &snapshot, unix_time())
        {
            Ok(PlaylistToggleOutcome::Added) => {
                self.view.status_line = format!("Added {} to {}", snapshot.title, playlist.name);
            }
            Ok(PlaylistToggleOutcome::Removed) => {
                self.view.status_line =
                    format!("Removed {} from {}", snapshot.title, playlist.name);
            }
            Err(error) => {
                if let Some(popup) = self.view.playlist_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
                return;
            }
        }
        self.refresh_open_playlist_popup();
        self.refresh_playlists_after_mutation(Some(&snapshot.id));
    }

    /// Opens the two-field create route while retaining the selected item.
    fn begin_new_playlist(&mut self) {
        let Some(popup) = self.view.playlist_popup.as_mut() else {
            return;
        };
        popup.mode = PlaylistPopupMode::Create;
        popup.editing_playlist_id = None;
        popup.editor_field = PlaylistEditorField::Name;
        popup.editor_name.clear();
        popup.editor_description.clear();
        popup.validation_error = None;
    }

    /// Opens the shared metadata editor for the selected playlist index row.
    fn edit_selected_playlist(&mut self) {
        if self.view.screen != Screen::Playlists
            || !matches!(self.playlists_route, PlaylistsRoute::Index)
        {
            self.view.status_line = "Select a playlist before editing it".to_owned();
            return;
        }
        let Some(summary) = self.playlist_summaries.get(self.view.selected).cloned() else {
            self.view.status_line = "No playlist is selected".to_owned();
            return;
        };
        self.playlist_popup_item = None;
        self.view.playlist_popup = Some(PlaylistPopupView {
            item_title: summary.name.clone(),
            mode: PlaylistPopupMode::Edit,
            editing_playlist_id: Some(summary.id),
            editor_name: summary.name,
            editor_description: summary.description.unwrap_or_default(),
            ..PlaylistPopupView::default()
        });
    }

    /// Appends one character under both display-character and persistence bounds.
    fn append_playlist_editor_character(&mut self, character: char) {
        let Some(popup) = self.view.playlist_popup.as_mut() else {
            return;
        };
        match popup.editor_field {
            PlaylistEditorField::Name => {
                let limit = popup.name_limit.min(MAX_PLAYLIST_NAME_BYTES);
                if popup.editor_name.len().saturating_add(character.len_utf8()) <= limit {
                    popup.editor_name.push(character);
                    popup.validation_error = None;
                }
            }
            PlaylistEditorField::Description => {
                if popup.editor_description.chars().count() < popup.description_limit {
                    popup.editor_description.push(character);
                    popup.validation_error = None;
                }
            }
        }
    }

    /// Removes the final Unicode scalar from the focused playlist editor field.
    fn delete_playlist_editor_character(&mut self) {
        let Some(popup) = self.view.playlist_popup.as_mut() else {
            return;
        };
        match popup.editor_field {
            PlaylistEditorField::Name => {
                popup.editor_name.pop();
            }
            PlaylistEditorField::Description => {
                popup.editor_description.pop();
            }
        }
        popup.validation_error = None;
    }

    /// Deletes one Vim-style word from the focused playlist editor field.
    fn delete_playlist_editor_word(&mut self) {
        let Some(popup) = self.view.playlist_popup.as_mut() else {
            return;
        };
        let value = match popup.editor_field {
            PlaylistEditorField::Name => &mut popup.editor_name,
            PlaylistEditorField::Description => &mut popup.editor_description,
        };
        let mut cursor = value.len();
        if delete_previous_editor_word(value, &mut cursor) {
            popup.validation_error = None;
        }
    }

    /// Creates a named playlist and adds the chooser item after validation.
    fn create_playlist_and_add(&mut self) {
        let Some(snapshot) = self.playlist_popup_item.as_ref().cloned() else {
            if let Some(popup) = self.view.playlist_popup.as_mut() {
                popup.validation_error =
                    Some("The selected media item is no longer available".to_owned());
            }
            return;
        };
        if let Err(error) = self.ensure_playlist_mutation_ready(&snapshot) {
            if let Some(popup) = self.view.playlist_popup.as_mut() {
                popup.validation_error = Some(error);
            }
            return;
        }
        let Some((name, description)) = self.view.playlist_popup.as_ref().map(|popup| {
            (
                popup.editor_name.clone(),
                optional_trimmed_text(&popup.editor_description),
            )
        }) else {
            return;
        };
        let now = unix_time();
        let summary = match self.store.create_playlist_with_entry(
            &name,
            description.as_deref(),
            &snapshot,
            now,
        ) {
            Ok(PlaylistCreateOutcome::Created(summary)) => summary,
            Ok(PlaylistCreateOutcome::Existing(summary)) => {
                if let Some(popup) = self.view.playlist_popup.as_mut() {
                    popup.validation_error = Some(format!(
                        "A playlist named `{}` already exists; return to the chooser to use it",
                        summary.name
                    ));
                }
                return;
            }
            Err(error) => {
                if let Some(popup) = self.view.playlist_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
                return;
            }
        };
        self.view.status_line = format!("Created {} and added {}", summary.name, snapshot.title);
        if let Some(popup) = self.view.playlist_popup.as_mut() {
            popup.mode = PlaylistPopupMode::Choose;
            popup.editing_playlist_id = None;
            popup.editor_name.clear();
            popup.editor_description.clear();
            popup.validation_error = None;
        }
        self.refresh_open_playlist_popup();
        self.refresh_playlists_after_mutation(Some(&snapshot.id));
    }

    /// Persists playlist display metadata without changing its stable identity.
    fn update_selected_playlist(&mut self) {
        let Some((playlist_id, name, description)) =
            self.view.playlist_popup.as_ref().and_then(|popup| {
                Some((
                    popup.editing_playlist_id.clone()?,
                    popup.editor_name.clone(),
                    optional_trimmed_text(&popup.editor_description),
                ))
            })
        else {
            return;
        };
        match self
            .store
            .update_playlist(&playlist_id, &name, description.as_deref(), unix_time())
        {
            Ok(Some(summary)) => {
                self.view.status_line = format!("Updated playlist {}", summary.name);
                self.view.playlist_popup = None;
                self.playlist_popup_item = None;
                self.refresh_playlists_after_mutation(None);
            }
            Ok(None) => {
                if let Some(popup) = self.view.playlist_popup.as_mut() {
                    popup.validation_error =
                        Some("That playlist was removed by another process".to_owned());
                }
            }
            Err(error) => {
                if let Some(popup) = self.view.playlist_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
            }
        }
    }

    /// Returns from create to chooser, or closes the current playlist popup.
    fn dismiss_playlist_popup(&mut self) {
        let return_to_chooser = self.view.playlist_popup.as_ref().is_some_and(|popup| {
            popup.mode == PlaylistPopupMode::Create && self.playlist_popup_item.is_some()
        });
        if return_to_chooser {
            if let Some(popup) = self.view.playlist_popup.as_mut() {
                popup.mode = PlaylistPopupMode::Choose;
                popup.editing_playlist_id = None;
                popup.editor_name.clear();
                popup.editor_description.clear();
                popup.validation_error = None;
            }
            self.refresh_open_playlist_popup();
            return;
        }
        self.view.playlist_popup = None;
        self.playlist_popup_item = None;
    }

    fn queue_selected(&mut self, play_next: bool) {
        let item = match self.selected_queue_item() {
            Ok(item) => item,
            Err(error) => {
                self.view.status_line = error;
                return;
            }
        };
        let title = item.media.title.clone();
        if play_next {
            self.playback_queue.play_next(item);
            self.view.status_line = format!("{title} will play next");
        } else {
            self.playback_queue.push(item);
            self.view.status_line = format!("{title} added to the queue");
        }
    }

    #[cfg(feature = "yt-dlp")]
    fn start_selected_download(&mut self) {
        if self.active_download.is_some() {
            self.view.status_line =
                "One download is already running; wait for it to finish".to_owned();
            return;
        }
        clear_download_completion_notice(
            &mut self.view,
            &mut self.download_completion_notice_deadline,
        );
        let item = match self.selected_queue_item() {
            Ok(item) => item,
            Err(error) => {
                self.view.status_line = error;
                return;
            }
        };
        let source_url = item.media.webpage_url.clone();
        if !matches!(source_url.scheme(), "http" | "https")
            || source_url.host_str().is_none()
            || !source_url.username().is_empty()
            || source_url.password().is_some()
        {
            self.view.status_line =
                "Downloads require a credential-free remote HTTP(S) item".to_owned();
            return;
        }
        let destination = match prepare_download_destination(&self.config) {
            Ok(destination) => destination,
            Err(error) => {
                self.show_error_message("Download destination is unavailable", error);
                return;
            }
        };
        let format = match configured_download_format(&self.config.subscriptions.audio_format) {
            Ok(format) => format,
            Err(error) => {
                self.show_error_message("Download format is invalid", error);
                return;
            }
        };
        let request = DownloadRequest {
            source_url,
            destination: destination.clone(),
            format,
            write_thumbnail: self.config.subscriptions.download_thumbnails,
        };
        let process = match self.download_launcher.start(&request) {
            Ok(process) => process,
            Err(error) => {
                self.show_error_message("Download could not start", error);
                return;
            }
        };
        let title = item.media.title;
        let active = match ActiveDownload::start(title.clone(), destination, process) {
            Ok(active) => active,
            Err(error) => {
                self.show_error_message("Download supervision could not start", error);
                return;
            }
        };
        self.view.download = Some(DownloadView {
            title: title.clone(),
            active: true,
            ..DownloadView::default()
        });
        self.view.status_line = format!("Downloading {title}");
        self.active_download = Some(active);
    }

    #[cfg(not(feature = "yt-dlp"))]
    fn start_selected_download(&mut self) {
        self.view.status_line =
            "Download support was disabled when this Youta binary was built".to_owned();
    }

    /// Polls one active download and expires a completed-path notice at `now`.
    #[cfg(feature = "yt-dlp")]
    fn poll_download_at(&mut self, now: Instant) {
        expire_download_completion_notice(
            &mut self.view,
            &mut self.download_completion_notice_deadline,
            now,
        );
        let Some(active) = self.active_download.as_mut() else {
            return;
        };
        let (progress, read_error) = {
            let output = active
                .output
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            (output.progress, output.read_error.clone())
        };
        apply_download_progress(&mut self.view, &active.title, progress);

        if let Some(error) = read_error {
            let mut active = self
                .active_download
                .take()
                .expect("an active download was checked above");
            active.cancel_and_join();
            let diagnostics = download_diagnostics(&active);
            mark_download_inactive(&mut self.view);
            self.show_error_message(
                "Download output could not be read",
                append_download_diagnostics(error, &diagnostics),
            );
            return;
        }

        let exit = match active.process.try_wait() {
            Ok(exit) => exit,
            Err(error) => {
                let mut active = self
                    .active_download
                    .take()
                    .expect("an active download was checked above");
                active.cancel_and_join();
                let diagnostics = download_diagnostics(&active);
                mark_download_inactive(&mut self.view);
                self.show_error_message(
                    "Download process could not be monitored",
                    append_download_diagnostics(error, &diagnostics),
                );
                return;
            }
        };
        let Some(exit) = exit else {
            return;
        };

        let mut active = self
            .active_download
            .take()
            .expect("the completed download is still active");
        active.join_readers();
        let (progress, completed_path, read_error, diagnostics) = {
            let output = active
                .output
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            (
                output.progress,
                output.completed_paths.back().cloned(),
                output.read_error.clone(),
                output.diagnostics(),
            )
        };
        apply_download_progress(&mut self.view, &active.title, progress);
        if let Some(error) = read_error {
            mark_download_inactive(&mut self.view);
            self.show_error_message(
                "Download output could not be read",
                append_download_diagnostics(error, &diagnostics),
            );
            return;
        }
        if !exit.success {
            mark_download_inactive(&mut self.view);
            self.show_error_message(
                "Download failed",
                append_download_diagnostics(
                    format!("yt-dlp exited with {}", exit.description),
                    &diagnostics,
                ),
            );
            return;
        }
        let Some(completed_path) = completed_path else {
            mark_download_inactive(&mut self.view);
            self.show_error_message(
                "Download result is incomplete",
                append_download_diagnostics(
                    "yt-dlp succeeded but did not report a completed media path".to_owned(),
                    &diagnostics,
                ),
            );
            return;
        };
        let completed_path =
            match validate_completed_download_path(&active.destination, &completed_path) {
                Ok(path) => path,
                Err(error) => {
                    mark_download_inactive(&mut self.view);
                    self.show_error_message("Download path failed validation", error);
                    return;
                }
            };
        self.view.download = Some(DownloadView {
            title: active.title,
            downloaded_bytes: progress.downloaded_bytes,
            total_bytes: progress.total_bytes,
            bytes_per_second: progress.bytes_per_second.map(rounded_download_rate),
            eta_seconds: Some(0),
            active: false,
            completed_path: Some(completed_path.display().to_string()),
        });
        self.download_completion_notice_deadline = Some(now + DOWNLOAD_COMPLETION_NOTICE_DURATION);
        if self.view.screen == Screen::Downloaded {
            self.populate_downloads();
            self.refresh_selected_playlist_state();
        }
        self.view.status_line = format!("Downloaded {}", completed_path.display());
    }

    fn activate_selection(&mut self) {
        if self.view.screen == Screen::Local {
            self.activate_local_browser_selection();
            return;
        }
        if self.view.screen == Screen::History {
            self.activate_history_selection();
            return;
        }
        if self.view.screen == Screen::Playlists {
            self.activate_playlist_selection();
            return;
        }
        if self.view.screen == Screen::Bandcamp {
            self.activate_bandcamp_selection();
            return;
        }
        if self.view.screen == Screen::ApplePodcasts {
            self.activate_apple_podcasts_selection();
            return;
        }
        if self.view.screen == Screen::Subscriptions {
            match (
                self.view.subscriptions.layout,
                self.view.subscriptions.route,
                self.view.subscriptions.focus,
            ) {
                (SubscriptionsLayout::DrillDown, SubscriptionRoute::Sources, _) => {
                    self.view.subscriptions.route = SubscriptionRoute::Items;
                    self.view.subscriptions.focus = SubscriptionPane::Items;
                    self.view.right_panel_mode = RightPanelMode::Details;
                    self.load_selected_subscription_videos();
                    if self.view.subscriptions.loading {
                        self.view.status_line = format!(
                            "Loading {} for {}…",
                            subscription_item_kind_label(self.view.subscriptions.source_kind),
                            self.view.subscriptions.source_title
                        );
                    }
                    return;
                }
                (SubscriptionsLayout::Split, _, SubscriptionPane::Sources) => {
                    self.view.subscriptions.focus = SubscriptionPane::Items;
                    self.view.right_panel_mode = RightPanelMode::Details;
                    self.load_selected_subscription_videos();
                    if self.view.subscriptions.items.is_empty() && !self.view.subscriptions.loading
                    {
                        self.view.status_line = format!(
                            "This subscription has no loaded playable {}",
                            subscription_item_kind_label(self.view.subscriptions.source_kind)
                        );
                    } else if !self.view.subscriptions.items.is_empty() {
                        if self.view.subscriptions.source_kind == SubscriptionKind::Rss {
                            self.update_selected_rss_episode_detail();
                        } else {
                            self.request_selected_details();
                        }
                    }
                    return;
                }
                _ => {}
            }
            if self.view.subscriptions.focus == SubscriptionPane::Items
                && self.view.subscriptions.items.is_empty()
            {
                self.load_next_subscription_page_if_needed();
                if !self.view.subscriptions.loading {
                    self.view.status_line = format!(
                        "This subscription has no loaded playable {}",
                        subscription_item_kind_label(self.view.subscriptions.source_kind)
                    );
                }
                return;
            }
        }
        #[cfg(feature = "tracker-music")]
        if self.view.screen == Screen::TrackerMusic && self.prepare_selected_tracker_item() {
            return;
        }
        let item = match self.selected_queue_item() {
            Ok(item) => item,
            Err(error) => {
                if matches!(self.selected_youtube_item(), Some(SearchItem::Channel(_))) {
                    self.show_selected_channel();
                } else {
                    self.view.status_line = error;
                }
                return;
            }
        };
        if item.media.id.source == SourceKind::YouTube {
            if self.view.screen == Screen::YouTubeMusic {
                self.youtube_music_start_override = None;
            } else {
                self.selected_start_override = None;
            }
        }
        self.play_queue_item(item, false);
    }

    /// Resolves and starts the selected Bandcamp release on explicit Enter.
    #[cfg(feature = "bandcamp")]
    fn activate_bandcamp_selection(&mut self) {
        let Some(summary) = self.bandcamp_results.get(self.view.selected).cloned() else {
            self.view.status_line = "No Bandcamp release is selected".to_owned();
            return;
        };
        self.request_bandcamp_resolution(summary, BandcampResolutionOwner::SearchSelection);
    }

    /// Submits one canonical Bandcamp page for action-owned media resolution.
    #[cfg(feature = "bandcamp")]
    fn request_bandcamp_resolution(
        &mut self,
        summary: BandcampSearchSummary,
        owner: BandcampResolutionOwner,
    ) {
        let media = match BandcampMediaUrl::parse(summary.webpage_url.clone()) {
            Ok(media) if media.stable_id() == summary.id.external_id => media,
            Ok(_) => {
                self.show_error_message(
                    "Bandcamp playback failed",
                    "the selected release identity does not match its canonical page",
                );
                return;
            }
            Err(error) => {
                self.show_error_message("Bandcamp playback failed", error.to_string());
                return;
            }
        };
        if !self.ensure_bandcamp_resolver_worker() {
            self.show_error_message(
                "Bandcamp playback failed",
                "the bounded Bandcamp resolver worker could not be started",
            );
            return;
        }
        self.bandcamp_resolve_generation = self.bandcamp_resolve_generation.wrapping_add(1);
        let generation = self.bandcamp_resolve_generation;
        if let Some(receiver) = self.bandcamp_resolve_request_drain.as_ref() {
            while receiver.try_recv().is_ok() {}
        }
        let command = BandcampResolveCommand::Resolve {
            generation,
            media,
            format: self.config.providers.bandcamp_audio_format,
            purpose: BandcampResolvePurpose::Playback,
        };
        let Some(sender) = self.bandcamp_resolve_requests.as_ref() else {
            return;
        };
        match sender.try_send(command) {
            Ok(()) => {
                self.pending_bandcamp_resolution = Some(PendingBandcampResolution {
                    generation,
                    summary,
                    owner,
                });
                self.begin_playback_start_activity();
                self.view.status_line = format!(
                    "Resolving Bandcamp audio as {}…",
                    self.config.providers.bandcamp_audio_format.label()
                );
            }
            Err(TrySendError::Full(_) | TrySendError::Disconnected(_)) => {
                self.show_error_message(
                    "Bandcamp playback failed",
                    "the bounded resolver worker could not accept the selected release",
                );
            }
        }
    }

    /// Reports that Bandcamp playback was omitted at build time.
    #[cfg(not(feature = "bandcamp"))]
    fn activate_bandcamp_selection(&mut self) {
        self.view.status_line =
            "This build omits the `bandcamp` feature; rebuild with it enabled".to_owned();
    }

    /// Lazily starts the single-request Bandcamp resolver worker.
    #[cfg(feature = "bandcamp")]
    fn ensure_bandcamp_resolver_worker(&mut self) -> bool {
        if self.bandcamp_resolve_requests.is_some() {
            return true;
        }
        let Some(resolver) = self.bandcamp_resolver.take() else {
            return false;
        };
        let (request_sender, request_receiver) = bounded(1);
        let request_drain = request_receiver.clone();
        let (response_sender, response_receiver) = bounded(1);
        let response_drain = response_receiver.clone();
        let thread = thread::Builder::new()
            .name("youta-bandcamp-resolver".to_owned())
            .spawn(move || {
                bandcamp_resolver_worker(
                    request_receiver,
                    response_sender,
                    response_drain,
                    resolver,
                );
            });
        let Ok(thread) = thread else {
            return false;
        };
        self.bandcamp_resolve_requests = Some(request_sender);
        self.bandcamp_resolve_request_drain = Some(request_drain);
        self.bandcamp_resolve_responses = Some(response_receiver);
        self.bandcamp_resolve_thread = Some(thread);
        true
    }

    /// Invalidates ownership of a result whose selected row changed.
    #[cfg(feature = "bandcamp")]
    fn cancel_pending_bandcamp_resolution(&mut self) {
        if self.pending_bandcamp_resolution.take().is_some() {
            self.bandcamp_resolve_generation = self.bandcamp_resolve_generation.wrapping_add(1);
            self.clear_playback_start_activity();
        }
    }

    /// Stops and joins the lazy Bandcamp resolver without retaining media URLs.
    #[cfg(feature = "bandcamp")]
    fn shutdown_bandcamp_resolver(&mut self) {
        self.pending_bandcamp_resolution = None;
        self.bandcamp_resolve_generation = self.bandcamp_resolve_generation.wrapping_add(1);
        if let Some(receiver) = self.bandcamp_resolve_request_drain.as_ref() {
            while receiver.try_recv().is_ok() {}
        }
        if let Some(sender) = self.bandcamp_resolve_requests.take() {
            let _ = sender.send(BandcampResolveCommand::Shutdown);
        }
        self.bandcamp_resolve_request_drain = None;
        self.bandcamp_resolve_responses = None;
        if let Some(thread) = self.bandcamp_resolve_thread.take() {
            let _ = thread.join();
        }
    }

    /// Applies only the latest exact Bandcamp selection completion.
    #[cfg(feature = "bandcamp")]
    fn drain_bandcamp_resolver_responses(&mut self) {
        loop {
            let completion = self
                .bandcamp_resolve_responses
                .as_ref()
                .and_then(|receiver| receiver.try_recv().ok());
            let Some(completion) = completion else {
                break;
            };
            let owns = self
                .pending_bandcamp_resolution
                .as_ref()
                .is_some_and(|pending| pending.generation == completion.generation);
            if !owns {
                continue;
            }
            let pending = self
                .pending_bandcamp_resolution
                .take()
                .expect("matching Bandcamp resolve ownership was checked above");
            self.clear_playback_start_activity();
            let still_selected = match &pending.owner {
                BandcampResolutionOwner::SearchSelection => {
                    self.view.screen == Screen::Bandcamp
                        && self
                            .bandcamp_results
                            .get(self.view.selected)
                            .is_some_and(|selected| selected.id == pending.summary.id)
                }
                BandcampResolutionOwner::Playlist(entry) => {
                    self.view.screen == Screen::Playlists
                        && matches!(self.playlists_route, PlaylistsRoute::Entries { .. })
                        && self
                            .active_playlist
                            .as_ref()
                            .and_then(|playlist| playlist.entries.get(self.view.selected))
                            .is_some_and(|selected| {
                                selected.media.id == entry.media.id
                                    && selected.added_at == entry.added_at
                            })
                }
            };
            if !still_selected {
                continue;
            }
            match completion.result {
                Ok(resolution) => {
                    self.play_bandcamp_resolution(pending.summary, resolution);
                }
                Err(error) => {
                    self.show_error("Bandcamp playback failed", &error);
                }
            }
        }
    }

    /// Starts only the first playable result while discarding every signed URL.
    #[cfg(feature = "bandcamp")]
    fn play_bandcamp_resolution(
        &mut self,
        summary: BandcampSearchSummary,
        mut resolution: BandcampResolution,
    ) {
        if resolution.purpose != BandcampResolvePurpose::Playback
            || resolution.format != self.config.providers.bandcamp_audio_format
            || resolution.source.as_url() != &summary.webpage_url
        {
            self.show_error_message(
                "Bandcamp playback failed",
                "the resolver returned media for a different release or action",
            );
            return;
        }
        let Some(track) = resolution.tracks.drain(..).next() else {
            self.show_error_message(
                "Bandcamp playback failed",
                format!(
                    "No playable Bandcamp audio matched {}; try Best available in Preferences",
                    resolution.format.label()
                ),
            );
            return;
        };
        let item = match queue_item_from_bandcamp_track(&summary, &resolution.source, &track) {
            Ok(item) => item,
            Err(error) => {
                self.show_error_message("Bandcamp playback failed", error);
                return;
            }
        };
        let mut input = PlaybackInput::new(track.media_url.to_string());
        input.http_headers = PlaybackHttpHeaders::new(track.http_headers);
        input.bypass_ytdl = true;
        self.play_queue_item_with_origin_and_input(item, false, None, Some(input));
    }

    /// Starts one Apple collection lookup with stable tab and row ownership.
    #[cfg(feature = "apple-podcasts")]
    fn request_apple_podcast_episodes(
        &mut self,
        show: PodcastShowSummary,
        origin: ApplePodcastEpisodeOrigin,
    ) {
        if self.view.search_activity == Some(SearchActivity::ApplePodcasts) {
            self.view.status_line = "An Apple Podcasts request is already running".to_owned();
            return;
        }
        let Ok(collection_id) = show.id.external_id.parse::<u64>() else {
            self.show_error_message(
                "Apple Podcasts episodes failed",
                "the cached podcast collection identifier is invalid",
            );
            return;
        };
        self.supersede_search_generation();
        let generation = self.search_generation;
        if !self.send_provider_request(
            ProviderRequest::ApplePodcastEpisodes {
                generation,
                country: self.apple_podcasts_storefront.clone(),
                collection_id,
            },
            "Could not load Apple Podcasts episodes",
        ) {
            return;
        }
        self.pending_apple_podcast_episodes = Some(PendingApplePodcastEpisodes {
            generation,
            collection_id,
            show: show.clone(),
            origin,
        });
        self.active_apple_podcast_show = Some(show);
        self.begin_search_activity(SearchActivity::ApplePodcasts);
        self.view.status_line = "Loading Apple’s bounded associated episode list…".to_owned();
    }

    /// Opens the selected Apple show or plays the selected resolved episode.
    #[cfg(feature = "apple-podcasts")]
    fn activate_apple_podcasts_selection(&mut self) {
        match self.apple_podcasts_route {
            ApplePodcastsRoute::Shows => {
                let Some(show) = self.apple_podcasts_results.get(self.view.selected).cloned()
                else {
                    self.view.status_line = "No Apple podcast show is selected".to_owned();
                    return;
                };
                self.request_apple_podcast_episodes(
                    show,
                    ApplePodcastEpisodeOrigin::Shows(self.view.selected),
                );
            }
            ApplePodcastsRoute::Episodes => {
                let Some(episode) = self.apple_podcast_episodes.get(self.view.selected) else {
                    self.view.status_line = "No Apple podcast episode is selected".to_owned();
                    return;
                };
                let item = match queue_item_from_apple_episode(
                    episode,
                    self.active_apple_podcast_show.as_ref(),
                ) {
                    Ok(item) => item,
                    Err(error) => {
                        self.view.status_line = error;
                        return;
                    }
                };
                self.play_queue_item(item, false);
            }
            ApplePodcastsRoute::Direct => {
                let Some(media) = self
                    .resolved_direct
                    .as_ref()
                    .filter(|media| media.source == SourceKind::ApplePodcasts)
                    .cloned()
                else {
                    self.view.status_line = "Apple Podcasts metadata is still resolving".to_owned();
                    return;
                };
                if media.playback_url.is_some() {
                    let item = match queue_item_from_resolved(&media) {
                        Ok(item) => item,
                        Err(error) => {
                            self.show_error_message("Apple Podcasts playback failed", error);
                            return;
                        }
                    };
                    self.play_queue_item(item, false);
                    return;
                }
                let show = PodcastShowSummary {
                    id: MediaId::new(SourceKind::ApplePodcasts, &media.external_id),
                    title: media.title,
                    author: None,
                    feed_url: None,
                    webpage_url: media.webpage_url,
                    artwork_url: media.artwork_url,
                    episode_count: None,
                    genres: Vec::new(),
                    explicit: None,
                };
                self.request_apple_podcast_episodes(show, ApplePodcastEpisodeOrigin::Direct);
            }
        }
    }

    /// Reports that Apple Podcasts support is absent in a minimal build.
    #[cfg(not(feature = "apple-podcasts"))]
    fn activate_apple_podcasts_selection(&mut self) {
        self.view.status_line =
            "This build omits the `apple-podcasts` feature; rebuild with it enabled".to_owned();
    }

    /// Replays the selected persisted item or reports why it is unavailable.
    fn activate_history_selection(&mut self) {
        let Some(entry) = self
            .history_entries
            .get(self.view.selected)
            .map(|history| history.entry.clone())
        else {
            "No History item is selected".clone_into(&mut self.view.status_line);
            return;
        };
        let target = match history_replay_target(&entry) {
            Ok(target) => target,
            Err(error) => {
                self.show_error_message("History item is unavailable", error);
                return;
            }
        };
        if let HistoryReplayTarget::Local(path) = &target
            && let Err(error) = validate_history_local_file(path)
        {
            let local_removed = history_local_file_removed(&entry);
            if let Some(history) = self.history_entries.get_mut(self.view.selected) {
                history.local_removed = local_removed;
            }
            if let Some(row) = self.view.rows.get_mut(self.view.selected)
                && self
                    .history_entries
                    .get(self.view.selected)
                    .is_some_and(|history| history.local_removed)
            {
                "Removed".clone_into(&mut row.subtitle);
                self.update_history_detail();
            }
            self.show_error_message("History item is unavailable", error);
            return;
        }
        if entry.media_id.source == SourceKind::ModArchive {
            self.show_error_message(
                "History item is unavailable",
                "Tracker replay needs its prepared local module, which is no longer retained; the History record was kept",
            );
            return;
        }
        if matches!(
            entry.media_id.source,
            SourceKind::ApplePodcasts
                | SourceKind::BbcRadio
                | SourceKind::SoundStream
                | SourceKind::LitRes
                | SourceKind::Jamendo
        ) {
            let HistoryReplayTarget::Remote(url) = target else {
                unreachable!("first-class History sources use remote provider pages");
            };
            self.resolve_history_selection(entry, url);
            return;
        }
        let item = match queue_item_from_history(&entry, &target) {
            Ok(item) => item,
            Err(error) => {
                self.show_error_message("History item is unavailable", error);
                return;
            }
        };
        self.play_queue_item(item, false);
    }

    /// Resolves a stable first-class provider page before replaying History.
    fn resolve_history_selection(&mut self, entry: HistoryEntry, url: url::Url) {
        self.supersede_search_generation();
        let generation = self.search_generation;
        let source = entry.media_id.source.clone();
        self.pending_history_replay = Some(PendingHistoryReplay { generation, entry });
        let request = if source == SourceKind::ApplePodcasts {
            ProviderRequest::ResolveApple { generation, url }
        } else {
            ProviderRequest::ResolveFirstClass {
                generation,
                direct: DirectSourceInput {
                    url,
                    source: source.clone(),
                },
            }
        };
        if !self.send_provider_request(request, "Could not resolve the History item") {
            self.pending_history_replay = None;
            return;
        }
        self.view.status_line = format!(
            "Resolving {} for History playback…",
            direct_source_label(&source)
        );
    }

    /// Consumes a provider response owned by one still-selected History row.
    fn finish_history_replay(
        &mut self,
        generation: u64,
        source: &SourceKind,
        result: &Result<ResolvedDirectMedia, String>,
    ) -> bool {
        let matches_pending = self.pending_history_replay.as_ref().is_some_and(|pending| {
            pending.generation == generation && &pending.entry.media_id.source == source
        });
        if !matches_pending {
            return false;
        }
        let pending = self
            .pending_history_replay
            .take()
            .expect("matching History replay was checked above");
        let still_selected = self.view.screen == Screen::History
            && self
                .history_entries
                .get(self.view.selected)
                .is_some_and(|history| history.entry.id == pending.entry.id);
        if generation != self.search_generation || !still_selected {
            return true;
        }
        let media = match result {
            Ok(media) => media,
            Err(error) => {
                self.show_error_message("History item could not be resolved", error);
                return true;
            }
        };
        let item = match queue_item_from_resolved(media) {
            Ok(item) => item,
            Err(error) => {
                self.show_error_message("History item is unavailable", error);
                return true;
            }
        };
        if item.media.id != pending.entry.media_id {
            self.show_error_message(
                "History item could not be resolved",
                "The provider page resolved to a different media identifier; the History record was kept",
            );
            return true;
        }
        self.play_queue_item(item, false);
        true
    }

    fn activate_local_browser_selection(&mut self) {
        use crate::local_browser::LocalEntryKind;

        let Some(listing) = self.local_listing.as_ref() else {
            self.view.status_line = "No local folder is loaded".to_owned();
            return;
        };
        if listing.parent.is_some() && self.view.selected == 0 {
            self.open_local_parent();
            return;
        }
        let Some(index) = self.local_entry_index() else {
            self.view.status_line = "No local entry is selected".to_owned();
            return;
        };
        let entry = listing.entries[index].clone();
        match entry.kind {
            LocalEntryKind::Directory => self.browse_local_directory(entry.path),
            LocalEntryKind::Image => {
                self.view.status_line =
                    "Image preview selected; only audio and video entries are playable".to_owned();
            }
            LocalEntryKind::Audio | LocalEntryKind::Video | LocalEntryKind::TrackerModule => {
                let item = local_media_item(entry.path);
                match queue_item_from_local(&item) {
                    Ok(item) => self.play_queue_item(item, false),
                    Err(error) => self.show_error_message("Local media could not be played", error),
                }
            }
        }
    }

    /// Opens the parent directory and reselects the child that was just left.
    ///
    /// Keeping this independent from Details navigation prevents Local's
    /// file-manager `Esc` behavior from changing global Backspace or Alt+Left.
    fn open_local_parent(&mut self) {
        let Some(listing) = self.local_listing.as_ref() else {
            self.view.status_line = if self.view.local_browse_pending {
                "Wait for the Local folder to finish loading".to_owned()
            } else {
                "No local folder is loaded".to_owned()
            };
            return;
        };
        let Some(parent) = listing.parent.clone() else {
            self.view.status_line = "Already at the filesystem root".to_owned();
            return;
        };
        let child = listing.path.clone();
        self.browse_local_directory_with_reselection(parent, Some(child));
    }

    /// Starts bounded background preparation for a selected remote module.
    ///
    /// Returns `true` when activation was fully handled without immediately
    /// entering the ordinary queue path.
    #[cfg(feature = "tracker-music")]
    fn prepare_selected_tracker_item(&mut self) -> bool {
        if self.view.selected >= self.tracker_results.len() {
            self.view.status_line = "No tracker item is selected".to_owned();
            return true;
        }
        self.prepare_tracker_item(self.view.selected, None)
    }

    /// Starts one selected or autoplay-owned tracker preparation.
    ///
    /// Returns `true` when the request was handled without entering the
    /// ordinary immediate-play path.
    #[cfg(feature = "tracker-music")]
    fn prepare_tracker_item(
        &mut self,
        index: usize,
        autoplay_origin: Option<AutoplayOrigin>,
    ) -> bool {
        if self.pending_tracker_preparation.is_some() {
            self.view.status_line =
                "One tracker module is already being prepared in the background".to_owned();
            return true;
        }
        let Some(item) = self.tracker_results.get(index) else {
            return true;
        };
        if item.prepared_path.is_some() {
            return false;
        }
        let Some(download_url) = item.download_url.clone() else {
            self.view.status_line = match item.access {
                TrackerAccess::Directory => {
                    "This tracker result is a directory; open its source page to browse it"
                        .to_owned()
                }
                _ => "This tracker result is metadata only; press o to open its source page"
                    .to_owned(),
            };
            return true;
        };
        let item_key = item.webpage_url.to_string();
        let title = item.title.clone();
        let mut request = crate::tracker_media::TrackerMediaRequest::new(download_url);
        request.source_label = Some(item.source.clone());
        request.expected_format.clone_from(&item.expected_format);
        request.display_name = Some(title.clone());
        request.allow_insecure_http =
            item.insecure_transport && self.config.providers.allow_insecure_http;
        if !self.send_provider_request(
            ProviderRequest::PrepareTracker {
                generation: self.search_generation,
                item_key: item_key.clone(),
                request,
            },
            "Could not prepare the tracker module",
        ) {
            return true;
        }
        let autoplay = autoplay_origin.is_some();
        let owner = autoplay_origin.map_or(
            TrackerPreparationOwner::Manual,
            TrackerPreparationOwner::Autoplay,
        );
        self.pending_tracker_preparation = Some(PendingTrackerPreparation {
            generation: self.search_generation,
            item_key,
            owner,
        });
        self.begin_playback_start_activity();
        self.view.status_line = if autoplay {
            format!("Autoplay is downloading and inspecting {title}…")
        } else {
            format!("Downloading and inspecting {title}…")
        };
        true
    }

    fn show_now_playing(&mut self) {
        let Some(item) = self.playback_queue.current().cloned() else {
            self.view.status_line = "Nothing is playing".to_owned();
            return;
        };
        let music_origin = item.media.webpage_url.host_str() == Some("music.youtube.com");

        #[cfg(feature = "radio")]
        if item.media.id.source == SourceKind::Radio
            && station_by_id(&item.media.id.external_id).is_some()
        {
            self.view.screen = Screen::Radio;
            self.radio_filter_query.clear();
            self.view.search_query.clear();
            self.radio_filter_edit_snapshot = None;
            self.radio_selected_station_id = Some(item.media.id.external_id.clone());
            self.populate_radio();
            if let Some(index) = self.view.rows.iter().position(|row| {
                row.media_id.as_ref().is_some_and(|media_id| {
                    media_id.source == SourceKind::Radio
                        && media_id.external_id == item.media.id.external_id
                })
            }) {
                self.view.selected = index;
                self.update_radio_detail();
            }
            self.view.right_panel_mode = RightPanelMode::Details;
            self.view.details_focused = true;
            self.view.status_line = format!("Selected playing station: {}", item.media.title);
            self.refresh_selected_playlist_state();
            return;
        }

        if item.media.id.source == SourceKind::YouTube
            && (self.view.screen == Screen::YouTubeMusic || music_origin)
            && let Some(index) = self.youtube_music_results.iter().position(|candidate| {
                matches!(
                    candidate,
                    SearchItem::Video(video)
                        if video.video_id == item.media.id.external_id
                )
            })
        {
            self.view.screen = Screen::YouTubeMusic;
            self.refresh_youtube_music_rows();
            self.view.selected = index;
            self.view.right_panel_mode = RightPanelMode::Details;
            self.request_selected_details();
            self.view.status_line = format!("Selected playing item: {}", item.media.title);
            self.refresh_selected_playlist_state();
            return;
        }

        if item.media.id.source == SourceKind::YouTube
            && let Some(index) = self.youtube_results.iter().position(|candidate| {
                matches!(
                    candidate,
                    SearchItem::Video(video)
                        if video.video_id == item.media.id.external_id
                )
            })
        {
            self.view.screen = Screen::Search;
            self.refresh_youtube_rows();
            self.view.selected = index;
            self.view.right_panel_mode = RightPanelMode::Details;
            self.request_selected_details();
            self.view.status_line = format!("Selected playing item: {}", item.media.title);
            self.refresh_selected_playlist_state();
            return;
        }

        if item.media.id.source == SourceKind::YouTube
            && let Some(index) = self.youtube_music_results.iter().position(|candidate| {
                matches!(
                    candidate,
                    SearchItem::Video(video)
                        if video.video_id == item.media.id.external_id
                )
            })
        {
            self.view.screen = Screen::YouTubeMusic;
            self.refresh_youtube_music_rows();
            self.view.selected = index;
            self.view.right_panel_mode = RightPanelMode::Details;
            self.request_selected_details();
            self.view.status_line = format!("Selected playing item: {}", item.media.title);
            self.refresh_selected_playlist_state();
            return;
        }

        if item.media.id.source == SourceKind::YouTube {
            let cached_subscription_match =
                self.subscription_video_cache
                    .iter()
                    .find_map(|(channel_id, cached)| {
                        cached
                            .items
                            .iter()
                            .position(|candidate| {
                                matches!(
                                    candidate,
                                    SearchItem::Video(video)
                                        if video.video_id == item.media.id.external_id
                                )
                            })
                            .map(|index| (channel_id.clone(), index))
                    });
            if let Some((channel_id, index)) = cached_subscription_match
                && self.subscription_tree.contains_youtube_channel(&channel_id)
            {
                self.subscription_entries = self.subscription_tree.flattened_subscriptions();
                if let Some(source_index) = self.subscription_entries.iter().position(|entry| {
                    entry.subscription.youtube_channel_id().as_deref() == Some(&channel_id)
                }) {
                    self.view.screen = Screen::Subscriptions;
                    self.rebuild_subscription_source_rows();
                    self.restore_cached_subscription_source_metadata();
                    self.view.subscriptions.selected_source = source_index;
                    self.update_selected_subscription_source();
                    self.active_subscription_channel_id = Some(channel_id);
                    self.view.subscriptions.route = SubscriptionRoute::Items;
                    self.view.subscriptions.focus = SubscriptionPane::Items;
                    self.view.subscriptions.selected_item = index;
                    self.view.subscriptions.description_expanded =
                        self.view.subscriptions.layout == SubscriptionsLayout::Split;
                    self.refresh_subscription_video_rows();
                    self.view.right_panel_mode = RightPanelMode::Details;
                    self.request_selected_details();
                    self.view.status_line = format!("Selected playing item: {}", item.media.title);
                    self.refresh_selected_playlist_state();
                    return;
                }
            }
        }

        if item.media.id.source == SourceKind::Local
            && let Some(listing) = self.local_listing.as_ref()
            && let Some(index) = listing
                .entries
                .iter()
                .position(|entry| entry.path.display().to_string() == item.media.id.external_id)
        {
            self.view.screen = Screen::Local;
            self.view.selected = index.saturating_add(usize::from(listing.parent.is_some()));
            self.view.right_panel_mode = RightPanelMode::Details;
            self.update_local_browser_detail();
            self.view.status_line = format!("Selected playing item: {}", item.media.title);
            self.refresh_selected_playlist_state();
            return;
        }

        if item.media.id.source == SourceKind::ModArchive
            && let Some(index) = self
                .tracker_results
                .iter()
                .position(|candidate| candidate.webpage_url.as_str() == item.media.id.external_id)
        {
            self.view.screen = Screen::TrackerMusic;
            self.view.selected = index;
            self.refresh_tracker_rows();
            self.view.right_panel_mode = RightPanelMode::Details;
            self.view.status_line = format!("Selected playing item: {}", item.media.title);
            self.refresh_selected_playlist_state();
            return;
        }

        self.view.right_panel_mode = RightPanelMode::Details;
        self.view.details_focused = true;
        self.view.details_scroll = 0;
        self.view.selected_detail_link = None;
        self.view.details = Some(detail_from_media_item(&item.media));
        self.view.status_line = format!(
            "Showing queued details for {}; it is not in the current list",
            item.media.title
        );
        self.refresh_selected_playlist_state();
    }

    fn show_selected_channel(&mut self) {
        if self.view.screen == Screen::Subscriptions
            && self.view.subscriptions.focus == SubscriptionPane::Sources
        {
            self.update_selected_subscription_source();
            self.refresh_selected_playlist_state();
            self.view.details_focused = true;
            self.view.right_panel_mode = RightPanelMode::Channel;
            self.view.status_line =
                format!("Channel selected: {}", self.view.subscriptions.source_title);
            self.schedule_visible_channel_details(Instant::now());
            return;
        }
        let Some(selected) = self.selected_youtube_item().cloned() else {
            self.view.status_line = "No channel information is available for this item".to_owned();
            return;
        };
        let (channel_id, name, description, channel_webpage_url) = match selected {
            SearchItem::Video(video) if !video.channel_id.is_empty() => {
                self.previous_detail = self.view.details.take();
                let channel_webpage_url = canonical_youtube_channel_url(&video.channel_id);
                (
                    video.channel_id,
                    video.channel_name,
                    String::new(),
                    channel_webpage_url,
                )
            }
            SearchItem::Video(_) => {
                self.view.status_line =
                    "The video provider has not returned a channel ID yet".to_owned();
                return;
            }
            SearchItem::Channel(channel) => (
                channel.channel_id.clone(),
                channel.name,
                channel.description,
                youtube_channel_webpage_url(&channel.channel_id, channel.webpage_url),
            ),
            SearchItem::PodcastEpisode(_) => {
                self.view.status_line =
                    "Podcast episodes do not have YouTube channel information".to_owned();
                return;
            }
        };
        self.details_generation = self.details_generation.wrapping_add(1);
        self.channel_details_generation = self.channel_details_generation.wrapping_add(1);
        self.scheduled_channel_details = None;
        self.view.details_focused = true;
        self.view.details_scroll = 0;
        self.view.details = Some(DetailView {
            title: name.clone(),
            source: "YouTube channel".to_owned(),
            channel_name: name.clone(),
            channel_id: channel_id.clone(),
            channel_webpage_url,
            channel_subscribed: self.subscription_tree.contains_youtube_channel(&channel_id),
            description: if description.is_empty() {
                format!("YouTube channel ID: {channel_id}")
            } else {
                description
            },
            license: "not applicable".to_owned(),
            wikidata: "not loaded".to_owned(),
            ..DetailView::default()
        });
        self.view.right_panel_mode = RightPanelMode::Channel;
        self.view.status_line = format!("Channel selected: {name}");
        #[cfg(feature = "wikidata")]
        self.request_wikidata(
            crate::providers::wikidata::WikidataExternalKind::YouTubeChannel,
            &channel_id,
        );
        #[cfg(not(feature = "wikidata"))]
        if let Some(details) = self.view.details.as_mut() {
            details.wikidata = "disabled at build time".to_owned();
        }
        self.schedule_visible_channel_details(Instant::now());
    }

    fn toggle_local_subscription(&mut self) {
        let Some(details) = self.view.details.as_ref() else {
            self.view.status_line = "No channel is selected".to_owned();
            return;
        };
        if details.channel_id.is_empty() {
            self.view.status_line =
                "The provider has not returned a subscribable channel ID".to_owned();
            return;
        }
        let channel_id = details.channel_id.clone();
        let channel_name = if details.channel_name.is_empty() {
            details.title.clone()
        } else {
            details.channel_name.clone()
        };
        let channel_webpage_url = details.channel_webpage_url.clone();
        let now_subscribed = !details.channel_subscribed;

        // Reload on each explicit mutation so external OPML edits are retained
        // and a malformed existing file can never be replaced by an empty tree.
        let mut candidate = match subscriptions::load(&self.config) {
            Ok(tree) => tree,
            Err(error) => {
                self.show_error("Cannot change local subscriptions", &error);
                return;
            }
        };
        let persisted_subscribed = candidate.contains_youtube_channel(&channel_id);
        if persisted_subscribed != now_subscribed {
            let changed = if now_subscribed {
                candidate.subscribe_youtube_channel_with_website(
                    channel_name.clone(),
                    &channel_id,
                    channel_webpage_url.as_ref(),
                )
            } else {
                candidate.unsubscribe_youtube_channel(&channel_id)
            };
            if !changed {
                self.show_error_message(
                    "Cannot change local subscriptions",
                    "The requested local subscription change could not be represented in OPML",
                );
                return;
            }
            if let Err(error) = subscriptions::save(&self.config, &candidate) {
                self.show_error("Cannot save local subscriptions", &error);
                return;
            }
        }

        self.subscription_tree = candidate;
        if !now_subscribed {
            self.subscription_generation = self.subscription_generation.wrapping_add(1);
            self.pending_subscription_refresh = None;
            self.subscription_video_cache.remove(&channel_id);
            self.subscription_cache_order
                .retain(|cached| cached != &channel_id);
            if let Err(error) = self
                .store
                .delete_cached_subscription_items(&SourceKind::YouTube, &channel_id)
            {
                self.show_error("Cannot remove cached subscription videos", &error);
            }
        }
        if let Some(details) = self.view.details.as_mut()
            && details.channel_id == channel_id
        {
            details.channel_subscribed = now_subscribed;
        }
        if let Some(details) = self.previous_detail.as_mut()
            && details.channel_id == channel_id
        {
            details.channel_subscribed = now_subscribed;
        }
        if self.view.screen == Screen::Subscriptions {
            self.populate_subscriptions();
        } else {
            self.refresh_youtube_rows();
        }
        self.view.status_line = format!(
            "{} {channel_name} locally",
            if now_subscribed {
                "Subscribed to"
            } else {
                "Unsubscribed from"
            }
        );
    }

    /// Opens the focused RSS/Atom feed editor.
    ///
    /// Feed URLs can contain private query tokens, so the popup's custom
    /// `Debug` implementation redacts both its draft and validation message.
    fn open_rss_subscription_popup(&mut self) {
        if self.view.rss_subscription_popup.is_some() {
            return;
        }
        self.view.help_open = false;
        self.view.text_selection_mode = false;
        self.view.details_text_selection = None;
        self.view.rss_subscription_popup = Some(RssSubscriptionPopupView {
            url: String::new(),
            validation_error: None,
            config_path: self.config.subscriptions_file().display().to_string(),
        });
        self.view.status_line = "Enter an RSS or Atom podcast feed URL".to_owned();
    }

    /// Deletes one Vim-style word from the draft RSS/Atom URL.
    fn delete_rss_subscription_word(&mut self) {
        let Some(popup) = self.view.rss_subscription_popup.as_mut() else {
            return;
        };
        let mut cursor = popup.url.len();
        if delete_previous_editor_word(&mut popup.url, &mut cursor) {
            popup.validation_error = None;
        }
    }

    /// Persists one validated feed without overwriting external OPML edits.
    fn submit_rss_subscription(&mut self) {
        let Some(url) = self
            .view
            .rss_subscription_popup
            .as_ref()
            .map(|popup| popup.url.clone())
        else {
            return;
        };
        let mut candidate = match subscriptions::load(&self.config) {
            Ok(tree) => tree,
            Err(error) => {
                if let Some(popup) = self.view.rss_subscription_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
                return;
            }
        };
        let changed = match candidate.subscribe_rss_feed("", &url) {
            Ok(changed) => changed,
            Err(error) => {
                if let Some(popup) = self.view.rss_subscription_popup.as_mut() {
                    popup.validation_error = Some(error.to_string());
                }
                return;
            }
        };
        if !changed {
            self.view.rss_subscription_popup = None;
            self.subscription_tree = candidate;
            self.populate_subscriptions();
            self.view.status_line = "That RSS feed is already subscribed locally".to_owned();
            return;
        }
        if let Err(error) = subscriptions::save(&self.config, &candidate) {
            if let Some(popup) = self.view.rss_subscription_popup.as_mut() {
                popup.validation_error = Some(error.to_string());
            }
            return;
        }
        self.view.rss_subscription_popup = None;
        self.subscription_tree = candidate;
        self.populate_subscriptions();
        self.view.status_line = "RSS feed subscribed locally".to_owned();
    }

    /// Drops internal Details history when a list or top-level route changes.
    fn clear_detail_navigation_history(&mut self) {
        self.detail_navigation_back.clear();
        self.detail_navigation_forward.clear();
        self.active_description_video = None;
    }

    /// Moves the current Details location into a bounded history stack.
    fn push_detail_navigation_snapshot(
        history: &mut VecDeque<DetailNavigationSnapshot>,
        snapshot: DetailNavigationSnapshot,
    ) {
        if history.len() >= MAX_DETAIL_NAVIGATION_HISTORY {
            history.pop_front();
        }
        history.push_back(snapshot);
    }

    /// Takes the current location without cloning its potentially large text.
    fn take_detail_navigation_snapshot(&mut self) -> DetailNavigationSnapshot {
        DetailNavigationSnapshot {
            screen: self.view.screen,
            selected: self.view.selected,
            subscription_route: self.view.subscriptions.route,
            subscription_focus: self.view.subscriptions.focus,
            subscription_selected_source: self.view.subscriptions.selected_source,
            subscription_selected_item: self.view.subscriptions.selected_item,
            subscription_description_expanded: self.view.subscriptions.description_expanded,
            details: self.view.details.take(),
            previous_detail: self.previous_detail.take(),
            details_scroll: self.view.details_scroll,
            details_focused: self.view.details_focused,
            text_selection_mode: self.view.text_selection_mode,
            details_text_selection: self.view.details_text_selection.take(),
            selected_detail_link: self.view.selected_detail_link,
            right_panel_mode: self.view.right_panel_mode,
            active_description_video: self.active_description_video.take(),
        }
    }

    /// Restores one move-only Details location and invalidates stale responses.
    fn restore_detail_navigation_snapshot(&mut self, snapshot: DetailNavigationSnapshot) {
        self.details_generation = self.details_generation.wrapping_add(1);
        #[cfg(feature = "wikidata")]
        self.invalidate_wikidata_lookup();
        self.view.screen = snapshot.screen;
        self.view.selected = snapshot.selected;
        self.view.subscriptions.route = snapshot.subscription_route;
        self.view.subscriptions.focus = snapshot.subscription_focus;
        self.view.subscriptions.selected_source = snapshot.subscription_selected_source;
        self.view.subscriptions.selected_item = snapshot.subscription_selected_item;
        self.view.subscriptions.description_expanded = snapshot.subscription_description_expanded;
        self.view.details = snapshot.details;
        self.previous_detail = snapshot.previous_detail;
        self.view.details_scroll = snapshot.details_scroll;
        self.view.details_focused = snapshot.details_focused;
        self.view.text_selection_mode = snapshot.text_selection_mode;
        self.view.details_text_selection = snapshot.details_text_selection;
        self.view.selected_detail_link = snapshot.selected_detail_link;
        self.view.right_panel_mode = snapshot.right_panel_mode;
        self.active_description_video = snapshot.active_description_video;

        let pending_video_id = self.active_description_video.as_ref().and_then(|linked| {
            self.view
                .details
                .as_ref()
                .is_some_and(|details| details.title == LINKED_VIDEO_LOADING_TITLE)
                .then(|| linked.video_id.clone())
        });
        if let Some(video_id) = pending_video_id
            && self.youtube_provider_available
        {
            if let Some(details) = self.cached_youtube_video_details(&video_id) {
                self.handle_provider_response(ProviderResponse::Details {
                    generation: self.details_generation,
                    result: Ok(details),
                });
            } else {
                self.send_provider_request(
                    ProviderRequest::Details {
                        generation: self.details_generation,
                        video_id: video_id.clone(),
                    },
                    "Could not resume loading linked YouTube video",
                );
            }
        }
        #[cfg(feature = "wikidata")]
        if let Some(video_id) = self
            .active_description_video
            .as_ref()
            .map(|linked| linked.video_id.clone())
        {
            self.request_wikidata(
                crate::providers::wikidata::WikidataExternalKind::YouTubeVideo,
                &video_id,
            );
        }
    }

    /// Opens a description-linked `YouTube` video in the existing Details pane.
    fn activate_description_video(&mut self, video_id: String, start_seconds: Option<u64>) {
        if let Err(error) = validate_youtube_video_id(&video_id) {
            self.show_error_message("Cannot open description video", error.to_string());
            return;
        }
        if !self.youtube_provider_available {
            self.open_youtube_setup();
            return;
        }

        let generation = self.details_generation.wrapping_add(1);
        let cached_details = self.cached_youtube_video_details(&video_id);
        if cached_details.is_none()
            && !self.send_provider_request(
                ProviderRequest::Details {
                    generation,
                    video_id: video_id.clone(),
                },
                "Could not load linked YouTube video",
            )
        {
            return;
        }

        let current = self.take_detail_navigation_snapshot();
        Self::push_detail_navigation_snapshot(&mut self.detail_navigation_back, current);
        self.detail_navigation_forward.clear();
        self.details_generation = generation;
        self.previous_detail = None;
        self.active_description_video = Some(ActiveDescriptionVideo {
            video_id: video_id.clone(),
            start_seconds,
        });
        self.view.details_focused = true;
        self.view.details_scroll = 0;
        self.view.text_selection_mode = false;
        self.view.details_text_selection = None;
        self.view.selected_detail_link = None;
        self.view.right_panel_mode = RightPanelMode::Details;
        self.view.details = Some(DetailView {
            media_id: Some(MediaId::new(SourceKind::YouTube, &video_id)),
            title: LINKED_VIDEO_LOADING_TITLE.to_owned(),
            source: "YouTube".to_owned(),
            description: LINKED_VIDEO_LOADING_DESCRIPTION.to_owned(),
            wikidata: "not loaded".to_owned(),
            ..DetailView::default()
        });
        self.view.status_line = start_seconds.map_or_else(
            || "Loading linked YouTube video…".to_owned(),
            |seconds| {
                format!(
                    "Loading linked YouTube video at {}…",
                    format_seconds(seconds)
                )
            },
        );
        if let Some(details) = cached_details {
            self.handle_provider_response(ProviderResponse::Details {
                generation,
                result: Ok(details),
            });
        }
        #[cfg(feature = "wikidata")]
        self.request_wikidata(
            crate::providers::wikidata::WikidataExternalKind::YouTubeVideo,
            &video_id,
        );
    }

    /// Restores a previous or later internal Details location.
    fn move_detail_navigation(&mut self, forward: bool) -> bool {
        let destination = if forward {
            self.detail_navigation_forward.pop_back()
        } else {
            self.detail_navigation_back.pop_back()
        };
        let Some(destination) = destination else {
            return false;
        };
        let current = self.take_detail_navigation_snapshot();
        if forward {
            Self::push_detail_navigation_snapshot(&mut self.detail_navigation_back, current);
        } else {
            Self::push_detail_navigation_snapshot(&mut self.detail_navigation_forward, current);
        }
        self.restore_detail_navigation_snapshot(destination);
        self.refresh_selected_playlist_state();
        self.view.status_line = if forward {
            "Moved forward in Details".to_owned()
        } else {
            "Moved back in Details".to_owned()
        };
        true
    }

    fn go_back(&mut self) {
        if self.view.screen == Screen::Playlists
            && matches!(self.playlists_route, PlaylistsRoute::Entries { .. })
        {
            self.playlists_route = PlaylistsRoute::Index;
            self.active_playlist = None;
            self.view.selected = self
                .playlist_selected
                .min(self.playlist_summaries.len().saturating_sub(1));
            self.populate_playlist_index();
            self.refresh_selected_playlist_state();
            self.view.status_line = "Returned to playlists".to_owned();
            return;
        }
        if self.move_detail_navigation(false) {
            return;
        }
        if self.view.screen == Screen::ApplePodcasts
            && self.apple_podcasts_route == ApplePodcastsRoute::Episodes
        {
            match self.apple_podcast_episode_origin {
                ApplePodcastEpisodeOrigin::Shows(source_row) => {
                    self.apple_podcasts_route = ApplePodcastsRoute::Shows;
                    self.apple_podcasts_selected =
                        source_row.min(self.apple_podcasts_results.len().saturating_sub(1));
                    self.view.selected = self.apple_podcasts_selected;
                    self.refresh_apple_podcasts_rows();
                    self.update_apple_podcasts_detail();
                    self.view.status_line = "Returned to Apple Podcasts shows".to_owned();
                }
                ApplePodcastEpisodeOrigin::Direct => {
                    self.apple_podcasts_route = ApplePodcastsRoute::Direct;
                    self.view.selected = 0;
                    self.refresh_apple_direct_view();
                    self.view.status_line = "Returned to the direct Apple Podcasts page".to_owned();
                }
            }
            self.refresh_selected_playlist_state();
            return;
        }
        if self.view.screen == Screen::ApplePodcasts
            && self.apple_podcasts_route == ApplePodcastsRoute::Direct
            && !self.apple_podcasts_results.is_empty()
        {
            self.apple_podcasts_route = ApplePodcastsRoute::Shows;
            self.view.selected = self
                .apple_podcasts_selected
                .min(self.apple_podcasts_results.len().saturating_sub(1));
            self.refresh_apple_podcasts_rows();
            self.update_apple_podcasts_detail();
            self.view.status_line = "Returned to Apple Podcasts shows".to_owned();
            self.refresh_selected_playlist_state();
            return;
        }
        if self.view.screen == Screen::Subscriptions {
            if self.view.subscriptions.description_expanded {
                self.view.subscriptions.description_expanded = false;
                self.view.subscriptions.focus = SubscriptionPane::Items;
                self.view.details_focused = false;
                self.view.status_line = format!(
                    "Returned to subscription {}",
                    subscription_item_kind_label(self.view.subscriptions.source_kind)
                );
                self.refresh_selected_playlist_state();
                return;
            }
            if self.view.subscriptions.layout == SubscriptionsLayout::DrillDown
                && self.view.subscriptions.route == SubscriptionRoute::Items
            {
                self.pending_subscription_refresh = None;
                self.view.subscriptions.route = SubscriptionRoute::Sources;
                self.view.subscriptions.focus = SubscriptionPane::Sources;
                self.update_selected_subscription_source();
                self.view.status_line = "Returned to subscription sources".to_owned();
                self.refresh_selected_playlist_state();
                return;
            }
            if self.view.subscriptions.layout == SubscriptionsLayout::Split
                && self.view.subscriptions.focus == SubscriptionPane::Items
            {
                self.pending_subscription_refresh = None;
                self.view.subscriptions.focus = SubscriptionPane::Sources;
                self.update_selected_subscription_source();
                self.view.status_line = "Subscription source list focused".to_owned();
                self.refresh_selected_playlist_state();
                return;
            }
        }
        if let Some(media_id) = self.current_media.clone()
            && let Some((_, position)) = self
                .seek_back
                .back()
                .filter(|(candidate, _)| candidate == &media_id)
                .cloned()
        {
            self.seek_back.pop_back();
            self.player_command(PlayerCommand::SeekAbsolute(position));
            self.view.status_line = format!("Returned to {}", format_seconds(position.as_secs()));
            return;
        }
        if let Some(previous) = self.previous_detail.take() {
            self.view.details = Some(previous);
        }
        self.view.details_scroll = 0;
        self.view.right_panel_mode = RightPanelMode::Details;
        if let Some(selected) = self.selected_youtube_item().cloned() {
            self.request_selected_wikidata(&selected);
        }
    }

    fn go_forward(&mut self) {
        if !self.move_detail_navigation(true) {
            self.view.status_line = "No later Details page".to_owned();
        }
    }

    /// Seeks by seconds while constraining live Radio to mpv's cached window.
    fn seek_relative(&mut self, seconds: i64) {
        if !self.current_media_is_radio() {
            self.player_command(PlayerCommand::SeekRelative(seconds));
            return;
        }
        let Some(range) = self.live_radio_seek_range() else {
            self.view.status_line = "No rewind buffer is available for this live radio".to_owned();
            return;
        };
        let current = range
            .start
            .saturating_add(self.view.playback.position)
            .clamp(range.start, range.end);
        let distance = Duration::from_secs(seconds.unsigned_abs());
        let target = if seconds.is_negative() {
            current.saturating_sub(distance)
        } else {
            current.saturating_add(distance)
        }
        .clamp(range.start, range.end);
        self.player_command(PlayerCommand::SeekAbsolute(
            target.min(live_seek_upper_bound(range)),
        ));
    }

    /// Seeks by bar percentage while preserving a live Radio cache origin.
    fn seek_percent(&mut self, percent: f64) {
        if !self.current_media_is_radio() {
            self.player_command(PlayerCommand::SeekPercent(percent));
            return;
        }
        let Some(range) = self.live_radio_seek_range() else {
            self.view.status_line = "No rewind buffer is available for this live radio".to_owned();
            return;
        };
        if !percent.is_finite() {
            self.view.status_line = "The live-radio seek percentage is invalid".to_owned();
            return;
        }
        let offset = range
            .end
            .saturating_sub(range.start)
            .mul_f64(percent.clamp(0.0, 100.0) / 100.0);
        self.player_command(PlayerCommand::SeekAbsolute(
            range
                .start
                .saturating_add(offset)
                .min(live_seek_upper_bound(range)),
        ));
    }

    /// Returns whether the active queue item is a curated Radio stream.
    fn current_media_is_radio(&self) -> bool {
        self.current_media
            .as_ref()
            .is_some_and(|media| media.source == SourceKind::Radio)
    }

    /// Returns the backend-time interval backing the live Radio seek bar.
    fn live_radio_seek_range(&self) -> Option<BufferedRange> {
        self.current_media_is_radio()
            .then_some(self.view.playback.live_seekable_range)
            .flatten()
    }

    /// Seeks the active item, or starts the selected item, at a description timecode.
    fn activate_timecode(&mut self, media_id: MediaId, seconds: u64) {
        if self.current_media.as_ref() == Some(&media_id) && self.player.is_some() {
            if self.seek_is_unavailable_for_live_radio() {
                return;
            }
            if self
                .view
                .playback
                .duration
                .is_some_and(|duration| seconds >= duration.as_secs())
            {
                self.view.status_line = "That timecode is outside the media duration".to_owned();
                return;
            }
            let previous = self.view.playback.position;
            if previous != Duration::from_secs(seconds) {
                const MAX_SEEK_BACK_ENTRIES: usize = 32;
                if self.seek_back.len() == MAX_SEEK_BACK_ENTRIES {
                    self.seek_back.pop_front();
                }
                self.seek_back.push_back((media_id, previous));
            }
            self.player_command(PlayerCommand::SeekAbsolute(Duration::from_secs(seconds)));
            self.view.status_line = format!("Seeking to {}", format_seconds(seconds));
            return;
        }

        let selected_item = (self
            .view
            .details
            .as_ref()
            .and_then(|details| details.media_id.as_ref())
            == Some(&media_id))
        .then(|| self.selected_queue_item().ok())
        .flatten()
        .filter(|item| item.media.id == media_id);
        if let Some(item) = selected_item {
            if item
                .media
                .duration_seconds
                .is_some_and(|duration| seconds >= duration)
            {
                self.view.status_line = "That timecode is outside the media duration".to_owned();
                return;
            }
            if self.view.screen == Screen::YouTubeMusic {
                self.youtube_music_start_override = Some(seconds);
            } else {
                self.selected_start_override = Some(seconds);
            }
            self.activate_selection();
        } else {
            self.view.status_line =
                "That timecode does not belong to the selected or playing item".to_owned();
        }
    }

    /// Navigates parsed description chapters without relying on backend metadata.
    fn change_chapter(&mut self, delta: i32) {
        if self.current_media_is_radio() {
            self.view.status_line = "Chapters are unavailable for live radio".to_owned();
            return;
        }
        if self.seek_is_unavailable_for_live_radio() {
            return;
        }
        if self.view.playback_chapters.is_empty() {
            self.player_command(PlayerCommand::ChangeChapter(delta));
            return;
        }
        let navigable = self
            .view
            .playback_chapters
            .iter()
            .enumerate()
            .filter(|(_, chapter)| {
                !self.config.playback.skip_advertisement_chapters
                    || !is_advertisement_chapter_title(&chapter.title)
            })
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        if navigable.is_empty() {
            return;
        }
        let current = navigable
            .partition_point(|index| {
                self.view.playback_chapters[*index].start_seconds
                    <= self.view.playback.position.as_secs()
            })
            .saturating_sub(1);
        let destination_position = if delta.is_negative() {
            current.saturating_sub(delta.unsigned_abs() as usize)
        } else {
            current
                .saturating_add(delta as usize)
                .min(navigable.len().saturating_sub(1))
        };
        let Some(chapter) = navigable
            .get(destination_position)
            .and_then(|index| self.view.playback_chapters.get(*index))
        else {
            return;
        };
        let Some(media_id) = self.current_media.clone() else {
            self.view.status_line = "Nothing is playing".to_owned();
            return;
        };
        self.activate_timecode(media_id, chapter.start_seconds);
    }

    /// Rejects a Radio seek until mpv reports an exact cached interval.
    fn seek_is_unavailable_for_live_radio(&mut self) -> bool {
        let unavailable = self.current_media_is_radio() && self.live_radio_seek_range().is_none();
        if unavailable {
            self.view.status_line = "No rewind buffer is available for this live radio".to_owned();
        }
        unavailable
    }

    /// Identifies the same-source cursor represented by a queue item.
    fn autoplay_origin_for_media(&self, media_id: &MediaId) -> Option<AutoplayOrigin> {
        let video_at = |items: &[SearchItem], index: usize| {
            items.get(index).is_some_and(|item| {
                matches!(
                    item,
                    SearchItem::Video(video)
                        if media_id.source == SourceKind::YouTube
                            && video.video_id == media_id.external_id
                )
            })
        };

        match self.view.screen {
            Screen::Search if video_at(&self.youtube_results, self.view.selected) => {
                return Some(AutoplayOrigin::YouTube {
                    generation: self.search_generation,
                    index: self.view.selected,
                });
            }
            Screen::YouTubeMusic if video_at(&self.youtube_music_results, self.view.selected) => {
                return Some(AutoplayOrigin::YouTubeMusic {
                    generation: self.search_generation,
                    index: self.view.selected,
                });
            }
            Screen::Subscriptions => {
                if let Some(channel_id) = self.active_subscription_channel_id.as_ref()
                    && let Some(items) = self.subscription_video_cache.get(channel_id)
                    && video_at(&items.items, self.view.subscriptions.selected_item)
                {
                    return Some(AutoplayOrigin::Subscription {
                        channel_id: channel_id.clone(),
                        index: self.view.subscriptions.selected_item,
                    });
                }
            }
            Screen::Local => {
                if let Some(listing) = self.local_listing.as_ref() {
                    let entries = listing
                        .entries
                        .iter()
                        .filter(|entry| entry.kind.is_playable())
                        .map(|entry| entry.path.clone())
                        .collect::<Vec<_>>();
                    if let Some(index) = entries
                        .iter()
                        .position(|path| local_path_matches_media_id(path, media_id))
                    {
                        return Some(AutoplayOrigin::LocalBrowser {
                            directory: listing.path.clone(),
                            entries: entries.into(),
                            index,
                        });
                    }
                }
            }
            Screen::TrackerMusic => {
                if self
                    .tracker_results
                    .get(self.view.selected)
                    .is_some_and(|item| tracker_item_matches_media_id(item, media_id))
                {
                    return Some(AutoplayOrigin::Tracker {
                        generation: self.search_generation,
                        index: self.view.selected,
                    });
                }
            }
            _ => {}
        }

        if media_id.source == SourceKind::YouTube {
            if let Some(index) = self.youtube_results.iter().position(|item| {
                matches!(item, SearchItem::Video(video) if video.video_id == media_id.external_id)
            }) {
                return Some(AutoplayOrigin::YouTube {
                    generation: self.search_generation,
                    index,
                });
            }
            if let Some(index) = self.youtube_music_results.iter().position(|item| {
                matches!(item, SearchItem::Video(video) if video.video_id == media_id.external_id)
            }) {
                return Some(AutoplayOrigin::YouTubeMusic {
                    generation: self.search_generation,
                    index,
                });
            }
            for channel_id in self.subscription_cache_order.iter().rev() {
                if let Some(items) = self.subscription_video_cache.get(channel_id)
                    && let Some(index) = items.items.iter().position(|item| {
                        matches!(
                            item,
                            SearchItem::Video(video) if video.video_id == media_id.external_id
                        )
                    })
                {
                    return Some(AutoplayOrigin::Subscription {
                        channel_id: channel_id.clone(),
                        index,
                    });
                }
            }
        }
        if media_id.source == SourceKind::Local {
            if let Some(index) = self
                .local_results
                .iter()
                .position(|item| local_path_matches_media_id(&item.path, media_id))
            {
                return Some(AutoplayOrigin::LocalScan {
                    generation: self.search_generation,
                    index,
                });
            }
        }
        if media_id.source == SourceKind::ModArchive
            && let Some(index) = self
                .tracker_results
                .iter()
                .position(|item| tracker_item_matches_media_id(item, media_id))
        {
            return Some(AutoplayOrigin::Tracker {
                generation: self.search_generation,
                index,
            });
        }
        None
    }

    /// Chooses the next playable entry without changing queue or player state.
    fn next_autoplay_step(&self, origin: &AutoplayOrigin) -> AutoplayStep {
        match origin {
            AutoplayOrigin::YouTube { generation, index } => {
                if *generation != self.search_generation {
                    return AutoplayStep::SourceChanged;
                }
                self.youtube_results
                    .iter()
                    .enumerate()
                    .skip(index.saturating_add(1))
                    .find_map(|(index, item)| match item {
                        SearchItem::Video(video) if video_is_autoplay_playable(video) => {
                            Some(AutoplayStep::Play {
                                item: Box::new(queue_item_from_video(video, None)),
                                origin: AutoplayOrigin::YouTube {
                                    generation: *generation,
                                    index,
                                },
                            })
                        }
                        _ => None,
                    })
                    .unwrap_or(AutoplayStep::Exhausted)
            }
            AutoplayOrigin::YouTubeMusic { generation, index } => {
                if *generation != self.search_generation {
                    return AutoplayStep::SourceChanged;
                }
                self.youtube_music_results
                    .iter()
                    .enumerate()
                    .skip(index.saturating_add(1))
                    .find_map(|(index, item)| match item {
                        SearchItem::Video(video) if video_is_autoplay_playable(video) => {
                            Some(AutoplayStep::Play {
                                item: Box::new(queue_item_from_video(video, None)),
                                origin: AutoplayOrigin::YouTubeMusic {
                                    generation: *generation,
                                    index,
                                },
                            })
                        }
                        _ => None,
                    })
                    .unwrap_or(AutoplayStep::Exhausted)
            }
            AutoplayOrigin::Subscription { channel_id, index } => self
                .subscription_video_cache
                .get(channel_id)
                .and_then(|cached| {
                    cached
                        .items
                        .iter()
                        .enumerate()
                        .skip(index.saturating_add(1))
                        .find_map(|(index, item)| match item {
                            SearchItem::Video(video) if video_is_autoplay_playable(video) => {
                                Some(AutoplayStep::Play {
                                    item: Box::new(queue_item_from_video(video, None)),
                                    origin: AutoplayOrigin::Subscription {
                                        channel_id: channel_id.clone(),
                                        index,
                                    },
                                })
                            }
                            _ => None,
                        })
                })
                .unwrap_or(AutoplayStep::Exhausted),
            AutoplayOrigin::LocalBrowser {
                directory,
                entries,
                index,
            } => entries
                .iter()
                .enumerate()
                .skip(index.saturating_add(1))
                .find_map(|(index, path)| {
                    queue_item_from_local(&local_media_item(path.clone()))
                        .ok()
                        .map(|item| AutoplayStep::Play {
                            item: Box::new(item),
                            origin: AutoplayOrigin::LocalBrowser {
                                directory: directory.clone(),
                                entries: Arc::clone(entries),
                                index,
                            },
                        })
                })
                .unwrap_or(AutoplayStep::Exhausted),
            AutoplayOrigin::LocalScan { generation, index } => {
                if *generation != self.search_generation {
                    return AutoplayStep::SourceChanged;
                }
                self.local_results
                    .iter()
                    .enumerate()
                    .skip(index.saturating_add(1))
                    .find_map(|(index, item)| {
                        queue_item_from_local(item)
                            .ok()
                            .map(|item| AutoplayStep::Play {
                                item: Box::new(item),
                                origin: AutoplayOrigin::LocalScan {
                                    generation: *generation,
                                    index,
                                },
                            })
                    })
                    .unwrap_or(AutoplayStep::Exhausted)
            }
            AutoplayOrigin::Tracker { generation, index } => {
                if *generation != self.search_generation {
                    return AutoplayStep::SourceChanged;
                }
                for (index, item) in self
                    .tracker_results
                    .iter()
                    .enumerate()
                    .skip(index.saturating_add(1))
                {
                    if let Ok(item) = queue_item_from_tracker(item) {
                        return AutoplayStep::Play {
                            item: Box::new(item),
                            origin: AutoplayOrigin::Tracker {
                                generation: *generation,
                                index,
                            },
                        };
                    }
                    #[cfg(feature = "tracker-music")]
                    if item.download_url.is_some()
                        && matches!(
                            item.access,
                            TrackerAccess::DirectModule | TrackerAccess::ArchiveNeedsInspection
                        )
                    {
                        return AutoplayStep::PrepareTracker {
                            index,
                            origin: AutoplayOrigin::Tracker {
                                generation: *generation,
                                index,
                            },
                        };
                    }
                }
                AutoplayStep::Exhausted
            }
        }
    }

    /// Continues an exhausted explicit queue from one same-source position.
    fn continue_autoplay(&mut self, origin: AutoplayOrigin) {
        match self.next_autoplay_step(&origin) {
            AutoplayStep::Play { item, origin } => {
                self.play_queue_item_with_origin(*item, false, Some(origin));
            }
            #[cfg(feature = "tracker-music")]
            AutoplayStep::PrepareTracker { index, origin } => {
                self.prepare_tracker_item(index, Some(origin));
            }
            AutoplayStep::SourceChanged => {
                self.view.status_line =
                    "Autoplay stopped because the source list changed".to_owned();
            }
            AutoplayStep::Exhausted => {
                self.view.status_line = "Autoplay reached the end of this list".to_owned();
            }
        }
    }

    fn play_queue_item(&mut self, item: QueueItem, queue_cursor_already_positioned: bool) {
        let origin = self
            .config
            .playback
            .autoplay
            .then(|| self.autoplay_origin_for_media(&item.media.id))
            .flatten();
        self.play_queue_item_with_origin(item, queue_cursor_already_positioned, origin);
    }

    /// Starts one queue item while retaining its same-source continuation
    /// position only after the playback backend accepts the input.
    fn play_queue_item_with_origin(
        &mut self,
        item: QueueItem,
        queue_cursor_already_positioned: bool,
        origin: Option<AutoplayOrigin>,
    ) {
        self.play_queue_item_with_origin_and_input(
            item,
            queue_cursor_already_positioned,
            origin,
            None,
        );
    }

    /// Starts one item with an optional action-resolved, RAM-only input.
    ///
    /// The queue and History retain `item.playback_location`, which must remain
    /// canonical and credential-free. The override is moved directly into the
    /// backend call and is never serialized.
    fn play_queue_item_with_origin_and_input(
        &mut self,
        item: QueueItem,
        queue_cursor_already_positioned: bool,
        origin: Option<AutoplayOrigin>,
        resolved_input: Option<PlaybackInput>,
    ) {
        #[cfg(feature = "radio")]
        if self.active_radio_recording.is_some()
            && self.current_media.as_ref() != Some(&item.media.id)
        {
            // mpv owns only one stream-record target. Finish the current
            // capture before replacing the stream, rather than letting a
            // backend transition silently leave a partial public file.
            self.stop_active_radio_recording();
        }
        if !queue_cursor_already_positioned {
            self.queued_autoplay_resume_origin = None;
            #[cfg(feature = "tracker-music")]
            self.cancel_pending_tracker_autoplay();
        }
        #[cfg(feature = "bbc-radio")]
        if resolved_input.is_none()
            && item.media.id.source == SourceKind::Radio
            && station_by_id(&item.media.id.external_id)
                .is_some_and(|station| station.stream_kind == RadioStreamKind::BbcSounds)
        {
            self.request_bbc_live(item, queue_cursor_already_positioned, origin);
            return;
        }
        #[cfg(feature = "bbc-radio")]
        if self.pending_bbc_playback.take().is_some() {
            self.bbc_playback_generation = self.bbc_playback_generation.wrapping_add(1);
            self.clear_playback_start_activity();
        }
        if self.player.is_none() {
            let Some(factory) = self.playback_factory.as_mut() else {
                self.view.status_line = "No playback backend was compiled or configured".to_owned();
                return;
            };
            match factory() {
                Ok(mut player) => {
                    if !self.config.playback.audiophile.enabled {
                        let initial_speed = f64::from(self.config.playback.speed_percent) / 100.0;
                        let initialized = player
                            .command(PlayerCommand::SetVolume(
                                self.config.playback.volume_percent,
                            ))
                            .and_then(|()| player.command(PlayerCommand::SetSpeed(initial_speed)));
                        if let Err(error) = initialized {
                            let _ = player.shutdown();
                            self.show_error("Cannot configure playback", &error);
                            return;
                        }
                    }
                    self.player = Some(player);
                }
                Err(error) => {
                    self.show_error("Cannot start playback", &error);
                    return;
                }
            }
        }
        let media_id = item.media.id.clone();
        let live_stream = item.media.kind == MediaKind::LiveStream;
        let media_changed = self.current_media.as_ref() != Some(&media_id);
        if media_changed {
            self.skipped_advertisement_chapter = None;
            if self.playback_phase == PlaybackPhase::Playing {
                self.persist_position();
                self.last_position_save = Instant::now();
            }
        }
        let chapters = item.media.chapters.clone();
        let stored_progress = if live_stream {
            None
        } else {
            match self.store.progress(&media_id) {
                Ok(progress) => progress,
                Err(error) => {
                    self.show_error("Could not restore the playback position", &error);
                    None
                }
            }
        };
        let start_at = if live_stream {
            0
        } else if let Some(start_at) = item.start_at_seconds {
            start_at
        } else {
            stored_progress.as_ref().map_or(0, |progress| {
                progress.resume_position_with_rewind(self.config.playback.resume_rewind_seconds)
            })
        };
        let mut canonical_input = PlaybackInput::new(item.playback_location.clone());
        canonical_input.start_at = Duration::from_secs(start_at);
        canonical_input.title = Some(item.media.title.clone());
        #[cfg(feature = "yt-dlp")]
        let had_resolved_input = resolved_input.is_some();
        let mut input = resolved_input.unwrap_or_else(|| canonical_input.clone());
        input.start_at = Duration::from_secs(start_at);
        input.title = Some(item.media.title.clone());
        let mut load_kind = if media_id.source == SourceKind::YouTube {
            PlaybackLoadKind::YouTubeCanonical
        } else {
            PlaybackLoadKind::Regular
        };
        #[cfg(feature = "yt-dlp")]
        if !had_resolved_input
            && media_id.source == SourceKind::YouTube
            && let Some(prewarmed) = self.take_ready_youtube_prewarm(&media_id)
        {
            let (media_url, headers) = prewarmed.into_playback_parts();
            input.location = media_url.into();
            input.http_headers = headers;
            input.bypass_ytdl = true;
            load_kind = PlaybackLoadKind::YouTubeDirect;
        }
        let had_active_media = self.current_media.is_some();
        let first_result = self
            .player
            .as_mut()
            .expect("player was initialized above")
            .play(&input);
        let play_result = if first_result.is_err() && load_kind == PlaybackLoadKind::YouTubeDirect {
            // A speculative signed URL is an optimization only. Discard its
            // error without surfacing potentially sensitive URL context and
            // immediately use the canonical extractor-backed route.
            load_kind = PlaybackLoadKind::YouTubeCanonical;
            self.player
                .as_mut()
                .expect("player was initialized above")
                .play(&canonical_input)
        } else {
            first_result
        };
        match play_result {
            Ok(()) => {
                if media_changed {
                    self.seek_back.clear();
                }
                if !queue_cursor_already_positioned {
                    self.playback_queue
                        .begin_now(item.clone(), had_active_media);
                }
                self.current_media = Some(media_id.clone());
                if live_stream {
                    self.view.repeating = false;
                    self.playback_queue.repeat_one = false;
                }
                #[cfg(feature = "radio")]
                self.refresh_playing_radio_metadata(None);
                #[cfg(not(feature = "radio"))]
                {
                    self.view.radio_now_playing = None;
                }
                let now = unix_time();
                self.current_playback_progress = (!live_stream).then(|| {
                    let mut current_progress = stored_progress.unwrap_or_else(|| {
                        PlaybackProgress::new(media_id.clone(), item.media.duration_seconds, now)
                    });
                    current_progress.duration_seconds = item
                        .media
                        .duration_seconds
                        .or(current_progress.duration_seconds);
                    current_progress.record_position(start_at, now);
                    current_progress
                });
                self.current_autoplay_origin = origin;
                self.playback_phase = PlaybackPhase::Loading;
                self.playback_load_kind = load_kind;
                self.begin_playback_start_activity();
                self.ignore_replaced_stop = had_active_media;
                self.last_tick = Instant::now();
                self.pending_history = Some(HistoryEntry {
                    id: 0,
                    media_id,
                    title: item.media.title.clone(),
                    replay_locator: history_replay_locator(&item),
                    started_at: now,
                    last_played_at: now,
                    position_seconds: start_at,
                    duration_seconds: item.media.duration_seconds,
                    finished: false,
                });
                self.view.playback = PlaybackStatus {
                    idle: false,
                    live: live_stream,
                    position: Duration::from_secs(start_at),
                    duration: item.media.duration_seconds.map(Duration::from_secs),
                    paused: true,
                    volume: self.config.playback.volume_percent,
                    speed: f64::from(self.config.playback.speed_percent) / 100.0,
                    buffering: true,
                    title: Some(item.media.title.clone()),
                    ..PlaybackStatus::default()
                };
                self.view.playback_chapters = chapters;
                self.view.status_line = format!("Loading {}…", item.media.title);
                if !live_stream
                    && self.playback_queue.repeat_one
                    && let Some(player) = self.player.as_mut()
                    && let Err(error) = player.command(PlayerCommand::SetRepeat(true))
                {
                    self.show_error("Loading, but repeat mode could not be enabled", &error);
                }
            }
            Err(error) => {
                self.playback_load_kind = PlaybackLoadKind::Regular;
                self.show_error("Playback failed", &error);
            }
        }
    }

    fn player_command(&mut self, command: PlayerCommand) {
        let Some(player) = self.player.as_mut() else {
            self.view.status_line = "Nothing is playing".to_owned();
            return;
        };
        if let Err(error) = player.command(command) {
            if matches!(error, PlaybackError::DirectProfileRestriction(_)) {
                self.view.status_line = error.to_string();
            } else {
                self.show_error("Playback command failed", &error);
            }
        }
    }

    /// Applies source-level playback semantics that a backend cannot infer reliably.
    ///
    /// Some live transports expose large synthetic `time-pos` and `duration`
    /// values. For a [`MediaKind::LiveStream`], only mpv's exact cached seek
    /// range becomes a rolling user timeline; the transport duration itself
    /// remains hidden.
    fn normalize_playback_status(&self, status: &mut PlaybackStatus) {
        let live_stream = self.current_media.as_ref().is_some_and(|media_id| {
            self.playback_queue.current().is_some_and(|item| {
                &item.media.id == media_id && item.media.kind == MediaKind::LiveStream
            })
        });
        status.live = live_stream;
        status.live_seekable_range = None;
        if live_stream {
            status.duration = None;
            status.chapter = None;
            let backend_position = status.position;
            let live_range = live_seekable_range(backend_position, &status.buffered_ranges);
            status.buffered_ranges.clear();
            if let Some(range) = live_range {
                let duration = range.end.saturating_sub(range.start);
                status.position = backend_position
                    .clamp(range.start, range.end)
                    .saturating_sub(range.start);
                status.duration = Some(duration);
                status.live_seekable_range = Some(range);
                status.buffered_ranges.push(BufferedRange {
                    start: Duration::ZERO,
                    end: duration,
                });
            } else {
                status.position = Duration::ZERO;
            }
        }
    }

    fn update_player(&mut self) {
        let now = Instant::now();
        let elapsed = now.saturating_duration_since(self.last_tick);
        self.last_tick = now;

        if self.drain_player_events(elapsed) {
            return;
        }
        let Some(status_result) = self.player.as_mut().map(|player| player.status()) else {
            return;
        };
        if self.drain_player_events(elapsed) {
            return;
        }
        match status_result {
            Ok(mut status) => {
                self.normalize_playback_status(&mut status);
                if self.playback_phase == PlaybackPhase::Idle {
                    self.view.playback = status;
                    return;
                }
                if status.idle {
                    // `idle-active` is not an end reason. In particular, it can
                    // change during yt-dlp loading. Only an `end-file` event may
                    // finish or fail the current queue item.
                    return;
                }
                if self.playback_phase != PlaybackPhase::Playing {
                    status.paused = true;
                    status.buffering = true;
                }
                // Backends may derive a title from a resolved CDN URL. Youta
                // already owns the stable user-facing title and must not
                // replace it with a long, expiring, potentially sensitive URL.
                status.title = Some(self.current_playback_title());
                self.view.playback = status;
                #[cfg(feature = "radio")]
                {
                    let icy_title = self.view.playback.stream_title.clone();
                    self.refresh_playing_radio_metadata(icy_title.as_deref());
                }
                if self.playback_phase == PlaybackPhase::Playing {
                    self.update_live_local_progress_view();
                    self.skip_current_advertisement_chapter();
                    self.account_listen_time(elapsed);
                    if self.unflushed_listen_time >= Duration::from_secs(30)
                        || self.last_position_save.elapsed()
                            >= Duration::from_secs(
                                self.config
                                    .persistence
                                    .position_save_interval_seconds
                                    .max(1),
                            )
                    {
                        self.checkpoint_position();
                        self.last_position_save = Instant::now();
                    }
                }
            }
            Err(error) => {
                self.fail_player("Playback status failed", &error, elapsed);
            }
        }
    }

    /// Skips one exact `Реклама` chapter and suppresses duplicate commands
    /// while the backend still reports its stale pre-seek position.
    fn skip_current_advertisement_chapter(&mut self) {
        if !self.config.playback.skip_advertisement_chapters {
            self.skipped_advertisement_chapter = None;
            return;
        }
        let Some(media_id) = self.current_media.clone() else {
            return;
        };
        let position = self.view.playback.position.as_secs();
        let matching = self.view.playback_chapters.iter().find(|chapter| {
            is_advertisement_chapter_title(&chapter.title)
                && chapter.end_seconds.is_some_and(|end| {
                    chapter.start_seconds <= position
                        && position < end
                        && end > chapter.start_seconds
                })
        });
        let Some(chapter) = matching else {
            self.skipped_advertisement_chapter = None;
            return;
        };
        let key = (media_id, chapter.start_seconds);
        if self.skipped_advertisement_chapter.as_ref() == Some(&key) {
            return;
        }
        let Some(end) = chapter.end_seconds else {
            return;
        };
        self.skipped_advertisement_chapter = Some(key);
        self.player_command(PlayerCommand::SeekAbsolute(Duration::from_secs(end)));
        self.view.status_line = format!("Skipped advertisement section to {}", format_seconds(end));
    }

    fn drain_player_events(&mut self, elapsed: Duration) -> bool {
        const MAX_EVENTS_PER_TICK: usize = 64;

        for _ in 0..MAX_EVENTS_PER_TICK {
            let Some(event_result) = self.player.as_mut().map(|player| player.poll_event()) else {
                return true;
            };
            match event_result {
                Ok(Some(PlaybackEvent::MediaLoaded)) => {
                    if self.playback_phase == PlaybackPhase::Loading {
                        self.playback_phase = PlaybackPhase::Loaded;
                        self.ignore_replaced_stop = false;
                        let title = self.current_playback_title();
                        self.view.status_line = format!("Loaded {title}; starting audio…");
                    }
                }
                Ok(Some(PlaybackEvent::PlaybackStarted)) => {
                    if self.playback_phase != PlaybackPhase::Playing {
                        self.playback_phase = PlaybackPhase::Playing;
                        self.playback_load_kind = PlaybackLoadKind::Regular;
                        self.clear_playback_start_activity();
                        self.view.playing_media_id = self.current_media.clone();
                        self.view.playback.idle = false;
                        self.view.playback.paused = false;
                        self.view.playback.buffering = false;
                        let title = self.current_playback_title();
                        self.view.status_line = format!("Playing {title}");
                        if let Some(history) = self.pending_history.take()
                            && let Err(error) = self.store.insert_history(&history)
                        {
                            self.show_error("Playing, but history could not be saved", &error);
                        }
                        self.checkpoint_playback_started();
                    }
                }
                Ok(Some(PlaybackEvent::Ended(end))) => {
                    if end.reason == PlaybackEndReason::Stop && self.ignore_replaced_stop {
                        self.ignore_replaced_stop = false;
                        continue;
                    }
                    self.handle_playback_end(end, elapsed);
                    return true;
                }
                Ok(Some(PlaybackEvent::ProcessExited { diagnostic })) => {
                    let message = diagnostic
                        .unwrap_or_else(|| "mpv exited without diagnostic output".to_owned());
                    #[cfg(feature = "radio")]
                    self.discard_active_radio_recording();
                    self.prepare_to_clear_playback(elapsed);
                    self.reset_playback_state();
                    if let Some(mut player) = self.player.take() {
                        let _ = player.shutdown();
                    }
                    self.show_error_message("Playback process stopped", message);
                    return true;
                }
                Ok(None) => return false,
                Err(error) => {
                    self.fail_player("Playback event polling failed", &error, elapsed);
                    return true;
                }
            }
        }

        #[cfg(feature = "radio")]
        self.disable_and_discard_active_radio_recording();
        self.prepare_to_clear_playback(elapsed);
        self.reset_playback_state();
        if let Some(mut player) = self.player.take() {
            let _ = player.shutdown();
        }
        self.show_error_message(
            "Playback event polling failed",
            "the playback backend emitted too many lifecycle events in one UI tick",
        );
        true
    }

    fn handle_playback_end(&mut self, end: PlaybackEnd, elapsed: Duration) {
        #[cfg(feature = "radio")]
        self.discard_active_radio_recording();
        if self.retry_youtube_load(&end) {
            return;
        }
        let playback_started = self.playback_phase == PlaybackPhase::Playing;
        let tracker_module = self
            .current_media
            .as_ref()
            .is_some_and(|media| media.source == SourceKind::ModArchive);
        self.prepare_to_clear_playback(elapsed);
        match end.reason.clone() {
            PlaybackEndReason::Eof if !playback_started => {
                let message = playback_before_start_message_for_media(&end, tracker_module);
                self.queued_autoplay_resume_origin = None;
                #[cfg(feature = "tracker-music")]
                self.cancel_pending_tracker_autoplay();
                self.reset_playback_state();
                self.show_error_message("Playback did not start", message);
            }
            PlaybackEndReason::Eof => {
                if let Some(duration) = self.view.playback.duration {
                    self.view.playback.position = duration;
                    self.persist_position();
                }
                let autoplay_origin = self.current_autoplay_origin.clone();
                self.reset_playback_state();
                match self.playback_queue.advance().cloned() {
                    Some(next) => {
                        if self.config.playback.autoplay
                            && self.queued_autoplay_resume_origin.is_none()
                            && autoplay_origin.is_some()
                        {
                            self.queued_autoplay_resume_origin = autoplay_origin;
                        }
                        self.play_queue_item_with_origin(next, true, None);
                    }
                    None if self.config.playback.autoplay => {
                        let origin = self
                            .queued_autoplay_resume_origin
                            .take()
                            .or(autoplay_origin);
                        if let Some(origin) = origin {
                            self.continue_autoplay(origin);
                        } else {
                            self.view.status_line =
                                "Playback queue finished; this item has no autoplay list"
                                    .to_owned();
                        }
                    }
                    None => {
                        self.queued_autoplay_resume_origin = None;
                        self.view.status_line = "Playback queue finished".to_owned();
                    }
                }
            }
            PlaybackEndReason::Stop => {
                self.queued_autoplay_resume_origin = None;
                #[cfg(feature = "tracker-music")]
                self.cancel_pending_tracker_autoplay();
                self.reset_playback_state();
                self.view.status_line = "Playback stopped".to_owned();
            }
            PlaybackEndReason::Error => {
                let message = if tracker_module && playback_end_reports_unsupported_format(&end) {
                    tracker_decoder_help(&playback_end_message(&end))
                } else {
                    playback_end_message(&end)
                };
                self.queued_autoplay_resume_origin = None;
                #[cfg(feature = "tracker-music")]
                self.cancel_pending_tracker_autoplay();
                self.reset_playback_state();
                self.show_error_message("Playback failed", message);
            }
            PlaybackEndReason::Other(reason) => {
                let message = format!(
                    "the playback backend ended the media for an unexpected reason: {reason}"
                );
                self.queued_autoplay_resume_origin = None;
                #[cfg(feature = "tracker-music")]
                self.cancel_pending_tracker_autoplay();
                self.reset_playback_state();
                self.show_error_message("Playback ended unexpectedly", message);
            }
        }
    }

    /// Advances one pre-start `YouTube` load through its bounded fallback chain.
    ///
    /// A speculative direct stream may fail for any reason before audible
    /// playback begins and falls back to the canonical watch URL. This remains
    /// true when `mpv` emitted [`PlaybackEvent::MediaLoaded`] before discovering
    /// that the resolved payload cannot be demuxed. A canonical pre-start HTTP
    /// 403 or unusable-format result enables the slower checked-format route,
    /// including when `file-loaded` preceded the failure. Once
    /// [`PlaybackEvent::PlaybackStarted`] arrives, no automatic replacement is
    /// attempted.
    fn retry_youtube_load(&mut self, end: &PlaybackEnd) -> bool {
        if !matches!(
            end.reason,
            PlaybackEndReason::Eof | PlaybackEndReason::Error
        ) {
            return false;
        }
        let next_kind = match self.playback_load_kind {
            PlaybackLoadKind::YouTubeDirect
                if matches!(
                    self.playback_phase,
                    PlaybackPhase::Loading | PlaybackPhase::Loaded
                ) =>
            {
                PlaybackLoadKind::YouTubeCanonical
            }
            PlaybackLoadKind::YouTubeCanonical
                if matches!(
                    self.playback_phase,
                    PlaybackPhase::Loading | PlaybackPhase::Loaded
                ) && (playback_end_reports_http_403(end)
                    || playback_end_reports_unsupported_format(end)) =>
            {
                PlaybackLoadKind::YouTubeChecked
            }
            PlaybackLoadKind::Regular
            | PlaybackLoadKind::YouTubeDirect
            | PlaybackLoadKind::YouTubeCanonical
            | PlaybackLoadKind::YouTubeChecked => return false,
        };
        let Some(media_id) = self.current_media.as_ref() else {
            return false;
        };
        if media_id.source != SourceKind::YouTube {
            return false;
        }
        let Some(item) = self.playback_queue.current().cloned() else {
            return false;
        };
        if &item.media.id != media_id {
            return false;
        }

        let title = item.media.title.clone();
        let start_at = self
            .pending_history
            .as_ref()
            .map_or(self.view.playback.position.as_secs(), |history| {
                history.position_seconds
            });
        let mut input = PlaybackInput::new(item.playback_location);
        input.start_at = Duration::from_secs(start_at);
        input.title = Some(title.clone());
        input.verify_remote_format = next_kind == PlaybackLoadKind::YouTubeChecked;
        let result = self
            .player
            .as_mut()
            .expect("an active load always owns a player")
            .play(&input);
        match result {
            Ok(()) => {
                self.playback_load_kind = next_kind;
                self.playback_phase = PlaybackPhase::Loading;
                self.begin_playback_start_activity();
                self.ignore_replaced_stop = true;
                self.last_tick = Instant::now();
                self.view.playback.idle = false;
                self.view.playback.position = Duration::from_secs(start_at);
                self.view.playback.paused = true;
                self.view.playback.buffering = true;
                self.view.playback.buffered_ranges.clear();
                self.view.status_line = match next_kind {
                    PlaybackLoadKind::YouTubeCanonical => {
                        format!("Retrying {title} through YouTube…")
                    }
                    PlaybackLoadKind::YouTubeChecked => {
                        format!("Retrying {title} after validating alternate YouTube formats…")
                    }
                    PlaybackLoadKind::Regular | PlaybackLoadKind::YouTubeDirect => {
                        unreachable!("the fallback target is canonical or checked")
                    }
                };
            }
            Err(error) => {
                self.queued_autoplay_resume_origin = None;
                #[cfg(feature = "tracker-music")]
                self.cancel_pending_tracker_autoplay();
                self.reset_playback_state();
                self.show_error("Playback failed", &error);
            }
        }
        true
    }

    fn current_playback_title(&self) -> String {
        self.pending_history
            .as_ref()
            .map(|history| history.title.clone())
            .or_else(|| self.view.playback.title.clone())
            .unwrap_or_else(|| "media".to_owned())
    }

    fn prepare_to_clear_playback(&mut self, elapsed: Duration) {
        if self.playback_phase == PlaybackPhase::Playing {
            self.account_listen_time(elapsed);
            self.persist_position();
        }
    }

    fn reset_playback_state(&mut self) {
        self.playback_phase = PlaybackPhase::Idle;
        self.playback_load_kind = PlaybackLoadKind::Regular;
        self.clear_playback_start_activity();
        self.view.playing_media_id = None;
        self.pending_history = None;
        self.ignore_replaced_stop = false;
        self.current_media = None;
        self.current_playback_progress = None;
        self.current_autoplay_origin = None;
        self.seek_back.clear();
        self.view.playback_chapters.clear();
        self.view.radio_now_playing = None;
        self.view.playback = PlaybackStatus {
            volume: self.config.playback.volume_percent,
            speed: f64::from(self.config.playback.speed_percent) / 100.0,
            ..PlaybackStatus::default()
        };
    }

    fn fail_player<E>(&mut self, title: &str, error: &E, elapsed: Duration)
    where
        E: std::error::Error + 'static,
    {
        #[cfg(feature = "radio")]
        self.disable_and_discard_active_radio_recording();
        self.prepare_to_clear_playback(elapsed);
        self.reset_playback_state();
        if let Some(mut player) = self.player.take() {
            let _ = player.shutdown();
        }
        self.show_error(title, error);
    }

    fn account_listen_time(&mut self, elapsed: Duration) {
        if self.playback_phase == PlaybackPhase::Playing
            && self.current_media.is_some()
            && !self.view.playback.paused
        {
            self.unflushed_listen_time += elapsed;
        }
    }

    /// Builds the next progress row from a per-item cache.
    ///
    /// Normal playback loads this cache once when an item starts. Periodic
    /// checkpoints therefore do not scan a growing human-readable progress
    /// document.
    fn current_progress_at_player_position(&mut self) -> Option<PlaybackProgress> {
        #[cfg(any(feature = "local-rename", feature = "local-move"))]
        if !self.local_move_persistence_queue.is_empty() {
            return None;
        }
        let Some(media_id) = self.current_media.clone() else {
            return None;
        };
        if media_id.source == SourceKind::Radio {
            return None;
        }
        let duration = self.view.playback.duration.map(|value| value.as_secs());
        let now = unix_time();
        let mut progress = self
            .current_playback_progress
            .take()
            .filter(|progress| progress.media_id == media_id)
            .unwrap_or_else(|| PlaybackProgress::new(media_id, duration, now));
        progress.duration_seconds = duration.or(progress.duration_seconds);
        progress.record_position(self.view.playback.position.as_secs(), now);
        self.current_playback_progress = Some(progress.clone());
        Some(progress)
    }

    /// Durably records that the backend accepted the current non-live item.
    ///
    /// A first start normally writes position zero. The existence of that
    /// progress record survives restart and distinguishes an accepted start
    /// from a failed load without fabricating a visible percentage.
    fn checkpoint_playback_started(&mut self) {
        let Some(progress) = self.current_playback_progress.clone() else {
            return;
        };
        let state = PlaybackRowState::from_progress(Some(&progress));
        self.update_visible_progress_view(&progress.media_id, state);
        if let Err(error) = self
            .store
            .checkpoint_playback(&progress, &progress.media_id.source, 0)
        {
            self.show_error("Playing, but initial progress could not be saved", &error);
        }
    }

    /// Atomically replaces the small periodic playback recovery document.
    fn checkpoint_position(&mut self) -> bool {
        if self
            .current_media
            .as_ref()
            .is_some_and(|media| media.source == SourceKind::Radio)
        {
            let listened_seconds = self.unflushed_listen_time.as_secs();
            return match self
                .store
                .checkpoint_listening(&SourceKind::Radio, listened_seconds)
            {
                Ok(()) => {
                    self.unflushed_listen_time -= Duration::from_secs(listened_seconds);
                    true
                }
                Err(error) => {
                    self.show_error("Could not checkpoint live-radio listening", &error);
                    false
                }
            };
        }
        let Some(progress) = self.current_progress_at_player_position() else {
            return false;
        };
        let listened_seconds = self.unflushed_listen_time.as_secs();
        match self
            .store
            .checkpoint_playback(&progress, &progress.media_id.source, listened_seconds)
        {
            Ok(()) => {
                self.unflushed_listen_time -= Duration::from_secs(listened_seconds);
                self.update_visible_progress_view(
                    &progress.media_id,
                    PlaybackRowState::from_progress(Some(&progress)),
                );
                true
            }
            Err(error) => {
                self.show_error("Could not checkpoint playback", &error);
                false
            }
        }
    }

    /// Saves the latest checkpoint and publishes it to canonical state.
    ///
    /// `true` means either no media needed a checkpoint or every applicable
    /// write completed. Errors remain visible through the diagnostic popup.
    fn persist_position(&mut self) -> bool {
        if self.current_media.is_none() {
            return true;
        }
        if !self.checkpoint_position() {
            return false;
        }
        self.publish_playback_checkpoint()
    }

    /// Publishes any durable recovery checkpoint into canonical state.
    fn publish_playback_checkpoint(&mut self) -> bool {
        if let Err(error) = self.store.flush_playback_checkpoint() {
            self.show_error("Could not publish playback checkpoint", &error);
            return false;
        }
        true
    }

    /// Switches top-level routes while accepting any already-applied local edit.
    ///
    /// Radio filtering is live, so leaving its editor keeps the visible query
    /// instead of restoring the snapshot captured when `/` was pressed.
    fn show_screen(&mut self, screen: Screen) {
        self.clear_detail_navigation_history();
        #[cfg(feature = "yt-dlp")]
        self.cancel_youtube_prewarm();
        if self.view.screen == Screen::Local && screen != Screen::Local {
            self.invalidate_local_folder_sizes();
        }
        self.view.search_editing = false;
        #[cfg(feature = "radio")]
        if self.view.screen == Screen::Radio {
            self.radio_filter_edit_snapshot = None;
        }
        match self.view.screen {
            Screen::Search => {
                self.youtube_search_query
                    .clone_from(&self.view.search_query);
                self.youtube_selected = self.view.selected;
            }
            Screen::YouTubeMusic => {
                self.youtube_music_search_query
                    .clone_from(&self.view.search_query);
                self.youtube_music_selected = self.view.selected;
            }
            #[cfg(feature = "bandcamp")]
            Screen::Bandcamp => {
                self.bandcamp_search_query
                    .clone_from(&self.view.search_query);
                self.bandcamp_selected = self.view.selected;
                self.cancel_pending_bandcamp_resolution();
            }
            Screen::ApplePodcasts => {
                self.apple_podcasts_search_query
                    .clone_from(&self.view.search_query);
                match self.apple_podcasts_route {
                    ApplePodcastsRoute::Shows => {
                        self.apple_podcasts_selected = self.view.selected;
                    }
                    ApplePodcastsRoute::Episodes => {
                        self.apple_podcast_episode_selected = self.view.selected;
                    }
                    ApplePodcastsRoute::Direct => {}
                }
            }
            Screen::Radio => {
                self.radio_filter_query.clone_from(&self.view.search_query);
                #[cfg(feature = "radio")]
                self.remember_selected_radio_station();
                #[cfg(not(feature = "radio"))]
                {
                    self.radio_selected = self.view.selected;
                }
            }
            Screen::TrackerMusic => {
                self.tracker_search_query
                    .clone_from(&self.view.search_query);
                self.tracker_selected = self.view.selected;
            }
            Screen::Playlists => match self.playlists_route {
                PlaylistsRoute::Index => self.playlist_selected = self.view.selected,
                PlaylistsRoute::Entries { .. } => {
                    self.playlist_entry_selected = self.view.selected;
                }
            },
            _ => {}
        }
        self.details_generation = self.details_generation.wrapping_add(1);
        #[cfg(feature = "wikidata")]
        self.invalidate_wikidata_lookup();
        self.channel_details_generation = self.channel_details_generation.wrapping_add(1);
        self.scheduled_channel_details = None;
        self.view.screen = screen;
        if self.view.right_panel_mode == RightPanelMode::Channel {
            self.view.right_panel_mode = RightPanelMode::Details;
        }
        match screen {
            Screen::Search => {
                self.view
                    .search_query
                    .clone_from(&self.youtube_search_query);
                self.view.selected = self.youtube_selected;
            }
            Screen::YouTubeMusic => {
                self.view
                    .search_query
                    .clone_from(&self.youtube_music_search_query);
                self.view.selected = self.youtube_music_selected;
            }
            #[cfg(feature = "bandcamp")]
            Screen::Bandcamp => {
                self.view
                    .search_query
                    .clone_from(&self.bandcamp_search_query);
                self.view.selected = self
                    .bandcamp_selected
                    .min(self.bandcamp_results.len().saturating_sub(1));
            }
            Screen::ApplePodcasts => {
                self.view
                    .search_query
                    .clone_from(&self.apple_podcasts_search_query);
                self.view.selected = match self.apple_podcasts_route {
                    ApplePodcastsRoute::Shows => self.apple_podcasts_selected,
                    ApplePodcastsRoute::Episodes => self.apple_podcast_episode_selected,
                    ApplePodcastsRoute::Direct => 0,
                };
            }
            Screen::Radio => {
                self.view.search_query.clone_from(&self.radio_filter_query);
                #[cfg(feature = "radio")]
                {
                    self.view.selected = self.radio_selected.min(station_count().saturating_sub(1));
                }
                #[cfg(not(feature = "radio"))]
                {
                    self.view.selected = 0;
                }
            }
            Screen::TrackerMusic => {
                self.view
                    .search_query
                    .clone_from(&self.tracker_search_query);
                self.view.selected = self.tracker_selected;
            }
            Screen::Playlists => {
                self.view.selected = match self.playlists_route {
                    PlaylistsRoute::Index => self.playlist_selected,
                    PlaylistsRoute::Entries { .. } => self.playlist_entry_selected,
                };
            }
            _ => self.view.selected = 0,
        }
        if screen == Screen::Subscriptions {
            self.view.subscriptions.selected_source = 0;
            self.view.subscriptions.selected_item = 0;
            self.view.subscriptions.route = SubscriptionRoute::Sources;
            self.view.subscriptions.focus = SubscriptionPane::Sources;
            self.view.subscriptions.description_expanded = false;
        }
        if screen != Screen::Subscriptions {
            let cancelled_refresh = self.pending_subscription_refresh.take().is_some();
            self.active_subscription_channel_id = None;
            if cancelled_refresh {
                // A deliberate refresh must not replace the cache after its
                // channel context is abandoned. Ordinary initial loads may
                // still populate that channel's cache in the background.
                self.subscription_generation = self.subscription_generation.wrapping_add(1);
            }
            self.view.subscriptions.loading = false;
        }
        self.view.details = None;
        self.view.details_focused = false;
        self.view.details_scroll = 0;
        self.view.selected_detail_link = None;
        self.populate_local_screen();
        if screen == Screen::Search && !self.youtube_results.is_empty() {
            self.request_visible_channel_subscriber_counts();
            self.request_selected_details();
        } else if screen == Screen::YouTubeMusic && !self.youtube_music_results.is_empty() {
            self.request_selected_details();
        } else if screen == Screen::ApplePodcasts {
            match self.apple_podcasts_route {
                ApplePodcastsRoute::Shows if !self.apple_podcasts_results.is_empty() => {
                    self.update_apple_podcasts_detail();
                }
                ApplePodcastsRoute::Episodes => self.update_apple_podcast_episode_detail(),
                ApplePodcastsRoute::Direct => self.refresh_apple_direct_view(),
                ApplePodcastsRoute::Shows => {}
            }
        }
        self.refresh_selected_playlist_state();
    }

    fn populate_local_screen(&mut self) {
        match self.view.screen {
            Screen::Search => {
                if !self.local_results.is_empty() {
                    self.refresh_local_rows();
                } else if let Some(media) = self.resolved_direct.clone() {
                    self.view.rows = vec![RowView {
                        media_id: Some(MediaId::new(
                            media.source.clone(),
                            media.external_id.clone(),
                        )),
                        title: media.title,
                        subtitle: media.duration_seconds.map_or_else(
                            || "podcast".to_owned(),
                            |duration| format!("episode · {}", format_seconds(duration)),
                        ),
                        source: media.source.to_string(),
                        ..RowView::default()
                    }];
                    hydrate_row_playback_progress(&self.store, &mut self.view.rows);
                } else if let Some(direct) = &self.direct_item {
                    self.view.rows = vec![RowView {
                        media_id: Some(MediaId::new(direct.source.clone(), direct.url.to_string())),
                        title: direct.url.to_string(),
                        subtitle: "direct link".to_owned(),
                        source: direct.source.to_string(),
                        ..RowView::default()
                    }];
                    hydrate_row_playback_progress(&self.store, &mut self.view.rows);
                } else {
                    self.refresh_youtube_rows();
                }
                self.view.status_line = "Default search: YouTube videos only".to_owned();
            }
            Screen::YouTubeMusic => {
                self.refresh_youtube_music_rows();
                self.view.status_line = if self.youtube_music_results.is_empty() {
                    "YouTube Music uses yt-dlp and does not require a YouTube API key; press / to search"
                        .to_owned()
                } else {
                    format!(
                        "{} YouTube Music track{}",
                        self.youtube_music_results.len(),
                        if self.youtube_music_results.len() == 1 {
                            ""
                        } else {
                            "s"
                        }
                    )
                };
            }
            Screen::Bandcamp => {
                #[cfg(feature = "bandcamp")]
                {
                    self.refresh_bandcamp_rows();
                    self.update_bandcamp_detail();
                    self.view.status_line = if self.bandcamp_results.is_empty() {
                        "Bandcamp searches public tracks and albums; press / to search".to_owned()
                    } else {
                        format!(
                            "{} Bandcamp release{} on page {}",
                            self.bandcamp_results.len(),
                            if self.bandcamp_results.len() == 1 {
                                ""
                            } else {
                                "s"
                            },
                            self.bandcamp_page
                        )
                    };
                }
                #[cfg(not(feature = "bandcamp"))]
                {
                    self.view.rows.clear();
                    self.view.status_line = "This build omits the `bandcamp` feature".to_owned();
                }
            }
            Screen::ApplePodcasts => match self.apple_podcasts_route {
                ApplePodcastsRoute::Shows => {
                    self.refresh_apple_podcasts_rows();
                    self.view.status_line = if self.apple_podcasts_results.is_empty() {
                        "Apple Podcasts uses the public catalogue; press / to search shows"
                            .to_owned()
                    } else {
                        format!(
                            "{} Apple Podcasts show{}",
                            self.apple_podcasts_results.len(),
                            if self.apple_podcasts_results.len() == 1 {
                                ""
                            } else {
                                "s"
                            }
                        )
                    };
                }
                ApplePodcastsRoute::Episodes => {
                    self.populate_apple_podcast_episode_screen();
                }
                ApplePodcastsRoute::Direct => self.refresh_apple_direct_view(),
            },
            Screen::Radio => self.populate_radio(),
            Screen::TrackerMusic => {
                self.refresh_tracker_rows();
                self.view.status_line =
                    "MOD/tracker search uses its own archive sources; press / to search".to_owned();
            }
            Screen::Local => {
                #[cfg(not(feature = "local-browser"))]
                {
                    self.view.rows.clear();
                    self.view.details = None;
                    self.view.status_line =
                        "This build omits the `local-browser` feature".to_owned();
                }
                #[cfg(feature = "local-browser")]
                if self.local_listing.is_some() {
                    self.sort_local_listing();
                    self.refresh_local_browser_rows();
                    self.schedule_local_folder_sizes();
                    self.view.status_line = format!("Local folder: {}", self.view.local_path);
                } else {
                    let restored = PathBuf::from(&self.view.local_path);
                    let directory = if !self.view.local_path.is_empty() && restored.is_dir() {
                        restored
                    } else {
                        default_local_browse_root()
                    };
                    self.browse_local_directory(directory);
                }
            }
            Screen::Subscriptions => self.populate_subscriptions(),
            Screen::Downloaded => self.populate_downloads(),
            Screen::History => self.populate_history(),
            Screen::Playlists => self.populate_playlists_screen(),
            Screen::Statistics => self.populate_statistics(),
        }
    }

    /// Rebuilds the zero-network Radio catalogue from compile-time presets.
    #[cfg(feature = "radio")]
    fn populate_radio(&mut self) {
        let stations =
            self.filtered_radio_stations(self.view.radio_sort, self.radio_filter_query.as_str());
        let selected_id = self.radio_selected_station_id.clone().or_else(|| {
            self.view
                .rows
                .get(self.view.selected)
                .and_then(|row| row.media_id.as_ref())
                .filter(|media_id| media_id.source == SourceKind::Radio)
                .map(|media_id| media_id.external_id.clone())
        });
        self.view.rows = stations
            .iter()
            .map(|station| RowView {
                media_id: Some(MediaId::new(SourceKind::Radio, station.id)),
                title: station.name.to_owned(),
                subtitle: self.radio_station_row_summary(station),
                source: "Radio".to_owned(),
                hide_watched_marker: true,
                compact: true,
                radio_favorite: self.radio_favorite_station_ids.contains(station.id),
                ..RowView::default()
            })
            .collect();
        self.view.selected = selected_id
            .as_deref()
            .and_then(|selected_id| {
                self.view.rows.iter().position(|row| {
                    row.media_id
                        .as_ref()
                        .is_some_and(|media_id| media_id.external_id == selected_id)
                })
            })
            .unwrap_or(0);
        self.update_radio_detail();
        let query = self.radio_filter_query.trim();
        self.view.status_line = if query.is_empty() {
            format!(
                "{} public radio station{}; Enter plays the selected live stream",
                station_count(),
                if station_count() == 1 { "" } else { "s" }
            )
        } else if self.view.rows.is_empty() {
            format!("No public radio stations match “{query}”")
        } else {
            format!(
                "{} of {} public radio stations match “{query}”; Enter plays the selected live stream",
                self.view.rows.len(),
                station_count()
            )
        };
    }

    /// Leaves a safe empty view when Radio was omitted at compile time.
    #[cfg(not(feature = "radio"))]
    fn populate_radio(&mut self) {
        self.view.rows.clear();
        self.view.details = None;
        self.view.status_line = "This build omits the `radio` feature".to_owned();
    }

    /// Resolves the selected Radio row by its stable station identifier.
    #[cfg(feature = "radio")]
    fn selected_radio_station(&self) -> Option<RadioStationPreset> {
        self.view
            .rows
            .get(self.view.selected)
            .and_then(|row| row.media_id.as_ref())
            .filter(|media_id| media_id.source == SourceKind::Radio)
            .and_then(|media_id| station_by_id(&media_id.external_id))
    }

    /// Starts or stops capture for the Radio row that is audibly playing.
    ///
    /// Recording is deliberately unavailable from every other screen and for
    /// merely selected stations. `mpv` receives `stream-record`, so the
    /// original encoded packets are copied instead of being decoded and
    /// re-encoded by Youta.
    #[cfg(feature = "radio")]
    fn toggle_radio_recording(&mut self) {
        if self.view.screen != Screen::Radio {
            self.view.status_line = "Open Radio to control live recording".to_owned();
            return;
        }
        if self.active_radio_recording.is_some() {
            self.stop_active_radio_recording();
            return;
        }

        let Some(playing) = self.view.playing_media_id.as_ref() else {
            self.view.status_line = "Play a Radio station before recording".to_owned();
            return;
        };
        if playing.source != SourceKind::Radio {
            self.view.status_line =
                "Only the currently playing Radio station can be recorded".to_owned();
            return;
        }
        let Some(station) = self.selected_radio_station() else {
            self.view.status_line =
                "Select the currently playing Radio station to record it".to_owned();
            return;
        };
        if station.id != playing.external_id {
            self.view.status_line =
                "Select the currently playing Radio station to control its recording".to_owned();
            return;
        }

        self.start_radio_recording(station);
    }

    /// Starts one private stream-record capture after validating its exact live owner.
    #[cfg(feature = "radio")]
    fn start_radio_recording(&mut self, station: RadioStationPreset) {
        let Some(player) = self.player.as_mut() else {
            self.view.status_line = "Nothing is playing".to_owned();
            return;
        };
        // mpv's `stream-record` delegates container selection to libavformat
        // using this filename extension. Matching the advertised source codec
        // preserves the original packets without demanding an incompatible
        // Matroska mux for every station.
        #[cfg(feature = "bbc-radio")]
        let bbc_extension = (station.stream_kind == RadioStreamKind::BbcSounds)
            .then(|| {
                self.bbc_quality_cache
                    .get(station.id)
                    .and_then(|quality| radio_recording_extension_from_bbc_codec(&quality.codec))
            })
            .flatten();
        #[cfg(not(feature = "bbc-radio"))]
        let bbc_extension: Option<&'static str> = None;
        let extension = bbc_extension
            .unwrap_or_else(|| radio_recording_extension(station.codec, station.stream));
        let staging_path = match prepare_radio_recording_staging_path(&self.config, extension) {
            Ok(path) => path,
            Err(error) => {
                self.show_error_message("Cannot start Radio recording", error);
                return;
            }
        };
        if let Err(error) = player.command(PlayerCommand::SetStreamRecording(Some(
            staging_path.clone(),
        ))) {
            // A failed property write may have reached mpv after it opened the
            // output. Do not unlink until the uncertain backend is stopped.
            self.shutdown_player_after_recording_stop_failure();
            remove_radio_recording_file(&staging_path);
            self.show_error("Cannot start Radio recording", &error);
            return;
        }
        self.active_radio_recording = Some(ActiveRadioRecording {
            station_id: station.id.to_owned(),
            station_name: station.name.to_owned(),
            staging_path,
            extension,
            started_at: Local::now(),
        });
        self.view.radio_recording =
            self.active_radio_recording
                .as_ref()
                .map(|recording| RadioRecordingView {
                    station_id: recording.station_id.clone(),
                    station_name: recording.station_name.clone(),
                });
        self.view.status_line = format!("Recording {} in original stream quality", station.name);
    }

    /// Stops `stream-record` and publishes its complete result without replacing a file.
    #[cfg(feature = "radio")]
    fn stop_active_radio_recording(&mut self) {
        let Some(recording) = self.active_radio_recording.take() else {
            self.view.status_line = "No Radio recording is active".to_owned();
            return;
        };
        let stop_result = self
            .player
            .as_mut()
            .ok_or_else(|| "the playback backend is no longer available".to_owned())
            .and_then(|player| {
                player
                    .command(PlayerCommand::SetStreamRecording(None))
                    .map_err(|error| error.to_string())
            });
        if let Err(error) = stop_result {
            // A rejected IPC command leaves the backend state unknown. Shut it
            // down before unlinking so it cannot continue writing an unlinked
            // private inode while a replacement item starts.
            self.shutdown_player_after_recording_stop_failure();
            remove_radio_recording_file(&recording.staging_path);
            self.view.radio_recording = None;
            self.show_error_message(
                "Radio recording was discarded",
                format!("could not stop the stream capture safely: {error}"),
            );
            return;
        }
        self.publish_stopped_radio_recording(recording);
    }

    /// Finalizes a recording whose backend has already been stopped during graceful shutdown.
    #[cfg(feature = "radio")]
    fn finalize_radio_recording_for_shutdown(&mut self) {
        let Some(recording) = self.active_radio_recording.take() else {
            return;
        };
        let stop_result = self
            .player
            .as_mut()
            .ok_or_else(|| "the playback backend is no longer available".to_owned())
            .and_then(|player| {
                player
                    .command(PlayerCommand::SetStreamRecording(None))
                    .map_err(|error| error.to_string())
            });
        if let Err(error) = stop_result {
            // Shutdown is already in progress; make the backend exit before
            // removing the staging pathname for the same inode-safety reason.
            self.shutdown_player_after_recording_stop_failure();
            remove_radio_recording_file(&recording.staging_path);
            self.view.radio_recording = None;
            self.show_error_message(
                "Radio recording was discarded during shutdown",
                format!("could not stop the stream capture safely: {error}"),
            );
            return;
        }
        self.publish_stopped_radio_recording(recording);
    }

    /// Moves a fully closed private capture into Downloaded and refreshes that view when open.
    #[cfg(feature = "radio")]
    fn publish_stopped_radio_recording(&mut self, recording: ActiveRadioRecording) {
        self.view.radio_recording = None;
        match publish_radio_recording(&self.config, &recording) {
            Ok(path) => {
                self.view.status_line = format!("Radio recording saved: {}", path.display());
                if self.view.screen == Screen::Downloaded {
                    self.populate_downloads();
                }
            }
            Err(error) => {
                remove_radio_recording_file(&recording.staging_path);
                self.show_error_message("Radio recording was discarded", error);
            }
        }
    }

    /// Stops an uncertain backend before discarding its private capture.
    #[cfg(feature = "radio")]
    fn shutdown_player_after_recording_stop_failure(&mut self) {
        if let Some(mut player) = self.player.take() {
            let _ = player.shutdown();
        }
        self.reset_playback_state();
    }

    /// Removes a capture only after a terminal backend event proves it stopped writing.
    #[cfg(feature = "radio")]
    fn discard_active_radio_recording(&mut self) {
        if let Some(recording) = self.active_radio_recording.take() {
            remove_radio_recording_file(&recording.staging_path);
            self.view.radio_recording = None;
            self.view.status_line =
                "Radio recording was discarded because playback ended".to_owned();
        }
    }

    /// Stops the backend before discarding a capture during an internal player failure.
    #[cfg(feature = "radio")]
    fn disable_and_discard_active_radio_recording(&mut self) {
        let Some(recording) = self.active_radio_recording.take() else {
            return;
        };
        if let Some(mut player) = self.player.take() {
            let _ = player.command(PlayerCommand::SetStreamRecording(None));
            let _ = player.shutdown();
        }
        remove_radio_recording_file(&recording.staging_path);
        self.view.radio_recording = None;
    }

    /// Maps the visible filtered selection back to the complete sorted catalogue.
    #[cfg(feature = "radio")]
    fn remember_selected_radio_station(&mut self) {
        let Some(station) = self.selected_radio_station() else {
            return;
        };
        self.radio_selected_station_id = Some(station.id.to_owned());
        if let Some(index) = self
            .sorted_radio_stations(self.view.radio_sort)
            .iter()
            .position(|candidate| candidate.id == station.id)
        {
            self.radio_selected = index;
        }
    }

    /// Formats one stable Radio row, reusing action-resolved BBC quality when available.
    #[cfg(feature = "radio")]
    fn radio_station_row_summary(&self, station: &RadioStationPreset) -> String {
        #[cfg(feature = "bbc-radio")]
        if station.stream_kind == RadioStreamKind::BbcSounds {
            return self
                .bbc_quality_cache
                .get(station.id)
                .map(CachedBbcQuality::display)
                .unwrap_or_default();
        }

        radio_station_quality(station, false)
    }

    /// Formats selected-station quality while omitting unresolved BBC data.
    #[cfg(feature = "radio")]
    fn radio_station_detail_quality(&self, station: &RadioStationPreset) -> String {
        #[cfg(feature = "bbc-radio")]
        if station.stream_kind == RadioStreamKind::BbcSounds {
            return self
                .bbc_quality_cache
                .get(station.id)
                .map(CachedBbcQuality::display)
                .unwrap_or_default();
        }

        radio_station_quality(station, true)
    }

    /// Returns the effective bitrate used by local Radio filtering and sorting.
    #[cfg(feature = "radio")]
    fn radio_station_bitrate(&self, station: &RadioStationPreset) -> Option<u32> {
        #[cfg(feature = "bbc-radio")]
        if station.stream_kind == RadioStreamKind::BbcSounds {
            return self
                .bbc_quality_cache
                .get(station.id)
                .and_then(|quality| quality.bitrate_kbps);
        }

        station.bitrate_kbps.map(u32::from)
    }

    /// Sorts Radio presets using action-resolved BBC bitrate when available.
    #[cfg(feature = "radio")]
    fn sorted_radio_stations(&self, sort: RadioSort) -> Vec<RadioStationPreset> {
        sorted_radio_stations_by(sort, |station| self.radio_station_bitrate(station))
    }

    /// Checks a Radio preset against stable metadata and trusted cached quality.
    #[cfg(feature = "radio")]
    fn radio_station_matches_filter(&self, station: &RadioStationPreset, query: &str) -> bool {
        let quality = self.radio_station_row_summary(station);
        radio_station_matches_filter_with_quality(
            station,
            query,
            &quality,
            self.radio_station_bitrate(station),
        )
    }

    /// Filters Radio presets using the same effective quality rendered in rows.
    #[cfg(feature = "radio")]
    fn filtered_radio_stations(&self, sort: RadioSort, query: &str) -> Vec<RadioStationPreset> {
        let stations = self
            .sorted_radio_stations(sort)
            .into_iter()
            .filter(|station| self.radio_station_matches_filter(station, query))
            .collect();
        pin_radio_favorite_stations(stations, &self.radio_favorite_station_ids)
    }

    /// Starts one BBC Sounds manifest lookup while retaining only its stable page.
    #[cfg(feature = "bbc-radio")]
    fn request_bbc_live(
        &mut self,
        item: QueueItem,
        queue_cursor_already_positioned: bool,
        origin: Option<AutoplayOrigin>,
    ) {
        let station_id = item.media.id.external_id.clone();
        if bbc_station_by_id(&station_id).is_none() {
            self.show_error_message(
                "BBC Radio playback failed",
                "the selected BBC station is not present in this build",
            );
            return;
        }
        let generation = self.bbc_playback_generation.wrapping_add(1);
        if !self.send_provider_request(
            ProviderRequest::ResolveBbcLive {
                generation,
                station_id,
            },
            "Could not resolve the BBC live stream",
        ) {
            return;
        }
        self.bbc_playback_generation = generation;
        self.pending_bbc_playback = Some(PendingBbcPlayback {
            generation,
            item,
            queue_cursor_already_positioned,
            origin,
        });
        self.begin_playback_start_activity();
        self.view.status_line =
            "Resolving the highest BBC audio quality available in this region…".to_owned();
    }

    /// Applies only the manifest belonging to the latest BBC playback action.
    #[cfg(feature = "bbc-radio")]
    fn handle_bbc_live(
        &mut self,
        generation: u64,
        station_id: String,
        result: Result<BbcLiveResolution, String>,
    ) {
        let owns_response = self.pending_bbc_playback.as_ref().is_some_and(|pending| {
            pending.generation == generation
                && pending.item.media.id.source == SourceKind::Radio
                && pending.item.media.id.external_id == station_id
        });
        if !owns_response {
            return;
        }
        let pending = self
            .pending_bbc_playback
            .take()
            .expect("matching BBC playback ownership was checked above");
        self.clear_playback_start_activity();
        let resolution = match result {
            Ok(resolution) if resolution.station.id == station_id => resolution,
            Ok(_) => {
                self.show_error_message(
                    "BBC Radio playback failed",
                    "BBC returned a manifest for a different station",
                );
                return;
            }
            Err(error) => {
                self.show_error_message("BBC Radio playback failed", error);
                return;
            }
        };
        self.bbc_quality_cache.insert(
            station_id.clone(),
            CachedBbcQuality::from_resolution(&resolution),
        );
        if self.view.screen == Screen::Radio {
            self.populate_radio();
        }
        let mut input = PlaybackInput::new(resolution.manifest_url.to_string());
        input.bypass_ytdl = true;
        self.play_queue_item_with_origin_and_input(
            pending.item,
            pending.queue_cursor_already_positioned,
            pending.origin,
            Some(input),
        );
    }

    /// Refreshes selected station details without contacting the stream.
    #[cfg(feature = "radio")]
    fn update_radio_detail(&mut self) {
        let Some(station) = self.selected_radio_station() else {
            self.view.details = None;
            return;
        };
        self.remember_selected_radio_station();
        let mut description = station.summary.to_owned();
        let quality = self.radio_station_detail_quality(&station);
        if !quality.is_empty() {
            description.push_str("\n\nQuality: ");
            description.push_str(&quality);
        }
        description.push_str("\nStream: ");
        description.push_str(station.stream);
        let selected_metadata = self
            .radio_now_playing_cache
            .get(station.id)
            .and_then(|cached| {
                if Instant::now() < cached.refresh_at {
                    radio_now_playing_display(&cached.value)
                } else {
                    radio_stale_now_playing_display(&cached.value)
                }
            });
        let playing_metadata = self.view.radio_now_playing.clone().filter(|_| {
            self.current_media.as_ref().is_some_and(|media| {
                media.source == SourceKind::Radio && media.external_id == station.id
            })
        });
        let canonical_metadata = if playing_metadata.is_some() {
            playing_metadata.as_ref()
        } else {
            selected_metadata.as_ref()
        };
        if let Some(now_playing) = canonical_metadata {
            description.push_str("\n\n");
            description.push_str(now_playing);
        }
        self.view.details = Some(DetailView {
            media_id: Some(MediaId::new(SourceKind::Radio, station.id)),
            title: station.name.to_owned(),
            source: "Radio".to_owned(),
            channel_webpage_url: station.homepage_url().ok(),
            description,
            radio_favorite: self.radio_favorite_station_ids.contains(station.id),
            ..DetailView::default()
        });
    }

    /// Selects at most one station whose passive metadata may be refreshed.
    #[cfg(feature = "radio")]
    fn radio_now_playing_target(&self) -> Option<RadioStationPreset> {
        let playing = (|| {
            let media = self
                .current_media
                .as_ref()
                .filter(|media| media.source == SourceKind::Radio)?;
            station_by_id(&media.external_id).filter(|station| station.now_playing.is_some())
        })();
        playing.or_else(|| {
            (self.view.screen == Screen::Radio)
                .then(|| self.selected_radio_station())
                .flatten()
                .filter(|station| station.now_playing.is_some())
        })
    }

    /// Schedules one selected/playing radio metadata request without UI errors.
    #[cfg(feature = "radio")]
    fn request_due_radio_now_playing(&mut self, now: Instant) {
        if self.pending_radio_now_playing.is_some() {
            return;
        }
        let Some(station) = self.radio_now_playing_target() else {
            return;
        };
        if self
            .radio_now_playing_cache
            .get(station.id)
            .is_some_and(|cached| now < cached.refresh_at)
            || self
                .radio_now_playing_retry_at
                .get(station.id)
                .is_some_and(|retry| now < retry.retry_at)
        {
            return;
        }
        let Some(endpoint) = station.now_playing else {
            return;
        };
        let generation = self.radio_now_playing_generation.wrapping_add(1);
        let request = ProviderRequest::RadioNowPlaying {
            generation,
            station_id: station.id.to_owned(),
            endpoint,
        };
        let Some(sender) = self.provider_requests.as_ref() else {
            return;
        };
        if sender.send(request).is_ok() {
            self.radio_now_playing_generation = generation;
            self.pending_radio_now_playing = Some(PendingRadioNowPlaying {
                generation,
                station_id: station.id.to_owned(),
            });
        }
    }

    /// Accepts passive metadata while retaining the last success on failures.
    #[cfg(feature = "radio")]
    fn handle_radio_now_playing(
        &mut self,
        generation: u64,
        station_id: String,
        result: Result<RadioNowPlaying, String>,
    ) {
        let expected = self
            .pending_radio_now_playing
            .as_ref()
            .is_some_and(|pending| {
                pending.generation == generation && pending.station_id == station_id
            });
        if !expected {
            return;
        }
        self.pending_radio_now_playing = None;
        let now = Instant::now();
        match result {
            Ok(value) => {
                let refresh_at = now
                    .checked_add(value.refresh_after)
                    .unwrap_or(now + MIN_NOW_PLAYING_REFRESH);
                self.radio_now_playing_cache.insert(
                    station_id.clone(),
                    CachedRadioNowPlaying { value, refresh_at },
                );
                self.radio_now_playing_retry_at.remove(&station_id);
            }
            Err(_) => {
                let consecutive_failures = self
                    .radio_now_playing_retry_at
                    .get(&station_id)
                    .map_or(1, |retry| retry.consecutive_failures.saturating_add(1));
                let delay = radio_now_playing_failure_delay(consecutive_failures);
                self.radio_now_playing_retry_at.insert(
                    station_id.clone(),
                    RadioNowPlayingRetry {
                        retry_at: now.checked_add(delay).unwrap_or(now),
                        consecutive_failures,
                    },
                );
            }
        }
        if self.current_media.as_ref().is_some_and(|media| {
            media.source == SourceKind::Radio && media.external_id == station_id
        }) {
            let icy_title = self.view.playback.stream_title.clone();
            self.refresh_playing_radio_metadata(icy_title.as_deref());
        }
        if self.view.screen == Screen::Radio
            && self
                .selected_radio_station()
                .is_some_and(|station| station.id == station_id)
        {
            self.update_radio_detail();
            self.refresh_selected_playlist_state();
        }
    }

    /// Clears stale details in builds where Radio is unavailable.
    #[cfg(not(feature = "radio"))]
    fn update_radio_detail(&mut self) {
        self.view.details = None;
    }

    /// Applies provider metadata before ICY metadata for the playing station.
    #[cfg(feature = "radio")]
    fn refresh_playing_radio_metadata(&mut self, icy_title: Option<&str>) {
        let cached = self
            .current_media
            .as_ref()
            .filter(|media| media.source == SourceKind::Radio)
            .and_then(|media| self.radio_now_playing_cache.get(&media.external_id));
        let next = playing_radio_metadata_display(cached, icy_title, Instant::now());
        if self.view.radio_now_playing == next {
            return;
        }
        self.view.radio_now_playing = next;
        if self.view.screen == Screen::Radio {
            self.update_radio_detail();
        }
    }

    /// Rebuilds the current persistent playlist route without network access.
    fn populate_playlists_screen(&mut self) {
        match self.playlists_route.clone() {
            PlaylistsRoute::Index => self.populate_playlist_index(),
            PlaylistsRoute::Entries { playlist_id } => match self.store.playlist(&playlist_id) {
                Ok(Some(playlist)) => {
                    self.active_playlist = Some(playlist);
                    self.populate_playlist_entries();
                }
                Ok(None) => {
                    self.playlists_route = PlaylistsRoute::Index;
                    self.active_playlist = None;
                    self.playlist_entry_selected = 0;
                    self.populate_playlist_index();
                    self.view.status_line =
                        "That playlist no longer exists; returned to Playlists".to_owned();
                }
                Err(error) => {
                    self.view.rows.clear();
                    self.view.details = None;
                    self.show_error("Cannot load playlist entries", &error);
                }
            },
        }
    }

    /// Loads compact playlist rows and the selected playlist description.
    fn populate_playlist_index(&mut self) {
        self.active_playlist = None;
        self.playlist_summaries = match self.store.playlists() {
            Ok(summaries) => summaries,
            Err(error) => {
                self.view.rows.clear();
                self.view.details = None;
                self.show_error("Cannot load playlists", &error);
                return;
            }
        };
        self.view.rows = self
            .playlist_summaries
            .iter()
            .map(|playlist| {
                let count = format!(
                    "{} item{}",
                    playlist.entry_count,
                    if playlist.entry_count == 1 { "" } else { "s" }
                );
                RowView {
                    title: playlist.name.clone(),
                    subtitle: playlist
                        .description
                        .as_deref()
                        .filter(|description| !description.is_empty())
                        .map_or_else(
                            || count.clone(),
                            |description| {
                                format!("{count} · {}", one_line_excerpt(description, 160))
                            },
                        ),
                    source: "Local playlist".to_owned(),
                    compact: true,
                    ..RowView::default()
                }
            })
            .collect();
        self.view.selected = self
            .playlist_selected
            .min(self.view.rows.len().saturating_sub(1));
        self.playlist_selected = self.view.selected;
        self.update_playlist_detail();
        self.view.status_line = if self.playlist_summaries.is_empty() {
            "No playlists yet; select a playable item and press P to create one".to_owned()
        } else {
            format!(
                "{} local playlist{}",
                self.playlist_summaries.len(),
                if self.playlist_summaries.len() == 1 {
                    ""
                } else {
                    "s"
                }
            )
        };
    }

    /// Rebuilds ordered media rows for the loaded playlist.
    fn populate_playlist_entries(&mut self) {
        let Some(playlist) = self.active_playlist.as_ref() else {
            self.view.rows.clear();
            self.view.details = None;
            return;
        };
        let playlist_name = playlist.name.clone();
        let playlist_entry_count = playlist.entries.len();
        self.view.rows = playlist
            .entries
            .iter()
            .map(|entry| {
                let live_stream = entry.media.kind == MediaKind::LiveStream;
                let playback = if live_stream {
                    PlaybackRowState::default()
                } else {
                    let progress = self.store.progress(&entry.media.id).ok().flatten();
                    PlaybackRowState::from_progress(progress.as_ref())
                };
                let mut metadata = Vec::with_capacity(3);
                if live_stream {
                    metadata.push("live".to_owned());
                } else {
                    if let Some(creator) = entry
                        .media
                        .creator
                        .as_deref()
                        .filter(|creator| !creator.is_empty())
                    {
                        metadata.push(creator.to_owned());
                    }
                    if let Some(duration) = entry.media.duration_seconds {
                        metadata.push(format_seconds(duration));
                    }
                    if entry.media.id.source == SourceKind::Local
                        && !Path::new(&entry.media.replay_locator).is_file()
                    {
                        metadata.push("Removed".to_owned());
                    }
                }
                RowView {
                    media_id: Some(entry.media.id.clone()),
                    title: entry.media.title.clone(),
                    subtitle: metadata.join(" · "),
                    source: if entry.media.id.source == SourceKind::Radio {
                        "Radio".to_owned()
                    } else {
                        entry.media.id.source.to_string()
                    },
                    watched_percent: playback.watched_percent,
                    playback_started: playback.playback_started,
                    thumbnail_url: entry.media.thumbnail_url.clone(),
                    hide_watched_marker: live_stream,
                    compact: true,
                    ..RowView::default()
                }
            })
            .collect();
        self.view.selected = self
            .playlist_entry_selected
            .min(self.view.rows.len().saturating_sub(1));
        self.playlist_entry_selected = self.view.selected;
        self.update_playlist_detail();
        self.view.status_line = format!(
            "{} item{} in {}",
            playlist_entry_count,
            if playlist_entry_count == 1 { "" } else { "s" },
            playlist_name
        );
    }

    /// Shows metadata for the selected playlist or its selected media entry.
    fn update_playlist_detail(&mut self) {
        match self.playlists_route {
            PlaylistsRoute::Index => {
                let Some(playlist) = self.playlist_summaries.get(self.view.selected) else {
                    self.view.details = None;
                    self.view.playlist_edit_available = false;
                    return;
                };
                let mut description = playlist.description.clone().unwrap_or_default();
                if !description.is_empty() {
                    description.push('\n');
                }
                description.push_str(&format!(
                    "{} item{}",
                    playlist.entry_count,
                    if playlist.entry_count == 1 { "" } else { "s" }
                ));
                self.view.details = Some(DetailView {
                    title: playlist.name.clone(),
                    source: "Local playlist".to_owned(),
                    description,
                    ..DetailView::default()
                });
                self.view.playlist_edit_available = true;
            }
            PlaylistsRoute::Entries { .. } => {
                let Some((playlist_name, entry)) =
                    self.active_playlist.as_ref().and_then(|playlist| {
                        Some((
                            playlist.name.clone(),
                            playlist.entries.get(self.view.selected)?.clone(),
                        ))
                    })
                else {
                    self.view.details = None;
                    self.view.playlist_edit_available = false;
                    return;
                };
                let mut description = entry
                    .media
                    .creator
                    .as_deref()
                    .filter(|creator| !creator.is_empty())
                    .map_or_else(String::new, |creator| format!("Creator: {creator}"));
                if !description.is_empty() {
                    description.push('\n');
                }
                description.push_str(&format!("Playlist: {playlist_name}"));
                let links = matches!(entry.media.webpage_url.scheme(), "http" | "https")
                    .then(|| DetailLinkView {
                        label: "Canonical media page".to_owned(),
                        url: entry.media.webpage_url.to_string(),
                        wikidata_item_id: None,
                    })
                    .into_iter()
                    .collect();
                let local_video_path = (entry.media.id.source == SourceKind::Local
                    && entry.media.kind == MediaKind::Video)
                    .then(|| PathBuf::from(&entry.media.replay_locator))
                    .filter(|path| path.is_file());
                let (local_video_thumbnail, metadata_pending) = local_video_path
                    .as_deref()
                    .map(|path| self.cached_local_video_thumbnail(path))
                    .unwrap_or((None, false));
                self.view.details = Some(DetailView {
                    media_id: Some(entry.media.id.clone()),
                    title: entry.media.title.clone(),
                    source: if entry.media.id.source == SourceKind::Radio {
                        "Radio".to_owned()
                    } else {
                        entry.media.id.source.to_string()
                    },
                    length: entry
                        .media
                        .duration_seconds
                        .map_or_else(String::new, format_seconds),
                    description,
                    thumbnail_url: entry.media.thumbnail_url.clone(),
                    local_video_thumbnail,
                    links,
                    ..DetailView::default()
                });
                self.view.playlist_edit_available = false;
                if metadata_pending && let Some(path) = local_video_path {
                    self.request_local_media_metadata(path);
                }
            }
        }
    }

    /// Opens the selected playlist or starts its selected persisted item.
    fn activate_playlist_selection(&mut self) {
        match self.playlists_route.clone() {
            PlaylistsRoute::Index => {
                let Some(summary) = self.playlist_summaries.get(self.view.selected).cloned() else {
                    self.view.status_line = "No playlist is selected".to_owned();
                    return;
                };
                let playlist = match self.store.playlist(&summary.id) {
                    Ok(Some(playlist)) => playlist,
                    Ok(None) => {
                        self.view.status_line =
                            "That playlist no longer exists; refreshing the list".to_owned();
                        self.populate_playlist_index();
                        return;
                    }
                    Err(error) => {
                        self.show_error("Cannot open playlist", &error);
                        return;
                    }
                };
                self.playlist_selected = self.view.selected;
                self.playlist_entry_selected = 0;
                self.playlists_route = PlaylistsRoute::Entries {
                    playlist_id: summary.id,
                };
                self.active_playlist = Some(playlist);
                self.view.selected = 0;
                self.populate_playlist_entries();
                self.refresh_selected_playlist_state();
            }
            PlaylistsRoute::Entries { .. } => {
                let Some(entry) = self
                    .active_playlist
                    .as_ref()
                    .and_then(|playlist| playlist.entries.get(self.view.selected))
                    .cloned()
                else {
                    self.view.status_line = "No playlist item is selected".to_owned();
                    return;
                };
                self.play_playlist_entry(entry);
            }
        }
    }

    /// Replays one stable playlist entry through its source-specific resolver.
    fn play_playlist_entry(&mut self, entry: PlaylistEntry) {
        if entry.media.id.source == SourceKind::Local {
            let path = PathBuf::from(&entry.media.replay_locator);
            if !path.is_absolute() || !path.is_file() {
                self.show_error_message(
                    "Playlist item is unavailable",
                    format!(
                        "The local file was removed or is not a regular file: {}",
                        path.display()
                    ),
                );
                return;
            }
            let item = match queue_item_from_local(&local_media_item(path)) {
                Ok(item) => item,
                Err(error) => {
                    self.show_error_message("Playlist item is unavailable", error);
                    return;
                }
            };
            self.play_queue_item(item, false);
            return;
        }

        if entry.media.id.source == SourceKind::Bandcamp {
            #[cfg(feature = "bandcamp")]
            {
                let summary = BandcampSearchSummary {
                    id: entry.media.id.clone(),
                    kind: BandcampReleaseKind::Track,
                    title: entry.media.title.clone(),
                    artist: entry.media.creator.clone(),
                    webpage_url: entry.media.webpage_url.clone(),
                    artwork_url: entry.media.thumbnail_url.clone(),
                };
                self.request_bandcamp_resolution(
                    summary,
                    BandcampResolutionOwner::Playlist(Box::new(entry)),
                );
                return;
            }
            #[cfg(not(feature = "bandcamp"))]
            {
                self.view.status_line =
                    "This build omits Bandcamp; rebuild with that feature to play this item"
                        .to_owned();
                return;
            }
        }

        if matches!(
            entry.media.id.source,
            SourceKind::ApplePodcasts
                | SourceKind::BbcRadio
                | SourceKind::SoundStream
                | SourceKind::LitRes
                | SourceKind::Jamendo
        ) {
            self.resolve_playlist_entry(entry);
            return;
        }

        let item = match queue_item_from_playlist_entry(&entry) {
            Ok(item) => item,
            Err(error) => {
                self.show_error_message("Playlist item is unavailable", error);
                return;
            }
        };
        self.play_queue_item(item, false);
    }

    /// Resolves one canonical first-class provider page before playlist replay.
    fn resolve_playlist_entry(&mut self, entry: PlaylistEntry) {
        let url = match url::Url::parse(&entry.media.replay_locator) {
            Ok(url) => url,
            Err(_) => {
                self.show_error_message(
                    "Playlist item is unavailable",
                    "The saved provider page is not a valid URL",
                );
                return;
            }
        };
        self.supersede_search_generation();
        let generation = self.search_generation;
        let source = entry.media.id.source.clone();
        self.pending_playlist_replay = Some(PendingPlaylistReplay { generation, entry });
        let request = if source == SourceKind::ApplePodcasts {
            ProviderRequest::ResolveApple { generation, url }
        } else {
            ProviderRequest::ResolveFirstClass {
                generation,
                direct: DirectSourceInput {
                    url,
                    source: source.clone(),
                },
            }
        };
        if !self.send_provider_request(request, "Could not resolve the playlist item") {
            self.pending_playlist_replay = None;
            return;
        }
        self.begin_playback_start_activity();
        self.view.status_line = format!(
            "Resolving {} for playlist playback…",
            direct_source_label(&source)
        );
    }

    /// Consumes one source response only while its playlist entry remains selected.
    fn finish_playlist_replay(
        &mut self,
        generation: u64,
        source: &SourceKind,
        result: &Result<ResolvedDirectMedia, String>,
    ) -> bool {
        let matches_pending = self
            .pending_playlist_replay
            .as_ref()
            .is_some_and(|pending| {
                pending.generation == generation && &pending.entry.media.id.source == source
            });
        if !matches_pending {
            return false;
        }
        let pending = self
            .pending_playlist_replay
            .take()
            .expect("matching playlist replay was checked above");
        self.clear_playback_start_activity();
        let still_selected = generation == self.search_generation
            && self.view.screen == Screen::Playlists
            && matches!(self.playlists_route, PlaylistsRoute::Entries { .. })
            && self
                .active_playlist
                .as_ref()
                .and_then(|playlist| playlist.entries.get(self.view.selected))
                .is_some_and(|selected| {
                    selected.media.id == pending.entry.media.id
                        && selected.added_at == pending.entry.added_at
                });
        if !still_selected {
            return true;
        }
        let media = match result {
            Ok(media) => media,
            Err(error) => {
                self.show_error_message("Playlist item could not be resolved", error);
                return true;
            }
        };
        let item = match queue_item_from_resolved(media) {
            Ok(item) => item,
            Err(error) => {
                self.show_error_message("Playlist item is unavailable", error);
                return true;
            }
        };
        if item.media.id != pending.entry.media.id {
            self.show_error_message(
                "Playlist item could not be resolved",
                "The provider page resolved to a different media identifier; the playlist entry was kept",
            );
            return true;
        }
        self.play_queue_item(item, false);
        true
    }

    /// Reloads the active playlist route and selected-item membership.
    fn refresh_playlists_after_mutation(&mut self, _media_id: Option<&MediaId>) {
        if self.view.screen == Screen::Playlists {
            self.populate_playlists_screen();
        }
        self.refresh_selected_playlist_state();
    }

    fn populate_subscriptions(&mut self) {
        #[cfg(feature = "yt-dlp")]
        self.cancel_youtube_prewarm();
        match subscriptions::load(&self.config) {
            Ok(tree) => self.subscription_tree = tree,
            Err(error) => {
                self.show_error("Cannot load subscriptions", &error);
                return;
            }
        }
        self.subscription_entries = self.subscription_tree.flattened_subscriptions();
        self.rebuild_subscription_source_rows();
        self.restore_cached_subscription_source_metadata();
        self.view.subscriptions.selected_source = self
            .view
            .subscriptions
            .selected_source
            .min(self.subscription_entries.len().saturating_sub(1));
        self.view.subscriptions.route = SubscriptionRoute::Sources;
        self.view.subscriptions.focus = SubscriptionPane::Sources;
        self.view.subscriptions.description_expanded = false;
        self.view.subscriptions.loading = false;
        self.view.subscriptions.items.clear();
        self.view.subscriptions.selected_item = 0;
        self.active_subscription_channel_id = None;
        #[cfg(feature = "rss")]
        {
            self.active_subscription_rss_url = None;
            self.pending_rss_subscription_refresh = None;
        }
        self.pending_subscription_refresh = None;
        self.subscription_generation = self.subscription_generation.wrapping_add(1);
        self.channel_details_generation = self.channel_details_generation.wrapping_add(1);
        self.scheduled_channel_details = None;
        self.update_selected_subscription_source();
        self.view.status_line = format!(
            "{} local subscription(s)",
            self.subscription_tree.subscription_count()
        );
        if self.view.subscriptions.layout == SubscriptionsLayout::Split
            && !self.subscription_entries.is_empty()
        {
            self.show_cached_selected_subscription_videos();
        }
        self.refresh_selected_playlist_state();
    }

    /// Rebuilds source rows with process-local or portable channel webpages.
    fn rebuild_subscription_source_rows(&mut self) {
        self.view.subscriptions.sources = self
            .subscription_entries
            .iter()
            .map(|entry| {
                let webpage_url = entry
                    .subscription
                    .youtube_channel_id()
                    .and_then(|channel_id| self.channel_webpage_cache.get(&channel_id).cloned());
                subscription_source_row(entry, webpage_url)
            })
            .collect();
    }

    /// Restores known channel artwork and aliases for every subscription source.
    ///
    /// Reading compact local state-cache records here lets the thumbnail worker
    /// warm image bytes and render human-readable URLs before keyboard or mouse
    /// navigation selects another channel. Provider requests remain lazy and
    /// independently debounced.
    fn restore_cached_subscription_source_metadata(&mut self) {
        let channel_rows = self
            .subscription_entries
            .iter()
            .enumerate()
            .filter_map(|(index, entry)| {
                entry
                    .subscription
                    .youtube_channel_id()
                    .map(|channel_id| (index, channel_id))
            })
            .collect::<Vec<_>>();
        for (index, channel_id) in channel_rows {
            let cached = match self.store.cached_channel_summary(&channel_id) {
                Ok(cached) => cached,
                Err(error) => {
                    self.show_error("Could not read cached channel metadata", &error);
                    return;
                }
            };
            let Some(cached) = cached else {
                continue;
            };
            self.cache_channel_webpage_url(&channel_id, cached.summary.webpage_url.clone());
            if let Some(row) = self.view.subscriptions.sources.get_mut(index) {
                row.thumbnail_url = preferred_thumbnail_url(&cached.summary.thumbnails);
            }
        }
    }

    fn update_selected_subscription_source(&mut self) {
        let Some(entry) = self
            .subscription_entries
            .get(self.view.subscriptions.selected_source)
            .cloned()
        else {
            self.view.details = None;
            self.view.subscriptions.source_title.clear();
            self.view.subscriptions.source_subscriber_count = None;
            self.view.subscriptions.source_created.clear();
            return;
        };
        let subscription = entry.subscription;
        self.view.subscriptions.source_kind = subscription.kind;
        let channel_id = subscription.youtube_channel_id().unwrap_or_default();
        let channel_webpage_url = (subscription.kind == SubscriptionKind::YouTube)
            .then(|| {
                self.cached_channel_webpage_url(&channel_id).or_else(|| {
                    youtube_channel_webpage_url(&channel_id, subscription.website_url.clone())
                })
            })
            .flatten();
        #[cfg(feature = "rss")]
        let rss_info = (subscription.kind == SubscriptionKind::Rss)
            .then(|| {
                self.rss_feed_info_cache
                    .get(subscription.url.as_str())
                    .cloned()
            })
            .flatten();
        #[cfg(not(feature = "rss"))]
        let rss_info: Option<()> = None;
        #[cfg(feature = "rss")]
        let source_title = rss_info
            .as_ref()
            .and_then(|info| info.title.as_deref())
            .filter(|title| !title.trim().is_empty())
            .unwrap_or(&subscription.title)
            .to_owned();
        #[cfg(not(feature = "rss"))]
        let source_title = subscription.title.clone();
        self.view.subscriptions.source_title = source_title.clone();
        let cached_subscribers = self
            .channel_subscriber_cache
            .get(&channel_id)
            .copied()
            .flatten();
        self.view.subscriptions.source_subscriber_count = cached_subscribers;
        self.view.subscriptions.source_created.clear();
        #[cfg(feature = "rss")]
        let description = if let Some(info) = rss_info.as_ref() {
            rss_feed_detail_text(info, subscription.description.as_deref())
        } else {
            subscription.description.clone().unwrap_or_else(|| {
                if subscription.kind == SubscriptionKind::YouTube {
                    "Loading channel description…".to_owned()
                } else {
                    "Press Enter to load episodes".to_owned()
                }
            })
        };
        #[cfg(not(feature = "rss"))]
        let description = subscription.description.clone().unwrap_or_else(|| {
            if subscription.kind == SubscriptionKind::YouTube {
                "Loading channel description…".to_owned()
            } else {
                "Press Enter to load episodes".to_owned()
            }
        });
        #[cfg(feature = "rss")]
        let links = rss_info
            .as_ref()
            .and_then(|info| info.webpage_url.as_ref())
            .map(|url| {
                vec![DetailLinkView {
                    label: "Podcast website".to_owned(),
                    url: url.to_string(),
                    wikidata_item_id: None,
                }]
            })
            .unwrap_or_default();
        #[cfg(not(feature = "rss"))]
        let links = Vec::new();
        self.view.details = Some(DetailView {
            title: source_title.clone(),
            source: subscription_kind_label(subscription.kind).to_owned(),
            channel_name: source_title,
            channel_id: channel_id.clone(),
            channel_webpage_url,
            channel_subscribed: true,
            channel_subscriber_count: cached_subscribers,
            description,
            #[cfg(feature = "rss")]
            thumbnail_url: rss_info.as_ref().and_then(|info| info.artwork_url.clone()),
            links,
            ..DetailView::default()
        });
        self.view.right_panel_mode = RightPanelMode::Channel;
        self.view.details_scroll = 0;
        if subscription.kind == SubscriptionKind::YouTube {
            self.schedule_selected_subscription_channel_details(Instant::now());
        }
    }

    fn select_subscription_source(&mut self, index: usize) {
        if index >= self.subscription_entries.len() {
            return;
        }
        #[cfg(feature = "yt-dlp")]
        self.cancel_youtube_prewarm();
        self.view.subscriptions.selected_source = index;
        self.view.subscriptions.selected_item = 0;
        self.view.subscriptions.description_expanded = false;
        self.view.subscriptions.focus = SubscriptionPane::Sources;
        self.view.subscriptions.loading = false;
        self.view.subscriptions.items.clear();
        self.view.selected_detail_link = None;
        self.active_subscription_channel_id = None;
        #[cfg(feature = "rss")]
        {
            self.active_subscription_rss_url = None;
            self.pending_rss_subscription_refresh = None;
        }
        self.pending_subscription_refresh = None;
        self.subscription_generation = self.subscription_generation.wrapping_add(1);
        self.channel_details_generation = self.channel_details_generation.wrapping_add(1);
        self.scheduled_channel_details = None;
        self.update_selected_subscription_source();
        if self.view.subscriptions.layout == SubscriptionsLayout::Split {
            self.show_cached_selected_subscription_videos();
        }
        self.refresh_selected_playlist_state();
    }

    /// Shows cached split-view rows without spending quota while sources move.
    ///
    /// An uncached source remains explicit: Enter starts its provider request.
    fn show_cached_selected_subscription_videos(&mut self) {
        let Some(entry) = self
            .subscription_entries
            .get(self.view.subscriptions.selected_source)
        else {
            return;
        };
        #[cfg(feature = "rss")]
        if entry.subscription.kind == SubscriptionKind::Rss {
            let source_url = entry.subscription.url.to_string();
            self.active_subscription_rss_url = Some(source_url.clone());
            self.restore_rss_subscription_snapshot(&source_url);
            if self.subscription_video_cache.contains_key(&source_url) {
                self.touch_subscription_cache(&source_url);
                self.refresh_subscription_video_rows();
                self.view.status_line = format!(
                    "{} cached episode{} for {}",
                    self.view.subscriptions.items.len(),
                    if self.view.subscriptions.items.len() == 1 {
                        ""
                    } else {
                        "s"
                    },
                    self.view.subscriptions.source_title
                );
            } else {
                self.view.status_line = format!(
                    "Press Enter to load episodes for {}",
                    self.view.subscriptions.source_title
                );
            }
            return;
        }
        if entry.subscription.kind != SubscriptionKind::YouTube {
            self.view.status_line =
                "This subscription format has no episode provider in this build".to_owned();
            return;
        }
        let Some(channel_id) = entry.subscription.youtube_channel_id() else {
            self.view.status_line =
                "This imported YouTube source has no exact channel ID to load".to_owned();
            return;
        };
        self.active_subscription_channel_id = Some(channel_id.clone());
        self.restore_subscription_video_snapshot(&channel_id);
        if self.subscription_video_cache.contains_key(&channel_id) {
            self.touch_subscription_cache(&channel_id);
            self.refresh_subscription_video_rows();
            self.view.status_line = format!(
                "{} cached video{} for {}",
                self.view.subscriptions.items.len(),
                if self.view.subscriptions.items.len() == 1 {
                    ""
                } else {
                    "s"
                },
                self.view.subscriptions.source_title
            );
        } else {
            self.view.status_line = format!(
                "Press Enter to load videos for {}",
                self.view.subscriptions.source_title
            );
        }
    }

    fn select_subscription_item(&mut self, index: usize) {
        if index >= self.view.subscriptions.items.len() {
            return;
        }
        self.view.subscriptions.selected_item = index;
        self.view.selected_detail_link = None;
        let selected_video_id = self
            .selected_subscription_item()
            .and_then(|item| match item {
                SearchItem::Video(video) => Some(video.video_id.clone()),
                SearchItem::Channel(_) | SearchItem::PodcastEpisode(_) => None,
            });
        if let Some(pending) = self.pending_subscription_refresh.as_mut()
            && self.active_subscription_channel_id.as_deref() == Some(pending.channel_id.as_str())
        {
            // A deliberate selection made while refresh is in flight takes
            // precedence over the snapshot captured when refresh started.
            pending.selected_video_id = selected_video_id;
            pending.fallback_index = index;
        }
        self.view.subscriptions.focus = SubscriptionPane::Items;
        self.view.right_panel_mode = RightPanelMode::Details;
        if matches!(
            self.selected_subscription_item(),
            Some(SearchItem::PodcastEpisode(_))
        ) {
            self.update_selected_rss_episode_detail();
        } else {
            self.request_selected_details();
        }
        self.load_next_subscription_page_if_needed();
        self.refresh_selected_playlist_state();
    }

    fn load_selected_subscription_videos(&mut self) {
        let Some(entry) = self
            .subscription_entries
            .get(self.view.subscriptions.selected_source)
        else {
            return;
        };
        #[cfg(feature = "rss")]
        if entry.subscription.kind == SubscriptionKind::Rss {
            let source_url = entry.subscription.url.to_string();
            self.active_subscription_channel_id = None;
            self.active_subscription_rss_url = Some(source_url.clone());
            self.restore_rss_subscription_snapshot(&source_url);
            if self.subscription_video_cache.contains_key(&source_url) {
                self.touch_subscription_cache(&source_url);
                self.refresh_subscription_video_rows();
                if !self.view.subscriptions.items.is_empty()
                    && (self.view.subscriptions.layout == SubscriptionsLayout::DrillDown
                        || self.view.subscriptions.focus == SubscriptionPane::Items)
                {
                    self.update_selected_rss_episode_detail();
                }
                self.refresh_selected_rss_subscription_with_feedback(false);
                self.refresh_selected_playlist_state();
                return;
            }
            self.request_rss_subscription(source_url);
            self.refresh_selected_playlist_state();
            return;
        }
        if entry.subscription.kind != SubscriptionKind::YouTube {
            self.view.subscriptions.items.clear();
            self.active_subscription_channel_id = None;
            self.view.status_line =
                "This subscription format has no episode provider in this build".to_owned();
            return;
        }
        let Some(channel_id) = entry.subscription.youtube_channel_id() else {
            self.view.subscriptions.items.clear();
            self.active_subscription_channel_id = None;
            self.view.status_line =
                "This imported YouTube source has no exact channel ID to load".to_owned();
            return;
        };
        self.active_subscription_channel_id = Some(channel_id.clone());
        self.restore_subscription_video_snapshot(&channel_id);
        if self.subscription_video_cache.contains_key(&channel_id) {
            self.touch_subscription_cache(&channel_id);
            self.refresh_subscription_video_rows();
            if !self.view.subscriptions.items.is_empty()
                && (self.view.subscriptions.layout == SubscriptionsLayout::DrillDown
                    || self.view.subscriptions.focus == SubscriptionPane::Items)
            {
                self.request_selected_details();
            }
            self.refresh_selected_subscription_videos_with_feedback(false);
            self.refresh_selected_playlist_state();
            return;
        }
        self.request_subscription_videos(channel_id, 1);
        self.refresh_selected_playlist_state();
    }

    /// Hydrates one compact RSS episode snapshot before network refresh.
    #[cfg(feature = "rss")]
    fn restore_rss_subscription_snapshot(&mut self, source_url: &str) {
        if self.subscription_video_cache.contains_key(source_url) {
            return;
        }
        let snapshot = match self
            .store
            .cached_subscription_items(&SourceKind::Rss, source_url)
        {
            Ok(snapshot) => snapshot,
            Err(error) => {
                self.show_error("Could not read cached podcast episodes", &error);
                return;
            }
        };
        let Some(mut snapshot) = snapshot else {
            return;
        };
        snapshot
            .items
            .retain(|item| matches!(item, SearchItem::PodcastEpisode(_)));
        for item in &mut snapshot.items {
            if let SearchItem::PodcastEpisode(episode) = item {
                episode.stream_url = None;
            }
        }
        self.subscription_video_cache.insert(
            source_url.to_owned(),
            CachedSubscriptionVideos {
                items: snapshot.items,
                next_page: None,
                consecutive_empty_pages: 0,
            },
        );
        self.touch_subscription_cache(source_url);
        self.enforce_subscription_cache_byte_budget(source_url);
    }

    /// Replaces the restart snapshot with current compact RSS episodes.
    #[cfg(feature = "rss")]
    fn persist_rss_subscription_snapshot(
        &self,
        source_url: &str,
    ) -> Result<(), crate::persistence::PersistenceError> {
        let mut items: Vec<SearchItem> = self
            .subscription_video_cache
            .get(source_url)
            .map_or(&[][..], |cached| cached.items.as_slice())
            .iter()
            .filter(|item| matches!(item, SearchItem::PodcastEpisode(_)))
            .take(MAX_SAVED_SUBSCRIPTION_ITEMS)
            .cloned()
            .collect();
        for item in &mut items {
            if let SearchItem::PodcastEpisode(episode) = item {
                episode.stream_url = None;
            }
        }
        self.store
            .put_cached_subscription_items(&CachedSubscriptionItems {
                source: SourceKind::Rss,
                source_id: source_url.to_owned(),
                items,
                fetched_at: unix_time(),
            })
    }

    /// Queues one guarded whole-feed request on the isolated RSS worker.
    #[cfg(feature = "rss")]
    fn request_rss_subscription(&mut self, source_url: String) {
        if self.view.subscriptions.loading {
            return;
        }
        let source = match url::Url::parse(&source_url) {
            Ok(source) => source,
            Err(error) => {
                self.show_error_message("Podcast feed failed", error.to_string());
                return;
            }
        };
        self.subscription_generation = self.subscription_generation.wrapping_add(1);
        if !self.send_provider_request(
            ProviderRequest::RssFeed {
                generation: self.subscription_generation,
                source_url: source,
            },
            "Could not load podcast episodes",
        ) {
            return;
        }
        self.view.subscriptions.loading = true;
        self.view.status_line = format!(
            "Loading episodes for {}…",
            self.view.subscriptions.source_title
        );
    }

    /// Reloads the active RSS source without blanking its cached rows.
    #[cfg(feature = "rss")]
    fn refresh_selected_rss_subscription_with_feedback(&mut self, report_errors: bool) {
        if self.view.subscriptions.loading {
            if report_errors {
                self.view.status_line = "Podcast episodes are already loading".to_owned();
            }
            return;
        }
        let Some(source_url) = self.active_subscription_rss_url.clone() else {
            if report_errors {
                self.view.status_line =
                    "Open a subscribed podcast before refreshing episodes".to_owned();
            }
            return;
        };
        let selected_external_id = self
            .selected_subscription_item()
            .and_then(subscription_item_media_id)
            .map(|media_id| media_id.external_id);
        self.pending_rss_subscription_refresh = Some(PendingRssSubscriptionRefresh {
            source_url: source_url.clone(),
            selected_external_id,
            fallback_index: self.view.subscriptions.selected_item,
            report_errors,
        });
        self.request_rss_subscription(source_url);
        if self.view.subscriptions.loading {
            self.view.status_line = format!(
                "Refreshing episodes for {}…",
                self.view.subscriptions.source_title
            );
        } else {
            self.pending_rss_subscription_refresh = None;
        }
    }

    /// Rebuilds Details directly from the selected RSS episode summary.
    fn update_selected_rss_episode_detail(&mut self) {
        #[cfg(feature = "rss")]
        {
            let Some(SearchItem::PodcastEpisode(episode)) =
                self.selected_subscription_item().cloned()
            else {
                return;
            };
            let mut detail = detail_from_podcast_episode(&episode);
            preserve_thumbnail_expansion(self.view.details.as_ref(), &mut detail);
            self.view.details = Some(detail);
            self.view.details_scroll = 0;
            self.view.selected_detail_link = None;
        }
    }

    /// Hydrates one compact first-page channel snapshot before network refresh.
    ///
    /// Invalid or unavailable disk rows are reported through the normal
    /// recoverable-error popup. A process-local cache always wins because it
    /// may already contain later pages loaded during this session.
    fn restore_subscription_video_snapshot(&mut self, channel_id: &str) {
        if self.subscription_video_cache.contains_key(channel_id) {
            return;
        }
        let snapshot = match self
            .store
            .cached_subscription_items(&SourceKind::YouTube, channel_id)
        {
            Ok(snapshot) => snapshot,
            Err(error) => {
                self.show_error("Could not read cached subscription videos", &error);
                return;
            }
        };
        let Some(mut snapshot) = snapshot else {
            return;
        };
        for item in &mut snapshot.items {
            if let SearchItem::Video(video) = item {
                // Direct provider streams can expire between processes and may
                // contain signed query material. Only the canonical page is
                // restart-safe; lazy details obtains a current stream.
                video.stream_url = None;
            }
        }
        self.subscription_video_cache.insert(
            channel_id.to_owned(),
            CachedSubscriptionVideos {
                items: snapshot.items,
                next_page: None,
                consecutive_empty_pages: 0,
            },
        );
        self.touch_subscription_cache(channel_id);
        self.enforce_subscription_cache_byte_budget(channel_id);
    }

    /// Replaces the restart snapshot with the current compact first page.
    ///
    /// Later in-memory pages remain process-local. This keeps restart cost and
    /// database growth bounded while page-one refreshes still reconcile
    /// episodes removed by the provider.
    fn persist_subscription_video_snapshot(
        &self,
        channel_id: &str,
    ) -> Result<(), crate::persistence::PersistenceError> {
        let mut items: Vec<SearchItem> = self
            .subscription_video_cache
            .get(channel_id)
            .map_or(&[][..], |cached| cached.items.as_slice())
            .iter()
            .take(MAX_SAVED_SUBSCRIPTION_ITEMS)
            .cloned()
            .collect();
        for item in &mut items {
            if let SearchItem::Video(video) = item {
                video.stream_url = None;
            }
        }
        self.store
            .put_cached_subscription_items(&CachedSubscriptionItems {
                source: SourceKind::YouTube,
                source_id: channel_id.to_owned(),
                items,
                fetched_at: unix_time(),
            })
    }

    /// Queues one guarded sequential channel page and marks the pane loading.
    fn request_subscription_videos(&mut self, channel_id: String, page: u32) {
        let report_errors = self
            .pending_subscription_refresh
            .as_ref()
            .filter(|pending| pending.channel_id == channel_id)
            .is_none_or(|pending| pending.report_errors);
        if !self.youtube_provider_available {
            if report_errors {
                self.open_youtube_setup();
            } else {
                self.view.status_line = format!(
                    "Showing cached videos for {}; press R to configure or refresh",
                    self.view.subscriptions.source_title
                );
                self.pending_subscription_refresh = None;
            }
            return;
        }
        if self.view.subscriptions.loading {
            return;
        }
        self.subscription_generation = self.subscription_generation.wrapping_add(1);
        let request = ChannelVideosRequest { channel_id, page };
        let provider_request = ProviderRequest::ChannelVideos {
            generation: self.subscription_generation,
            request,
        };
        let sent = if report_errors {
            self.send_provider_request(provider_request, "Could not load subscription videos")
        } else {
            self.provider_requests
                .as_ref()
                .is_some_and(|sender| sender.send(provider_request).is_ok())
        };
        if !sent {
            if !report_errors {
                self.view.status_line = format!(
                    "Showing cached videos for {}; background refresh is unavailable",
                    self.view.subscriptions.source_title
                );
                self.pending_subscription_refresh = None;
            }
            return;
        }
        self.view.subscriptions.loading = true;
        self.view.status_line = format!(
            "Loading videos for {}…",
            self.view.subscriptions.source_title
        );
    }

    /// Reloads page one for the active channel without blanking cached rows.
    ///
    /// The current video identity remains visible while the provider works and
    /// is restored after replacement when the refreshed page still contains
    /// it. A second request is ignored until the first one completes.
    fn refresh_selected_subscription_videos(&mut self) {
        #[cfg(feature = "rss")]
        if self.active_subscription_rss_url.is_some() {
            self.refresh_selected_rss_subscription_with_feedback(true);
            return;
        }
        self.refresh_selected_subscription_videos_with_feedback(true);
    }

    /// Reloads page one while choosing whether failures may cover cached rows.
    ///
    /// Cache-restoration refreshes are best-effort: an unavailable provider or
    /// worker leaves the restored rows usable. Explicit `[R]` refreshes retain
    /// the setup and diagnostic flow because the user requested fresh data.
    fn refresh_selected_subscription_videos_with_feedback(&mut self, report_errors: bool) {
        if self.view.screen != Screen::Subscriptions {
            if report_errors {
                self.view.status_line =
                    "Subscription videos can be refreshed only inside a channel".to_owned();
            }
            return;
        }
        if self.view.subscriptions.loading {
            if report_errors {
                self.view.status_line = "Subscription videos are already loading".to_owned();
            }
            return;
        }
        let Some(channel_id) = self.active_subscription_channel_id.clone() else {
            if report_errors {
                self.view.status_line =
                    "Open a subscribed channel before refreshing videos".to_owned();
            }
            return;
        };
        if !report_errors && (!self.youtube_provider_available || self.provider_requests.is_none())
        {
            self.view.status_line = format!(
                "Showing cached videos for {}; press R to configure or refresh",
                self.view.subscriptions.source_title
            );
            return;
        }
        let selected_video_id = self
            .selected_subscription_item()
            .and_then(|item| match item {
                SearchItem::Video(video) => Some(video.video_id.clone()),
                SearchItem::Channel(_) | SearchItem::PodcastEpisode(_) => None,
            });
        self.pending_subscription_refresh = Some(PendingSubscriptionRefresh {
            channel_id: channel_id.clone(),
            selected_video_id,
            fallback_index: self.view.subscriptions.selected_item,
            staged_cache: None,
            report_errors,
        });
        self.request_subscription_videos(channel_id, 1);
        if self.view.subscriptions.loading {
            self.view.status_line = format!(
                "Refreshing videos for {}…",
                self.view.subscriptions.source_title
            );
        } else {
            self.pending_subscription_refresh = None;
        }
    }

    /// Restores the pre-refresh selection after page one replaces the cache.
    fn restore_subscription_refresh_selection(&mut self, channel_id: &str) {
        let Some(pending) = self
            .pending_subscription_refresh
            .take()
            .filter(|pending| pending.channel_id == channel_id)
        else {
            return;
        };
        let refreshed = self
            .subscription_video_cache
            .get(channel_id)
            .map_or(&[][..], |cached| cached.items.as_slice());
        let selected = pending
            .selected_video_id
            .as_deref()
            .and_then(|video_id| {
                refreshed.iter().position(|item| {
                    matches!(
                        item,
                        SearchItem::Video(video) if video.video_id == video_id
                    )
                })
            })
            .unwrap_or_else(|| {
                pending
                    .fallback_index
                    .min(refreshed.len().saturating_sub(1))
            });
        self.view.subscriptions.selected_item = selected;
    }

    /// Loads the next page near the visible end or after empty-list Enter.
    fn load_next_subscription_page_if_needed(&mut self) {
        if self.view.subscriptions.loading
            || self.view.subscriptions.selected_item.saturating_add(2)
                < self.view.subscriptions.items.len()
        {
            return;
        }
        let Some(channel_id) = self.active_subscription_channel_id.clone() else {
            return;
        };
        let next_page = self
            .subscription_video_cache
            .get(&channel_id)
            .and_then(|cached| cached.next_page);
        if let Some(page) = next_page {
            self.request_subscription_videos(channel_id, page);
        }
    }

    /// Replaces page one or appends a later page within the per-channel cap.
    ///
    /// Touching the separate order deque maintains bounded LRU eviction across
    /// channels. Empty pages retain their continuation because private videos
    /// can otherwise hide a later playable page.
    fn cache_subscription_video_page(&mut self, channel_id: &str, page: SearchPage) {
        if page.page == 1 && !self.subscription_video_cache.contains_key(channel_id) {
            while self.subscription_video_cache.len() >= MAX_CACHED_SUBSCRIPTION_CHANNELS {
                let Some(oldest) = self.subscription_cache_order.pop_front() else {
                    break;
                };
                if oldest != channel_id {
                    self.subscription_video_cache.remove(&oldest);
                }
            }
        }
        let cached = self
            .subscription_video_cache
            .entry(channel_id.to_owned())
            .or_default();
        Self::apply_subscription_video_page(cached, page);
        self.touch_subscription_cache(channel_id);
        self.enforce_subscription_cache_byte_budget(channel_id);
    }

    /// Applies one validated sequential page to a bounded cache value.
    fn apply_subscription_video_page(cached: &mut CachedSubscriptionVideos, mut page: SearchPage) {
        if page.page == 1 {
            cached.items.clear();
            cached.consecutive_empty_pages = 0;
        }
        for item in &mut page.items {
            compact_subscription_item(item);
        }
        let remaining =
            MAX_CACHED_SUBSCRIPTION_VIDEOS_PER_CHANNEL.saturating_sub(cached.items.len());
        let page_is_empty = page.items.is_empty();
        cached.items.extend(page.items.into_iter().take(remaining));
        cached.consecutive_empty_pages = if page_is_empty {
            cached.consecutive_empty_pages.saturating_add(1)
        } else {
            0
        };
        cached.next_page = (cached.items.len() < MAX_CACHED_SUBSCRIPTION_VIDEOS_PER_CHANNEL)
            .then_some(page.next_page)
            .flatten();
    }

    /// Evicts least-recently-used channels until the shared byte budget holds.
    fn enforce_subscription_cache_byte_budget(&mut self, preserved_channel_id: &str) {
        while self.subscription_cache_estimated_heap_bytes() > MAX_CACHED_SUBSCRIPTION_BYTES
            && self.subscription_video_cache.len() > 1
        {
            let Some(eviction_index) = self
                .subscription_cache_order
                .iter()
                .position(|channel_id| channel_id != preserved_channel_id)
            else {
                break;
            };
            let Some(oldest) = self.subscription_cache_order.remove(eviction_index) else {
                break;
            };
            self.subscription_video_cache.remove(&oldest);
        }
    }

    /// Returns the approximate heap bytes owned by all channel summaries.
    fn subscription_cache_estimated_heap_bytes(&self) -> usize {
        self.subscription_video_cache
            .values()
            .map(CachedSubscriptionVideos::estimated_heap_bytes)
            .fold(0usize, usize::saturating_add)
    }

    fn touch_subscription_cache(&mut self, channel_id: &str) {
        self.subscription_cache_order
            .retain(|cached| cached != channel_id);
        self.subscription_cache_order
            .push_back(channel_id.to_owned());
    }

    fn refresh_subscription_video_rows(&mut self) {
        let today = Local::now().date_naive();
        let active_source_id = self.active_subscription_channel_id.as_deref().or_else(|| {
            #[cfg(feature = "rss")]
            {
                self.active_subscription_rss_url.as_deref()
            }
            #[cfg(not(feature = "rss"))]
            {
                None
            }
        });
        let items = self
            .subscription_video_cache
            .get(active_source_id.unwrap_or_default())
            .map_or(&[][..], |cached| cached.items.as_slice());
        self.view.subscriptions.items = items
            .iter()
            .map(|item| {
                row_from_search_item(
                    item,
                    &self.store,
                    &self.subscription_tree,
                    &self.channel_subscriber_cache,
                    SearchRowContext::SubscriptionFeed,
                    today,
                )
            })
            .collect();
        self.view.subscriptions.selected_item = self
            .view
            .subscriptions
            .selected_item
            .min(self.view.subscriptions.items.len().saturating_sub(1));
    }

    fn selected_subscription_item(&self) -> Option<&SearchItem> {
        let source_id = self.active_subscription_channel_id.as_deref().or_else(|| {
            #[cfg(feature = "rss")]
            {
                self.active_subscription_rss_url.as_deref()
            }
            #[cfg(not(feature = "rss"))]
            {
                None
            }
        })?;
        self.subscription_video_cache
            .get(source_id)?
            .items
            .get(self.view.subscriptions.selected_item)
    }

    fn selected_youtube_item(&self) -> Option<&SearchItem> {
        match self.view.screen {
            Screen::Search
                if self.local_results.is_empty()
                    && self.direct_item.is_none()
                    && self.resolved_direct.is_none() =>
            {
                self.youtube_results.get(self.view.selected)
            }
            Screen::YouTubeMusic => self.youtube_music_results.get(self.view.selected),
            Screen::Subscriptions
                if self.view.subscriptions.route == SubscriptionRoute::Items
                    || (self.view.subscriptions.layout == SubscriptionsLayout::Split
                        && self.view.subscriptions.focus == SubscriptionPane::Items) =>
            {
                self.selected_subscription_item()
                    .filter(|item| !matches!(item, SearchItem::PodcastEpisode(_)))
            }
            _ => None,
        }
    }

    fn populate_downloads(&mut self) {
        self.view.rows.clear();
        self.view.details = None;
        let path = self.config.downloads_dir();
        let entries = match std::fs::read_dir(&path) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                self.view.status_line = "No downloaded media yet".to_owned();
                return;
            }
            Err(error) => {
                self.show_error("Cannot read the downloads directory", &error);
                return;
            }
        };
        let mut read_failures = Vec::new();
        for entry in entries {
            let entry = match entry {
                Ok(entry) => entry,
                Err(error) => {
                    read_failures.push(error.to_string());
                    continue;
                }
            };
            let file_type = match entry.file_type() {
                Ok(file_type) => file_type,
                Err(error) => {
                    read_failures.push(format!("{}: {error}", entry.file_name().to_string_lossy()));
                    continue;
                }
            };
            if !file_type.is_file() {
                continue;
            }
            let entry_path = entry.path();
            if !is_supported_media_path(&entry_path.to_string_lossy()) {
                continue;
            }
            let size = match entry.metadata() {
                Ok(metadata) => metadata.len(),
                Err(error) => {
                    read_failures.push(format!("{}: {error}", entry.file_name().to_string_lossy()));
                    continue;
                }
            };
            self.view.rows.push(RowView {
                media_id: Some(MediaId::new(
                    SourceKind::Local,
                    entry_path.display().to_string(),
                )),
                title: entry.file_name().to_string_lossy().into_owned(),
                subtitle: human_bytes(size),
                source: "Local download".to_owned(),
                ..RowView::default()
            });
        }
        hydrate_row_playback_progress(&self.store, &mut self.view.rows);
        self.view.status_line = format!("{} downloaded file(s)", self.view.rows.len());
        self.view.selected = self
            .view
            .selected
            .min(self.view.rows.len().saturating_sub(1));
        self.update_downloaded_detail();
        if !read_failures.is_empty() {
            self.show_error_message(
                "Some downloaded files could not be inspected",
                read_failures.join("\n"),
            );
        }
    }

    /// Shows stable local metadata for the selected offline download.
    fn update_downloaded_detail(&mut self) {
        let Some(row) = self.view.rows.get(self.view.selected).cloned() else {
            self.view.details = None;
            return;
        };
        let Some(media_id) = row
            .media_id
            .as_ref()
            .filter(|media_id| media_id.source == SourceKind::Local)
            .cloned()
        else {
            self.view.details = None;
            return;
        };
        let path = PathBuf::from(&media_id.external_id);
        let local_video = crate::local_browser::classify_local_file(&path)
            == Some(crate::local_browser::LocalEntryKind::Video);
        let (description, length, local_video_thumbnail, metadata_pending) = if local_video {
            let size_bytes = std::fs::metadata(&path)
                .map(|metadata| metadata.len())
                .unwrap_or_default();
            let item = self
                .cached_local_media_item(&path, size_bytes)
                .unwrap_or_else(|| local_media_item_stub(path.clone(), Some(size_bytes)));
            (
                local_media_description(&item),
                item.duration_seconds
                    .map_or_else(String::new, format_seconds),
                local_video_thumbnail_view(&item.path, item.duration_seconds),
                !item.technical_metadata_probed,
            )
        } else {
            (
                format!("Full path: {}", path.display()),
                String::new(),
                None,
                false,
            )
        };
        self.view.details = Some(DetailView {
            media_id: Some(media_id),
            title: row.title,
            source: "Local download".to_owned(),
            length,
            description,
            local_video_thumbnail,
            ..DetailView::default()
        });
        if metadata_pending {
            self.request_local_media_metadata(path);
        }
        #[cfg(all(feature = "local-artwork", feature = "images"))]
        self.request_selected_local_artwork();
    }

    fn populate_history(&mut self) {
        self.view.rows.clear();
        self.history_entries.clear();
        match self.store.history(false, 500) {
            Ok(entries) => {
                self.history_entries = entries
                    .into_iter()
                    .map(|entry| HistoryListEntry {
                        local_removed: history_local_file_removed(&entry),
                        entry,
                    })
                    .collect();
                self.view.rows = self
                    .history_entries
                    .iter()
                    .map(|history| {
                        let live_radio = history.entry.media_id.source == SourceKind::Radio;
                        RowView {
                            media_id: Some(history.entry.media_id.clone()),
                            title: history.entry.title.clone(),
                            subtitle: if live_radio {
                                "live".to_owned()
                            } else if history.local_removed {
                                "Removed".to_owned()
                            } else if history.entry.finished {
                                "played".to_owned()
                            } else {
                                format!(
                                    "stopped at {}",
                                    format_seconds(history.entry.position_seconds)
                                )
                            },
                            source: if live_radio {
                                "Radio".to_owned()
                            } else {
                                history.entry.media_id.source.to_string()
                            },
                            watched_percent: if live_radio {
                                0
                            } else if history.entry.finished {
                                100
                            } else {
                                history
                                    .entry
                                    .duration_seconds
                                    .filter(|duration| *duration > 0)
                                    .map_or(0, |duration| {
                                        ((history.entry.position_seconds.min(duration) * 100)
                                            / duration)
                                            as u8
                                    })
                            },
                            playback_started: !live_radio,
                            hide_watched_marker: live_radio,
                            ..RowView::default()
                        }
                    })
                    .collect();
                hydrate_row_playback_progress(&self.store, &mut self.view.rows);
                self.view.status_line = format!("{} history item(s)", self.view.rows.len());
                self.update_history_detail();
            }
            Err(error) => {
                self.view.details = None;
                self.show_error("Cannot load history", &error);
            }
        }
    }

    fn populate_statistics(&mut self) {
        self.view.rows.clear();
        match self.store.listen_totals() {
            Ok(totals) => {
                self.view.rows = totals
                    .into_iter()
                    .map(|total| RowView {
                        title: total.source.to_string(),
                        subtitle: format!("{:.2} hours", total.total_seconds as f64 / 3600.0),
                        source: total.source.to_string(),
                        ..RowView::default()
                    })
                    .collect();
                self.view.status_line = "Listening time is displayed in hours".to_owned();
            }
            Err(error) => self.show_error("Cannot load statistics", &error),
        }
    }

    fn current_url(&self) -> Option<String> {
        if let Some(linked) = self.active_description_video.as_ref() {
            return LinkTarget::YouTubeVideo {
                video_id: linked.video_id.clone(),
                start_seconds: linked.start_seconds,
            }
            .canonical_url()
            .map(|url| url.to_string());
        }
        if self.view.screen == Screen::TrackerMusic {
            return self
                .tracker_results
                .get(self.view.selected)
                .map(|item| item.webpage_url.to_string());
        }
        if self.view.screen == Screen::Subscriptions {
            if let Some(item) = self.selected_subscription_item()
                && (self.view.subscriptions.route == SubscriptionRoute::Items
                    || self.view.subscriptions.focus == SubscriptionPane::Items)
            {
                return search_item_url(item);
            }
            return self
                .subscription_entries
                .get(self.view.subscriptions.selected_source)
                .map(|entry| {
                    entry
                        .subscription
                        .website_url
                        .as_ref()
                        .unwrap_or(&entry.subscription.url)
                        .to_string()
                });
        }
        if self.view.screen == Screen::YouTubeMusic {
            return search_item_url(self.youtube_music_results.get(self.view.selected)?);
        }
        if self.view.screen == Screen::Bandcamp {
            #[cfg(feature = "bandcamp")]
            {
                return self
                    .bandcamp_results
                    .get(self.view.selected)
                    .map(|release| release.webpage_url.to_string());
            }
            #[cfg(not(feature = "bandcamp"))]
            return None;
        }
        if self.view.screen == Screen::ApplePodcasts {
            return self.current_apple_podcasts_url();
        }
        if self.view.screen == Screen::Radio {
            #[cfg(feature = "radio")]
            {
                return self
                    .selected_radio_station()
                    .map(|station| station.homepage.to_owned());
            }
            #[cfg(not(feature = "radio"))]
            return None;
        }
        if self.view.screen == Screen::Playlists {
            return matches!(self.playlists_route, PlaylistsRoute::Entries { .. })
                .then(|| {
                    self.active_playlist
                        .as_ref()?
                        .entries
                        .get(self.view.selected)
                        .map(|entry| {
                            if entry.media.id.source == SourceKind::Local {
                                entry.media.replay_locator.clone()
                            } else {
                                entry.media.webpage_url.to_string()
                            }
                        })
                })
                .flatten();
        }
        if self.view.screen != Screen::Search {
            return None;
        }
        if let Some(item) = self.local_results.get(self.view.selected) {
            return Some(item.path.display().to_string());
        }
        if let Some(media) = &self.resolved_direct
            && let Some(url) = &media.webpage_url
        {
            return Some(url.to_string());
        }
        if let Some(direct) = &self.direct_item {
            return Some(direct.url.to_string());
        }
        search_item_url(self.youtube_results.get(self.view.selected)?)
    }

    /// Returns the provider page owned by the active Apple show or episode row.
    #[cfg(feature = "apple-podcasts")]
    fn current_apple_podcasts_url(&self) -> Option<String> {
        match self.apple_podcasts_route {
            ApplePodcastsRoute::Shows => self
                .apple_podcasts_results
                .get(self.view.selected)?
                .webpage_url
                .as_ref()
                .map(ToString::to_string),
            ApplePodcastsRoute::Episodes => self
                .apple_podcast_episodes
                .get(self.view.selected)
                .and_then(|episode| {
                    canonical_apple_episode_url(episode, self.active_apple_podcast_show.as_ref())
                })
                .map(|url| url.to_string()),
            ApplePodcastsRoute::Direct => self
                .resolved_direct
                .as_ref()
                .filter(|media| media.source == SourceKind::ApplePodcasts)
                .and_then(|media| media.webpage_url.as_ref())
                .map(ToString::to_string)
                .or_else(|| {
                    self.direct_item
                        .as_ref()
                        .filter(|direct| direct.source == SourceKind::ApplePodcasts)
                        .map(|direct| direct.url.to_string())
                }),
        }
    }

    /// Returns no Apple URL when that provider was omitted at build time.
    #[cfg(not(feature = "apple-podcasts"))]
    fn current_apple_podcasts_url(&self) -> Option<String> {
        None
    }

    fn current_channel_url(&self) -> Option<String> {
        self.view
            .details
            .as_ref()?
            .channel_webpage_url
            .as_ref()
            .map(ToString::to_string)
    }

    fn move_detail_link(&mut self, delta: i32) {
        let link_count = self
            .view
            .details
            .as_ref()
            .map_or(0, |details| details.links.len());
        if link_count == 0 {
            self.view.selected_detail_link = None;
            self.view.status_line = "No external detail link is available".to_owned();
            return;
        }
        let current = self.view.selected_detail_link.unwrap_or_else(|| {
            if delta.is_negative() {
                0
            } else {
                link_count.saturating_sub(1)
            }
        });
        let link_count_i64 = i64::try_from(link_count).unwrap_or(i64::MAX);
        let next = (i64::try_from(current).unwrap_or_default() + i64::from(delta))
            .rem_euclid(link_count_i64);
        self.view.selected_detail_link = usize::try_from(next).ok();
    }

    fn select_detail_link(&mut self, index: usize) {
        if self
            .view
            .details
            .as_ref()
            .is_some_and(|details| index < details.links.len())
        {
            self.view.selected_detail_link = Some(index);
        }
    }

    fn activate_detail_link(&mut self, index: usize) {
        let Some(link) = self
            .view
            .details
            .as_ref()
            .and_then(|details| details.links.get(index))
            .cloned()
        else {
            self.view.status_line = "The selected detail link is no longer available".to_owned();
            return;
        };
        self.view.selected_detail_link = Some(index);
        self.open_external_url(&link.url);
    }

    /// Opens one provider-validated Wikidata value target.
    fn open_wikidata_value(&mut self, url: &str) {
        self.open_external_url(url);
    }

    /// Moves keyboard selection among the currently expanded Commons controls.
    fn move_wikidata_media(&mut self, delta: i32) {
        let count = self
            .expanded_wikidata_media_controls()
            .map_or(0, <[DetailWikidataMediaView]>::len);
        if count == 0 {
            self.view.selected_wikidata_media = None;
            self.view.status_line = "No playable Wikidata media value is available".to_owned();
            return;
        }
        let current = self.view.selected_wikidata_media.unwrap_or_else(|| {
            if delta.is_negative() {
                0
            } else {
                count.saturating_sub(1)
            }
        });
        let count = i64::try_from(count).unwrap_or(i64::MAX);
        let selected =
            (i64::try_from(current).unwrap_or_default() + i64::from(delta)).rem_euclid(count);
        self.view.selected_wikidata_media = usize::try_from(selected).ok();
        self.view.details_focused = true;
    }

    /// Starts a Commons value or toggles pause for that same active value.
    fn activate_wikidata_media(&mut self, index: usize) {
        let Some(media) = self
            .expanded_wikidata_media_controls()
            .and_then(|controls| controls.get(index))
            .cloned()
        else {
            self.view.status_line =
                "The selected Wikidata media control is no longer available".to_owned();
            return;
        };
        self.view.selected_wikidata_media = Some(index);
        self.view.details_focused = true;
        if self.current_media.as_ref() == Some(&media.media_id) && self.player.is_some() {
            self.player_command(PlayerCommand::TogglePause);
            return;
        }
        match queue_item_from_wikidata_media(&media) {
            Ok(item) => self.play_queue_item(item, false),
            Err(error) => {
                self.view.status_line = format!("Unsupported Wikidata media: {error}");
            }
        }
    }

    /// Returns media controls owned by the exact expanded Wikidata entity.
    fn expanded_wikidata_media_controls(&self) -> Option<&[DetailWikidataMediaView]> {
        let details = self.view.details.as_ref()?;
        let item_id = details.expanded_wikidata_item.as_deref()?;
        details
            .wikidata_entities
            .iter()
            .find(|entity| entity.item_id == item_id)
            .map(|entity| entity.media_controls.as_slice())
    }

    /// Expands or collapses one linked Wikidata item's lazy property spoiler.
    fn toggle_wikidata_statements(&mut self, index: usize) {
        let Some(item_id) = self
            .view
            .details
            .as_ref()
            .and_then(|details| details.links.get(index))
            .and_then(|link| link.wikidata_item_id.clone())
        else {
            self.view.status_line =
                "The selected external link has no Wikidata properties".to_owned();
            return;
        };
        self.view.selected_detail_link = Some(index);
        let already_expanded = self
            .view
            .details
            .as_ref()
            .and_then(|details| details.expanded_wikidata_item.as_deref())
            == Some(item_id.as_str());
        if already_expanded {
            if let Some(details) = self.view.details.as_mut() {
                details.expanded_wikidata_item = None;
            }
            self.view.selected_wikidata_media = None;
            self.view.details_scroll = 0;
            self.view.status_line = format!("Collapsed Wikidata properties for {item_id}");
            return;
        }
        if let Some(details) = self.view.details.as_mut() {
            details.expanded_wikidata_item = Some(item_id.clone());
        }
        self.view.selected_wikidata_media = None;
        self.view.details_focused = true;
        self.view.details_scroll = 0;

        #[cfg(feature = "wikidata")]
        {
            if let Some(entity) = self.wikidata_entity_cache.get(&item_id).cloned() {
                self.touch_wikidata_entity_cache(&item_id);
                if let Some(details) = self.view.details.as_mut() {
                    let media_count = apply_wikidata_entity_to_details(details, &entity);
                    self.view.selected_wikidata_media = (media_count > 0).then_some(0);
                }
                self.view.status_line =
                    format!("Expanded cached Wikidata properties for {item_id}");
                return;
            }
            if self.pending_wikidata_entities.contains(&item_id) {
                if let Some(details) = self.view.details.as_mut() {
                    details.loading_wikidata_item = Some(item_id);
                }
                return;
            }
            let sent = self.provider_requests.as_ref().is_some_and(|sender| {
                sender
                    .send(ProviderRequest::WikidataStatements {
                        item_id: item_id.clone(),
                    })
                    .is_ok()
            });
            if sent {
                self.pending_wikidata_entities.insert(item_id.clone());
                if let Some(details) = self.view.details.as_mut() {
                    details.loading_wikidata_item = Some(item_id.clone());
                }
                self.view.status_line = format!("Loading Wikidata properties for {item_id}…");
            } else {
                if let Some(details) = self.view.details.as_mut() {
                    details.loading_wikidata_item = None;
                }
                self.view.status_line = "Wikidata provider worker is unavailable".to_owned();
            }
        }
        #[cfg(not(feature = "wikidata"))]
        {
            if let Some(details) = self.view.details.as_mut() {
                details.loading_wikidata_item = None;
            }
            self.view.status_line = "This build omits Wikidata property loading".to_owned();
        }
    }

    #[cfg(feature = "wikidata")]
    fn cache_wikidata_entity(
        &mut self,
        entity: crate::providers::wikidata::WikidataEntityStatements,
    ) {
        let item_id = entity.item_id.clone();
        if !self.wikidata_entity_cache.contains_key(&item_id) {
            while self.wikidata_entity_cache.len() >= MAX_CACHED_WIKIDATA_ENTITIES {
                let Some(oldest) = self.wikidata_entity_cache_order.pop_front() else {
                    break;
                };
                self.wikidata_entity_cache.remove(&oldest);
            }
        }
        self.wikidata_entity_cache.insert(item_id.clone(), entity);
        self.touch_wikidata_entity_cache(&item_id);
    }

    #[cfg(feature = "wikidata")]
    fn touch_wikidata_entity_cache(&mut self, item_id: &str) {
        self.wikidata_entity_cache_order
            .retain(|cached| cached != item_id);
        self.wikidata_entity_cache_order
            .push_back(item_id.to_owned());
    }

    fn diagnostic_helpers(&mut self) -> Vec<ExternalHelper> {
        if self.diagnostic_helpers_cache.is_none() {
            self.diagnostic_helpers_cache = Some(ExternalHelper::probe_many([
                (
                    ExternalHelperKind::Mpv,
                    Some(self.config.providers.mpv_executable.clone()),
                ),
                (
                    ExternalHelperKind::YtDlp,
                    Some(self.config.providers.yt_dlp_executable.clone()),
                ),
            ]));
        }
        self.diagnostic_helpers_cache
            .as_ref()
            .expect("diagnostic helper cache was initialized")
            .clone()
    }

    fn show_error<E>(&mut self, title: &str, error: &E)
    where
        E: std::error::Error + 'static,
    {
        let report = DiagnosticReport::capture_error(error, self.diagnostic_helpers()).render();
        self.show_diagnostic_report(title, report);
        self.view.status_line = format!("{title}: {error}");
    }

    fn show_error_message(&mut self, title: &str, message: impl std::fmt::Display) {
        let report =
            DiagnosticReport::capture_message(&message, self.diagnostic_helpers()).render();
        self.show_diagnostic_report(title, report);
        self.view.status_line = format!("{title}: {message}");
    }

    /// Opens the diagnostic popup with a complete, already-redacted report.
    ///
    /// This is also used by the process-level panic boundary after the normal
    /// terminal session has restored raw mode and the alternate screen.
    pub fn show_diagnostic_report(&mut self, title: impl Into<String>, report: impl Into<String>) {
        self.view.error_popup = Some(ErrorPopupView {
            title: title.into(),
            report: report.into(),
            scroll_offset: 0,
            gh_available: self.report_actions.gh_available(),
            action_status: None,
        });
    }

    /// Stops background activity and prepares a safe error-only TUI after a
    /// fatal panic or terminal-loop failure.
    pub fn enter_fatal_diagnostic_mode(
        &mut self,
        title: impl Into<String>,
        report: impl Into<String>,
    ) {
        #[cfg(feature = "yt-dlp")]
        self.shutdown_youtube_prewarm();
        if let Some(mut player) = self.player.take() {
            let _ = player.shutdown();
        }
        self.invalidate_local_folder_sizes();
        if let Some(sender) = self.local_browse_requests.take() {
            let _ = sender.send(LocalBrowseRequest::Shutdown);
        }
        if let Some(sender) = self.provider_requests.take() {
            let _ = sender.send(ProviderRequest::Shutdown);
        }
        if let Some(handle) = self.local_browse_thread.take() {
            let _ = handle.join();
        }
        if let Some(handle) = self.provider_thread.take() {
            let _ = handle.join();
        }
        self.diagnostic_only = true;
        self.quit_on_error_dismiss = true;
        self.clear_search_activity();
        self.clear_playback_start_activity();
        self.view.playing_media_id = None;
        self.view.quitting = false;
        self.view.help_open = false;
        self.view.search_editing = false;
        self.show_diagnostic_report(title, report);
    }

    fn scroll_details(&mut self, movement: DetailsScroll) {
        self.view.details_focused = true;
        if self.view.details.is_none() {
            self.view.details_scroll = 0;
            return;
        }
        self.view.details_scroll = match movement {
            DetailsScroll::Lines(lines) => self
                .view
                .details_scroll
                .saturating_add_signed(isize::try_from(lines).unwrap_or_default()),
            DetailsScroll::Pages(pages) => self.view.details_scroll.saturating_add_signed(
                isize::try_from(pages)
                    .unwrap_or_default()
                    .saturating_mul(20),
            ),
            DetailsScroll::Home => 0,
            DetailsScroll::End => usize::MAX,
        };
    }

    fn scroll_error_popup(&mut self, movement: ErrorPopupScroll) {
        let Some(error) = self.view.error_popup.as_mut() else {
            return;
        };
        error.scroll_offset = match movement {
            ErrorPopupScroll::Lines(lines) => error
                .scroll_offset
                .saturating_add_signed(isize::try_from(lines).unwrap_or_default()),
            ErrorPopupScroll::Pages(pages) => error.scroll_offset.saturating_add_signed(
                isize::try_from(pages)
                    .unwrap_or_default()
                    .saturating_mul(20),
            ),
            ErrorPopupScroll::Home => 0,
            ErrorPopupScroll::End => usize::MAX,
        };
    }

    fn error_report_snapshot(&self) -> Option<(String, String)> {
        self.view
            .error_popup
            .as_ref()
            .map(|error| (error.title.clone(), error.report.clone()))
    }

    fn set_error_action_status(&mut self, status: impl Into<String>) {
        if let Some(error) = self.view.error_popup.as_mut() {
            error.action_status = Some(status.into());
        }
    }

    fn copy_error_report(&mut self) {
        let Some((_, report)) = self.error_report_snapshot() else {
            return;
        };
        match self.report_actions.copy_report(&report) {
            Ok(transport) => {
                self.set_error_action_status(format!("Copied with {transport}"));
            }
            Err(error) => {
                self.set_error_action_status(format!("Copy failed: {error}"));
            }
        }
    }

    fn fill_github_issue(&mut self) {
        let Some((title, report)) = self.error_report_snapshot() else {
            return;
        };
        match self
            .report_actions
            .fill_github_issue(&format!("Youta error: {title}"), &report)
        {
            Ok(()) => {
                self.set_error_action_status("Opened a pre-filled issue for review");
            }
            Err(error) => {
                self.set_error_action_status(format!("Could not open `gh`: {error}"));
            }
        }
    }

    fn copy_and_open_github_issue(&mut self) {
        let Some((title, report)) = self.error_report_snapshot() else {
            return;
        };
        match self
            .report_actions
            .copy_and_open_github_issue(&format!("Youta error: {title}"), &report)
        {
            Ok(transport) => {
                self.set_error_action_status(format!(
                    "Copied with {transport}; opened the issue form"
                ));
            }
            Err(error) => {
                self.set_error_action_status(format!("Issue form action failed: {error}"));
            }
        }
    }

    fn open_current_in_browser(&mut self) {
        let Some(url) = self.current_url() else {
            self.view.status_line = "No link is selected".to_owned();
            return;
        };
        self.spawn_url_opener(&url);
    }

    fn open_current_channel_in_browser(&mut self) {
        let Some(url) = self.current_channel_url() else {
            self.view.status_line = "No channel webpage is available".to_owned();
            return;
        };
        self.open_external_url(&url);
    }

    fn selected_local_regular_file(&self) -> Option<PathBuf> {
        let listing = self.local_listing.as_ref()?;
        let index = self.local_entry_index()?;
        let entry = listing.entries.get(index)?;
        (!entry.is_directory()).then(|| entry.path.clone())
    }

    fn selected_local_trash_target(&self) -> Option<(PathBuf, PathBuf)> {
        let listing = self.local_listing.as_ref()?;
        let index = self.local_entry_index()?;
        let entry = listing.entries.get(index)?;
        Some((listing.path.clone(), entry.path.clone()))
    }

    #[cfg(feature = "local-rename")]
    fn begin_local_rename(&mut self) {
        let Some(path) = self.selected_local_regular_file() else {
            self.view.status_line = "Select a local file before renaming".to_owned();
            return;
        };
        let Some(name) = path.file_name() else {
            self.view.status_line = "The selected file has no basename".to_owned();
            return;
        };
        let value = name.to_string_lossy().into_owned();
        self.view.local_file_popup = Some(LocalFilePopupView::Rename {
            cursor_byte: value.len(),
            value,
            error: None,
        });
    }

    #[cfg(not(feature = "local-rename"))]
    fn begin_local_rename(&mut self) {
        self.view.status_line = "This build omits the `local-rename` feature".to_owned();
    }

    fn append_local_rename_character(&mut self, character: char) {
        let Some(LocalFilePopupView::Rename {
            value,
            cursor_byte,
            error,
        }) = self.view.local_file_popup.as_mut()
        else {
            return;
        };
        if value.len().saturating_add(character.len_utf8()) <= 255 {
            let cursor = rename_cursor_boundary(value, *cursor_byte);
            value.insert(cursor, character);
            *cursor_byte = cursor.saturating_add(character.len_utf8());
            *error = None;
        }
    }

    /// Moves the rename insertion point by one whole displayed grapheme.
    fn move_local_rename_cursor(&mut self, direction: i8) {
        let Some(LocalFilePopupView::Rename {
            value, cursor_byte, ..
        }) = self.view.local_file_popup.as_mut()
        else {
            return;
        };
        let cursor = rename_cursor_boundary(value, *cursor_byte);
        *cursor_byte = if direction < 0 {
            value[..cursor]
                .grapheme_indices(true)
                .next_back()
                .map_or(0, |(index, _)| index)
        } else if direction > 0 {
            value[cursor..]
                .graphemes(true)
                .next()
                .map_or(cursor, |grapheme| cursor.saturating_add(grapheme.len()))
        } else {
            cursor
        };
    }

    fn delete_local_rename_character(&mut self) {
        if let Some(LocalFilePopupView::Rename {
            value,
            cursor_byte,
            error,
        }) = self.view.local_file_popup.as_mut()
        {
            let cursor = rename_cursor_boundary(value, *cursor_byte);
            let previous = value[..cursor]
                .grapheme_indices(true)
                .next_back()
                .map_or(cursor, |(index, _)| index);
            value.drain(previous..cursor);
            *cursor_byte = previous;
            *error = None;
        }
    }

    /// Deletes one Vim-style word before the local-rename cursor.
    fn delete_local_rename_word(&mut self) {
        let Some(LocalFilePopupView::Rename {
            value,
            cursor_byte,
            error,
        }) = self.view.local_file_popup.as_mut()
        else {
            return;
        };
        if delete_previous_editor_word(value, cursor_byte) {
            *error = None;
        }
    }

    fn submit_local_rename(&mut self) {
        let value = match self.view.local_file_popup.as_ref() {
            Some(LocalFilePopupView::Rename { value, .. }) => value.clone(),
            _ => return,
        };
        let Some(source) = self.selected_local_regular_file() else {
            self.view.local_file_popup = None;
            self.view.status_line = "The selected local file is no longer available".to_owned();
            return;
        };
        #[cfg(not(feature = "local-rename"))]
        let _ = (&value, &source);
        #[cfg(feature = "local-rename")]
        {
            let target = match crate::local_browser::validate_local_rename(
                &source,
                std::ffi::OsStr::new(&value),
            ) {
                Ok(target) => target,
                Err(error) => {
                    if let Some(LocalFilePopupView::Rename {
                        error: popup_error, ..
                    }) = self.view.local_file_popup.as_mut()
                    {
                        *popup_error = Some(error.to_string());
                    }
                    return;
                }
            };
            let mapping = LocalMoveMapping {
                source: source.clone(),
                target: target.clone(),
            };
            if let Some(collision) =
                self.local_progress_cache_collision(std::slice::from_ref(&mapping))
            {
                if let Some(LocalFilePopupView::Rename {
                    error: popup_error, ..
                }) = self.view.local_file_popup.as_mut()
                {
                    *popup_error = Some(format!(
                        "Rename cancelled because watched progress already exists for destination `{}`",
                        collision.external_id
                    ));
                }
                return;
            }
            if let Err(error) = self
                .store
                .journal_local_move_intent(std::slice::from_ref(&mapping), unix_time())
            {
                self.show_error("Could not save the Local rename recovery intent", &error);
                return;
            }
            self.local_move_journal_pending = true;
            let mut actions = crate::local_browser::SystemLocalFileActions;
            match crate::local_browser::rename_local_file(
                &mut actions,
                &source,
                std::ffi::OsStr::new(&value),
            ) {
                Ok(_) => {
                    let warnings =
                        self.apply_completed_local_move_mappings(std::slice::from_ref(&mapping));
                    #[cfg(feature = "local-move")]
                    self.local_move_marks.remove(&source);
                    self.view.local_file_popup = None;
                    self.view.status_line = format!("Renamed to {}", target.display());
                    let _ = self.persist_pending_local_move_mappings(
                        LocalMovePersistenceAttempt::Automatic,
                    );
                    if let Some(directory) = target.parent().map(Path::to_owned) {
                        self.browse_local_directory_with_reselection(
                            directory,
                            Some(target.clone()),
                        );
                    }
                    if !warnings.is_empty() {
                        self.show_error_message(
                            "Local rename completed with warnings",
                            warnings.join("\n"),
                        );
                    }
                }
                Err(rename_error) => {
                    let error = match self
                        .store
                        .discard_local_move_intents(std::slice::from_ref(&mapping))
                    {
                        Ok(()) => {
                            self.local_move_journal_pending = false;
                            rename_error.to_string()
                        }
                        Err(discard_error) => {
                            self.local_move_journal_pending = true;
                            format!(
                                "{rename_error}; the durable recovery intent could not be cleared: {discard_error}"
                            )
                        }
                    };
                    if let Some(LocalFilePopupView::Rename {
                        error: popup_error, ..
                    }) = self.view.local_file_popup.as_mut()
                    {
                        *popup_error = Some(error);
                    }
                }
            }
        }
        #[cfg(not(feature = "local-rename"))]
        if let Some(LocalFilePopupView::Rename {
            error: popup_error, ..
        }) = self.view.local_file_popup.as_mut()
        {
            *popup_error = Some("this build omits the `local-rename` feature".to_owned());
        }
    }

    #[cfg(feature = "local-trash")]
    fn request_local_trash(&mut self) {
        let Some((_, path)) = self.selected_local_trash_target() else {
            self.view.status_line =
                "Select a local file or folder before moving it to Trash".to_owned();
            return;
        };
        self.view.local_file_popup = Some(LocalFilePopupView::Trash {
            name: path
                .file_name()
                .unwrap_or_default()
                .to_string_lossy()
                .into_owned(),
            path: path.display().to_string(),
            error: None,
        });
    }

    #[cfg(not(feature = "local-trash"))]
    fn request_local_trash(&mut self) {
        self.view.status_line = "This build omits the `local-trash` feature".to_owned();
    }

    #[cfg(feature = "local-trash")]
    fn request_downloaded_trash(&mut self) {
        let (_, path) = match self.selected_downloaded_trash_target() {
            Ok(target) => target,
            Err(error) => {
                self.view.status_line = error;
                return;
            }
        };
        self.view.local_file_popup = Some(LocalFilePopupView::DownloadedTrash {
            name: path
                .file_name()
                .unwrap_or_default()
                .to_string_lossy()
                .into_owned(),
            path: path.display().to_string(),
            error: None,
        });
    }

    #[cfg(not(feature = "local-trash"))]
    fn request_downloaded_trash(&mut self) {
        self.view.status_line = "This build omits the `local-trash` feature".to_owned();
    }

    /// Removes a confirmed Trash target from the visible snapshot immediately.
    ///
    /// The following background refresh remains authoritative, while this
    /// optimistic update avoids a blank or already-deleted row. Unchanged
    /// sibling cache entries remain available for identity validation.
    #[cfg(any(feature = "local-trash", test))]
    fn remove_confirmed_local_trash_target(&mut self, source: &Path) -> Option<PathBuf> {
        let listing = self.local_listing.as_mut()?;
        let removed_index = listing
            .entries
            .iter()
            .position(|entry| entry.path == source)?;
        listing.entries.remove(removed_index);
        let reselected_path = listing
            .entries
            .get(removed_index)
            .or_else(|| {
                removed_index
                    .checked_sub(1)
                    .and_then(|index| listing.entries.get(index))
            })
            .map(|entry| entry.path.clone())
            .or_else(|| listing.parent.clone());

        self.local_folder_size_cache.remove(source);
        self.local_folder_size_cache_order
            .retain(|cached_path| cached_path != source);
        self.local_folder_size_failures.remove(source);
        self.local_folder_size_failure_order
            .retain(|failed_path| failed_path != source);
        self.local_folder_size_queue
            .retain(|queued_path| queued_path != source);
        if self.local_folder_size_pending.as_deref() == Some(source) {
            self.local_folder_size_pending = None;
        }

        self.select_local_path(reselected_path.as_deref());
        self.refresh_local_browser_rows();
        reselected_path
    }

    fn confirm_local_trash(&mut self) {
        let Some((directory, source)) = self.selected_local_trash_target() else {
            self.view.local_file_popup = None;
            self.view.status_line = "The selected local entry is no longer available".to_owned();
            return;
        };
        #[cfg(not(feature = "local-trash"))]
        let _ = (&directory, &source);
        #[cfg(feature = "local-trash")]
        {
            let mut actions = crate::local_browser::SystemLocalFileActions;
            match crate::local_browser::trash_local_entry(&mut actions, &directory, &source) {
                Ok(()) => {
                    self.view.local_file_popup = None;
                    self.view.status_line = format!("Moved {} to system Trash", source.display());
                    let reselected_path = self.remove_confirmed_local_trash_target(&source);
                    self.browse_local_directory_with_reselection(directory, reselected_path);
                }
                Err(error) => self.show_local_trash_error(&error),
            }
        }
        #[cfg(not(feature = "local-trash"))]
        if let Some(LocalFilePopupView::Trash {
            error: popup_error, ..
        }) = self.view.local_file_popup.as_mut()
        {
            *popup_error = Some("this build omits the `local-trash` feature".to_owned());
        }
    }

    #[cfg(feature = "local-trash")]
    fn confirm_downloaded_trash(&mut self) {
        let mut actions = crate::local_browser::SystemLocalFileActions;
        self.confirm_downloaded_trash_with(&mut actions);
    }

    #[cfg(not(feature = "local-trash"))]
    fn confirm_downloaded_trash(&mut self) {
        if let Some(LocalFilePopupView::DownloadedTrash {
            error: popup_error, ..
        }) = self.view.local_file_popup.as_mut()
        {
            *popup_error = Some("this build omits the `local-trash` feature".to_owned());
        }
    }

    /// Revalidates and moves the selected download through an injected backend.
    ///
    /// Injection keeps regression tests recoverable and deterministic without
    /// writing to the developer's desktop Trash.
    #[cfg(feature = "local-trash")]
    fn confirm_downloaded_trash_with<A>(&mut self, actions: &mut A)
    where
        A: crate::local_browser::LocalFileActions + ?Sized,
    {
        let popup_path = match self.view.local_file_popup.as_ref() {
            Some(LocalFilePopupView::DownloadedTrash { path, .. }) => PathBuf::from(path),
            _ => {
                self.view.local_file_popup = None;
                self.view.status_line = "No downloaded item is awaiting removal".to_owned();
                return;
            }
        };
        let (directory, source) = match self.selected_downloaded_trash_target() {
            Ok(target) if target.1 == popup_path => target,
            Ok(_) | Err(_) => {
                self.view.local_file_popup = None;
                self.view.status_line =
                    "The selected downloaded item is no longer available".to_owned();
                return;
            }
        };
        match crate::local_browser::trash_local_entry(actions, &directory, &source) {
            Ok(()) => {
                self.view.local_file_popup = None;
                self.populate_downloads();
                self.refresh_selected_playlist_state();
                self.view.status_line =
                    format!("Moved {} to recoverable system Trash", source.display());
            }
            Err(error) => self.show_downloaded_trash_error(&error),
        }
    }

    /// Keeps the confirmation context and exposes the complete Trash error chain.
    ///
    /// A single popup row cannot represent nested operating-system or desktop
    /// Trash errors. The normal scrollable diagnostic therefore owns the full
    /// report while the confirmation retains a concise summary underneath it.
    #[cfg(any(feature = "local-trash", test))]
    fn show_local_trash_error(&mut self, error: &crate::local_browser::LocalBrowserError) {
        if let Some(LocalFilePopupView::Trash {
            error: popup_error, ..
        }) = self.view.local_file_popup.as_mut()
        {
            *popup_error = Some(error.to_string());
        }
        self.show_error("Could not move local entry to Trash", error);
    }

    /// Keeps the download confirmation and exposes the complete Trash error chain.
    #[cfg(feature = "local-trash")]
    fn show_downloaded_trash_error(&mut self, error: &crate::local_browser::LocalBrowserError) {
        if let Some(LocalFilePopupView::DownloadedTrash {
            error: popup_error, ..
        }) = self.view.local_file_popup.as_mut()
        {
            *popup_error = Some(error.to_string());
        }
        self.show_error("Could not move downloaded item to Trash", error);
    }

    /// Toggles the selected real Local entry and advances one signed row.
    ///
    /// The synthetic `..` row is navigation only and can never enter a move
    /// batch. Marks are exact paths, so sorting does not change their meaning.
    #[cfg(feature = "local-move")]
    fn extend_local_move_selection(&mut self, direction: i32) {
        if self.view.screen != Screen::Local {
            return;
        }
        if let Some(index) = self.local_entry_index()
            && let Some(path) = self
                .local_listing
                .as_ref()
                .and_then(|listing| listing.entries.get(index))
                .map(|entry| entry.path.clone())
        {
            if !self.local_move_marks.insert(path.clone()) {
                self.local_move_marks.remove(&path);
            }
            self.rebuild_local_browser_rows();
        }
        self.move_selection(direction);
    }

    /// Opens the asynchronous destination chooser for marks or the current row.
    #[cfg(feature = "local-move")]
    fn begin_local_move(&mut self) {
        if self.view.screen != Screen::Local {
            self.view.status_line = "Move is available in the Local browser".to_owned();
            return;
        }
        if !self.persist_pending_local_move_mappings(LocalMovePersistenceAttempt::Explicit) {
            return;
        }
        let Some(listing) = self.local_listing.as_ref() else {
            self.view.status_line = "No local folder is loaded".to_owned();
            return;
        };
        let source_directory = listing.path.clone();
        let mut sources = listing
            .entries
            .iter()
            .filter(|entry| self.local_move_marks.contains(&entry.path))
            .map(|entry| entry.path.clone())
            .collect::<Vec<_>>();
        if sources.is_empty()
            && let Some(index) = self.local_entry_index()
            && let Some(entry) = listing.entries.get(index)
        {
            sources.push(entry.path.clone());
        }
        if sources.is_empty() {
            self.view.status_line = "Select a local file or folder before choosing Move".to_owned();
            return;
        }

        let destination_directory = listing
            .parent
            .clone()
            .unwrap_or_else(|| source_directory.clone());
        let source_names = sources
            .iter()
            .map(|source| {
                source
                    .file_name()
                    .unwrap_or_default()
                    .to_string_lossy()
                    .into_owned()
            })
            .collect();
        self.local_move_selection = Some(LocalMoveSelection {
            source_directory,
            sources,
            destination_directory: destination_directory.clone(),
            destination_rows: Vec::new(),
        });
        self.local_move_execution_pending = false;
        self.view.local_file_popup = Some(LocalFilePopupView::Move {
            source_names,
            destination: destination_directory.display().to_string(),
            directories: Vec::new(),
            selected: 0,
            pending: true,
            error: None,
        });
        self.request_local_move_destinations(destination_directory);
    }

    /// Selects one exact destination row without interpreting its display text.
    #[cfg(feature = "local-move")]
    fn select_local_move_destination(&mut self, index: usize) {
        let Some(LocalFilePopupView::Move {
            directories,
            selected,
            error,
            ..
        }) = self.view.local_file_popup.as_mut()
        else {
            return;
        };
        if index < directories.len() {
            *selected = index;
            *error = None;
        }
    }

    /// Moves the destination chooser by a signed number of rows.
    #[cfg(feature = "local-move")]
    fn move_local_move_destination(&mut self, direction: i32) {
        let Some(LocalFilePopupView::Move {
            directories,
            selected,
            ..
        }) = self.view.local_file_popup.as_mut()
        else {
            return;
        };
        let Some(index) = moved_index(*selected, directories.len(), direction) else {
            return;
        };
        *selected = index;
    }

    /// Opens the exact selected parent or child in the destination chooser.
    #[cfg(feature = "local-move")]
    fn activate_local_move_destination(&mut self) {
        let Some(LocalFilePopupView::Move {
            selected, pending, ..
        }) = self.view.local_file_popup.as_ref()
        else {
            return;
        };
        if *pending {
            return;
        }
        let Some(directory) = self
            .local_move_selection
            .as_ref()
            .and_then(|selection| selection.destination_rows.get(*selected))
            .cloned()
        else {
            self.view.status_line = "No destination folder is selected".to_owned();
            return;
        };
        if let Some(LocalFilePopupView::Move { pending, error, .. }) =
            self.view.local_file_popup.as_mut()
        {
            *pending = true;
            *error = None;
        }
        self.request_local_move_destinations(directory);
    }

    /// Sends one bounded directory-only destination listing to the Local worker.
    #[cfg(feature = "local-move")]
    fn request_local_move_destinations(&mut self, directory: PathBuf) {
        self.local_move_generation = self.local_move_generation.wrapping_add(1);
        let generation = self.local_move_generation;
        if !self.send_local_browse_request(
            LocalBrowseRequest::MoveDestinations {
                generation,
                directory,
            },
            "Could not browse Local move destinations",
        ) && let Some(LocalFilePopupView::Move { pending, error, .. }) =
            self.view.local_file_popup.as_mut()
        {
            *pending = false;
            *error = Some("The Local filesystem worker is unavailable".to_owned());
        }
    }

    /// Starts the explicit no-overwrite batch move on the isolated worker.
    #[cfg(feature = "local-move")]
    fn confirm_local_move_here(&mut self) {
        let Some(LocalFilePopupView::Move { pending, .. }) = self.view.local_file_popup.as_ref()
        else {
            return;
        };
        if *pending {
            self.view.status_line =
                "Wait for the current Local move operation to finish".to_owned();
            return;
        }
        let Some(selection) = self.local_move_selection.as_ref() else {
            if let Some(LocalFilePopupView::Move { error, .. }) =
                self.view.local_file_popup.as_mut()
            {
                *error = Some("The Local move selection is no longer available".to_owned());
            }
            return;
        };
        let plan = match crate::local_move::validate_local_move(
            &selection.source_directory,
            &selection.sources,
            &selection.destination_directory,
            LocalMoveLimits::default(),
        ) {
            Ok(plan) => plan,
            Err(validation_error) => {
                if let Some(LocalFilePopupView::Move { error, .. }) =
                    self.view.local_file_popup.as_mut()
                {
                    *error = Some(validation_error.to_string());
                }
                return;
            }
        };
        let mappings = plan.mappings();
        if let Some(collision) = self.local_progress_cache_collision(&mappings) {
            if let Some(LocalFilePopupView::Move { error, .. }) =
                self.view.local_file_popup.as_mut()
            {
                *error = Some(format!(
                    "Move cancelled because watched progress already exists for destination `{}`",
                    collision.external_id
                ));
            }
            return;
        }
        if let Err(error) = self.store.journal_local_move_intent(&mappings, unix_time()) {
            self.show_error("Could not save the Local move recovery intent", &error);
            return;
        }
        self.local_move_journal_pending = true;
        if let Some(LocalFilePopupView::Move { pending, error, .. }) =
            self.view.local_file_popup.as_mut()
        {
            *pending = true;
            *error = None;
        }
        self.local_move_execution_pending = true;
        self.local_move_generation = self.local_move_generation.wrapping_add(1);
        let generation = self.local_move_generation;
        if !self.send_local_browse_request(
            LocalBrowseRequest::Move { generation, plan },
            "Could not move Local entries",
        ) {
            self.local_move_execution_pending = false;
            let message = match self.store.discard_local_move_intents(&mappings) {
                Ok(()) => {
                    self.local_move_journal_pending = false;
                    "The Local filesystem worker is unavailable".to_owned()
                }
                Err(discard_error) => format!(
                    "The Local filesystem worker is unavailable; the durable recovery intent could not be cleared: {discard_error}"
                ),
            };
            if let Some(LocalFilePopupView::Move { pending, error, .. }) =
                self.view.local_file_popup.as_mut()
            {
                *pending = false;
                *error = Some(message);
            }
        }
    }

    /// Applies one current destination listing without disturbing Local rows.
    #[cfg(feature = "local-move")]
    fn handle_local_move_destinations_response(
        &mut self,
        generation: u64,
        result: Result<crate::local_move::LocalMoveDestinationListing, String>,
    ) {
        if generation != self.local_move_generation
            || !matches!(
                self.view.local_file_popup.as_ref(),
                Some(LocalFilePopupView::Move { .. })
            )
        {
            return;
        }
        match result {
            Ok(listing) => {
                let mut exact_rows = Vec::with_capacity(
                    listing
                        .directories
                        .len()
                        .saturating_add(usize::from(listing.parent.is_some())),
                );
                let mut rows = Vec::with_capacity(exact_rows.capacity());
                if let Some(parent) = listing.parent {
                    rows.push(LocalMoveDestinationView {
                        name: "..".to_owned(),
                        path: parent.display().to_string(),
                    });
                    exact_rows.push(parent);
                }
                for directory in listing.directories {
                    rows.push(LocalMoveDestinationView {
                        name: directory.name.to_string_lossy().into_owned(),
                        path: directory.path.display().to_string(),
                    });
                    exact_rows.push(directory.path);
                }
                if let Some(selection) = self.local_move_selection.as_mut() {
                    selection.destination_directory.clone_from(&listing.path);
                    selection.destination_rows = exact_rows;
                }
                if let Some(LocalFilePopupView::Move {
                    destination,
                    directories,
                    selected,
                    pending,
                    error,
                    ..
                }) = self.view.local_file_popup.as_mut()
                {
                    *destination = listing.path.display().to_string();
                    *directories = rows;
                    *selected = 0;
                    *pending = false;
                    *error = None;
                }
                if listing.truncated {
                    self.view.status_line =
                        "The Local move destination list reached its safety bound".to_owned();
                }
            }
            Err(listing_error) => {
                if let Some(LocalFilePopupView::Move { pending, error, .. }) =
                    self.view.local_file_popup.as_mut()
                {
                    *pending = false;
                    *error = Some(listing_error);
                }
            }
        }
    }

    /// Finds the first deterministic destination key that would overwrite
    /// independently cached watched progress.
    #[cfg(any(feature = "local-rename", feature = "local-move"))]
    fn local_progress_cache_collision(&self, mappings: &[LocalMoveMapping]) -> Option<MediaId> {
        let mut collisions = self
            .local_progress_cache
            .keys()
            .filter_map(|source_id| {
                let mut target_id = source_id.clone();
                match crate::local_move::remap_local_media_id(&mut target_id, mappings) {
                    Ok(true)
                        if target_id != *source_id
                            && self.local_progress_cache.contains_key(&target_id) =>
                    {
                        Some(target_id)
                    }
                    Ok(_) | Err(_) => None,
                }
            })
            .collect::<Vec<_>>();
        collisions.sort_unstable_by(|left, right| {
            left.source
                .as_str()
                .cmp(right.source.as_str())
                .then_with(|| left.external_id.cmp(&right.external_id))
        });
        collisions.dedup();
        collisions.into_iter().next()
    }

    /// Applies only authoritative completed mappings from one move result.
    #[cfg(feature = "local-move")]
    fn handle_local_move_response(
        &mut self,
        generation: u64,
        planned: &[LocalMoveMapping],
        result: Result<LocalMoveReport, LocalMoveError>,
    ) {
        if generation != self.local_move_generation || !self.local_move_execution_pending {
            return;
        }
        self.local_move_execution_pending = false;
        let source_directory = self
            .local_move_selection
            .as_ref()
            .map(|selection| selection.source_directory.clone());
        let (completed, recovery, error) = match result {
            Ok(report) => (report.completed, report.recovery, None),
            Err(LocalMoveError::Validation(error)) => {
                (Vec::new(), Vec::new(), Some(error.to_string()))
            }
            Err(LocalMoveError::Execution(failure)) => {
                let message = failure.to_string();
                (
                    failure.completed.clone(),
                    vec![failure.recovery.clone()],
                    Some(message),
                )
            }
        };

        let operation_failed = error.is_some();
        let identity_warnings = self.apply_completed_local_move_mappings(&completed);
        let has_identity_warnings = !identity_warnings.is_empty();
        let recovery_message = local_move_recovery_message(&recovery);
        let needs_recovery_diagnostic = recovery_message.is_some();
        let mut popup_message = error;
        for warning in identity_warnings {
            append_local_move_message(&mut popup_message, warning);
        }
        if let Some(recovery_message) = recovery_message {
            append_local_move_message(&mut popup_message, recovery_message);
        }

        for mapping in &completed {
            self.local_move_marks.remove(&mapping.source);
        }
        let moved_count = completed.len();
        if !operation_failed {
            self.local_move_marks.clear();
            self.local_move_selection = None;
            self.view.local_file_popup = None;
            self.view.status_line = format!(
                "Moved {moved_count} local entr{}",
                if moved_count == 1 { "y" } else { "ies" }
            );
        } else {
            if let Some(selection) = self.local_move_selection.as_mut() {
                selection
                    .sources
                    .retain(|source| !completed.iter().any(|mapping| &mapping.source == source));
            }
            if let Some(LocalFilePopupView::Move {
                source_names,
                pending,
                error,
                ..
            }) = self.view.local_file_popup.as_mut()
            {
                if let Some(selection) = self.local_move_selection.as_ref() {
                    *source_names = selection
                        .sources
                        .iter()
                        .map(|source| {
                            source
                                .file_name()
                                .unwrap_or_default()
                                .to_string_lossy()
                                .into_owned()
                        })
                        .collect();
                }
                *pending = false;
                *error = popup_message.clone();
            }
            self.view.status_line = if moved_count == 0 {
                "Local entries were not moved".to_owned()
            } else {
                format!("Moved {moved_count} local entries before an error")
            };
        }

        if moved_count > 0
            && let Some(directory) = source_directory
            && self.local_browse_requests.is_some()
            && self
                .local_listing
                .as_ref()
                .is_some_and(|listing| listing.path == directory)
        {
            let selected = self.selected_local_path();
            self.browse_local_directory_with_reselection(directory, selected);
        }
        if (needs_recovery_diagnostic || has_identity_warnings)
            && let Some(message) = popup_message
        {
            self.show_error_message(
                if needs_recovery_diagnostic {
                    "Local move requires recovery"
                } else {
                    "Local move completed with warnings"
                },
                message,
            );
        }
        if moved_count > 0 {
            let _ =
                self.persist_pending_local_move_mappings(LocalMovePersistenceAttempt::Automatic);
        }
        if completed.len() < planned.len() {
            self.reconcile_pending_local_move_journal(LocalMovePersistenceAttempt::Automatic);
        }
    }

    /// Remaps process-local identities and queues mappings for durable storage.
    ///
    /// The persistence layer consumes [`Self::take_local_move_mappings_for_persistence`]
    /// separately, allowing filesystem success to remain authoritative even if
    /// a later database transaction fails.
    #[cfg(any(feature = "local-rename", feature = "local-move"))]
    fn apply_completed_local_move_mappings(
        &mut self,
        mappings: &[LocalMoveMapping],
    ) -> Vec<String> {
        if mappings.is_empty() {
            return Vec::new();
        }
        self.local_move_persistence_queue
            .extend_from_slice(mappings);
        let mut warnings = Vec::new();

        macro_rules! remap_id {
            ($media_id:expr) => {
                if let Err(error) = crate::local_move::remap_local_media_id($media_id, mappings) {
                    warnings.push(format!(
                        "Could not remap an in-memory media identity: {error}"
                    ));
                }
            };
        }
        if let Some(media_id) = self.current_media.as_mut() {
            remap_id!(media_id);
        }
        if let Some(media_id) = self.view.playing_media_id.as_mut() {
            remap_id!(media_id);
        }
        if let Some(details) = self.view.details.as_mut()
            && let Some(media_id) = details.media_id.as_mut()
        {
            remap_id!(media_id);
        }
        for item in &mut self.playback_queue.items {
            remap_id!(&mut item.media.id);
            remap_local_queue_item(item, mappings);
        }
        if let Some(origin) = self.current_autoplay_origin.as_mut() {
            remap_local_autoplay_origin(origin, mappings);
        }
        if let Some(origin) = self.queued_autoplay_resume_origin.as_mut() {
            remap_local_autoplay_origin(origin, mappings);
        }
        for history in &mut self.history_entries {
            remap_id!(&mut history.entry.media_id);
            if history.entry.media_id.source == SourceKind::Local
                && let Some(locator) = history.entry.replay_locator.as_mut()
                && let Err(error) = crate::local_move::remap_local_replay_locator(locator, mappings)
            {
                warnings.push(format!(
                    "Could not remap an in-memory History path: {error}"
                ));
            }
        }
        if let Some(history) = self.pending_history.as_mut() {
            remap_id!(&mut history.media_id);
            if history.media_id.source == SourceKind::Local
                && let Some(locator) = history.replay_locator.as_mut()
                && let Err(error) = crate::local_move::remap_local_replay_locator(locator, mappings)
            {
                warnings.push(format!("Could not remap the pending History path: {error}"));
            }
        }
        if let Some(replay) = self.pending_history_replay.as_mut() {
            remap_id!(&mut replay.entry.media_id);
            if replay.entry.media_id.source == SourceKind::Local
                && let Some(locator) = replay.entry.replay_locator.as_mut()
                && let Err(error) = crate::local_move::remap_local_replay_locator(locator, mappings)
            {
                warnings.push(format!(
                    "Could not remap the selected History path: {error}"
                ));
            }
        }

        for item in &mut self.local_results {
            if let Some(path) = crate::local_move::remap_local_path_prefix(&item.path, mappings) {
                item.path = path;
            }
        }
        if let Some(details) = self.view.details.as_mut()
            && let Some(thumbnail) = details.thumbnail_url.as_mut()
            && let Ok(path) = thumbnail.to_file_path()
            && let Some(remapped) = crate::local_move::remap_local_path_prefix(&path, mappings)
            && let Ok(url) = url::Url::from_file_path(remapped)
        {
            *thumbnail = url;
        }
        if let Some(collision) = self.local_progress_cache_collision(mappings) {
            self.local_progress_cache.clear();
            warnings.push(format!(
                "Cleared the Local watched-progress cache because destination `{}` acquired a second in-memory identity; durable progress was preserved",
                collision.external_id
            ));
        } else {
            let mut remapped_progress = HashMap::with_capacity(self.local_progress_cache.len());
            for (mut media_id, watched) in self.local_progress_cache.drain() {
                remap_id!(&mut media_id);
                remapped_progress.insert(media_id, watched);
            }
            self.local_progress_cache = remapped_progress;
        }

        self.purge_moved_local_cache_paths(mappings);
        if let Some(listing) = self.local_listing.as_mut() {
            listing
                .entries
                .retain(|entry| !mappings.iter().any(|mapping| entry.path == mapping.source));
            self.view.selected = self.view.selected.min(
                listing
                    .entries
                    .len()
                    .saturating_add(usize::from(listing.parent.is_some()))
                    .saturating_sub(1),
            );
            self.refresh_local_browser_rows();
        }
        warnings
    }

    /// Drains filesystem mappings that must be applied in one StateStore transaction.
    #[cfg(any(feature = "local-rename", feature = "local-move"))]
    pub fn take_local_move_mappings_for_persistence(&mut self) -> Vec<LocalMoveMapping> {
        std::mem::take(&mut self.local_move_persistence_queue)
    }

    /// Persists one complete batch of authoritative Local move mappings.
    ///
    /// Failed transactions restore the entire batch. Automatic callers report
    /// a new failure once and then stop touching SQLite until an explicit Move
    /// or Quit action requests another attempt.
    #[cfg(any(feature = "local-rename", feature = "local-move"))]
    fn persist_pending_local_move_mappings(
        &mut self,
        attempt: LocalMovePersistenceAttempt,
    ) -> bool {
        if self.local_move_persistence_queue.is_empty() {
            return self.reconcile_pending_local_move_journal(attempt);
        }
        if attempt == LocalMovePersistenceAttempt::Automatic
            && self.local_move_persistence_failure.is_some()
        {
            return false;
        }
        let mappings = self.take_local_move_mappings_for_persistence();
        match self.store.remap_local_move_state(&mappings) {
            Ok(_) => {
                self.local_move_persistence_failure = None;
                self.local_move_journal_pending = self
                    .store
                    .local_move_intents()
                    .map_or(true, |mappings| !mappings.is_empty());
                true
            }
            Err(error) => {
                self.local_move_persistence_queue = mappings;
                let message = error.to_string();
                let should_report = attempt == LocalMovePersistenceAttempt::Explicit
                    || self.local_move_persistence_failure.as_deref() != Some(&message);
                self.local_move_persistence_failure = Some(message);
                if should_report {
                    self.show_error("Could not save moved Local identities", &error);
                }
                false
            }
        }
    }

    /// Rechecks durable crash-recovery intents without retrying known failures
    /// from a periodic tick.
    #[cfg(any(feature = "local-rename", feature = "local-move"))]
    fn reconcile_pending_local_move_journal(
        &mut self,
        attempt: LocalMovePersistenceAttempt,
    ) -> bool {
        if !self.local_move_persistence_queue.is_empty() {
            return false;
        }
        if !self.local_move_journal_pending {
            return true;
        }
        if attempt == LocalMovePersistenceAttempt::Automatic
            && self.local_move_persistence_failure.is_some()
        {
            return false;
        }
        match reconcile_local_move_journal(&self.store) {
            Ok(report) if report.unresolved.is_empty() => {
                self.local_move_journal_pending = false;
                self.local_move_persistence_failure = None;
                true
            }
            Ok(report) => {
                self.local_move_journal_pending = true;
                let message = format_local_move_reconciliation(&report);
                let should_report = attempt == LocalMovePersistenceAttempt::Explicit
                    || self.local_move_persistence_failure.as_deref() != Some(&message);
                self.local_move_persistence_failure = Some(message.clone());
                if should_report {
                    self.show_error_message("Local move recovery is required", message);
                }
                false
            }
            Err(error) => {
                self.local_move_journal_pending = true;
                let should_report = attempt == LocalMovePersistenceAttempt::Explicit
                    || self.local_move_persistence_failure.as_deref() != Some(&error);
                self.local_move_persistence_failure = Some(error.clone());
                if should_report {
                    self.show_error_message("Could not reconcile interrupted Local moves", error);
                }
                false
            }
        }
    }

    /// Drops cached filesystem facts whose source or destination identity changed.
    #[cfg(any(feature = "local-rename", feature = "local-move"))]
    fn purge_moved_local_cache_paths(&mut self, mappings: &[LocalMoveMapping]) {
        let affected = |path: &Path| {
            mappings.iter().any(|mapping| {
                path.starts_with(&mapping.source) || path.starts_with(&mapping.target)
            })
        };
        self.local_folder_size_cache
            .retain(|path, _| !affected(path));
        self.local_folder_size_cache_order
            .retain(|path| !affected(path));
        self.local_folder_size_failures
            .retain(|path, _| !affected(path));
        self.local_folder_size_failure_order
            .retain(|path| !affected(path));
        self.local_folder_size_queue.retain(|path| !affected(path));
        if self
            .local_folder_size_pending
            .as_deref()
            .is_some_and(&affected)
        {
            self.local_folder_size_pending = None;
        }
        #[cfg(all(feature = "local-artwork", feature = "images"))]
        {
            self.local_artwork_cache.retain(|path, _| !affected(path));
            self.local_artwork_cache_order
                .retain(|path| !affected(path));
            if self
                .pending_local_artwork
                .as_ref()
                .is_some_and(|(_, path)| affected(path))
            {
                self.pending_local_artwork = None;
                self.view.local_artwork_pending = false;
            }
        }
    }

    /// Reports whether an approved Local move may currently mutate the filesystem.
    fn local_move_is_executing(&self) -> bool {
        #[cfg(feature = "local-move")]
        {
            self.local_move_execution_pending
        }
        #[cfg(not(feature = "local-move"))]
        {
            false
        }
    }

    /// Closes a Local popup unless an approved move is already executing.
    fn dismiss_local_file_popup(&mut self) {
        let downloaded_trash = matches!(
            self.view.local_file_popup.as_ref(),
            Some(LocalFilePopupView::DownloadedTrash { .. })
        );
        #[cfg(feature = "local-move")]
        if self.local_move_execution_pending
            && matches!(
                self.view.local_file_popup.as_ref(),
                Some(LocalFilePopupView::Move { .. })
            )
        {
            self.view.status_line =
                "Wait for the Local move to finish before closing it".to_owned();
            return;
        }
        #[cfg(feature = "local-move")]
        if matches!(
            self.view.local_file_popup.as_ref(),
            Some(LocalFilePopupView::Move { .. })
        ) {
            self.local_move_generation = self.local_move_generation.wrapping_add(1);
            self.local_move_selection = None;
        }
        self.view.local_file_popup = None;
        self.view.status_line = if downloaded_trash {
            "Downloaded item was not changed"
        } else {
            "Local file was not changed"
        }
        .to_owned();
    }

