fn provider_worker(
    provider: Option<Box<dyn Provider>>,
    requests: Receiver<ProviderRequest>,
    responses: Sender<ProviderResponse>,
    allow_insecure_http: bool,
    mod_archive_api_key: Option<String>,
    jamendo_client_id: Option<String>,
    #[cfg(feature = "apple-podcasts")] apple_client: Box<dyn AppleProviderClient>,
    #[cfg(feature = "bandcamp")] bandcamp_search_client: Box<dyn BandcampSearchProvider>,
    #[cfg(feature = "rss")] rss_client: Box<dyn RssFeedClient>,
    #[cfg(feature = "youtube-music")] youtube_music_client: Box<dyn YouTubeMusicSearchProvider>,
    provider_storage_root: PathBuf,
) {
    let mut provider = provider;
    #[cfg(feature = "rss")]
    let (rss_requests, rss_pending, rss_stopping, rss_thread, rss_start_error) = {
        let (rss_requests, rss_receiver) = bounded(1);
        let rss_pending = rss_receiver.clone();
        let rss_stopping = Arc::new(AtomicBool::new(false));
        let worker_stopping = Arc::clone(&rss_stopping);
        let rss_responses = responses.clone();
        match thread::Builder::new()
            .name("youta-rss".to_owned())
            .spawn(move || {
                rss_provider_worker(rss_receiver, rss_responses, worker_stopping, rss_client);
            }) {
            Ok(handle) => (
                Some(rss_requests),
                Some(rss_pending),
                rss_stopping,
                Some(handle),
                None,
            ),
            Err(error) => (None, None, rss_stopping, None, Some(error.to_string())),
        }
    };
    #[cfg(feature = "apple-podcasts")]
    let (apple_requests, apple_pending, apple_stopping, apple_thread, apple_start_error) = {
        let (apple_requests, apple_receiver) = bounded(1);
        let apple_pending = apple_receiver.clone();
        let apple_stopping = Arc::new(AtomicBool::new(false));
        let worker_stopping = Arc::clone(&apple_stopping);
        let apple_responses = responses.clone();
        match thread::Builder::new()
            .name("youta-apple-podcasts".to_owned())
            .spawn(move || {
                apple_provider_worker(
                    apple_receiver,
                    apple_responses,
                    worker_stopping,
                    apple_client,
                );
            }) {
            Ok(handle) => (
                Some(apple_requests),
                Some(apple_pending),
                apple_stopping,
                Some(handle),
                None,
            ),
            Err(error) => (None, None, apple_stopping, None, Some(error.to_string())),
        }
    };
    #[cfg(feature = "bandcamp")]
    let (
        bandcamp_search_requests,
        bandcamp_search_pending,
        bandcamp_search_stopping,
        bandcamp_search_thread,
        bandcamp_search_start_error,
    ) = {
        let (search_requests, search_receiver) = bounded(1);
        let search_pending = search_receiver.clone();
        let search_stopping = Arc::new(AtomicBool::new(false));
        let worker_stopping = Arc::clone(&search_stopping);
        let search_responses = responses.clone();
        match thread::Builder::new()
            .name("youta-bandcamp-search".to_owned())
            .spawn(move || {
                bandcamp_search_worker(
                    search_receiver,
                    search_responses,
                    worker_stopping,
                    bandcamp_search_client,
                );
            }) {
            Ok(handle) => (
                Some(search_requests),
                Some(search_pending),
                search_stopping,
                Some(handle),
                None,
            ),
            Err(error) => (None, None, search_stopping, None, Some(error.to_string())),
        }
    };
    #[cfg(feature = "youtube-music")]
    let (
        youtube_music_requests,
        youtube_music_pending,
        youtube_music_stopping,
        youtube_music_thread,
        youtube_music_start_error,
    ) = {
        let (music_requests, music_receiver) = bounded(1);
        let music_pending = music_receiver.clone();
        let music_stopping = Arc::new(AtomicBool::new(false));
        let worker_stopping = Arc::clone(&music_stopping);
        let music_responses = responses.clone();
        match thread::Builder::new()
            .name("youta-youtube-music".to_owned())
            .spawn(move || {
                youtube_music_provider_worker(
                    music_receiver,
                    music_responses,
                    worker_stopping,
                    youtube_music_client,
                );
            }) {
            Ok(handle) => (
                Some(music_requests),
                Some(music_pending),
                music_stopping,
                Some(handle),
                None,
            ),
            Err(error) => (None, None, music_stopping, None, Some(error.to_string())),
        }
    };
    #[cfg(feature = "soundstream")]
    let soundstream = crate::providers::soundstream::SoundStreamResolver::new();
    #[cfg(feature = "litres")]
    let litres = crate::providers::litres::LitresPublicResolver::new();
    #[cfg(feature = "jamendo")]
    let jamendo = jamendo_client_id
        .map(crate::providers::jamendo::JamendoProvider::new)
        .transpose()
        .map_err(|error| format!("invalid `providers.jamendo_client_id`: {error}"));
    #[cfg(feature = "tracker-music")]
    let tracker = crate::providers::tracker::TrackerArchiveHub::new(allow_insecure_http);
    #[cfg(feature = "tracker-music")]
    let mut tracker_preparer = {
        let limits = crate::tracker_media::TrackerMediaLimits::default();
        crate::tracker_media::UreqTrackerTransport::for_limits(
            crate::providers::DEFAULT_REQUEST_TIMEOUT,
            limits,
        )
        .map_err(|error| error.to_string())
        .and_then(|transport| {
            crate::tracker_media::TrackerMediaPreparer::new(
                &provider_storage_root,
                transport,
                limits,
            )
            .map_err(|error| error.to_string())
        })
    };
    #[cfg(feature = "tracker-music")]
    let mod_archive = mod_archive_api_key
        .and_then(|key| crate::providers::modarchive::ModArchiveProvider::new(key).ok());
    #[cfg(feature = "wikidata")]
    let wikidata = crate::providers::wikidata::WikidataProvider::new();
    #[cfg(feature = "radio")]
    let radio_now_playing = crate::providers::radio::RadioNowPlayingClient::new();
    #[cfg(feature = "bbc-radio")]
    let bbc_live = BbcLiveResolver::new();
    #[cfg(feature = "network")]
    let youtube_channel_page =
        crate::providers::youtube_channel_page::YouTubeChannelPageClient::new();
    #[cfg(not(feature = "tracker-music"))]
    let _ = (
        allow_insecure_http,
        mod_archive_api_key,
        provider_storage_root,
    );
    #[cfg(not(feature = "jamendo"))]
    let _ = jamendo_client_id;

    while let Ok(request) = requests.recv() {
        match request {
            ProviderRequest::ReplaceYouTubeProvider {
                provider: replacement,
            } => {
                provider = Some(replacement);
            }
            ProviderRequest::Search {
                generation,
                request,
            } => {
                let result = provider.as_ref().map_or_else(
                    || Err("YouTube provider is not configured".to_owned()),
                    |provider| provider.search(&request).map_err(|error| error.to_string()),
                );
                if responses
                    .send(ProviderResponse::Search {
                        generation,
                        request,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "youtube-music")]
            ProviderRequest::YouTubeMusicSearch { generation, query } => {
                let dispatch = youtube_music_requests
                    .as_ref()
                    .zip(youtube_music_pending.as_ref())
                    .map_or_else(
                        || {
                            Err(youtube_music_start_error.clone().unwrap_or_else(|| {
                                "YouTube Music worker is unavailable".to_owned()
                            }))
                        },
                        |(sender, pending)| {
                            replace_latest_provider_request(
                                sender,
                                pending,
                                YouTubeMusicProviderRequest::Search {
                                    generation,
                                    query: query.clone(),
                                },
                            )
                            .map_err(|()| "YouTube Music worker stopped".to_owned())
                        },
                    );
                if let Err(error) = dispatch
                    && responses
                        .send(ProviderResponse::YouTubeMusicSearch {
                            generation,
                            query,
                            result: Err(error),
                        })
                        .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "bandcamp")]
            ProviderRequest::BandcampSearch {
                generation,
                query,
                page,
            } => {
                let dispatch = bandcamp_search_requests
                    .as_ref()
                    .zip(bandcamp_search_pending.as_ref())
                    .map_or_else(
                        || {
                            Err(bandcamp_search_start_error.clone().unwrap_or_else(|| {
                                "Bandcamp search worker is unavailable".to_owned()
                            }))
                        },
                        |(sender, pending)| {
                            replace_latest_provider_request(
                                sender,
                                pending,
                                BandcampSearchRequest::Search {
                                    generation,
                                    query: query.clone(),
                                    page,
                                },
                            )
                            .map_err(|()| "Bandcamp search worker stopped".to_owned())
                        },
                    );
                if let Err(error) = dispatch
                    && responses
                        .send(ProviderResponse::BandcampSearch {
                            generation,
                            query,
                            page,
                            result: Err(error),
                        })
                        .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "apple-podcasts")]
            ProviderRequest::ApplePodcastsSearch {
                generation,
                request,
            } => {
                let dispatch = apple_requests
                    .as_ref()
                    .zip(apple_pending.as_ref())
                    .map_or_else(
                        || {
                            Err(apple_start_error.clone().unwrap_or_else(|| {
                                "Apple Podcasts worker is unavailable".to_owned()
                            }))
                        },
                        |(sender, pending)| {
                            replace_latest_provider_request(
                                sender,
                                pending,
                                AppleProviderRequest::Search {
                                    generation,
                                    request: request.clone(),
                                },
                            )
                            .map_err(|()| "Apple Podcasts worker stopped".to_owned())
                        },
                    );
                if let Err(error) = dispatch
                    && responses
                        .send(ProviderResponse::ApplePodcastsSearch {
                            generation,
                            request,
                            result: Err(error),
                        })
                        .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "apple-podcasts")]
            ProviderRequest::ApplePodcastEpisodes {
                generation,
                country,
                collection_id,
            } => {
                let dispatch = apple_requests
                    .as_ref()
                    .zip(apple_pending.as_ref())
                    .map_or_else(
                        || {
                            Err(apple_start_error.clone().unwrap_or_else(|| {
                                "Apple Podcasts worker is unavailable".to_owned()
                            }))
                        },
                        |(sender, pending)| {
                            replace_latest_provider_request(
                                sender,
                                pending,
                                AppleProviderRequest::Episodes {
                                    generation,
                                    country,
                                    collection_id,
                                },
                            )
                            .map_err(|()| "Apple Podcasts worker stopped".to_owned())
                        },
                    );
                if let Err(error) = dispatch
                    && responses
                        .send(ProviderResponse::ApplePodcastEpisodes {
                            generation,
                            collection_id,
                            result: Err(error),
                        })
                        .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "rss")]
            ProviderRequest::RssFeed {
                generation,
                source_url,
            } => {
                let dispatch = rss_requests.as_ref().zip(rss_pending.as_ref()).map_or_else(
                    || {
                        Err(rss_start_error
                            .clone()
                            .unwrap_or_else(|| "RSS worker is unavailable".to_owned()))
                    },
                    |(sender, pending)| {
                        replace_latest_provider_request(
                            sender,
                            pending,
                            RssProviderRequest::Fetch {
                                generation,
                                source_url: source_url.clone(),
                            },
                        )
                        .map_err(|()| "RSS worker stopped".to_owned())
                    },
                );
                if let Err(error) = dispatch
                    && responses
                        .send(ProviderResponse::RssFeed {
                            generation,
                            requested_url: source_url,
                            result: Err(error),
                        })
                        .is_err()
                {
                    break;
                }
            }
            ProviderRequest::ChannelVideos {
                generation,
                request,
            } => {
                let result = provider.as_ref().map_or_else(
                    || Err("YouTube provider is not configured".to_owned()),
                    |provider| {
                        provider
                            .channel_videos(&request)
                            .map_err(|error| error.to_string())
                    },
                );
                if responses
                    .send(ProviderResponse::ChannelVideos {
                        generation,
                        request,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            ProviderRequest::Details {
                generation,
                video_id,
            } => {
                let result = provider.as_ref().map_or_else(
                    || Err("YouTube provider is not configured".to_owned()),
                    |provider| {
                        provider
                            .video_details(&video_id)
                            .map_err(|error| error.to_string())
                    },
                );
                if responses
                    .send(ProviderResponse::Details { generation, result })
                    .is_err()
                {
                    break;
                }
            }
            ProviderRequest::ChannelDetails {
                generation,
                provider_generation,
                channel_id,
            } => {
                let result = provider.as_ref().map_or_else(
                    || Err("YouTube provider is not configured".to_owned()),
                    |provider| {
                        provider
                            .full_channel_details(&channel_id)
                            .map_err(|error| error.to_string())
                    },
                );
                let can_enrich_from_page = result.is_ok();
                if responses
                    .send(ProviderResponse::ChannelDetails {
                        generation,
                        provider_generation,
                        channel_id: channel_id.clone(),
                        result,
                    })
                    .is_err()
                {
                    break;
                }
                #[cfg(feature = "network")]
                if can_enrich_from_page {
                    let result = youtube_channel_page
                        .channel_metadata(&channel_id)
                        .map_err(|error| error.to_string());
                    if responses
                        .send(ProviderResponse::ChannelPageMetadata {
                            generation,
                            provider_generation,
                            channel_id,
                            result,
                        })
                        .is_err()
                    {
                        break;
                    }
                }
                #[cfg(not(feature = "network"))]
                let _ = can_enrich_from_page;
            }
            ProviderRequest::ChannelSubscriberCounts {
                provider_generation,
                channel_ids,
            } => {
                let requested_ids = channel_ids.clone();
                let result = provider.as_ref().map_or_else(
                    || Err("YouTube provider is not configured".to_owned()),
                    |provider| {
                        provider
                            .channel_subscriber_counts(&channel_ids)
                            .map_err(|error| error.to_string())
                    },
                );
                if responses
                    .send(ProviderResponse::ChannelSubscriberCounts {
                        provider_generation,
                        requested_ids,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            ProviderRequest::ResolveApple { generation, url } => {
                #[cfg(feature = "apple-podcasts")]
                let result: Result<(), String> = apple_requests
                    .as_ref()
                    .zip(apple_pending.as_ref())
                    .map_or_else(
                        || {
                            Err(apple_start_error.clone().unwrap_or_else(|| {
                                "Apple Podcasts worker is unavailable".to_owned()
                            }))
                        },
                        |(sender, pending)| {
                            replace_latest_provider_request(
                                sender,
                                pending,
                                AppleProviderRequest::Resolve { generation, url },
                            )
                            .map_err(|()| "Apple Podcasts worker stopped".to_owned())
                        },
                    );
                #[cfg(not(feature = "apple-podcasts"))]
                let result: Result<(), String> = {
                    let _ = url;
                    Err("this build omits the `apple-podcasts` feature".to_owned())
                };
                if let Err(error) = result
                    && responses
                        .send(ProviderResponse::Apple {
                            generation,
                            result: Err(error),
                        })
                        .is_err()
                {
                    break;
                }
            }
            ProviderRequest::ResolveFirstClass { generation, direct } => {
                let source = direct.source.clone();
                let result = match direct.source {
                    SourceKind::SoundStream => {
                        #[cfg(feature = "soundstream")]
                        {
                            soundstream
                                .resolve(&direct.url)
                                .map(resolved_soundstream_media)
                                .map_err(|error| error.to_string())
                        }
                        #[cfg(not(feature = "soundstream"))]
                        {
                            Err("this build omits the `soundstream` feature".to_owned())
                        }
                    }
                    SourceKind::LitRes => {
                        #[cfg(feature = "litres")]
                        {
                            litres
                                .resolve(&direct.url)
                                .map(resolved_litres_media)
                                .map_err(|error| error.to_string())
                        }
                        #[cfg(not(feature = "litres"))]
                        {
                            Err("this build omits the `litres` feature".to_owned())
                        }
                    }
                    SourceKind::Jamendo => {
                        #[cfg(feature = "jamendo")]
                        {
                            jamendo.as_ref().map_err(Clone::clone).and_then(|provider| {
                                let provider = provider.as_ref().ok_or_else(|| {
                                    "set `providers.jamendo_client_id` to a client ID issued \
                                     for your Jamendo application"
                                        .to_owned()
                                })?;
                                let track_id = jamendo_track_id(&direct.url)?;
                                provider
                                    .track(&track_id)
                                    .map(resolved_jamendo_media)
                                    .map_err(|error| error.to_string())
                            })
                        }
                        #[cfg(not(feature = "jamendo"))]
                        {
                            Err("this build omits the `jamendo` feature".to_owned())
                        }
                    }
                    SourceKind::BbcRadio => {
                        #[cfg(feature = "bbc-radio")]
                        {
                            bbc_station_from_url(&direct.url)
                                .ok_or_else(|| {
                                    "the BBC Sounds link is not a stable live-station page"
                                        .to_owned()
                                })
                                .and_then(|station| {
                                    bbc_live
                                        .resolve_station(station)
                                        .map(resolved_bbc_media)
                                        .map_err(|error| error.to_string())
                                })
                        }
                        #[cfg(not(feature = "bbc-radio"))]
                        {
                            Err("this build omits the `bbc-radio` feature".to_owned())
                        }
                    }
                    _ => Err("the requested source has no first-class direct resolver".to_owned()),
                };
                if responses
                    .send(ProviderResponse::FirstClass {
                        generation,
                        source,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            ProviderRequest::TrackerSearch { generation, query } => {
                #[cfg(feature = "tracker-music")]
                {
                    if let Some(provider) = &mod_archive {
                        let request =
                            crate::providers::modarchive::ModuleSearchRequest::new(query.clone());
                        let result = provider
                            .search(&request)
                            .map(|page| {
                                page.modules
                                    .into_iter()
                                    .map(|module| TrackerItem {
                                        source: "The Mod Archive".to_owned(),
                                        title: if module.song_title.trim().is_empty() {
                                            module.filename
                                        } else {
                                            module.song_title
                                        },
                                        subtitle: format!(
                                            "{} · {}",
                                            module.format,
                                            module.size_bytes.map_or_else(
                                                || "unknown size".to_owned(),
                                                human_bytes,
                                            )
                                        ),
                                        webpage_url: module.webpage_url,
                                        download_url: Some(module.download_url),
                                        expected_format: Some(module.format),
                                        access: TrackerAccess::DirectModule,
                                        prepared_path: None,
                                        insecure_transport: false,
                                    })
                                    .collect()
                            })
                            .map_err(|error| error.to_string());
                        if responses
                            .send(ProviderResponse::TrackerSource {
                                generation,
                                source: "The Mod Archive".to_owned(),
                                result,
                            })
                            .is_err()
                        {
                            break;
                        }
                    }
                    for source in crate::providers::tracker::TrackerArchiveSource::ALL {
                        let descriptor = source.descriptor();
                        let request =
                            crate::providers::tracker::TrackerSearchRequest::new(query.clone());
                        let result = tracker
                            .search(source, &request)
                            .map(|page| {
                                page.items
                                    .into_iter()
                                    .map(tracker_item_from_provider)
                                    .collect()
                            })
                            .map_err(|error| error.to_string());
                        if responses
                            .send(ProviderResponse::TrackerSource {
                                generation,
                                source: descriptor.display_name.to_owned(),
                                result,
                            })
                            .is_err()
                        {
                            return;
                        }
                    }
                }
                #[cfg(not(feature = "tracker-music"))]
                {
                    let _ = query;
                    if responses
                        .send(ProviderResponse::TrackerSource {
                            generation,
                            source: "MOD/tracker".to_owned(),
                            result: Err("this build omits the `tracker-music` feature".to_owned()),
                        })
                        .is_err()
                    {
                        break;
                    }
                }
                if responses
                    .send(ProviderResponse::TrackerComplete { generation })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "tracker-music")]
            ProviderRequest::PrepareTracker {
                generation,
                item_key,
                request,
            } => {
                let result = match tracker_preparer.as_mut() {
                    Ok(preparer) => preparer
                        .prepare(&request)
                        .map_err(|error| error.to_string()),
                    Err(error) => Err(error.clone()),
                };
                if responses
                    .send(ProviderResponse::TrackerPrepared {
                        generation,
                        item_key,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "local-browser")]
            ProviderRequest::ScanLocal { generation, root } => {
                let result = scan_local_media(&root);
                if responses
                    .send(ProviderResponse::LocalScan {
                        generation,
                        root,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(all(feature = "local-artwork", feature = "images"))]
            ProviderRequest::LocalArtwork {
                generation,
                path,
                cache_directory,
                kind,
            } => {
                let result = match kind {
                    LocalArtworkKind::EmbeddedMedia => {
                        crate::thumbnails::cached_local_artwork(&path, &cache_directory)
                            .map_err(|error| error.to_string())
                    }
                    LocalArtworkKind::FolderCover => {
                        crate::local_browser::find_local_folder_cover(&path)
                            .map(|cover| {
                                cover.and_then(|cover| url::Url::from_file_path(cover).ok())
                            })
                            .map_err(|error| error.to_string())
                    }
                };
                if responses
                    .send(ProviderResponse::LocalArtwork {
                        generation,
                        path,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            ProviderRequest::LocalFolderSize {
                generation,
                path,
                cancellation,
                cached,
            } => {
                let cancelled = || cancellation.load(AtomicOrdering::Relaxed) != generation;
                let reusable = (!cancelled())
                    .then_some(cached)
                    .flatten()
                    .filter(|measurement| {
                        crate::local_browser::local_directory_identity(&path)
                            .is_ok_and(|identity| identity == measurement.identity)
                    });
                let result = reusable
                    .map_or_else(
                        || {
                            crate::local_browser::measure_local_folder_size(
                                &path,
                                crate::local_browser::LocalFolderSizeLimits::default(),
                                cancelled,
                            )
                            .map(|measurement| {
                                LocalFolderSizeWorkerResult {
                                    measurement,
                                    reused: false,
                                }
                            })
                        },
                        |measurement| {
                            Ok(LocalFolderSizeWorkerResult {
                                measurement,
                                reused: true,
                            })
                        },
                    )
                    .map_err(|error| error.to_string());
                if responses
                    .send(ProviderResponse::LocalFolderSize {
                        generation,
                        path,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "wikidata")]
            ProviderRequest::Wikidata {
                generation,
                kind,
                external_id,
            } => {
                let property_id = kind.property_id().to_owned();
                let result = wikidata
                    .lookup_external(kind, &external_id)
                    .map(|lookup| lookup.items)
                    .map_err(|error| error.to_string());
                if responses
                    .send(ProviderResponse::Wikidata {
                        generation,
                        property_id,
                        external_id,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "wikidata")]
            ProviderRequest::WikidataStatements { item_id } => {
                let result = wikidata
                    .load_entity_statements(&item_id)
                    .map_err(|error| error.to_string());
                if responses
                    .send(ProviderResponse::WikidataStatements { item_id, result })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "radio")]
            ProviderRequest::RadioNowPlaying {
                generation,
                station_id,
                endpoint,
            } => {
                let result = radio_now_playing
                    .fetch(endpoint)
                    .map_err(|error| error.to_string());
                if responses
                    .send(ProviderResponse::RadioNowPlaying {
                        generation,
                        station_id,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            #[cfg(feature = "bbc-radio")]
            ProviderRequest::ResolveBbcLive {
                generation,
                station_id,
            } => {
                let result = bbc_station_by_id(&station_id)
                    .ok_or_else(|| "the BBC station is not present in this build".to_owned())
                    .and_then(|station| {
                        bbc_live
                            .resolve_station(station)
                            .map_err(|error| error.to_string())
                    });
                if responses
                    .send(ProviderResponse::BbcLive {
                        generation,
                        station_id,
                        result,
                    })
                    .is_err()
                {
                    break;
                }
            }
            ProviderRequest::Shutdown => break,
        }
    }
    #[cfg(feature = "apple-podcasts")]
    {
        apple_stopping.store(true, AtomicOrdering::Release);
        drop(apple_requests);
        drop(apple_pending);
    }
    #[cfg(feature = "rss")]
    {
        rss_stopping.store(true, AtomicOrdering::Release);
        drop(rss_requests);
        drop(rss_pending);
    }
    #[cfg(feature = "bandcamp")]
    {
        bandcamp_search_stopping.store(true, AtomicOrdering::Release);
        drop(bandcamp_search_requests);
        drop(bandcamp_search_pending);
    }
    #[cfg(feature = "youtube-music")]
    {
        youtube_music_stopping.store(true, AtomicOrdering::Release);
        drop(youtube_music_requests);
        drop(youtube_music_pending);
    }
    #[cfg(feature = "apple-podcasts")]
    if let Some(handle) = apple_thread {
        let _ = handle.join();
    }
    #[cfg(feature = "rss")]
    if let Some(handle) = rss_thread {
        let _ = handle.join();
    }
    #[cfg(feature = "bandcamp")]
    if let Some(handle) = bandcamp_search_thread {
        let _ = handle.join();
    }
    #[cfg(feature = "youtube-music")]
    if let Some(handle) = youtube_music_thread {
        let _ = handle.join();
    }
}

#[cfg(feature = "apple-podcasts")]
fn podcast_show_summary_from_apple(podcast: ApplePodcastMetadata) -> PodcastShowSummary {
    PodcastShowSummary {
        id: MediaId::new(SourceKind::ApplePodcasts, podcast.collection_id.to_string()),
        title: podcast.title,
        author: podcast.author,
        feed_url: podcast.feed_url,
        webpage_url: podcast.webpage_url,
        artwork_url: podcast.artwork_url,
        episode_count: podcast.episode_count,
        genres: podcast.genres,
        explicit: podcast.explicit,
    }
}

#[cfg(feature = "apple-podcasts")]
fn resolved_apple_media(
    resolved: crate::providers::apple_podcasts::ResolvedApplePodcast,
) -> ResolvedDirectMedia {
    if let Some(episode) = resolved.episode {
        let playable = episode.media_url.is_some();
        let description = episode.description.unwrap_or_else(|| {
            format!(
                "Episode of {}{}",
                episode.podcast_title,
                resolved
                    .podcast
                    .feed_url
                    .as_ref()
                    .map_or_else(String::new, |url| format!("\nRSS: {url}"))
            )
        });
        ResolvedDirectMedia {
            source: SourceKind::ApplePodcasts,
            external_id: episode.episode_id.to_string(),
            title: episode.title,
            row_subtitle: episode.duration_seconds.map_or_else(
                || "episode".to_owned(),
                |duration| format!("episode · {}", format_seconds(duration)),
            ),
            description,
            license: "publisher terms".to_owned(),
            published: episode.published_at,
            artwork_url: episode.artwork_url.or(resolved.podcast.artwork_url),
            duration_seconds: episode.duration_seconds,
            playback_url: episode.media_url,
            webpage_url: episode.webpage_url.or(resolved.podcast.webpage_url),
            status_line: if playable {
                "Apple Podcasts episode resolved; press Enter to play".to_owned()
            } else {
                "Apple Podcasts metadata resolved, but its RSS item has no public enclosure"
                    .to_owned()
            },
        }
    } else {
        let description = format!(
            "{}{}{}",
            resolved.podcast.author.unwrap_or_default(),
            resolved
                .podcast
                .feed_url
                .as_ref()
                .map_or_else(String::new, |url| format!("\nRSS: {url}")),
            if resolved.podcast.genres.is_empty() {
                String::new()
            } else {
                format!("\nGenres: {}", resolved.podcast.genres.join(", "))
            }
        );
        ResolvedDirectMedia {
            source: SourceKind::ApplePodcasts,
            external_id: resolved.podcast.collection_id.to_string(),
            title: resolved.podcast.title,
            row_subtitle: "podcast show".to_owned(),
            description,
            license: "publisher terms".to_owned(),
            published: None,
            artwork_url: resolved.podcast.artwork_url,
            duration_seconds: None,
            playback_url: None,
            webpage_url: resolved.podcast.webpage_url,
            status_line: "Apple podcast resolved to its public RSS feed; select an episode to play"
                .to_owned(),
        }
    }
}

fn direct_source_label(source: &SourceKind) -> &'static str {
    match source {
        SourceKind::ApplePodcasts => "Apple Podcasts",
        SourceKind::BbcRadio => "BBC Sounds",
        SourceKind::SoundStream => "SoundStream",
        SourceKind::LitRes => "LitRes",
        SourceKind::Jamendo => "Jamendo",
        _ => "Direct source",
    }
}

fn requires_first_class_direct_resolution(source: &SourceKind) -> bool {
    matches!(
        source,
        SourceKind::BbcRadio | SourceKind::SoundStream | SourceKind::LitRes | SourceKind::Jamendo
    )
}

/// Converts one action-scoped BBC manifest into first-class display metadata.
#[cfg(feature = "bbc-radio")]
fn resolved_bbc_media(resolution: BbcLiveResolution) -> ResolvedDirectMedia {
    let station = resolution.station;
    let quality = format_bbc_quality(&resolution);
    ResolvedDirectMedia {
        source: SourceKind::BbcRadio,
        external_id: station.id.to_owned(),
        title: station.name.to_owned(),
        row_subtitle: quality.clone(),
        description: format!("{}\nQuality: {quality}", station.group.summary()),
        license: "BBC terms".to_owned(),
        published: None,
        artwork_url: None,
        duration_seconds: None,
        playback_url: Some(resolution.manifest_url),
        webpage_url: station.sounds_url().ok(),
        status_line: "BBC live radio resolved; press Enter to play".to_owned(),
    }
}

fn apply_resolved_direct_view(
    store: &StateStore,
    view: &mut ViewModel,
    media: &ResolvedDirectMedia,
) {
    let source = direct_source_label(&media.source);
    let media_id = MediaId::new(media.source.clone(), media.external_id.clone());
    view.rows = vec![RowView {
        media_id: Some(media_id.clone()),
        title: media.title.clone(),
        subtitle: media.row_subtitle.clone(),
        source: source.to_owned(),
        ..RowView::default()
    }];
    hydrate_row_playback_progress(store, &mut view.rows);
    view.details = Some(DetailView {
        media_id: Some(media_id),
        title: media.title.clone(),
        source: source.to_owned(),
        length: media
            .duration_seconds
            .map_or_else(|| "unknown".to_owned(), format_seconds),
        description: media.description.clone(),
        timecodes: detail_timecodes(&media.description),
        published: media
            .published
            .clone()
            .unwrap_or_else(|| "unknown".to_owned()),
        license: media.license.clone(),
        wikidata: "not loaded".to_owned(),
        thumbnail_url: media.artwork_url.clone(),
        ..DetailView::default()
    });
    view.status_line.clone_from(&media.status_line);
}

#[cfg(feature = "soundstream")]
fn resolved_soundstream_media(
    resolved: crate::providers::soundstream::ResolvedSoundStream,
) -> ResolvedDirectMedia {
    use crate::providers::soundstream::SoundStreamMetadata;

    match resolved.metadata {
        SoundStreamMetadata::Playlist(playlist) => {
            let mut metadata = Vec::new();
            if let Some(source) = playlist.source_url {
                metadata.push(format!("Publisher page: {source}"));
            }
            if let Some(feed) = playlist.feed_url {
                metadata.push(format!("RSS: {feed}"));
            }
            if let Some(count) = playlist.clip_count {
                metadata.push(format!("Episodes: {count}"));
            }
            if let Some(explicit) = playlist.explicit {
                metadata.push(format!("Explicit: {}", if explicit { "yes" } else { "no" }));
            }
            ResolvedDirectMedia {
                source: SourceKind::SoundStream,
                external_id: playlist.playlist_id.to_string(),
                title: playlist.title,
                row_subtitle: playlist.clip_count.map_or_else(
                    || "playlist".to_owned(),
                    |count| format!("playlist · {count} episode(s)"),
                ),
                description: append_metadata(playlist.description, metadata),
                license: "publisher terms".to_owned(),
                published: None,
                artwork_url: playlist.artwork_url,
                duration_seconds: None,
                playback_url: None,
                webpage_url: Some(playlist.webpage_url),
                status_line: "SoundStream playlist metadata resolved; no public episode was \
                              selected for playback"
                    .to_owned(),
            }
        }
        SoundStreamMetadata::Clip(clip) => {
            let playable = clip.media_url.is_some();
            let mut metadata = Vec::new();
            for playlist in &clip.playlists {
                metadata.push(format!(
                    "Playlist: {} ({}){}",
                    playlist.title,
                    playlist.webpage_url,
                    playlist
                        .feed_url
                        .as_ref()
                        .map_or_else(String::new, |feed| format!(" · RSS: {feed}"))
                ));
            }
            if let Some(explicit) = clip.explicit {
                metadata.push(format!("Explicit: {}", if explicit { "yes" } else { "no" }));
            }
            ResolvedDirectMedia {
                source: SourceKind::SoundStream,
                external_id: clip.clip_id.to_string(),
                title: clip.title,
                row_subtitle: clip.duration_seconds.map_or_else(
                    || "clip".to_owned(),
                    |duration| format!("clip · {}", format_seconds(duration)),
                ),
                description: append_metadata(clip.description, metadata),
                license: "publisher terms".to_owned(),
                published: clip.published_at,
                artwork_url: clip.artwork_url,
                duration_seconds: clip.duration_seconds,
                playback_url: clip.media_url,
                webpage_url: Some(clip.webpage_url),
                status_line: if playable {
                    "SoundStream exposed a public media enclosure; press Enter to play".to_owned()
                } else {
                    "SoundStream clip metadata resolved, but no credential-free public media \
                     enclosure was exposed"
                        .to_owned()
                },
            }
        }
    }
}

#[cfg(feature = "litres")]
fn resolved_litres_media(page: crate::providers::litres::LitresPublicPage) -> ResolvedDirectMedia {
    use crate::providers::litres::LitresPublicMediaAccess;

    let selected_media = page
        .media
        .iter()
        .find(|media| media.access == LitresPublicMediaAccess::Full)
        .or_else(|| page.media.first())
        .cloned();
    let access = selected_media.as_ref().map(|media| media.access);
    let mut metadata = Vec::new();
    if !page.creators.is_empty() {
        metadata.push(format!("Creators: {}", page.creators.join(", ")));
    }
    if let Some(is_free) = page.is_free {
        metadata.push(format!(
            "Public page marks item free: {}",
            if is_free { "yes" } else { "no" }
        ));
    }
    if let Some(price) = &page.price {
        metadata.push(format!(
            "Price: {price}{}",
            page.price_currency
                .as_ref()
                .map_or_else(String::new, |currency| format!(" {currency}"))
        ));
    }
    match access {
        Some(LitresPublicMediaAccess::Preview) => {
            metadata.push("Playback media: preview only".to_owned());
        }
        Some(LitresPublicMediaAccess::Full) => {
            metadata.push("Playback media: explicitly public full item".to_owned());
        }
        None => metadata.push("Playback media: not exposed by the public page".to_owned()),
    }
    if let Some(mime_type) = selected_media
        .as_ref()
        .and_then(|media| media.mime_type.as_deref())
    {
        metadata.push(format!("Playback media type: {mime_type}"));
    }

    ResolvedDirectMedia {
        source: SourceKind::LitRes,
        external_id: page.link.item_id.to_string(),
        title: page.title,
        row_subtitle: match access {
            Some(LitresPublicMediaAccess::Preview) => "preview".to_owned(),
            Some(LitresPublicMediaAccess::Full) => "free public media".to_owned(),
            None => "metadata only".to_owned(),
        },
        description: append_metadata(page.description, metadata),
        license: "publisher terms".to_owned(),
        published: page.published_at,
        artwork_url: page.artwork_url,
        duration_seconds: page.duration_seconds,
        playback_url: selected_media.map(|media| media.url),
        webpage_url: Some(page.link.canonical_url),
        status_line: match access {
            Some(LitresPublicMediaAccess::Preview) => {
                "LitRes preview resolved; press Enter to play the preview".to_owned()
            }
            Some(LitresPublicMediaAccess::Full) => {
                "LitRes explicitly public media resolved; press Enter to play".to_owned()
            }
            None => {
                "LitRes metadata resolved; the public page exposes no playable media URL".to_owned()
            }
        },
    }
}

#[cfg(feature = "jamendo")]
fn resolved_jamendo_media(track: crate::providers::jamendo::JamendoTrack) -> ResolvedDirectMedia {
    let mut metadata = vec![
        format!("Artist: {}", track.artist_name),
        format!("Artist ID: {}", track.artist_id),
    ];
    if let Some(album) = &track.album_name {
        metadata.push(format!(
            "Album: {album}{}",
            track
                .album_id
                .as_ref()
                .map_or_else(String::new, |album_id| format!(" (ID: {album_id})"))
        ));
    }
    if !track.tags.is_empty() {
        metadata.push(format!("Tags: {}", track.tags.join(", ")));
    }
    if let Some(short_url) = &track.short_url {
        metadata.push(format!("Short link: {short_url}"));
    }
    metadata.push(if let Some(url) = &track.download_url {
        format!("Official download allowed: yes ({url})")
    } else {
        "Official download allowed: no".to_owned()
    });

    ResolvedDirectMedia {
        source: SourceKind::Jamendo,
        external_id: track.track_id,
        title: track.title,
        row_subtitle: format!(
            "{} · {}",
            track.artist_name,
            format_seconds(track.duration_seconds)
        ),
        description: append_metadata(None, metadata),
        license: track.license_ccurl,
        published: track.release_date,
        artwork_url: track.artwork_url,
        duration_seconds: Some(track.duration_seconds),
        playback_url: Some(track.audio_stream_url),
        webpage_url: Some(track.share_url),
        status_line: "Jamendo track resolved through the official API; press Enter to play"
            .to_owned(),
    }
}

#[cfg(any(feature = "soundstream", feature = "litres", feature = "jamendo"))]
fn append_metadata(description: Option<String>, metadata: Vec<String>) -> String {
    let mut parts = description
        .filter(|value| !value.trim().is_empty())
        .into_iter()
        .collect::<Vec<_>>();
    parts.extend(
        metadata
            .into_iter()
            .filter(|value| !value.trim().is_empty()),
    );
    parts.join("\n")
}

#[cfg(feature = "jamendo")]
fn jamendo_track_id(url: &url::Url) -> Result<String, String> {
    if url.scheme() != "https"
        || !url.username().is_empty()
        || url.password().is_some()
        || url.port().is_some()
    {
        return Err(
            "Jamendo track links must use credential-free HTTPS without a custom port".to_owned(),
        );
    }
    let host = url.host_str().unwrap_or_default();
    let mut segments = url
        .path_segments()
        .ok_or_else(|| "Jamendo track link must have path segments".to_owned())?
        .filter(|segment| !segment.is_empty());
    let prefix = segments.next();
    let track_id = segments.next();
    let remaining = segments.count();
    let expected_prefix = match host {
        "jamendo.com" | "www.jamendo.com" => "track",
        "jamen.do" | "www.jamen.do" => "t",
        _ => {
            return Err(
                "Jamendo direct lookup accepts jamendo.com track links and jamen.do short links"
                    .to_owned(),
            );
        }
    };
    if prefix != Some(expected_prefix) || remaining > 1 {
        return Err(format!(
            "expected an official Jamendo /{expected_prefix}/{{track-id}} link"
        ));
    }
    let track_id = track_id.unwrap_or_default();
    if track_id.is_empty()
        || track_id.len() > 20
        || !track_id.bytes().all(|byte| byte.is_ascii_digit())
        || track_id.bytes().all(|byte| byte == b'0')
    {
        return Err("Jamendo track ID must be a positive decimal integer".to_owned());
    }
    Ok(track_id.to_owned())
}

#[cfg(feature = "tracker-music")]
fn tracker_item_from_provider(item: crate::providers::tracker::TrackerSearchResult) -> TrackerItem {
    use crate::providers::tracker::TrackerMediaAccess;

    TrackerItem {
        source: item.source.descriptor().display_name.to_owned(),
        title: item.title,
        subtitle: format!(
            "{}{}{}",
            item.artist.unwrap_or_default(),
            item.format
                .as_ref()
                .map_or_else(String::new, |format| format!(" · {format}")),
            item.size_bytes
                .map_or_else(String::new, |size| format!(" · {}", human_bytes(size)))
        ),
        webpage_url: item.webpage_url,
        download_url: item.download_url,
        expected_format: item.format,
        access: match item.access {
            TrackerMediaAccess::DirectModule => TrackerAccess::DirectModule,
            TrackerMediaAccess::ArchiveNeedsInspection => TrackerAccess::ArchiveNeedsInspection,
            TrackerMediaAccess::MetadataOnly => TrackerAccess::MetadataOnly,
            TrackerMediaAccess::Directory => TrackerAccess::Directory,
        },
        prepared_path: None,
        insecure_transport: item.insecure_transport,
    }
}

/// Parses one bounded `ffprobe` JSON document for its first audio stream.
fn parse_local_ffprobe_output(path: &Path, payload: &[u8]) -> Option<LocalTechnicalMetadata> {
    if payload.len() > MAX_LOCAL_FFPROBE_JSON_BYTES {
        return None;
    }
    let output: LocalFfprobeOutput = serde_json::from_slice(payload).ok()?;
    let stream = output.streams.first();
    let format = output.format.as_ref();
    Some(LocalTechnicalMetadata {
        container: format
            .and_then(|format| format.format_name.as_deref())
            .and_then(|format_name| local_probe_container_label(path, format_name)),
        audio_codec: stream.and_then(|stream| {
            local_probe_codec_label(
                stream.codec_name.as_deref(),
                stream.codec_long_name.as_deref(),
            )
        }),
        bitrate_kbps: stream
            .and_then(|stream| stream.bit_rate.as_deref())
            .and_then(parse_local_probe_bitrate),
        sample_rate_hz: stream
            .and_then(|stream| stream.sample_rate.as_deref())
            .and_then(|sample_rate| sample_rate.parse::<u32>().ok())
            .filter(|sample_rate| *sample_rate > 0),
        channels: stream
            .and_then(|stream| stream.channels)
            .and_then(|channels| u8::try_from(channels).ok())
            .filter(|channels| *channels > 0),
        duration_seconds: format
            .and_then(|format| format.duration.as_deref())
            .and_then(parse_local_probe_duration),
    })
}

/// Converts an `ffprobe` format identifier into a stable container label.
fn local_probe_container_label(path: &Path, format_name: &str) -> Option<String> {
    let extension = path
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    let label = match extension.as_str() {
        "webm" => "WebM",
        "mkv" => "Matroska",
        "mp4" | "m4a" | "m4v" => "MP4",
        "mov" => "QuickTime",
        "avi" => "AVI",
        "ogg" | "oga" | "opus" => "Ogg",
        "wav" => "WAV",
        "flac" => "FLAC",
        "mp3" => "MP3",
        "aac" => "ADTS",
        _ if format_name.split(',').any(|format| format == "webm") => "WebM",
        _ if format_name.split(',').any(|format| format == "matroska") => "Matroska",
        _ if format_name
            .split(',')
            .any(|format| matches!(format, "mov" | "mp4" | "m4a")) =>
        {
            "MP4"
        }
        _ if format_name.split(',').any(|format| format == "ogg") => "Ogg",
        _ => return normalized_local_probe_label(format_name, 64),
    };
    Some(label.to_owned())
}

/// Converts an `ffprobe` codec identifier into a stable audio-codec label.
fn local_probe_codec_label(
    codec_name: Option<&str>,
    codec_long_name: Option<&str>,
) -> Option<String> {
    let codec_name = codec_name?.trim();
    let label = match codec_name.to_ascii_lowercase().as_str() {
        "aac" => "AAC",
        "ac3" => "AC-3",
        "alac" => "ALAC",
        "eac3" => "E-AC-3",
        "flac" => "FLAC",
        "mp1" => "MP1",
        "mp2" => "MP2",
        "mp3" => "MP3",
        "opus" => "Opus",
        "speex" => "Speex",
        "vorbis" => "Vorbis",
        _ => {
            return codec_long_name
                .and_then(|value| normalized_local_probe_label(value, 128))
                .or_else(|| normalized_local_probe_label(codec_name, 64));
        }
    };
    Some(label.to_owned())
}

/// Normalizes one helper-provided display label without retaining controls.
fn normalized_local_probe_label(value: &str, maximum_bytes: usize) -> Option<String> {
    let value = value.trim();
    (!value.is_empty()
        && value.len() <= maximum_bytes
        && !value.bytes().any(|byte| byte.is_ascii_control()))
    .then(|| value.to_owned())
}

/// Converts an audio-stream bitrate in bits per second to rounded kilobits.
fn parse_local_probe_bitrate(value: &str) -> Option<u32> {
    let bits_per_second = value.parse::<u64>().ok()?;
    let kilobits = bits_per_second.saturating_add(500) / 1_000;
    u32::try_from(kilobits).ok().filter(|bitrate| *bitrate > 0)
}

/// Converts a finite positive decimal duration to whole seconds.
fn parse_local_probe_duration(value: &str) -> Option<u64> {
    let seconds = value.parse::<f64>().ok()?;
    Duration::try_from_secs_f64(seconds)
        .ok()
        .map(|duration| duration.as_secs())
        .filter(|seconds| *seconds > 0)
}

/// Returns the best-effort container label available without a media probe.
fn local_container_label_from_path(path: &Path) -> String {
    let extension = path
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    match extension.as_str() {
        "webm" => "WebM".to_owned(),
        "mkv" => "Matroska".to_owned(),
        "mp4" | "m4a" | "m4v" => "MP4".to_owned(),
        "mov" => "QuickTime".to_owned(),
        "avi" => "AVI".to_owned(),
        "ogg" | "oga" | "opus" => "Ogg".to_owned(),
        "wav" => "WAV".to_owned(),
        "aac" => "ADTS".to_owned(),
        "flac" => "FLAC".to_owned(),
        "mp3" => "MP3".to_owned(),
        _ if extension.is_empty() => "unknown".to_owned(),
        _ => extension.to_ascii_uppercase(),
    }
}

/// Returns the codec implied by a codec-native extension, when trustworthy.
fn local_codec_label_from_path(path: &Path) -> String {
    let extension = path
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .unwrap_or_default()
        .to_ascii_lowercase();
    match extension.as_str() {
        "aac" => "AAC".to_owned(),
        "flac" => "FLAC".to_owned(),
        "mp3" => "MP3".to_owned(),
        "opus" => "Opus".to_owned(),
        "mod" | "xm" | "it" | "s3m" | "mptm" | "stm" | "mtm" | "669" => {
            extension.to_ascii_uppercase()
        }
        _ => "unknown".to_owned(),
    }
}

/// Applies trustworthy probe fields while preserving library-derived fallbacks.
fn apply_local_technical_metadata(item: &mut LocalMediaItem, metadata: LocalTechnicalMetadata) {
    if let Some(container) = metadata.container {
        item.container = container;
    }
    if let Some(audio_codec) = metadata.audio_codec {
        item.codec = audio_codec;
    }
    if let Some(bitrate_kbps) = metadata.bitrate_kbps {
        item.bitrate_kbps = Some(bitrate_kbps);
    }
    if let Some(sample_rate_hz) = metadata.sample_rate_hz {
        item.sample_rate_hz = Some(sample_rate_hz);
    }
    if let Some(channels) = metadata.channels {
        item.channels = Some(channels);
    }
    if let Some(duration_seconds) = metadata.duration_seconds {
        item.duration_seconds = Some(duration_seconds);
    }
}

/// Reads one local item and enriches it through the installed media probe.
fn local_media_item(path: PathBuf) -> LocalMediaItem {
    local_media_item_with_probe(path, &mut SystemLocalMediaProbe)
}

/// Reads one local item through an injectable technical-metadata probe.
fn local_media_item_with_probe(path: PathBuf, probe: &mut dyn LocalMediaProbe) -> LocalMediaItem {
    let mut item = local_media_item_without_probe(path);
    if let Some(metadata) = probe.probe(&item.path) {
        apply_local_technical_metadata(&mut item, metadata);
    }
    item.technical_metadata_probed = true;
    item
}

/// Reads tags and cheap file properties without spawning `ffprobe`.
fn local_media_item_without_probe(path: PathBuf) -> LocalMediaItem {
    let mut item = local_media_item_stub(path, None);
    read_local_tags(&mut item);
    item
}

/// Builds immediate filename-based metadata without opening media contents.
fn local_media_item_stub(path: PathBuf, known_size_bytes: Option<u64>) -> LocalMediaItem {
    let size_bytes = known_size_bytes.unwrap_or_else(|| {
        std::fs::metadata(&path)
            .map(|metadata| metadata.len())
            .unwrap_or_default()
    });
    let title = path
        .file_stem()
        .and_then(std::ffi::OsStr::to_str)
        .filter(|title| !title.is_empty())
        .unwrap_or("untitled local media")
        .to_owned();
    let container = local_container_label_from_path(&path);
    let codec = local_codec_label_from_path(&path);
    LocalMediaItem {
        path,
        title,
        artist: None,
        album: None,
        genre: None,
        comment: None,
        metadata_url: None,
        acoustid_id: None,
        duration_seconds: None,
        size_bytes,
        container,
        codec,
        bitrate_kbps: None,
        sample_rate_hz: None,
        channels: None,
        embedded_artwork: false,
        technical_metadata_probed: false,
    }
}

/// Selects `~/Music` when it exists, otherwise the user's home directory.
#[cfg(feature = "local-browser")]
fn default_local_browse_root() -> PathBuf {
    directories::BaseDirs::new().map_or_else(
        || PathBuf::from("."),
        |directories| {
            let music = directories.home_dir().join("Music");
            if music.is_dir() {
                music
            } else {
                directories.home_dir().to_owned()
            }
        },
    )
}

#[cfg(feature = "local-metadata")]
fn read_local_tags(item: &mut LocalMediaItem) {
    use lofty::config::ParseOptions;
    use lofty::file::{AudioFile, TaggedFileExt};
    use lofty::probe::Probe;

    if item
        .path
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .is_some_and(|extension| extension.eq_ignore_ascii_case("flac"))
        && read_local_flac_tags(item)
    {
        return;
    }
    if item
        .path
        .extension()
        .and_then(std::ffi::OsStr::to_str)
        .is_some_and(|extension| extension.eq_ignore_ascii_case("mp3"))
        && read_local_mpeg_tags(item)
    {
        return;
    }

    let options = ParseOptions::new()
        .read_properties(true)
        .read_cover_art(false);
    let Ok(tagged) = Probe::open(&item.path)
        .map(|probe| probe.options(options))
        .and_then(Probe::read)
    else {
        return;
    };
    let properties = tagged.properties();
    item.duration_seconds =
        (!properties.duration().is_zero()).then(|| properties.duration().as_secs());
    item.bitrate_kbps = properties.audio_bitrate().or(properties.overall_bitrate());
    item.sample_rate_hz = properties.sample_rate();
    item.channels = properties.channels();
    (item.container, item.codec) = local_lofty_container_and_codec(tagged.file_type());

    if let Some(tag) = tagged.primary_tag().or_else(|| tagged.first_tag()) {
        apply_local_generic_tag(item, tag);
    }
}

/// Maps Lofty's audio-oriented file type to separate container and codec labels.
#[cfg(feature = "local-metadata")]
fn local_lofty_container_and_codec(file_type: lofty::file::FileType) -> (String, String) {
    use lofty::file::FileType;

    let (container, codec) = match file_type {
        FileType::Aac => ("ADTS", "AAC"),
        FileType::Aiff => ("AIFF", "unknown"),
        FileType::Ape => ("APE", "Monkey's Audio"),
        FileType::Flac => ("FLAC", "FLAC"),
        FileType::Mpeg => ("MPEG", "MP3"),
        FileType::Mp4 => ("MP4", "unknown"),
        FileType::Mpc => ("Musepack", "Musepack"),
        FileType::Opus => ("Ogg", "Opus"),
        FileType::Vorbis => ("Ogg", "Vorbis"),
        FileType::Speex => ("Ogg", "Speex"),
        FileType::Wav => ("WAV", "unknown"),
        FileType::WavPack => ("WavPack", "WavPack"),
        _ => {
            let label = format!("{file_type:?}");
            return (label.clone(), label);
        }
    };
    (container.to_owned(), codec.to_owned())
}

#[cfg(not(feature = "local-metadata"))]
fn read_local_tags(_item: &mut LocalMediaItem) {}

/// Reads one MPEG file while retaining the declared encoding of ID3 text frames.
///
/// Generic Lofty tags intentionally erase format-specific frame encodings.
/// Keeping the MPEG representation lets Youta repair a narrowly recognized
/// Windows-1251-as-Latin-1 display error without changing the source file.
#[cfg(feature = "local-metadata")]
fn read_local_mpeg_tags(item: &mut LocalMediaItem) -> bool {
    use lofty::config::ParseOptions;
    use lofty::file::AudioFile;
    use lofty::mpeg::MpegFile;

    let Ok(mut file) = std::fs::File::open(&item.path) else {
        return false;
    };
    let options = ParseOptions::new()
        .read_properties(true)
        .read_cover_art(false);
    let Ok(mpeg) = MpegFile::read_from(&mut file, options) else {
        return false;
    };
    let properties = mpeg.properties();
    item.duration_seconds =
        (!properties.duration().is_zero()).then(|| properties.duration().as_secs());
    item.bitrate_kbps = (properties.audio_bitrate() > 0)
        .then(|| properties.audio_bitrate())
        .or_else(|| (properties.overall_bitrate() > 0).then(|| properties.overall_bitrate()));
    item.sample_rate_hz = (properties.sample_rate() > 0).then(|| properties.sample_rate());
    item.channels = (properties.channels() > 0).then(|| properties.channels());
    item.container = "MPEG".to_owned();
    item.codec = "MP3".to_owned();

    if let Some(tag) = mpeg.id3v2() {
        apply_local_id3v2_tag(item, tag);
    } else if let Some(tag) = mpeg.id3v1() {
        apply_local_id3v1_tag(item, tag);
    } else if let Some(tag) = mpeg.ape() {
        let generic = tag.clone().into();
        apply_local_generic_tag(item, &generic);
    }
    true
}

/// Applies ID3v2 fields and repairs only frames explicitly declared Latin-1.
#[cfg(feature = "local-metadata")]
fn apply_local_id3v2_tag(item: &mut LocalMediaItem, tag: &lofty::id3::v2::Id3v2Tag) {
    use lofty::tag::{Accessor, ItemKey};

    let generic: lofty::tag::Tag = tag.clone().into();

    if let Some(title) = normalized_local_id3v2_value(
        generic.title().as_deref(),
        local_id3v2_text_encoding(tag, "TIT2"),
    ) {
        item.title = title;
    }
    let artist_encoding = local_id3v2_text_encoding(tag, "TPE1");
    item.artist =
        normalized_local_id3v2_value(generic.get_string(ItemKey::TrackArtists), artist_encoding)
            .or_else(|| normalized_local_id3v2_value(generic.artist().as_deref(), artist_encoding));
    item.album = normalized_local_id3v2_value(
        generic.album().as_deref(),
        local_id3v2_text_encoding(tag, "TALB"),
    );
    item.genre = normalized_local_id3v2_value(
        generic.genre().as_deref(),
        local_id3v2_text_encoding(tag, "TCON"),
    );
    item.comment = normalized_local_id3v2_value(
        generic.comment().as_deref(),
        local_id3v2_comment_encoding(tag),
    );

    apply_local_generic_identifiers(item, &generic);
}

/// Returns the declared encoding for one ID3v2 text-information frame.
#[cfg(feature = "local-metadata")]
fn local_id3v2_text_encoding(
    tag: &lofty::id3::v2::Id3v2Tag,
    frame_id: &str,
) -> Option<lofty::TextEncoding> {
    use lofty::id3::v2::Frame;

    tag.into_iter().find_map(|frame| match frame {
        Frame::Text(text) if text.id().as_str() == frame_id => Some(text.encoding),
        _ => None,
    })
}

/// Returns the declared encoding of the default ID3v2 comment frame.
#[cfg(feature = "local-metadata")]
fn local_id3v2_comment_encoding(tag: &lofty::id3::v2::Id3v2Tag) -> Option<lofty::TextEncoding> {
    use lofty::id3::v2::Frame;

    tag.into_iter().find_map(|frame| match frame {
        Frame::Comment(comment) if comment.description.is_empty() => Some(comment.encoding),
        _ => None,
    })
}

/// Applies ambiguous ID3v1 fields through the conservative legacy repair.
#[cfg(feature = "local-metadata")]
fn apply_local_id3v1_tag(item: &mut LocalMediaItem, tag: &lofty::id3::v1::Id3v1Tag) {
    use lofty::tag::Accessor;

    if let Some(title) = normalized_legacy_windows_1251_value(tag.title.as_deref()) {
        item.title = title;
    }
    item.artist = normalized_legacy_windows_1251_value(tag.artist.as_deref());
    item.album = normalized_legacy_windows_1251_value(tag.album.as_deref());
    item.genre = trimmed_tag_value(tag.genre().as_deref());
    item.comment = normalized_legacy_windows_1251_value(tag.comment.as_deref());
}

/// Normalizes one ID3v2 value without guessing for Unicode-declared frames.
#[cfg(feature = "local-metadata")]
fn normalized_local_id3v2_value(
    value: Option<&str>,
    encoding: Option<lofty::TextEncoding>,
) -> Option<String> {
    if encoding == Some(lofty::TextEncoding::Latin1) {
        normalized_legacy_windows_1251_value(value)
    } else {
        trimmed_tag_value(value)
    }
}

/// Repairs a strong Windows-1251-as-Latin-1 signature for display only.
///
/// The repair is deliberately restricted to long, Cyrillic-looking words and
/// never writes metadata back to the media file. Ambiguous short strings and
/// ordinary accented Latin text retain the exact value supplied by Lofty.
#[cfg(feature = "local-metadata")]
fn normalized_legacy_windows_1251_value(value: Option<&str>) -> Option<String> {
    let value = value.map(str::trim).filter(|value| !value.is_empty())?;
    let bytes = value
        .chars()
        .map(|character| u8::try_from(u32::from(character)))
        .collect::<Result<Vec<_>, _>>();
    let Ok(bytes) = bytes else {
        return Some(value.to_owned());
    };
    let (decoded, had_errors) =
        encoding_rs::WINDOWS_1251.decode_without_bom_handling(bytes.as_slice());
    if had_errors || !has_strong_legacy_windows_1251_signature(value, decoded.as_ref()) {
        return Some(value.to_owned());
    }
    Some(decoded.into_owned())
}

/// Recognizes word-level Cyrillic evidence while rejecting common Latin names.
#[cfg(feature = "local-metadata")]
fn has_strong_legacy_windows_1251_signature(source: &str, decoded: &str) -> bool {
    #[derive(Default)]
    struct WordEvidence {
        letters: usize,
        source_high_latin: usize,
        decoded_cyrillic: usize,
        cyrillic_vowels: usize,
        cyrillic_consonants: usize,
    }

    fn qualifies(word: &WordEvidence, minimum_letters: usize) -> bool {
        word.letters >= minimum_letters
            && word.source_high_latin.saturating_mul(5) >= word.letters.saturating_mul(4)
            && word.decoded_cyrillic.saturating_mul(5) >= word.letters.saturating_mul(4)
            && word.cyrillic_vowels > 0
            && word.cyrillic_consonants > 0
    }

    fn is_cyrillic(character: char) -> bool {
        matches!(character, '\u{0400}'..='\u{052f}')
    }

    fn is_cyrillic_vowel(character: char) -> bool {
        matches!(
            character,
            'А' | 'Е'
                | 'Ё'
                | 'И'
                | 'О'
                | 'У'
                | 'Ы'
                | 'Э'
                | 'Ю'
                | 'Я'
                | 'а'
                | 'е'
                | 'ё'
                | 'и'
                | 'о'
                | 'у'
                | 'ы'
                | 'э'
                | 'ю'
                | 'я'
                | 'І'
                | 'Ї'
                | 'Є'
                | 'і'
                | 'ї'
                | 'є'
        )
    }

    if source == decoded || source.chars().any(is_cyrillic) {
        return false;
    }
    let mut word = WordEvidence::default();
    let mut strong_words = 0_usize;
    let mut medium_words = 0_usize;
    for (source_character, decoded_character) in
        source.chars().zip(decoded.chars()).chain([(' ', ' ')])
    {
        if decoded_character.is_alphabetic() {
            word.letters = word.letters.saturating_add(1);
            word.source_high_latin = word.source_high_latin.saturating_add(usize::from(matches!(
                source_character,
                '\u{00c0}'..='\u{00ff}'
            )));
            if is_cyrillic(decoded_character) {
                word.decoded_cyrillic = word.decoded_cyrillic.saturating_add(1);
                if is_cyrillic_vowel(decoded_character) {
                    word.cyrillic_vowels = word.cyrillic_vowels.saturating_add(1);
                } else {
                    word.cyrillic_consonants = word.cyrillic_consonants.saturating_add(1);
                }
            }
            continue;
        }
        strong_words = strong_words.saturating_add(usize::from(qualifies(&word, 6)));
        medium_words = medium_words.saturating_add(usize::from(qualifies(&word, 4)));
        word = WordEvidence::default();
    }
    strong_words > 0 || medium_words >= 2
}

#[cfg(feature = "local-metadata")]
fn read_local_flac_tags(item: &mut LocalMediaItem) -> bool {
    use lofty::config::ParseOptions;
    use lofty::file::AudioFile;
    use lofty::flac::FlacFile;

    let Ok(mut file) = std::fs::File::open(&item.path) else {
        return false;
    };
    let options = ParseOptions::new()
        .read_properties(true)
        .read_cover_art(false);
    let Ok(flac) = FlacFile::read_from(&mut file, options) else {
        return false;
    };
    let properties = flac.properties();
    item.duration_seconds =
        (!properties.duration().is_zero()).then(|| properties.duration().as_secs());
    item.bitrate_kbps = (properties.audio_bitrate() > 0)
        .then(|| properties.audio_bitrate())
        .or_else(|| (properties.overall_bitrate() > 0).then(|| properties.overall_bitrate()));
    item.sample_rate_hz = (properties.sample_rate() > 0).then(|| properties.sample_rate());
    item.channels = (properties.channels() > 0).then(|| properties.channels());
    item.container = "FLAC".to_owned();
    item.codec = "FLAC".to_owned();

    if let Some(tag) = flac.vorbis_comments() {
        apply_local_vorbis_comments(item, tag);
    }
    true
}

#[cfg(feature = "local-metadata")]
fn apply_local_vorbis_comments(item: &mut LocalMediaItem, tag: &lofty::ogg::VorbisComments) {
    if let Some(title) = trimmed_tag_value(tag.get("TITLE")) {
        item.title = title;
    }
    item.artist = joined_tag_values(tag.get_all("ARTISTS"))
        .or_else(|| joined_tag_values(tag.get_all("ARTIST")));
    item.album = trimmed_tag_value(tag.get("ALBUM"));
    item.genre = joined_tag_values(tag.get_all("GENRE"));
    item.comment = joined_tag_values(tag.get_all("COMMENT"));
    item.metadata_url = trimmed_tag_value(tag.get("URL"));
    item.acoustid_id = trimmed_tag_value(tag.get("ACOUSTID_ID"));
}

/// Applies format-agnostic tags without legacy character-set guessing.
#[cfg(feature = "local-metadata")]
fn apply_local_generic_tag(item: &mut LocalMediaItem, tag: &lofty::tag::Tag) {
    use lofty::tag::{Accessor, ItemKey};

    if let Some(title) = trimmed_tag_value(tag.title().as_deref()) {
        item.title = title;
    }
    item.artist = trimmed_tag_value(tag.get_string(ItemKey::TrackArtists))
        .or_else(|| trimmed_tag_value(tag.artist().as_deref()));
    item.album = trimmed_tag_value(tag.album().as_deref());
    item.genre = trimmed_tag_value(tag.genre().as_deref());
    item.comment = trimmed_tag_value(tag.comment().as_deref());
    apply_local_generic_identifiers(item, tag);
}

/// Applies URL and identifier values without any character-set repair.
#[cfg(feature = "local-metadata")]
fn apply_local_generic_identifiers(item: &mut LocalMediaItem, tag: &lofty::tag::Tag) {
    use lofty::tag::ItemKey;

    item.metadata_url = local_standard_tag_url(tag);
    item.acoustid_id = trimmed_tag_value(tag.get_string(ItemKey::AcoustId));
}

#[cfg(feature = "local-metadata")]
fn trimmed_tag_value(value: Option<&str>) -> Option<String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
}

#[cfg(feature = "local-metadata")]
fn joined_tag_values<'a>(values: impl Iterator<Item = &'a str>) -> Option<String> {
    let values = values
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    (!values.is_empty()).then(|| values.join("; "))
}

#[cfg(feature = "local-metadata")]
fn local_standard_tag_url(tag: &lofty::tag::Tag) -> Option<String> {
    use lofty::tag::ItemKey;

    [
        ItemKey::AudioFileUrl,
        ItemKey::AudioSourceUrl,
        ItemKey::TrackArtistUrl,
        ItemKey::PublisherUrl,
        ItemKey::CommercialInformationUrl,
        ItemKey::CopyrightUrl,
        ItemKey::PodcastUrl,
        ItemKey::RadioStationUrl,
    ]
    .into_iter()
    .find_map(|key| trimmed_tag_value(local_tag_text_or_locator(tag, key)))
}

/// Reads a generic tag's textual or locator value without altering its bytes.
///
/// Lofty represents ID3 URL frames as locators, while `Tag::get_string` only
/// accepts ordinary text values. Keeping both variants here preserves URLs
/// when a format-specific ID3v2 tag is converted into a generic tag.
#[cfg(feature = "local-metadata")]
fn local_tag_text_or_locator(tag: &lofty::tag::Tag, key: lofty::tag::ItemKey) -> Option<&str> {
    tag.get(key)
        .and_then(|item| item.value().text().or_else(|| item.value().locator()))
}

fn local_media_subtitle(item: &LocalMediaItem) -> String {
    let mut fields = Vec::new();
    if let Some(artist) = &item.artist {
        fields.push(artist.clone());
    }
    if let Some(album) = &item.album {
        fields.push(album.clone());
    }
    if let Some(duration) = item.duration_seconds {
        fields.push(format_seconds(duration));
    }
    fields.push(item.codec.clone());
    if let Some(bitrate) = item.bitrate_kbps {
        fields.push(format!("{bitrate} kbps"));
    }
    if let Some(sample_rate) = item.sample_rate_hz {
        fields.push(format!("{sample_rate} Hz"));
    }
    if let Some(channels) = item.channels {
        fields.push(format!("{channels} ch"));
    }
    fields.push(human_bytes(item.size_bytes));
    if item.embedded_artwork {
        fields.push("embedded artwork".to_owned());
    }
    fields.join(" · ")
}

/// Builds a lazy midpoint-frame request for one finite local video.
///
/// Durations are stored as whole seconds, so multiplying by 500 yields the
/// midpoint of the measured whole-second duration in milliseconds without
/// floating-point rounding. Text-only builds and builds without local-video
/// extraction keep Details unchanged.
fn local_video_thumbnail_view(
    path: &Path,
    duration_seconds: Option<u64>,
) -> Option<LocalVideoThumbnailView> {
    #[cfg(all(feature = "images", feature = "local-video-thumbnails"))]
    {
        let duration_seconds = duration_seconds.filter(|duration| *duration > 0)?;
        (crate::local_browser::classify_local_file(path)
            == Some(crate::local_browser::LocalEntryKind::Video))
        .then(|| LocalVideoThumbnailView {
            path: path.to_owned(),
            midpoint_millis: duration_seconds.saturating_mul(500),
        })
    }
    #[cfg(not(all(feature = "images", feature = "local-video-thumbnails")))]
    {
        let _ = (path, duration_seconds);
        None
    }
}

/// Formats human and technical metadata for one playable Local Details panel.
fn local_media_description(item: &LocalMediaItem) -> String {
    let mut lines = vec![format!("Full path: {}", item.path.display())];
    if let Some(artist) = &item.artist {
        lines.push(format!("Artists: {artist}"));
    }
    if let Some(album) = &item.album {
        lines.push(format!("Album: {album}"));
    }
    if let Some(genre) = &item.genre {
        lines.push(format!("Genre: {genre}"));
    }
    if let Some(comment) = &item.comment {
        lines.push(format!("Comment: {comment}"));
    }
    if let Some(url) = &item.metadata_url {
        lines.push(format!("URL: {url}"));
    }
    if let Some(acoustid_id) = &item.acoustid_id {
        lines.push("Identifiers:".to_owned());
        lines.push(format!("AcoustID ID: {acoustid_id}"));
    }
    lines.push(format!("Container: {}", item.container));
    lines.push(format!("Codec: {}", item.codec));
    lines.push(format!("Size: {}", human_bytes(item.size_bytes)));
    if let Some(value) = item.bitrate_kbps {
        lines.push(format!("Bitrate: {value} kb/s"));
    }
    if let Some(value) = item.sample_rate_hz {
        lines.push(format!("Sample rate: {value} Hz"));
    }
    if let Some(value) = item.channels {
        lines.push(format!("Channels: {value}"));
    }
    lines.join("\n")
}

#[cfg(any(feature = "local-browser", test))]
fn scan_local_media(root: &Path) -> Result<Vec<LocalMediaItem>, String> {
    const MAX_VISITED_ENTRIES: usize = 100_000;
    const MAX_MEDIA_FILES: usize = 10_000;
    const MAX_DEPTH: usize = 64;

    let mut stack = vec![(root.to_owned(), 0_usize)];
    let mut media = Vec::new();
    let mut visited = 0_usize;
    while let Some((directory, depth)) = stack.pop() {
        if depth > MAX_DEPTH {
            continue;
        }
        let entries = std::fs::read_dir(&directory)
            .map_err(|error| format!("cannot read {}: {error}", directory.display()))?;
        for entry in entries {
            let entry =
                entry.map_err(|error| format!("cannot read {}: {error}", directory.display()))?;
            visited = visited.saturating_add(1);
            if visited > MAX_VISITED_ENTRIES {
                return Err(format!(
                    "scan stopped after {MAX_VISITED_ENTRIES} filesystem entries"
                ));
            }
            let file_type = entry
                .file_type()
                .map_err(|error| format!("cannot inspect {}: {error}", entry.path().display()))?;
            if file_type.is_dir() {
                stack.push((entry.path(), depth.saturating_add(1)));
            } else if file_type.is_file()
                && is_supported_media_path(&entry.path().to_string_lossy())
            {
                media.push(local_media_item_without_probe(entry.path()));
                if media.len() >= MAX_MEDIA_FILES {
                    media.sort_by(|left, right| left.path.cmp(&right.path));
                    return Ok(media);
                }
            }
        }
    }
    media.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(media)
}

/// Presentation context for one YouTube result row.
///
/// A subscription feed omits channel facts already expressed by its heading.
#[derive(Clone, Copy)]
enum SearchRowContext {
    /// A cross-channel result on the global Search screen.
    GlobalSearch,
    /// A playable track returned by the dedicated `YouTube Music` tab.
    YouTubeMusic,
    /// A video inside one locally subscribed channel's feed.
    SubscriptionFeed,
}

/// Persisted playback state projected into one compact list row.
///
/// A stored progress row proves that the backend accepted playback even when
/// its rounded percentage remains zero. An explicit played override maps to a
/// completed row, while an explicit unplayed override clears both presentation
/// fields so the user's choice remains authoritative.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct PlaybackRowState {
    watched_percent: u8,
    playback_started: bool,
}

impl PlaybackRowState {
    /// Projects one optional persistence record into watched-row state.
    fn from_progress(progress: Option<&PlaybackProgress>) -> Self {
        let Some(progress) = progress else {
            return Self::default();
        };
        match progress.played_override {
            Some(false) => Self::default(),
            Some(true) => Self {
                watched_percent: 100,
                playback_started: true,
            },
            None => Self {
                watched_percent: progress.watched_percent(),
                playback_started: true,
            },
        }
    }
}

/// Hydrates playable, non-live rows through one bounded persistence query.
///
/// Missing progress leaves a row's source-specific state untouched. The store
/// chunks SQLite requests and overlays the human-readable backend's pending
/// crash checkpoint, so callers neither issue one query per row nor lose the
/// newest restart-safe position.
fn hydrate_row_playback_progress(store: &StateStore, rows: &mut [RowView]) {
    let media_ids = rows
        .iter()
        .filter(|row| !row.hide_watched_marker)
        .filter_map(|row| row.media_id.clone())
        .collect::<HashSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let Ok(progress) = store.progress_for_media_ids(&media_ids) else {
        return;
    };
    for row in rows {
        let Some(media_id) = row.media_id.as_ref() else {
            continue;
        };
        if let Some(progress) = progress.get(media_id) {
            let state = PlaybackRowState::from_progress(Some(progress));
            row.watched_percent = state.watched_percent;
            row.playback_started = state.playback_started;
        }
    }
}

/// Converts one provider item into a compact row for its presentation context.
fn row_from_search_item(
    item: &SearchItem,
    store: &StateStore,
    subscriptions: &SubscriptionTree,
    channel_subscribers: &HashMap<String, Option<u64>>,
    context: SearchRowContext,
    today: NaiveDate,
) -> RowView {
    match item {
        SearchItem::Video(video) => {
            let progress = store
                .progress(&MediaId::new(SourceKind::YouTube, &video.video_id))
                .ok()
                .flatten();
            let playback = PlaybackRowState::from_progress(progress.as_ref());
            let subscriber_count = match context {
                SearchRowContext::GlobalSearch => channel_subscribers
                    .get(&video.channel_id)
                    .copied()
                    .flatten(),
                SearchRowContext::YouTubeMusic | SearchRowContext::SubscriptionFeed => None,
            };
            RowView {
                media_id: Some(MediaId::new(SourceKind::YouTube, &video.video_id)),
                title: video.title.clone(),
                subtitle: youtube_video_row_subtitle(video, subscriber_count, context, today),
                source: if matches!(context, SearchRowContext::YouTubeMusic) {
                    "YouTube Music".to_owned()
                } else {
                    "YouTube".to_owned()
                },
                watched_percent: playback.watched_percent,
                playback_started: playback.playback_started,
                subscribed: matches!(context, SearchRowContext::GlobalSearch)
                    && subscriptions.contains_youtube_channel(&video.channel_id),
                thumbnail_url: preferred_thumbnail_url(&video.thumbnails),
                vertical: video.orientation == VideoOrientation::Vertical,
                hide_watched_marker: false,
                compact: false,
                radio_favorite: false,
                local_marked: false,
            }
        }
        SearchItem::Channel(channel) => RowView {
            title: channel.name.clone(),
            subtitle: channel.subscriber_count.map_or_else(
                || "channel".to_owned(),
                |count| format!("{} subscribers", format_count(count)),
            ),
            source: "YouTube channel".to_owned(),
            subscribed: subscriptions.contains_youtube_channel(&channel.channel_id),
            thumbnail_url: preferred_thumbnail_url(&channel.thumbnails),
            ..RowView::default()
        },
        SearchItem::PodcastEpisode(episode) => {
            #[cfg(feature = "rss")]
            {
                let media_id = MediaId::new(
                    SourceKind::Rss,
                    podcast_episode_external_id(&episode.feed_url, &episode.episode_id),
                );
                let progress = store.progress(&media_id).ok().flatten();
                let playback = PlaybackRowState::from_progress(progress.as_ref());
                let mut metadata = Vec::with_capacity(3);
                if let Some(published) = episode.published_at {
                    metadata.push(format_unix_local_date_relative(published, today));
                }
                if let Some(duration) = episode.duration_seconds.filter(|duration| *duration > 0) {
                    metadata.push(format_seconds(duration));
                }
                if episode.stream_url.is_none() {
                    metadata.push("enclosure refresh needed".to_owned());
                }
                RowView {
                    media_id: Some(media_id),
                    title: episode.title.clone(),
                    subtitle: metadata.join(" · "),
                    source: "RSS podcast".to_owned(),
                    watched_percent: playback.watched_percent,
                    playback_started: playback.playback_started,
                    thumbnail_url: episode.artwork_url.clone(),
                    compact: true,
                    ..RowView::default()
                }
            }
            #[cfg(not(feature = "rss"))]
            {
                RowView {
                    title: episode.title.clone(),
                    subtitle: "RSS support omitted".to_owned(),
                    source: "RSS podcast".to_owned(),
                    compact: true,
                    ..RowView::default()
                }
            }
        }
    }
}

/// Returns the stable playable identity represented by a subscription item.
fn subscription_item_media_id(item: &SearchItem) -> Option<MediaId> {
    match item {
        SearchItem::Video(video) => Some(MediaId::new(SourceKind::YouTube, &video.video_id)),
        SearchItem::PodcastEpisode(episode) => {
            #[cfg(feature = "rss")]
            {
                Some(MediaId::new(
                    SourceKind::Rss,
                    podcast_episode_external_id(&episode.feed_url, &episode.episode_id),
                ))
            }
            #[cfg(not(feature = "rss"))]
            {
                let _ = episode;
                None
            }
        }
        SearchItem::Channel(_) => None,
    }
}

/// Formats context-aware metadata beneath one YouTube video title.
///
/// Global Search retains the channel identity and selected-only subscriber
/// count. A subscription feed omits both because its heading already owns
/// those facts.
fn youtube_video_row_subtitle(
    video: &VideoSummary,
    subscriber_count: Option<u64>,
    context: SearchRowContext,
    today: NaiveDate,
) -> String {
    let mut fields = Vec::with_capacity(4);
    let channel_name = video.channel_name.trim();
    if matches!(
        context,
        SearchRowContext::GlobalSearch | SearchRowContext::YouTubeMusic
    ) && !channel_name.is_empty()
    {
        fields.push(channel_name.to_owned());
    }
    if matches!(context, SearchRowContext::GlobalSearch)
        && let Some(count) = subscriber_count
    {
        fields.push(format!("{} subscribers", format_count(count)));
    }
    if let Some(timestamp) = video.published_at {
        let date = format_unix_local_date_relative(timestamp, today);
        if date != "unknown" {
            fields.push(date);
        }
    }
    if let Some(duration) = video.duration_seconds {
        fields.push(format_seconds(duration));
    }
    fields.join(" · ")
}

#[cfg(feature = "youtube-music")]
fn search_item_from_youtube_music_track(track: YouTubeMusicTrack) -> SearchItem {
    SearchItem::Video(VideoSummary {
        video_id: track.video_id,
        title: track.title,
        channel_name: track.artist.unwrap_or_else(|| "YouTube Music".to_owned()),
        channel_id: String::new(),
        description: String::new(),
        duration_seconds: track.duration_seconds,
        view_count: None,
        published_at: None,
        published_text: None,
        live: false,
        orientation: VideoOrientation::Unknown,
        thumbnails: vec![Thumbnail {
            url: track.thumbnail_url,
            quality: Some("YouTube Music search".to_owned()),
            width: None,
            height: None,
        }],
        webpage_url: Some(track.webpage_url),
        stream_url: None,
    })
}

/// Returns bounded, clickable timestamp spans for a Details description.
fn detail_timecodes(description: &str) -> Vec<DetailTimecodeView> {
    const MAX_DESCRIPTION_TIMECODES: usize = 512;

    let chapter_timestamps = parse_description_chapters(description, None)
        .into_iter()
        .map(|chapter| (chapter.timestamp_start_byte, chapter.timestamp_end_byte))
        .collect::<HashSet<_>>();
    parse_description_links(description)
        .into_iter()
        .filter_map(|link| match link.target {
            LinkTarget::Timecode { seconds } => Some(DetailTimecodeView {
                start_byte: link.start_byte,
                end_byte: link.end_byte,
                seconds,
                is_chapter: chapter_timestamps.contains(&(link.start_byte, link.end_byte)),
            }),
            _ => None,
        })
        .take(MAX_DESCRIPTION_TIMECODES)
        .collect()
}

/// Returns bounded internal actions for `YouTube` video URLs in Details text.
fn detail_video_links(description: &str) -> Vec<DetailVideoLinkView> {
    const MAX_DESCRIPTION_VIDEO_LINKS: usize = 256;

    parse_description_video_links(description)
        .into_iter()
        .take(MAX_DESCRIPTION_VIDEO_LINKS)
        .map(|link| DetailVideoLinkView {
            start_byte: link.start_byte,
            end_byte: link.end_byte,
            video_id: link.video_id,
            start_seconds: link.start_seconds,
        })
        .collect()
}

/// Converts line-leading description timecodes into bounded playback chapters.
fn description_chapters(description: &str, duration_seconds: Option<u64>) -> Vec<Chapter> {
    const MAX_DESCRIPTION_CHAPTERS: usize = 512;

    parse_description_chapters(description, duration_seconds)
        .into_iter()
        .take(MAX_DESCRIPTION_CHAPTERS)
        .map(|chapter| Chapter {
            title: chapter.title,
            start_seconds: chapter.start_seconds,
            end_seconds: chapter.end_seconds,
        })
        .collect()
}

fn preliminary_detail(item: &SearchItem, subscriptions: &SubscriptionTree) -> DetailView {
    match item {
        SearchItem::Video(video) => {
            let description = normalize_description_chapter_lines(&video.description);
            DetailView {
                media_id: Some(MediaId::new(SourceKind::YouTube, &video.video_id)),
                title: video.title.clone(),
                source: "YouTube".to_owned(),
                channel_name: video.channel_name.clone(),
                channel_id: video.channel_id.clone(),
                channel_webpage_url: youtube_channel_webpage_url(
                    &video.channel_id,
                    subscriptions.youtube_channel_website_url(&video.channel_id),
                ),
                channel_subscribed: subscriptions.contains_youtube_channel(&video.channel_id),
                length: video
                    .duration_seconds
                    .map_or_else(|| "unknown".to_owned(), format_seconds),
                timecodes: detail_timecodes(&description),
                video_links: detail_video_links(&description),
                description,
                views: video
                    .view_count
                    .map_or_else(|| "unknown".to_owned(), format_count),
                published: video
                    .published_text
                    .clone()
                    .or_else(|| video.published_at.map(format_unix_utc_date))
                    .unwrap_or_else(|| "unknown".to_owned()),
                license: "loading…".to_owned(),
                wikidata: "not loaded".to_owned(),
                thumbnail_url: preferred_thumbnail_url(&video.thumbnails),
                ..DetailView::default()
            }
        }
        SearchItem::Channel(channel) => detail_from_channel(channel, subscriptions),
        SearchItem::PodcastEpisode(episode) => {
            #[cfg(feature = "rss")]
            {
                detail_from_podcast_episode(episode)
            }
            #[cfg(not(feature = "rss"))]
            {
                DetailView {
                    title: episode.title.clone(),
                    source: "RSS podcast".to_owned(),
                    description: "This build omits RSS subscription support".to_owned(),
                    ..DetailView::default()
                }
            }
        }
    }
}

/// Builds selected RSS episode details without issuing a YouTube metadata call.
#[cfg(feature = "rss")]
fn detail_from_podcast_episode(episode: &PodcastEpisodeSummary) -> DetailView {
    let media_id = MediaId::new(
        SourceKind::Rss,
        podcast_episode_external_id(&episode.feed_url, &episode.episode_id),
    );
    let description = normalize_description_chapter_lines(&episode.description);
    let mut metadata = Vec::new();
    if !episode.authors.is_empty() {
        metadata.push(format!("Authors: {}", episode.authors.join(", ")));
    }
    if let Some(language) = episode.language.as_deref() {
        metadata.push(format!("Language: {language}"));
    }
    if !episode.categories.is_empty() {
        metadata.push(format!("Categories: {}", episode.categories.join(", ")));
    }
    if let Some(mime) = episode.stream_mime_type.as_deref() {
        metadata.push(format!("Enclosure: {mime}"));
    }
    if let Some(bytes) = episode.stream_byte_length {
        metadata.push(format!("Size: {}", human_bytes(bytes)));
    }
    let description = if metadata.is_empty() {
        description
    } else if description.is_empty() {
        metadata.join("\n")
    } else {
        format!("{}\n\n{}", metadata.join("\n"), description)
    };
    DetailView {
        media_id: Some(media_id),
        title: episode.title.clone(),
        source: "RSS podcast".to_owned(),
        channel_name: episode.feed_title.clone(),
        length: episode
            .duration_seconds
            .map_or_else(String::new, format_seconds),
        description: description.clone(),
        timecodes: detail_timecodes(&description),
        video_links: detail_video_links(&description),
        published: episode
            .published_at
            .map_or_else(String::new, format_unix_utc_date),
        thumbnail_url: episode.artwork_url.clone(),
        ..DetailView::default()
    }
}

/// Carries interaction-only artwork state across metadata for the same item.
///
/// Provider detail responses replace preliminary metadata asynchronously.
/// Expansion survives that replacement, while any media or channel identity
/// change restores the configured artwork height.
fn preserve_thumbnail_expansion(previous: Option<&DetailView>, next: &mut DetailView) {
    let Some(previous) = previous else {
        return;
    };
    let same_media = previous
        .media_id
        .as_ref()
        .zip(next.media_id.as_ref())
        .is_some_and(|(previous, next)| previous == next);
    let same_channel = previous.media_id.is_none()
        && next.media_id.is_none()
        && !previous.channel_id.is_empty()
        && previous.channel_id == next.channel_id;
    if same_media || same_channel {
        next.thumbnail_expanded = previous.thumbnail_expanded;
    }
}

fn preferred_thumbnail_url(thumbnails: &[Thumbnail]) -> Option<url::Url> {
    const TARGET_WIDTH: u32 = 480;
    const TARGET_HEIGHT: u32 = 270;

    let known_dimensions = thumbnails
        .iter()
        .filter_map(|thumbnail| {
            thumbnail
                .width
                .zip(thumbnail.height)
                .map(|(width, height)| (thumbnail, width, height))
        })
        .collect::<Vec<_>>();
    let selected = known_dimensions
        .iter()
        .filter(|(_, width, height)| *width >= TARGET_WIDTH && *height >= TARGET_HEIGHT)
        .min_by_key(|(_, width, height)| u64::from(*width) * u64::from(*height))
        .map(|(thumbnail, _, _)| *thumbnail)
        .or_else(|| {
            known_dimensions
                .iter()
                .max_by_key(|(_, width, height)| u64::from(*width) * u64::from(*height))
                .map(|(thumbnail, _, _)| *thumbnail)
        })
        .or_else(|| thumbnails.last());
    selected.map(|thumbnail| thumbnail.url.clone())
}

/// Compacts selected-only channel metadata before process-local caching.
fn compact_channel_summary(channel: &mut ChannelSummary) {
    compact_cached_string(&mut channel.channel_id, 128);
    compact_cached_string(&mut channel.name, MAX_CACHED_SUBSCRIPTION_LABEL_BYTES);
    compact_cached_string(
        &mut channel.description,
        MAX_CACHED_SUBSCRIPTION_DESCRIPTION_BYTES,
    );
    channel
        .webpage_url
        .take_if(|url| url.as_str().len() > MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
    let preferred_thumbnail = preferred_thumbnail_url(&channel.thumbnails);
    channel.thumbnails.retain(|thumbnail| {
        preferred_thumbnail.as_ref() == Some(&thumbnail.url)
            && thumbnail.url.as_str().len() <= MAX_CACHED_SUBSCRIPTION_FIELD_BYTES
    });
    channel.thumbnails.truncate(1);
    channel.thumbnails.shrink_to_fit();
    if let Some(thumbnail) = channel.thumbnails.first_mut()
        && let Some(quality) = thumbnail.quality.as_mut()
    {
        compact_cached_string(quality, 128);
    }
}

/// Compacts provider list metadata before it enters the low-RAM channel cache.
fn compact_subscription_item(item: &mut SearchItem) {
    match item {
        SearchItem::Video(video) => {
            compact_cached_string(&mut video.video_id, 128);
            compact_cached_string(&mut video.channel_id, 128);
            compact_cached_string(&mut video.title, MAX_CACHED_SUBSCRIPTION_LABEL_BYTES);
            compact_cached_string(&mut video.channel_name, MAX_CACHED_SUBSCRIPTION_LABEL_BYTES);
            compact_cached_string(
                &mut video.description,
                MAX_CACHED_SUBSCRIPTION_DESCRIPTION_BYTES,
            );
            if let Some(published) = video.published_text.as_mut() {
                compact_cached_string(published, MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
            }
            video
                .webpage_url
                .take_if(|url| url.as_str().len() > MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
            video
                .stream_url
                .take_if(|url| url.as_str().len() > MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);

            let preferred_thumbnail = preferred_thumbnail_url(&video.thumbnails);
            video.thumbnails.retain(|thumbnail| {
                preferred_thumbnail.as_ref() == Some(&thumbnail.url)
                    && thumbnail.url.as_str().len() <= MAX_CACHED_SUBSCRIPTION_FIELD_BYTES
            });
            video.thumbnails.truncate(1);
            video.thumbnails.shrink_to_fit();
            if let Some(thumbnail) = video.thumbnails.first_mut()
                && let Some(quality) = thumbnail.quality.as_mut()
            {
                compact_cached_string(quality, 128);
            }
        }
        SearchItem::PodcastEpisode(episode) => {
            compact_cached_string(&mut episode.episode_id, MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
            compact_cached_string(&mut episode.feed_title, MAX_CACHED_SUBSCRIPTION_LABEL_BYTES);
            compact_cached_string(&mut episode.title, MAX_CACHED_SUBSCRIPTION_LABEL_BYTES);
            compact_cached_string(
                &mut episode.description,
                MAX_CACHED_SUBSCRIPTION_DESCRIPTION_BYTES,
            );
            for author in &mut episode.authors {
                compact_cached_string(author, MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
            }
            episode.authors.truncate(16);
            for category in &mut episode.categories {
                compact_cached_string(category, MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
            }
            episode.categories.truncate(32);
            if let Some(language) = episode.language.as_mut() {
                compact_cached_string(language, 128);
            }
            for url in [
                &mut episode.webpage_url,
                &mut episode.feed_webpage_url,
                &mut episode.artwork_url,
                &mut episode.stream_url,
            ] {
                url.take_if(|url| url.as_str().len() > MAX_CACHED_SUBSCRIPTION_FIELD_BYTES);
            }
            if let Some(mime) = episode.stream_mime_type.as_mut() {
                compact_cached_string(mime, 256);
            }
        }
        SearchItem::Channel(_) => {}
    }
}

/// Truncates one cached string at a UTF-8 boundary and releases spare capacity.
fn compact_cached_string(value: &mut String, maximum_bytes: usize) {
    truncate_utf8_bytes(value, maximum_bytes);
    value.shrink_to_fit();
}

/// Estimates heap ownership for enforcing the global subscription-cache cap.
fn subscription_item_estimated_heap_bytes(item: &SearchItem) -> usize {
    let base = std::mem::size_of::<SearchItem>();
    match item {
        SearchItem::Video(video) => {
            let strings = [
                video.video_id.capacity(),
                video.title.capacity(),
                video.channel_name.capacity(),
                video.channel_id.capacity(),
                video.description.capacity(),
                video.published_text.as_ref().map_or(0, String::capacity),
                video
                    .webpage_url
                    .as_ref()
                    .map_or(0, |url| url.as_str().len()),
                video
                    .stream_url
                    .as_ref()
                    .map_or(0, |url| url.as_str().len()),
            ]
            .into_iter()
            .fold(0usize, usize::saturating_add);
            let thumbnails = video
                .thumbnails
                .iter()
                .map(|thumbnail| {
                    thumbnail
                        .url
                        .as_str()
                        .len()
                        .saturating_add(thumbnail.quality.as_ref().map_or(0, String::capacity))
                })
                .fold(
                    video
                        .thumbnails
                        .capacity()
                        .saturating_mul(std::mem::size_of::<Thumbnail>()),
                    usize::saturating_add,
                );
            base.saturating_add(strings).saturating_add(thumbnails)
        }
        SearchItem::Channel(channel) => {
            let strings = channel
                .channel_id
                .capacity()
                .saturating_add(channel.name.capacity())
                .saturating_add(channel.description.capacity())
                .saturating_add(
                    channel
                        .webpage_url
                        .as_ref()
                        .map_or(0, |url| url.as_str().len()),
                );
            base.saturating_add(strings)
        }
        SearchItem::PodcastEpisode(episode) => {
            let strings = episode
                .feed_url
                .as_str()
                .len()
                .saturating_add(episode.episode_id.capacity())
                .saturating_add(episode.feed_title.capacity())
                .saturating_add(episode.title.capacity())
                .saturating_add(episode.description.capacity())
                .saturating_add(
                    episode
                        .authors
                        .iter()
                        .map(String::capacity)
                        .fold(0usize, usize::saturating_add),
                )
                .saturating_add(
                    episode
                        .categories
                        .iter()
                        .map(String::capacity)
                        .fold(0usize, usize::saturating_add),
                )
                .saturating_add(episode.language.as_ref().map_or(0, String::capacity))
                .saturating_add(
                    [
                        episode.webpage_url.as_ref(),
                        episode.feed_webpage_url.as_ref(),
                        episode.artwork_url.as_ref(),
                        episode.stream_url.as_ref(),
                    ]
                    .into_iter()
                    .flatten()
                    .map(|url| url.as_str().len())
                    .fold(0usize, usize::saturating_add),
                )
                .saturating_add(
                    episode
                        .stream_mime_type
                        .as_ref()
                        .map_or(0, String::capacity),
                );
            base.saturating_add(strings)
        }
    }
}

/// Conservatively estimates heap ownership for one full YouTube detail record.
fn youtube_video_details_estimated_heap_bytes(details: &VideoDetails) -> usize {
    let strings = [
        // The cache owns one cloned ID as its `HashMap` key.
        details.video_id.capacity(),
        details.video_id.capacity(),
        details.title.capacity(),
        details.channel_name.capacity(),
        details.channel_id.capacity(),
        details.description.capacity(),
        details.published_text.as_ref().map_or(0, String::capacity),
        details.license.as_ref().map_or(0, String::capacity),
        details
            .webpage_url
            .as_ref()
            .map_or(0, |url| url.as_str().len()),
        details
            .stream_url
            .as_ref()
            .map_or(0, |url| url.as_str().len()),
    ]
    .into_iter()
    .fold(0usize, usize::saturating_add);
    let keywords = details.keywords.iter().map(String::capacity).fold(
        details
            .keywords
            .capacity()
            .saturating_mul(std::mem::size_of::<String>()),
        usize::saturating_add,
    );
    let thumbnails = details
        .thumbnails
        .iter()
        .map(|thumbnail| {
            thumbnail
                .url
                .as_str()
                .len()
                .saturating_add(thumbnail.quality.as_ref().map_or(0, String::capacity))
        })
        .fold(
            details
                .thumbnails
                .capacity()
                .saturating_mul(std::mem::size_of::<Thumbnail>()),
            usize::saturating_add,
        );
    std::mem::size_of::<VideoDetails>()
        .saturating_add(strings)
        .saturating_add(keywords)
        .saturating_add(thumbnails)
}

fn detail_from_channel(channel: &ChannelSummary, subscriptions: &SubscriptionTree) -> DetailView {
    DetailView {
        title: channel.name.clone(),
        source: "YouTube channel".to_owned(),
        channel_name: channel.name.clone(),
        channel_id: channel.channel_id.clone(),
        channel_webpage_url: youtube_channel_webpage_url(
            &channel.channel_id,
            channel.webpage_url.clone(),
        ),
        channel_subscribed: subscriptions.contains_youtube_channel(&channel.channel_id),
        channel_subscriber_count: channel.subscriber_count,
        description: channel.description.clone(),
        license: "not applicable".to_owned(),
        wikidata: "not loaded".to_owned(),
        thumbnail_url: preferred_thumbnail_url(&channel.thumbnails),
        ..DetailView::default()
    }
}

fn detail_from_video(video: &VideoDetails, subscriptions: &SubscriptionTree) -> DetailView {
    let description = normalize_description_chapter_lines(&video.description);
    DetailView {
        media_id: Some(MediaId::new(SourceKind::YouTube, &video.video_id)),
        title: video.title.clone(),
        source: "YouTube".to_owned(),
        channel_name: video.channel_name.clone(),
        channel_id: video.channel_id.clone(),
        channel_webpage_url: youtube_channel_webpage_url(
            &video.channel_id,
            subscriptions.youtube_channel_website_url(&video.channel_id),
        ),
        channel_subscribed: subscriptions.contains_youtube_channel(&video.channel_id),
        channel_subscriber_count: None,
        length: video
            .duration_seconds
            .map_or_else(|| "unknown".to_owned(), format_seconds),
        timecodes: detail_timecodes(&description),
        video_links: detail_video_links(&description),
        description,
        likes: video
            .like_count
            .map_or_else(|| "unknown".to_owned(), format_count),
        views: video
            .view_count
            .map_or_else(|| "unknown".to_owned(), format_count),
        published: video
            .published_text
            .clone()
            .or_else(|| video.published_at.map(format_unix_utc_date))
            .unwrap_or_else(|| "unknown".to_owned()),
        license: video
            .license
            .clone()
            .unwrap_or_else(|| "unknown".to_owned()),
        wikidata: "not loaded (lazy)".to_owned(),
        thumbnail_url: preferred_thumbnail_url(&video.thumbnails),
        links: Vec::new(),
        ..DetailView::default()
    }
}

fn detail_from_media_item(media: &MediaItem) -> DetailView {
    let description = media.description.clone().unwrap_or_default();
    DetailView {
        media_id: Some(media.id.clone()),
        title: media.title.clone(),
        source: media.id.source.to_string(),
        channel_name: media.creator.clone().unwrap_or_default(),
        length: media
            .duration_seconds
            .map_or_else(String::new, format_seconds),
        description: description.clone(),
        timecodes: detail_timecodes(&description),
        video_links: detail_video_links(&description),
        likes: media
            .statistics
            .likes
            .map_or_else(String::new, format_count),
        views: media
            .statistics
            .views
            .map_or_else(String::new, format_count),
        published: media
            .published_at
            .map_or_else(String::new, format_unix_utc_date),
        license: match &media.license {
            MediaLicense::CreativeCommons(label) => label.clone(),
            _ => String::new(),
        },
        thumbnail_url: media.thumbnail_url.clone(),
        ..DetailView::default()
    }
}

fn summary_from_details(video: &VideoDetails) -> VideoSummary {
    VideoSummary {
        video_id: video.video_id.clone(),
        title: video.title.clone(),
        channel_name: video.channel_name.clone(),
        channel_id: video.channel_id.clone(),
        description: video.description.clone(),
        duration_seconds: video.duration_seconds,
        view_count: video.view_count,
        published_at: video.published_at,
        published_text: video.published_text.clone(),
        live: video.live,
        orientation: video.orientation,
        thumbnails: video.thumbnails.clone(),
        webpage_url: video.webpage_url.clone(),
        stream_url: video.stream_url.clone(),
    }
}

/// Builds a source-list row without changing its portable feed identity.
fn subscription_source_row(
    entry: &FlattenedSubscription,
    preferred_youtube_webpage_url: Option<url::Url>,
) -> RowView {
    RowView {
        title: format!("{}{}", "  ".repeat(entry.depth), entry.subscription.title),
        subtitle: subscription_source_subtitle(entry, preferred_youtube_webpage_url),
        source: subscription_kind_label(entry.subscription.kind).to_owned(),
        subscribed: true,
        ..RowView::default()
    }
}

/// Formats one loaded podcast feed for the source Details pane.
#[cfg(feature = "rss")]
fn rss_feed_detail_text(info: &CachedRssFeedInfo, fallback_description: Option<&str>) -> String {
    let mut metadata = Vec::with_capacity(5);
    if !info.authors.is_empty() {
        metadata.push(format!("Authors: {}", info.authors.join(", ")));
    }
    if let Some(language) = info
        .language
        .as_deref()
        .filter(|language| !language.trim().is_empty())
    {
        metadata.push(format!("Language: {language}"));
    }
    if !info.categories.is_empty() {
        metadata.push(format!("Categories: {}", info.categories.join(", ")));
    }
    if let Some(updated) = info
        .updated_at
        .as_deref()
        .filter(|updated| !updated.trim().is_empty())
    {
        metadata.push(format!("Updated: {updated}"));
    }
    metadata.push(format!(
        "Episodes: {}",
        format_count(u64::try_from(info.episode_count).unwrap_or(u64::MAX))
    ));
    let description = info
        .description
        .as_deref()
        .or(fallback_description)
        .unwrap_or_default()
        .trim();
    if description.is_empty() {
        metadata.join("\n")
    } else {
        format!("{}\n\n{description}", metadata.join("\n"))
    }
}

/// Formats a safe public channel route while retaining non-YouTube feed URLs.
fn subscription_source_subtitle(
    entry: &FlattenedSubscription,
    preferred_youtube_webpage_url: Option<url::Url>,
) -> String {
    if entry.subscription.kind != SubscriptionKind::YouTube {
        return entry.subscription.url.to_string();
    }
    let channel_id = entry.subscription.youtube_channel_id().unwrap_or_default();
    let preferred_youtube_webpage_url = preferred_youtube_webpage_url
        .or_else(|| entry.subscription.website_url.clone())
        .or_else(|| Some(entry.subscription.url.clone()));
    readable_youtube_channel_url(&channel_id, preferred_youtube_webpage_url)
        .unwrap_or_else(|| "youtube.com".to_owned())
}

const fn subscription_kind_label(kind: SubscriptionKind) -> &'static str {
    match kind {
        SubscriptionKind::YouTube => "YouTube channel",
        SubscriptionKind::Rss => "RSS podcast",
        SubscriptionKind::Other => "Subscription",
    }
}

/// Returns the plural media noun used by source-specific subscription status.
const fn subscription_item_kind_label(kind: SubscriptionKind) -> &'static str {
    match kind {
        SubscriptionKind::Rss => "episodes",
        SubscriptionKind::YouTube | SubscriptionKind::Other => "videos",
    }
}

fn moved_index(current: usize, length: usize, delta: i32) -> Option<usize> {
    if length == 0 {
        return None;
    }
    let last = length.saturating_sub(1);
    Some(if delta.is_negative() {
        current.saturating_sub(delta.unsigned_abs() as usize)
    } else {
        current.saturating_add(delta as usize).min(last)
    })
}

/// Builds a canonical channel page only from a bounded path-safe identifier.
fn canonical_youtube_channel_url(channel_id: &str) -> Option<url::Url> {
    if channel_id.is_empty()
        || channel_id.len() > 128
        || !channel_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return None;
    }
    let mut url = url::Url::parse("https://www.youtube.com/channel/").ok()?;
    url.path_segments_mut()
        .ok()?
        .pop_if_empty()
        .push(channel_id);
    Some(url)
}

/// Accepts a provider channel page from a strict YouTube allowlist.
///
/// Unsafe, unrelated, or mismatched pages fall back to the canonical channel
/// identifier instead of reaching `xdg-open`.
fn youtube_channel_webpage_url(channel_id: &str, preferred: Option<url::Url>) -> Option<url::Url> {
    preferred
        .filter(|url| is_safe_youtube_channel_webpage(url, channel_id))
        .or_else(|| canonical_youtube_channel_url(channel_id))
}

/// Shortens a validated channel page to a stable, readable display URL.
fn readable_youtube_channel_url(channel_id: &str, preferred: Option<url::Url>) -> Option<String> {
    let webpage_url = youtube_channel_webpage_url(channel_id, preferred)?;
    let path = decoded_youtube_channel_path_segments(&webpage_url)?;
    Some(format!("youtube.com/{}", path.join("/")))
}

/// Checks that a preferred URL is an exact credential-free YouTube channel page.
fn is_safe_youtube_channel_webpage(url: &url::Url, channel_id: &str) -> bool {
    if url.scheme() != "https"
        || !matches!(
            url.host_str(),
            Some("youtube.com" | "www.youtube.com" | "m.youtube.com")
        )
        || url.port().is_some()
        || !url.username().is_empty()
        || url.password().is_some()
        || url.query().is_some()
        || url.fragment().is_some()
    {
        return false;
    }
    let Some(segments) = decoded_youtube_channel_path_segments(url) else {
        return false;
    };
    match segments.as_slice() {
        [handle] => handle
            .strip_prefix('@')
            .is_some_and(valid_youtube_channel_webpage_alias),
        [namespace, candidate] if namespace == "channel" => {
            canonical_youtube_channel_url(candidate).is_some()
                && (channel_id.is_empty() || candidate == channel_id)
        }
        [namespace, legacy_name] if matches!(namespace.as_str(), "c" | "user") => {
            valid_youtube_channel_webpage_alias(legacy_name)
        }
        _ => false,
    }
}

/// Checks that a safe channel page carries a human-readable handle or alias.
fn is_youtube_channel_alias_webpage(url: &url::Url, channel_id: &str) -> bool {
    if !is_safe_youtube_channel_webpage(url, channel_id) {
        return false;
    }
    decoded_youtube_channel_path_segments(url).is_some_and(|segments| {
        matches!(
            segments.as_slice(),
            [handle] if handle.starts_with('@')
        ) || matches!(
            segments.as_slice(),
            [namespace, _] if matches!(namespace.as_str(), "c" | "user")
        )
    })
}

/// Decodes an exact channel route while tolerating one conventional trailing slash.
fn decoded_youtube_channel_path_segments(url: &url::Url) -> Option<Vec<String>> {
    let mut segments = url
        .path_segments()?
        .map(decode_url_path_segment_once)
        .collect::<Option<Vec<_>>>()?;
    if segments.last().is_some_and(String::is_empty) {
        segments.pop();
    }
    Some(segments)
}

/// Checks a provider-supplied human channel path without accepting other routes.
fn valid_youtube_channel_webpage_alias(alias: &str) -> bool {
    !alias.is_empty()
        && alias.len() <= 128
        && !matches!(alias, "." | "..")
        && !alias.chars().any(|character| {
            character.is_control()
                || character.is_whitespace()
                || matches!(character, '/' | '\\' | '?' | '#' | '%' | '@' | ':')
        })
}

/// Returns the validated item URL shared by Search browser and copy actions.
fn search_item_url(item: &SearchItem) -> Option<String> {
    match item {
        SearchItem::Video(video) => Some(
            video
                .webpage_url
                .as_ref()
                .map(ToString::to_string)
                .unwrap_or_else(|| youtube_video_url(&video.video_id)),
        ),
        SearchItem::Channel(channel) => {
            youtube_channel_webpage_url(&channel.channel_id, channel.webpage_url.clone())
                .map(|url| url.to_string())
        }
        SearchItem::PodcastEpisode(episode) => episode
            .webpage_url
            .as_ref()
            .or(episode.feed_webpage_url.as_ref())
            .map(ToString::to_string),
    }
}

fn stored_screen_from_tui(screen: Screen) -> StoredScreen {
    match screen {
        Screen::Search => StoredScreen::Search,
        #[cfg(feature = "youtube-music")]
        Screen::YouTubeMusic => StoredScreen::YouTubeMusic,
        #[cfg(not(feature = "youtube-music"))]
        Screen::YouTubeMusic => StoredScreen::Search,
        #[cfg(feature = "bandcamp")]
        Screen::Bandcamp => StoredScreen::Bandcamp,
        #[cfg(not(feature = "bandcamp"))]
        Screen::Bandcamp => StoredScreen::Search,
        #[cfg(feature = "apple-podcasts")]
        Screen::ApplePodcasts => StoredScreen::ApplePodcasts,
        #[cfg(not(feature = "apple-podcasts"))]
        Screen::ApplePodcasts => StoredScreen::Search,
        #[cfg(feature = "radio")]
        Screen::Radio => StoredScreen::Radio,
        #[cfg(not(feature = "radio"))]
        Screen::Radio => StoredScreen::Search,
        Screen::Local => StoredScreen::Local,
        Screen::Subscriptions => StoredScreen::Subscriptions,
        Screen::Downloaded => StoredScreen::Downloaded,
        Screen::History => StoredScreen::History,
        Screen::Playlists => StoredScreen::Playlists,
        Screen::Statistics => StoredScreen::Statistics,
        Screen::TrackerMusic => StoredScreen::TrackerMusic,
    }
}

/// Preserves the exact persistent-playlist route in the existing screen field.
///
/// `StoredScreen::Playlist` predates the TUI playlist index, so retaining its
/// stable identifier requires no session-schema change.
fn stored_session_screen(screen: Screen, route: &PlaylistsRoute) -> StoredScreen {
    if screen == Screen::Playlists
        && let PlaylistsRoute::Entries { playlist_id } = route
    {
        return StoredScreen::Playlist(playlist_id.clone());
    }
    stored_screen_from_tui(screen)
}

/// Restores both the playlist navigation level and its route-specific row.
fn restored_playlists_route(
    screen: &StoredScreen,
    selected_row: usize,
) -> (PlaylistsRoute, usize, usize) {
    match screen {
        StoredScreen::Playlist(playlist_id) => (
            PlaylistsRoute::Entries {
                playlist_id: playlist_id.clone(),
            },
            0,
            selected_row,
        ),
        StoredScreen::Playlists => (PlaylistsRoute::Index, selected_row, 0),
        _ => (PlaylistsRoute::Index, 0, 0),
    }
}

fn tui_screen_from_stored(screen: &StoredScreen) -> Screen {
    match screen {
        StoredScreen::Search => Screen::Search,
        #[cfg(feature = "youtube-music")]
        StoredScreen::YouTubeMusic => Screen::YouTubeMusic,
        #[cfg(not(feature = "youtube-music"))]
        StoredScreen::YouTubeMusic => Screen::Search,
        #[cfg(feature = "bandcamp")]
        StoredScreen::Bandcamp => Screen::Bandcamp,
        #[cfg(not(feature = "bandcamp"))]
        StoredScreen::Bandcamp => Screen::Search,
        #[cfg(feature = "apple-podcasts")]
        StoredScreen::ApplePodcasts => Screen::ApplePodcasts,
        #[cfg(not(feature = "apple-podcasts"))]
        StoredScreen::ApplePodcasts => Screen::Search,
        #[cfg(feature = "radio")]
        StoredScreen::Radio => Screen::Radio,
        #[cfg(not(feature = "radio"))]
        StoredScreen::Radio => Screen::Search,
        StoredScreen::Local => Screen::Local,
        StoredScreen::Subscriptions => Screen::Subscriptions,
        StoredScreen::Downloaded => Screen::Downloaded,
        StoredScreen::History => Screen::History,
        StoredScreen::Playlists | StoredScreen::Playlist(_) | StoredScreen::Queue => {
            Screen::Playlists
        }
        StoredScreen::Statistics => Screen::Statistics,
        StoredScreen::TrackerMusic => Screen::TrackerMusic,
        StoredScreen::Channel(_) | StoredScreen::Waveform => Screen::Search,
    }
}

fn youtube_video_url(video_id: &str) -> String {
    format!("https://www.youtube.com/watch?v={video_id}")
}

#[cfg(feature = "yt-dlp")]
fn configured_download_format(value: &str) -> Result<DownloadFormat, String> {
    match value.trim().to_ascii_lowercase().as_str() {
        "opus" | "opus-copy" => Ok(DownloadFormat::OpusWithoutTranscoding),
        "original" | "best" | "best-audio" => Ok(DownloadFormat::OriginalBestAudio),
        "transcode-opus" | "opus-transcode" => Ok(DownloadFormat::TranscodeToOpus),
        value => Err(format!(
            "unsupported subscriptions.audio_format `{value}`; use `opus`, `original`, or `transcode-opus`"
        )),
    }
}

#[cfg(feature = "yt-dlp")]
fn prepare_download_destination(config: &Config) -> Result<PathBuf, String> {
    config
        .ensure_directories()
        .map_err(|error| format!("cannot prepare Youta's private directories: {error}"))?;
    let destination = config.downloads_dir();
    let root = std::fs::canonicalize(config.config_dir())
        .map_err(|error| format!("cannot resolve the Youta config directory: {error}"))?;
    let destination = std::fs::canonicalize(&destination)
        .map_err(|error| format!("cannot resolve the downloads directory: {error}"))?;
    if destination == root || !destination.starts_with(&root) {
        return Err(format!(
            "the downloads directory resolves outside the Youta config directory: {}",
            destination.display()
        ));
    }
    Ok(destination)
}

#[cfg(feature = "yt-dlp")]
fn validate_completed_download_path(
    destination: &Path,
    reported_path: &Path,
) -> Result<PathBuf, String> {
    let candidate = if reported_path.is_absolute() {
        reported_path.to_owned()
    } else {
        destination.join(reported_path)
    };
    let candidate = std::fs::canonicalize(&candidate).map_err(|error| {
        format!(
            "cannot resolve the completed media path `{}`: {error}",
            candidate.display()
        )
    })?;
    if !candidate.starts_with(destination) {
        return Err(format!(
            "yt-dlp reported a path outside Youta's downloads directory: {}",
            candidate.display()
        ));
    }
    if !candidate.is_file() {
        return Err(format!(
            "yt-dlp reported a completed path that is not a file: {}",
            candidate.display()
        ));
    }
    Ok(candidate)
}

#[cfg(feature = "yt-dlp")]
/// Clears a scheduled success notice without removing active or failed state.
fn clear_download_completion_notice(view: &mut ViewModel, deadline: &mut Option<Instant>) {
    *deadline = None;
    if view
        .download
        .as_ref()
        .is_some_and(|download| !download.active && download.completed_path.is_some())
    {
        view.download = None;
    }
}

#[cfg(feature = "yt-dlp")]
/// Removes a successful completed-path notice at or after its exact deadline.
fn expire_download_completion_notice(
    view: &mut ViewModel,
    deadline: &mut Option<Instant>,
    now: Instant,
) {
    let Some(expires_at) = *deadline else {
        return;
    };
    if now < expires_at {
        return;
    }
    clear_download_completion_notice(view, deadline);
}

#[cfg(feature = "yt-dlp")]
fn apply_download_progress(view: &mut ViewModel, title: &str, progress: DownloadProgress) {
    view.download = Some(DownloadView {
        title: title.to_owned(),
        downloaded_bytes: progress.downloaded_bytes,
        total_bytes: progress.total_bytes,
        bytes_per_second: progress.bytes_per_second.map(rounded_download_rate),
        eta_seconds: progress.eta_seconds,
        active: true,
        completed_path: None,
    });
}

#[cfg(feature = "yt-dlp")]
fn mark_download_inactive(view: &mut ViewModel) {
    if let Some(download) = view.download.as_mut() {
        download.active = false;
    }
}

#[cfg(feature = "yt-dlp")]
fn rounded_download_rate(value: f64) -> u64 {
    match Duration::try_from_secs_f64(value) {
        Ok(duration) => duration
            .as_secs()
            .saturating_add(u64::from(duration.subsec_nanos() >= 500_000_000)),
        Err(_) if value.is_sign_negative() || value.is_nan() => 0,
        Err(_) => u64::MAX,
    }
}

#[cfg(feature = "yt-dlp")]
fn download_diagnostics(active: &ActiveDownload) -> String {
    active
        .output
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .diagnostics()
}

#[cfg(feature = "yt-dlp")]
fn append_download_diagnostics(message: String, diagnostics: &str) -> String {
    if diagnostics.is_empty() {
        message
    } else {
        format!("{message}\n\nBounded yt-dlp output:\n{diagnostics}")
    }
}

fn queue_item_from_video(video: &VideoSummary, start_at_seconds: Option<u64>) -> QueueItem {
    let canonical_playback_url = url::Url::parse(&youtube_video_url(&video.video_id))
        .expect("a validated YouTube video ID always forms a valid URL");
    let webpage_url = video
        .webpage_url
        .clone()
        .unwrap_or_else(|| canonical_playback_url.clone());
    // Provider-advertised CDN and proxy URLs can be signed, short-lived, or
    // tied to request headers. Let yt-dlp resolve the stable watch page at the
    // moment playback starts instead of persisting such a locator in the queue.
    let playback_location = canonical_playback_url.to_string();
    QueueItem {
        media: MediaItem {
            id: MediaId::new(SourceKind::YouTube, video.video_id.clone()),
            kind: if video.live {
                MediaKind::LiveStream
            } else {
                MediaKind::Video
            },
            title: video.title.clone(),
            creator: (!video.channel_name.is_empty()).then(|| video.channel_name.clone()),
            description: (!video.description.is_empty()).then(|| video.description.clone()),
            webpage_url,
            thumbnail_url: video
                .thumbnails
                .first()
                .map(|thumbnail| thumbnail.url.clone()),
            duration_seconds: video.duration_seconds,
            published_at: video.published_at,
            statistics: MediaStatistics {
                views: video.view_count,
                likes: None,
            },
            license: MediaLicense::Unknown,
            chapters: description_chapters(&video.description, video.duration_seconds),
            captions: Vec::new(),
        },
        playback_location,
        start_at_seconds,
        added_at: unix_time(),
    }
}

/// Builds a live queue item while keeping the station page separate from audio.
#[cfg(feature = "radio")]
fn queue_item_from_radio_station(station: &RadioStationPreset) -> Result<QueueItem, String> {
    let webpage_url = station
        .homepage_url()
        .map_err(|error| format!("The built-in station homepage is invalid: {error}"))?;
    station
        .stream_url()
        .map_err(|error| format!("The built-in station stream is invalid: {error}"))?;
    Ok(QueueItem {
        media: MediaItem {
            id: MediaId::new(SourceKind::Radio, station.id),
            kind: MediaKind::LiveStream,
            title: station.name.to_owned(),
            creator: None,
            description: Some(station.summary.to_owned()),
            webpage_url,
            thumbnail_url: None,
            duration_seconds: None,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: Vec::new(),
            captions: Vec::new(),
        },
        playback_location: station.stream.to_owned(),
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Adapts one stable BBC Sounds entry to the shared Radio catalogue model.
///
/// The `stream` field deliberately retains the credential-free BBC page. A
/// short-lived geo-specific manifest is resolved only for an explicit playback
/// action and is passed to the backend outside this persisted model.
#[cfg(feature = "bbc-radio")]
fn radio_station_from_bbc(station: BbcStationPreset) -> RadioStationPreset {
    RadioStationPreset {
        id: station.id,
        name: station.name,
        homepage: station.page,
        stream: station.page,
        summary: station.group.summary(),
        codec: None,
        bitrate_kbps: None,
        sample_rate_hz: None,
        channels: None,
        stream_kind: RadioStreamKind::BbcSounds,
        now_playing: None,
    }
}

/// Formats public BBC selector metadata without exposing its transient URL.
#[cfg(feature = "bbc-radio")]
fn format_bbc_quality(resolution: &BbcLiveResolution) -> String {
    CachedBbcQuality::from_resolution(resolution).display()
}

/// Iterates over every station visible in the Radio tab for this build.
#[cfg(all(feature = "radio", feature = "bbc-radio"))]
fn all_stations() -> impl Iterator<Item = RadioStationPreset> {
    curated_radio_stations().chain(BBC_STATIONS.iter().copied().map(radio_station_from_bbc))
}

/// Iterates over the non-BBC Radio catalogue in minimal builds.
#[cfg(all(feature = "radio", not(feature = "bbc-radio")))]
fn all_stations() -> impl Iterator<Item = RadioStationPreset> {
    curated_radio_stations()
}

/// Resolves one visible Radio identifier without contacting its stream.
#[cfg(all(feature = "radio", feature = "bbc-radio"))]
fn station_by_id(id: &str) -> Option<RadioStationPreset> {
    curated_radio_station_by_id(id).or_else(|| bbc_station_by_id(id).map(radio_station_from_bbc))
}

/// Resolves one non-BBC Radio identifier in minimal builds.
#[cfg(all(feature = "radio", not(feature = "bbc-radio")))]
fn station_by_id(id: &str) -> Option<RadioStationPreset> {
    curated_radio_station_by_id(id)
}

/// Returns the complete Radio row count for this build.
#[cfg(all(feature = "radio", feature = "bbc-radio"))]
fn station_count() -> usize {
    curated_radio_station_count().saturating_add(BBC_STATIONS.len())
}

/// Returns the non-BBC Radio row count for minimal builds.
#[cfg(all(feature = "radio", not(feature = "bbc-radio")))]
fn station_count() -> usize {
    curated_radio_station_count()
}

#[cfg(feature = "radio")]
fn radio_codec_label(codec: Option<RadioCodec>) -> &'static str {
    match codec {
        Some(RadioCodec::Aac) => "AAC",
        Some(RadioCodec::Flac) => "FLAC",
        Some(RadioCodec::Mp3) => "MP3",
        Some(RadioCodec::Opus) => "Opus",
        Some(RadioCodec::Pcm) => "PCM",
        Some(RadioCodec::Vorbis) => "Ogg Vorbis",
        None => "not published",
    }
}

/// Returns the Radio catalogue in the requested deterministic display order.
///
/// Both bitrate modes retain unknown bitrates after every known bitrate, so
/// an absent quality claim never outranks an advertised stream.
#[cfg(feature = "radio")]
fn sorted_radio_stations(sort: RadioSort) -> Vec<RadioStationPreset> {
    sorted_radio_stations_by(sort, |station| station.bitrate_kbps.map(u32::from))
}

/// Sorts Radio presets by an explicit effective-bitrate projection.
#[cfg(feature = "radio")]
fn sorted_radio_stations_by(
    sort: RadioSort,
    effective_bitrate: impl Fn(&RadioStationPreset) -> Option<u32>,
) -> Vec<RadioStationPreset> {
    let mut stations: Vec<_> = all_stations().collect();
    stations.sort_by(|left, right| {
        let name_order = || {
            left.name
                .to_lowercase()
                .cmp(&right.name.to_lowercase())
                .then_with(|| left.id.cmp(right.id))
        };
        match sort {
            RadioSort::Name => name_order(),
            RadioSort::BitrateDescending | RadioSort::BitrateAscending => {
                let bitrate_order = match (effective_bitrate(left), effective_bitrate(right)) {
                    (Some(left), Some(right)) => {
                        if sort == RadioSort::BitrateDescending {
                            right.cmp(&left)
                        } else {
                            left.cmp(&right)
                        }
                    }
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (None, None) => std::cmp::Ordering::Equal,
                };
                bitrate_order.then_with(name_order)
            }
        }
    });
    stations
}

/// Stably pins favorite stations before the already sorted and filtered rest.
#[cfg(feature = "radio")]
fn pin_radio_favorite_stations(
    stations: Vec<RadioStationPreset>,
    favorite_ids: &HashSet<String>,
) -> Vec<RadioStationPreset> {
    let (mut favorites, others): (Vec<_>, Vec<_>) = stations
        .into_iter()
        .partition(|station| favorite_ids.contains(station.id));
    favorites.extend(others);
    favorites
}

/// Returns sorted Radio presets whose stable metadata contains every query term.
///
/// Matching is local, case-insensitive, and deliberately excludes transient
/// now-playing text. Visible quality labels and their raw numeric values make
/// filters such as `flac`, `aac`, `320`, and `44100 stereo` useful. Stereo is
/// searchable even though the routine two-channel label is omitted from rows.
#[cfg(all(feature = "radio", test))]
fn filtered_radio_stations(sort: RadioSort, query: &str) -> Vec<RadioStationPreset> {
    sorted_radio_stations(sort)
        .into_iter()
        .filter(|station| radio_station_matches_filter(station, query))
        .collect()
}

/// Checks one Radio preset against whitespace-separated local filter terms.
#[cfg(all(feature = "radio", test))]
fn radio_station_matches_filter(station: &RadioStationPreset, query: &str) -> bool {
    let quality = radio_station_quality(station, true);
    radio_station_matches_filter_with_quality(
        station,
        query,
        &quality,
        station.bitrate_kbps.map(u32::from),
    )
}

/// Checks one Radio preset with an explicit effective quality projection.
#[cfg(feature = "radio")]
fn radio_station_matches_filter_with_quality(
    station: &RadioStationPreset,
    query: &str,
    quality: &str,
    effective_bitrate: Option<u32>,
) -> bool {
    let raw_bitrate = effective_bitrate.map_or_else(String::new, |value| value.to_string());
    let raw_sample_rate = station
        .sample_rate_hz
        .map_or_else(String::new, |value| value.to_string());
    let raw_channels = station
        .channels
        .map_or_else(String::new, |value| value.to_string());
    let channel_layout = match station.channels {
        Some(1) => "mono",
        Some(2) => "stereo",
        Some(_) => "multichannel",
        None => "",
    };
    let searchable = format!(
        "{} {} {quality} {raw_bitrate} {raw_sample_rate} {raw_channels} {channel_layout}",
        station.name, station.summary
    )
    .to_lowercase();

    query
        .split_whitespace()
        .map(str::to_lowercase)
        .all(|term| searchable.contains(&term))
}

/// Formats only trustworthy quality attributes supplied by the preset.
///
/// FLAC's missing encoded bitrate is content-dependent and distinct from
/// metadata that a lossy-stream publisher did not provide.
#[cfg(feature = "radio")]
fn radio_station_quality(station: &RadioStationPreset, include_unknown_bitrate: bool) -> String {
    let mut parts = Vec::with_capacity(4);
    if let Some(codec) = station.codec {
        parts.push(radio_codec_label(Some(codec)).to_owned());
    }
    if let Some(rate) = station.bitrate_kbps {
        parts.push(format!("{rate} kbps"));
    } else if station.codec == Some(RadioCodec::Flac) {
        parts.push("variable bitrate".to_owned());
    } else if include_unknown_bitrate {
        parts.push("bitrate unknown".to_owned());
    }
    if let Some(rate) = station.sample_rate_hz {
        let kilohertz = f64::from(rate) / 1_000.0;
        parts.push(if rate % 1_000 == 0 {
            format!("{kilohertz:.0} kHz")
        } else {
            format!("{kilohertz:.1} kHz")
        });
    }
    if let Some(channels) = station.channels
        && channels != 2
    {
        parts.push(match channels {
            1 => "mono".to_owned(),
            channels => format!("{channels} channels"),
        });
    }
    if parts.is_empty() {
        "quality unknown".to_owned()
    } else {
        parts.join(" · ")
    }
}

/// Formats optional station metadata with its correct user-facing meaning.
#[cfg(feature = "radio")]
fn radio_now_playing_display(metadata: &RadioNowPlaying) -> Option<String> {
    let body = match metadata.kind {
        RadioNowPlayingKind::Track => match (
            metadata.artist.as_deref().filter(|value| !value.is_empty()),
            metadata.title.as_deref().filter(|value| !value.is_empty()),
        ) {
            (Some(artist), Some(title)) => Some(format!("{artist} — {title}")),
            (Some(artist), None) => Some(artist.to_owned()),
            (None, Some(title)) => Some(title.to_owned()),
            (None, None) => None,
        },
        RadioNowPlayingKind::OnAir => match (
            metadata
                .programme
                .as_deref()
                .filter(|value| !value.is_empty()),
            metadata.title.as_deref().filter(|value| !value.is_empty()),
        ) {
            (Some(programme), Some(segment)) => Some(format!("{programme} — {segment}")),
            (Some(programme), None) => Some(programme.to_owned()),
            (None, Some(segment)) => Some(segment.to_owned()),
            (None, None) => None,
        },
    }?;
    Some(format!(
        "{}: {body}",
        match metadata.kind {
            RadioNowPlayingKind::Track => "Track",
            RadioNowPlayingKind::OnAir => "On air",
        }
    ))
}

/// Returns a capped, station-scoped delay for passive metadata failures.
#[cfg(feature = "radio")]
fn radio_now_playing_failure_delay(consecutive_failures: u8) -> Duration {
    let index = usize::from(consecutive_failures.saturating_sub(1))
        .min(RADIO_NOW_PLAYING_FAILURE_BACKOFF.len() - 1);
    RADIO_NOW_PLAYING_FAILURE_BACKOFF[index]
}

/// Labels an expired provider record without claiming that it is current.
#[cfg(feature = "radio")]
fn radio_stale_now_playing_display(metadata: &RadioNowPlaying) -> Option<String> {
    let current = radio_now_playing_display(metadata)?;
    Some(match metadata.kind {
        RadioNowPlayingKind::Track => current.replacen("Track:", "Last known track:", 1),
        RadioNowPlayingKind::OnAir => current.replacen("On air:", "Last known programme:", 1),
    })
}

/// Resolves current playing metadata with clock-explicit freshness semantics.
#[cfg(feature = "radio")]
fn playing_radio_metadata_display(
    cached: Option<&CachedRadioNowPlaying>,
    icy_title: Option<&str>,
    now: Instant,
) -> Option<String> {
    cached
        .filter(|cached| now < cached.refresh_at)
        .and_then(|cached| radio_now_playing_display(&cached.value))
        .or_else(|| {
            icy_title
                .filter(|title| !title.trim().is_empty())
                .map(|title| format!("Track: {}", title.trim()))
        })
}

/// Largest stable replay locator retained in one History row.
const MAX_HISTORY_REPLAY_LOCATOR_BYTES: usize = 16 * 1024;

/// A validated History replay target ready for queue reconstruction.
#[derive(Clone, Debug, Eq, PartialEq)]
enum HistoryReplayTarget {
    Local(PathBuf),
    Remote(url::Url),
}

/// Selects a stable, credential-free locator without persisting resolved media.
///
/// The queue's playback location may be a signed CDN URL. History therefore
/// derives replay state from canonical identity and webpage fields only.
fn history_replay_locator(item: &QueueItem) -> Option<String> {
    // TODO: GenericYtDlp and RemoteFiles still use the original direct URL as
    // MediaId. The replay locator deliberately rejects untrusted queries, but
    // removing query secrets from identity/progress needs a separate migration.
    match item.media.id.source {
        SourceKind::Local => {
            let path = Path::new(&item.media.id.external_id);
            (path.is_absolute()
                && !item.media.id.external_id.is_empty()
                && item.media.id.external_id.len() <= MAX_HISTORY_REPLAY_LOCATOR_BYTES)
                .then(|| item.media.id.external_id.clone())
        }
        SourceKind::YouTube => validate_youtube_video_id(&item.media.id.external_id)
            .is_ok()
            .then(|| youtube_video_url(&item.media.id.external_id)),
        SourceKind::ModArchive => None,
        _ => stable_history_remote_url(&item.media.id.source, &item.media.webpage_url)
            .map(|url| url.to_string()),
    }
}

/// Converts one queue entry into bounded, credential-free playlist metadata.
///
/// Playback locations are deliberately ignored because they can contain
/// signed CDN URLs or request-specific provider state. The same canonical
/// locator policy used by History supplies the restart-safe replay target.
fn playlist_snapshot_from_queue_item(item: &QueueItem) -> Result<PlaylistMediaSnapshot, String> {
    let replay_locator = history_replay_locator(item).ok_or_else(|| {
        format!(
            "{} cannot be saved because it has no credential-free stable replay location",
            item.media.title
        )
    })?;
    let webpage_url = if item.media.id.source == SourceKind::Local {
        item.media.webpage_url.clone()
    } else {
        url::Url::parse(&replay_locator)
            .map_err(|_| "The canonical playlist replay URL is invalid".to_owned())?
    };
    Ok(PlaylistMediaSnapshot {
        id: item.media.id.clone(),
        kind: item.media.kind,
        title: item.media.title.clone(),
        creator: item.media.creator.clone(),
        webpage_url,
        thumbnail_url: item.media.thumbnail_url.clone(),
        duration_seconds: item.media.duration_seconds,
        replay_locator,
    })
}

/// Confirms that a persisted Local playlist item still names a regular file.
///
/// Remote snapshots are resolved lazily through their canonical provider
/// pages. A missing Local path has no equivalent resolver and must not be
/// copied into another playlist under a dead identity.
fn ensure_playlist_snapshot_available(snapshot: &PlaylistMediaSnapshot) -> Result<(), String> {
    if snapshot.id.source != SourceKind::Local {
        return Ok(());
    }
    let path = Path::new(&snapshot.replay_locator);
    if path.is_absolute() && path.is_file() {
        Ok(())
    } else {
        Err("The local playlist file was removed or moved".to_owned())
    }
}

/// Produces a bounded stable remote locator and strips only known-safe noise.
fn stable_history_remote_url(source: &SourceKind, url: &url::Url) -> Option<url::Url> {
    if !matches!(url.scheme(), "http" | "https")
        || url.host_str().is_none()
        || !url.username().is_empty()
        || url.password().is_some()
        || url.fragment().is_some()
    {
        return None;
    }

    let mut stable = url.clone();
    match source {
        SourceKind::ApplePodcasts => {
            let host = stable.host_str()?.to_ascii_lowercase();
            if !host_matches(&host, "podcasts.apple.com") {
                return None;
            }
            let episode_ids = stable
                .query_pairs()
                .filter_map(|(key, value)| (key == "i").then_some(value.into_owned()))
                .collect::<Vec<_>>();
            let [episode_id] = episode_ids.as_slice() else {
                return None;
            };
            if episode_id.is_empty()
                || episode_id.len() > 20
                || !episode_id.bytes().all(|byte| byte.is_ascii_digit())
                || episode_id.starts_with('0')
            {
                return None;
            }
            stable.set_query(None);
            stable.query_pairs_mut().append_pair("i", episode_id);
        }
        SourceKind::YouTube => {
            let video_id = stable
                .query_pairs()
                .find_map(|(key, value)| (key == "v").then_some(value.into_owned()))?;
            validate_youtube_video_id(&video_id).ok()?;
            stable = url::Url::parse(&youtube_video_url(&video_id)).ok()?;
        }
        _ if stable.query().is_some_and(|query| !query.is_empty()) => return None,
        _ => stable.set_query(None),
    }
    (stable.as_str().len() <= MAX_HISTORY_REPLAY_LOCATOR_BYTES).then_some(stable)
}

/// Resolves a new locator or a safe fallback from a pre-v8 History identity.
fn history_replay_target(entry: &HistoryEntry) -> Result<HistoryReplayTarget, String> {
    if entry.media_id.source == SourceKind::Local {
        let locator = entry
            .replay_locator
            .as_deref()
            .unwrap_or(&entry.media_id.external_id);
        if locator.is_empty() || locator.len() > MAX_HISTORY_REPLAY_LOCATOR_BYTES {
            return Err("The saved local path is empty or exceeds the supported limit".to_owned());
        }
        let path = PathBuf::from(locator);
        if !path.is_absolute() {
            return Err("The saved local path is not absolute".to_owned());
        }
        return Ok(HistoryReplayTarget::Local(path));
    }

    if entry.media_id.source == SourceKind::YouTube {
        validate_youtube_video_id(&entry.media_id.external_id)
            .map_err(|_| "The saved YouTube video identifier is invalid".to_owned())?;
        let url = url::Url::parse(&youtube_video_url(&entry.media_id.external_id))
            .map_err(|_| "The saved YouTube video URL is invalid".to_owned())?;
        return Ok(HistoryReplayTarget::Remote(url));
    }

    let locator = entry
        .replay_locator
        .as_deref()
        .unwrap_or(&entry.media_id.external_id);
    if locator.is_empty() || locator.len() > MAX_HISTORY_REPLAY_LOCATOR_BYTES {
        return Err("This History item has no bounded replay locator".to_owned());
    }
    let url = url::Url::parse(locator)
        .map_err(|_| "This History item has no valid remote replay URL".to_owned())?;
    let Some(url) = stable_history_remote_url(&entry.media_id.source, &url) else {
        return Err(
            "This History item has no credential-free stable replay URL; the record was kept"
                .to_owned(),
        );
    };
    Ok(HistoryReplayTarget::Remote(url))
}

/// Reconstructs one persisted playlist entry from its stable replay locator.
///
/// The stored canonical page or absolute local path is revalidated before it
/// reaches the player. Transient signed media URLs are never reconstructed.
fn queue_item_from_playlist_entry(entry: &PlaylistEntry) -> Result<QueueItem, String> {
    if let Some(segment) = entry.segment.as_ref()
        && segment.media_id != entry.media.id
    {
        return Err("The saved playlist segment belongs to different media".to_owned());
    }

    #[cfg(feature = "radio")]
    if entry.media.id.source == SourceKind::Radio {
        if entry.segment.is_some() {
            return Err("Live radio stations cannot be saved as finite segments".to_owned());
        }
        let station = station_by_id(&entry.media.id.external_id)
            .ok_or_else(|| "The saved radio station is not present in this build".to_owned())?;
        let saved = url::Url::parse(&entry.media.replay_locator)
            .map_err(|_| "The saved radio station page is invalid".to_owned())?;
        let expected = station
            .homepage_url()
            .map_err(|error| format!("The built-in station homepage is invalid: {error}"))?;
        if stable_history_remote_url(&SourceKind::Radio, &saved).as_ref() != Some(&expected) {
            return Err("The saved radio station page does not match its station ID".to_owned());
        }
        return queue_item_from_radio_station(&station);
    }

    let (webpage_url, playback_location) = if entry.media.id.source == SourceKind::Local {
        let path = PathBuf::from(&entry.media.replay_locator);
        if !path.is_absolute() {
            return Err("The saved local playlist path is not absolute".to_owned());
        }
        let webpage_url = url::Url::from_file_path(&path).map_err(|()| {
            format!(
                "The saved local playlist path cannot be represented as a file URL: {}",
                path.display()
            )
        })?;
        (webpage_url, path.to_string_lossy().into_owned())
    } else if entry.media.id.source == SourceKind::YouTube {
        validate_youtube_video_id(&entry.media.id.external_id)
            .map_err(|_| "The saved YouTube playlist identifier is invalid".to_owned())?;
        let expected = url::Url::parse(&youtube_video_url(&entry.media.id.external_id))
            .map_err(|_| "The saved YouTube playlist URL is invalid".to_owned())?;
        let saved = url::Url::parse(&entry.media.replay_locator)
            .map_err(|_| "The saved YouTube playlist URL is invalid".to_owned())?;
        let stable = stable_history_remote_url(&SourceKind::YouTube, &saved)
            .ok_or_else(|| "The saved YouTube playlist URL is not canonical".to_owned())?;
        if stable != expected {
            return Err(
                "The saved YouTube playlist URL does not match its video identifier".to_owned(),
            );
        }
        (expected.clone(), expected.to_string())
    } else {
        let saved = url::Url::parse(&entry.media.replay_locator)
            .map_err(|_| "The saved playlist replay URL is invalid".to_owned())?;
        let stable =
            stable_history_remote_url(&entry.media.id.source, &saved).ok_or_else(|| {
                "The saved playlist has no credential-free stable replay URL".to_owned()
            })?;
        (stable.clone(), stable.to_string())
    };

    Ok(QueueItem {
        media: MediaItem {
            id: entry.media.id.clone(),
            kind: entry.media.kind,
            title: entry.media.title.clone(),
            creator: entry.media.creator.clone(),
            description: None,
            webpage_url,
            thumbnail_url: entry.media.thumbnail_url.clone(),
            duration_seconds: entry.media.duration_seconds,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: Vec::new(),
            captions: Vec::new(),
        },
        playback_location,
        start_at_seconds: entry.segment.as_ref().map(|segment| segment.start_seconds),
        added_at: unix_time(),
    })
}

/// Reconstructs minimal queue metadata while leaving resume to saved progress.
fn queue_item_from_history(
    entry: &HistoryEntry,
    target: &HistoryReplayTarget,
) -> Result<QueueItem, String> {
    #[cfg(feature = "radio")]
    if entry.media_id.source == SourceKind::Radio {
        let station = station_by_id(&entry.media_id.external_id)
            .ok_or_else(|| "The saved radio station is not present in this build".to_owned())?;
        let expected = station
            .homepage_url()
            .map_err(|error| format!("The built-in station homepage is invalid: {error}"))?;
        let HistoryReplayTarget::Remote(saved) = target else {
            return Err("The saved radio station page is not remote".to_owned());
        };
        if saved != &expected {
            return Err("The saved radio station page does not match its station ID".to_owned());
        }
        return queue_item_from_radio_station(&station);
    }

    let (webpage_url, playback_location, path_hint) = match target {
        HistoryReplayTarget::Local(path) => {
            let webpage_url = url::Url::from_file_path(path).map_err(|()| {
                format!(
                    "The saved local path cannot be represented as a file URL: {}",
                    path.display()
                )
            })?;
            (
                webpage_url,
                path.display().to_string(),
                path.to_string_lossy().into_owned(),
            )
        }
        HistoryReplayTarget::Remote(url) => (url.clone(), url.to_string(), url.path().to_owned()),
    };
    Ok(QueueItem {
        media: MediaItem {
            id: entry.media_id.clone(),
            kind: media_kind_for_source(&entry.media_id.source, &path_hint),
            title: entry.title.clone(),
            creator: None,
            description: None,
            webpage_url,
            thumbnail_url: None,
            duration_seconds: entry.duration_seconds,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: Vec::new(),
            captions: Vec::new(),
        },
        playback_location,
        // The progress table remains authoritative and applies the configured
        // context rewind in play_queue_item_with_origin.
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Samples whether a local History file disappeared during list refresh.
fn history_local_file_removed(entry: &HistoryEntry) -> bool {
    let Ok(HistoryReplayTarget::Local(path)) = history_replay_target(entry) else {
        return false;
    };
    std::fs::metadata(path).is_err_and(|error| error.kind() == std::io::ErrorKind::NotFound)
}

/// Validates a local History target immediately before handing it to mpv.
fn validate_history_local_file(path: &Path) -> Result<(), String> {
    match std::fs::metadata(path) {
        Ok(metadata) if metadata.is_file() => Ok(()),
        Ok(_) => Err(format!(
            "The saved local media path is no longer a regular file: {}. The History record was kept.",
            path.display()
        )),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Err(format!(
            "The local media file was removed or moved: {}. The History record was kept.",
            path.display()
        )),
        Err(error) => Err(format!(
            "The saved local media file cannot be accessed: {}: {error}. The History record was kept.",
            path.display()
        )),
    }
}

/// Returns whether a YouTube result can start without representing a scheduled
/// zero-duration placeholder.
fn video_is_autoplay_playable(video: &VideoSummary) -> bool {
    video.duration_seconds != Some(0) || video.live
}

/// Matches the stable local path encoded in a queue media identifier.
fn local_path_matches_media_id(path: &Path, media_id: &MediaId) -> bool {
    media_id.source == SourceKind::Local && path.display().to_string() == media_id.external_id
}

/// Matches a prepared tracker row without relying on a possibly duplicated
/// extracted filename.
fn tracker_item_matches_media_id(item: &TrackerItem, media_id: &MediaId) -> bool {
    media_id.source == SourceKind::ModArchive && item.webpage_url.as_str() == media_id.external_id
}

fn queue_item_from_direct(direct: &DirectSourceInput) -> QueueItem {
    QueueItem {
        media: MediaItem {
            id: MediaId::new(direct.source.clone(), direct.url.to_string()),
            kind: media_kind_for_source(&direct.source, direct.url.path()),
            title: direct.url.to_string(),
            creator: None,
            description: None,
            webpage_url: direct.url.clone(),
            thumbnail_url: None,
            duration_seconds: None,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: Vec::new(),
            captions: Vec::new(),
        },
        playback_location: direct.url.to_string(),
        start_at_seconds: None,
        added_at: unix_time(),
    }
}

/// Builds a queue item from an app-owned, provider-classified Commons value.
///
/// Both URLs are revalidated here because a UI action may outlive the Details
/// model that originally created it. Only stable queryless Commons URLs reach
/// the backend or persistent history identity.
fn queue_item_from_wikidata_media(media: &DetailWikidataMediaView) -> Result<QueueItem, String> {
    let page_suffix = safe_commons_url_suffix(&media.webpage_url, "/wiki/File:")
        .ok_or_else(|| "invalid Commons file-page URL".to_owned())?;
    let playback_suffix =
        safe_commons_url_suffix(&media.playback_url, "/wiki/Special:Redirect/file/")
            .ok_or_else(|| "invalid Commons playback URL".to_owned())?;
    if page_suffix != playback_suffix {
        return Err("Commons page and playback targets refer to different files".to_owned());
    }
    if media.title.is_empty()
        || media.title.len() > 4 * 1024
        || media
            .title
            .chars()
            .any(|character| matches!(character, '\0' | '\r' | '\n'))
    {
        return Err("invalid Commons media title".to_owned());
    }
    if !matches!(media.kind, MediaKind::Audio | MediaKind::Video) {
        return Err("unsupported Commons media kind".to_owned());
    }
    if !commons_media_extension_supported(media.kind, playback_suffix) {
        return Err("Commons media does not use a supported open format".to_owned());
    }
    let media_id = MediaId::new(SourceKind::WikimediaCommons, media.webpage_url.to_string());
    if media.media_id != media_id {
        return Err("Commons media identity does not match its file page".to_owned());
    }
    Ok(QueueItem {
        media: MediaItem {
            id: media_id,
            kind: media.kind,
            title: media.title.clone(),
            creator: Some("Wikimedia Commons".to_owned()),
            description: None,
            webpage_url: media.webpage_url.clone(),
            thumbnail_url: None,
            duration_seconds: None,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: Vec::new(),
            captions: Vec::new(),
        },
        playback_location: media.playback_url.to_string(),
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Returns the encoded filename suffix of one credential-free Commons URL.
fn safe_commons_url_suffix<'a>(url: &'a url::Url, prefix: &str) -> Option<&'a str> {
    (url.scheme() == "https"
        && url.host_str() == Some("commons.wikimedia.org")
        && url.port().is_none()
        && url.username().is_empty()
        && url.password().is_none()
        && url.query().is_none()
        && url.fragment().is_none())
    .then(|| url.path().strip_prefix(prefix))
    .flatten()
    .filter(|suffix| !suffix.is_empty())
}

/// Revalidates the provider's conservative open-format media classification.
fn commons_media_extension_supported(kind: MediaKind, encoded_filename: &str) -> bool {
    let Some(extension) = encoded_filename
        .rsplit_once('.')
        .map(|(_, extension)| extension)
    else {
        return false;
    };
    let extension = extension.to_ascii_lowercase();
    match kind {
        MediaKind::Audio => matches!(
            extension.as_str(),
            "flac" | "oga" | "ogg" | "opus" | "wav" | "webm"
        ),
        MediaKind::Video => matches!(extension.as_str(), "ogg" | "ogv" | "webm"),
        _ => false,
    }
}

fn queue_item_from_resolved(media: &ResolvedDirectMedia) -> Result<QueueItem, String> {
    let playback_url = media
        .playback_url
        .clone()
        .ok_or_else(|| media.status_line.clone())?;
    let webpage_url = media
        .webpage_url
        .clone()
        .unwrap_or_else(|| playback_url.clone());
    Ok(QueueItem {
        media: MediaItem {
            id: MediaId::new(media.source.clone(), media.external_id.clone()),
            kind: media_kind_for_source(&media.source, playback_url.path()),
            title: media.title.clone(),
            creator: None,
            description: (!media.description.is_empty()).then(|| media.description.clone()),
            webpage_url,
            thumbnail_url: media.artwork_url.clone(),
            duration_seconds: media.duration_seconds,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: media_license_from_label(&media.license),
            chapters: description_chapters(&media.description, media.duration_seconds),
            captions: Vec::new(),
        },
        playback_location: playback_url.to_string(),
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Converts public search metadata into the credential-free restart model.
#[cfg(feature = "bandcamp")]
fn bandcamp_search_summary(
    result: crate::providers::bandcamp::BandcampSearchResult,
) -> BandcampSearchSummary {
    let kind = match result.media.kind() {
        BandcampMediaKind::Track => BandcampReleaseKind::Track,
        BandcampMediaKind::Album => BandcampReleaseKind::Album,
    };
    let id = MediaId::new(SourceKind::Bandcamp, result.media.stable_id());
    BandcampSearchSummary {
        id,
        kind,
        title: result.title,
        artist: result.artist,
        webpage_url: result.media.into_url(),
        artwork_url: result.artwork_url,
    }
}

/// Builds a canonical queue item from one action-resolved Bandcamp track.
///
/// The short-lived `media_url` and its headers deliberately remain outside
/// the returned queue item.
#[cfg(feature = "bandcamp")]
fn queue_item_from_bandcamp_track(
    summary: &BandcampSearchSummary,
    source: &BandcampMediaUrl,
    track: &crate::playback::ytdlp::ResolvedMedia,
) -> Result<QueueItem, String> {
    let webpage_url = track
        .webpage_url
        .clone()
        .unwrap_or_else(|| source.as_url().clone());
    let media = BandcampMediaUrl::parse(webpage_url.clone())
        .map_err(|error| format!("resolved Bandcamp page is not canonical: {error}"))?;
    let duration_seconds = track
        .duration_seconds
        .and_then(|seconds| Duration::try_from_secs_f64(seconds).ok())
        .map(|duration| duration.as_secs());
    Ok(QueueItem {
        media: MediaItem {
            id: MediaId::new(SourceKind::Bandcamp, media.stable_id()),
            kind: MediaKind::Audio,
            title: if track.title.is_empty() {
                summary.title.clone()
            } else {
                track.title.clone()
            },
            creator: summary.artist.clone(),
            description: None,
            webpage_url,
            thumbnail_url: track
                .thumbnail_url
                .clone()
                .or_else(|| summary.artwork_url.clone()),
            duration_seconds,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: Vec::new(),
            captions: Vec::new(),
        },
        playback_location: media.as_url().to_string(),
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Builds a playable Apple episode without resolving its enclosure a second time.
#[cfg(feature = "apple-podcasts")]
fn queue_item_from_apple_episode(
    episode: &ApplePodcastEpisodeMetadata,
    show: Option<&PodcastShowSummary>,
) -> Result<QueueItem, String> {
    let playback_url = episode.media_url.clone().ok_or_else(|| {
        "This Apple Podcasts episode has no public audio enclosure to play".to_owned()
    })?;
    let webpage_url =
        canonical_apple_episode_url(episode, show).unwrap_or_else(|| playback_url.clone());
    let description = episode.description.clone().unwrap_or_default();
    Ok(QueueItem {
        media: MediaItem {
            id: MediaId::new(SourceKind::ApplePodcasts, episode.episode_id.to_string()),
            kind: media_kind_for_source(&SourceKind::ApplePodcasts, playback_url.path()),
            title: episode.title.clone(),
            creator: episode
                .author
                .clone()
                .or_else(|| show.and_then(|show| show.author.clone())),
            description: (!description.is_empty()).then(|| description.clone()),
            webpage_url,
            thumbnail_url: episode
                .artwork_url
                .clone()
                .or_else(|| show.and_then(|show| show.artwork_url.clone())),
            duration_seconds: episode.duration_seconds,
            published_at: None,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: description_chapters(&description, episode.duration_seconds),
            captions: Vec::new(),
        },
        playback_location: playback_url.to_string(),
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Converts one normalized feed entry into a compact subscription summary.
#[cfg(feature = "rss")]
fn podcast_episode_summary(
    feed: &PodcastFeed,
    episode: &PodcastEpisode,
    identity_scope: &url::Url,
) -> PodcastEpisodeSummary {
    let enclosure = episode.preferred_playable_enclosure();
    PodcastEpisodeSummary {
        feed_url: identity_scope.clone(),
        episode_id: episode.id.clone(),
        feed_title: feed
            .title
            .clone()
            .unwrap_or_else(|| "RSS podcast".to_owned()),
        title: episode
            .title
            .clone()
            .unwrap_or_else(|| "Untitled episode".to_owned()),
        authors: episode.authors.clone(),
        description: episode.description.clone().unwrap_or_default(),
        language: episode.language.clone(),
        categories: episode.categories.clone(),
        duration_seconds: episode
            .duration_seconds
            .or_else(|| enclosure.and_then(|enclosure| enclosure.duration_seconds)),
        published_at: episode
            .published_at
            .as_deref()
            .and_then(|value| DateTime::parse_from_rfc3339(value).ok())
            .map(|value| value.timestamp()),
        webpage_url: episode.webpage_url.clone(),
        feed_webpage_url: feed.webpage_url.clone(),
        artwork_url: episode
            .artwork_url
            .clone()
            .or_else(|| feed.artwork_url.clone()),
        stream_url: enclosure.map(|enclosure| enclosure.url.clone()),
        stream_mime_type: enclosure.and_then(|enclosure| enclosure.mime_type.clone()),
        stream_byte_length: enclosure.and_then(|enclosure| enclosure.byte_length),
    }
}

/// Builds a directly playable queue entry for one cached podcast episode.
#[cfg(feature = "rss")]
fn queue_item_from_podcast_episode(episode: &PodcastEpisodeSummary) -> Result<QueueItem, String> {
    let playback_url = episode.stream_url.clone().ok_or_else(|| {
        "This podcast episode has no playable audio or video enclosure; refresh the feed if it was restored from disk"
            .to_owned()
    })?;
    let webpage_url = episode
        .webpage_url
        .clone()
        .or_else(|| episode.feed_webpage_url.clone())
        .unwrap_or_else(|| playback_url.clone());
    let description = episode.description.clone();
    Ok(QueueItem {
        media: MediaItem {
            id: MediaId::new(
                SourceKind::Rss,
                podcast_episode_external_id(&episode.feed_url, &episode.episode_id),
            ),
            kind: MediaKind::PodcastEpisode,
            title: episode.title.clone(),
            creator: episode.authors.first().cloned(),
            description: (!description.is_empty()).then(|| description.clone()),
            webpage_url,
            thumbnail_url: episode.artwork_url.clone(),
            duration_seconds: episode.duration_seconds,
            published_at: episode.published_at,
            statistics: MediaStatistics::default(),
            license: MediaLicense::Unknown,
            chapters: description_chapters(&description, episode.duration_seconds),
            captions: Vec::new(),
        },
        playback_location: playback_url.to_string(),
        start_at_seconds: None,
        added_at: unix_time(),
    })
}

/// Returns a credential-free Apple episode page suitable for History replay.
#[cfg(feature = "apple-podcasts")]
fn canonical_apple_episode_url(
    episode: &ApplePodcastEpisodeMetadata,
    show: Option<&PodcastShowSummary>,
) -> Option<url::Url> {
    let mut url = episode
        .webpage_url
        .clone()
        .or_else(|| show.and_then(|show| show.webpage_url.clone()))?;
    url.set_query(None);
    url.set_fragment(None);
    url.query_pairs_mut()
        .append_pair("i", &episode.episode_id.to_string());
    let link = crate::providers::apple_podcasts::ApplePodcastLink::parse(&url).ok()?;
    (link.collection_id == episode.collection_id && link.episode_id == Some(episode.episode_id))
        .then_some(url)
}

