    #[cfg(feature = "radio")]
    #[test]
    fn radio_catalog_rows_are_compact_marker_free_and_show_quality() {
        let config = Config::for_dir("/tmp/youta-radio-catalog-test");
        let store = StateStore::open_in_memory().expect("in-memory state");
        let mut controller = AppController::new(config, store, None, None);

        controller.show_screen(Screen::Radio);

        assert_eq!(controller.view.rows.len(), station_count());
        assert!(controller.view.rows.iter().all(|row| row.compact));
        assert!(
            controller
                .view
                .rows
                .iter()
                .all(|row| row.hide_watched_marker)
        );
        for row in &controller.view.rows {
            let station_id = &row
                .media_id
                .as_ref()
                .expect("Radio row identity")
                .external_id;
            let station = station_by_id(station_id).expect("catalogued Radio station");
            if station.stream_kind == RadioStreamKind::BbcSounds {
                assert!(
                    row.subtitle.is_empty(),
                    "unresolved BBC quality must not render a placeholder"
                );
            } else {
                assert!(
                    !row.subtitle.trim().is_empty(),
                    "static station quality must remain visible"
                );
            }
        }
        let sector_index = select_radio_station(&mut controller, "sector-radio-progressive-flac");
        assert_eq!(
            controller.view.rows[sector_index].subtitle,
            "FLAC · variable bitrate · 44.1 kHz"
        );
        let details = controller.view.details.as_ref().expect("radio details");
        assert!(
            details
                .description
                .contains("Quality: FLAC · variable bitrate · 44.1 kHz")
        );
        assert!(!details.description.contains("stereo"));
        assert!(
            details
                .description
                .contains("http://89.223.45.5:8000/progressive-flac")
        );
        assert!(details.length.is_empty());
        assert!(details.likes.is_empty());
        assert!(details.views.is_empty());
    }

