    #[cfg(feature = "bbc-radio")]
    #[test]
    fn bbc_playback_uses_one_ram_only_manifest_then_resolves_fresh_again() {
        let (mut controller, playback) = controller_with_mock_statuses([]);
        let (requests, captured_requests) = unbounded();
        controller.provider_requests = Some(requests);
        controller.show_screen(Screen::Radio);
        select_radio_station(&mut controller, "bbc_radio_three");
        let item = fixture_radio_item("bbc_radio_three");
        let initial_row = controller
            .view
            .rows
            .iter()
            .find(|row| {
                row.media_id
                    .as_ref()
                    .is_some_and(|media_id| media_id.external_id == "bbc_radio_three")
            })
            .expect("BBC Radio 3 row");
        assert!(
            initial_row.subtitle.is_empty(),
            "unresolved region-specific BBC quality must remain absent"
        );
        assert!(
            controller
                .view
                .details
                .as_ref()
                .is_some_and(|details| !details.description.contains("Quality:")),
            "unresolved BBC details must omit the complete quality row"
        );

        controller.play_queue_item(item.clone(), false);

        let ProviderRequest::ResolveBbcLive {
            generation: first_generation,
            station_id,
        } = captured_requests
            .recv_timeout(Duration::from_secs(1))
            .expect("BBC manifest request")
        else {
            panic!("expected a BBC live request");
        };
        assert!(playback.lock().expect("mock playback").played.is_empty());
        controller.handle_bbc_live(
            first_generation,
            station_id.clone(),
            Ok(fixture_bbc_resolution(
                &station_id,
                "https://audio.example.test/radio-three.m3u8",
            )),
        );

        {
            let playback = playback.lock().expect("mock playback");
            assert_eq!(playback.played.len(), 1);
            assert_eq!(
                playback.played[0].location,
                "https://audio.example.test/radio-three.m3u8"
            );
            assert!(playback.played[0].bypass_ytdl);
        }
        assert_eq!(
            controller
                .bbc_quality_cache
                .get(&station_id)
                .map(CachedBbcQuality::display)
                .as_deref(),
            Some("AAC · 320 kbps · HLS · international")
        );
        let refreshed_row = controller
            .view
            .rows
            .iter()
            .find(|row| {
                row.media_id
                    .as_ref()
                    .is_some_and(|media_id| media_id.external_id == station_id)
            })
            .expect("resolved BBC Radio 3 row");
        assert_eq!(
            refreshed_row.subtitle,
            "AAC · 320 kbps · HLS · international"
        );
        assert!(controller.view.details.as_ref().is_some_and(|details| {
            details
                .description
                .contains("Quality: AAC · 320 kbps · HLS · international")
        }));

        let resolved_station = station_by_id(&station_id).expect("resolved BBC fixture");
        assert!(
            controller.radio_station_matches_filter(&resolved_station, "aac 320 hls international")
        );
        controller.view.radio_sort = RadioSort::BitrateDescending;
        controller.populate_radio();
        let resolved_index = controller
            .view
            .rows
            .iter()
            .position(|row| {
                row.media_id
                    .as_ref()
                    .is_some_and(|media_id| media_id.external_id == station_id)
            })
            .expect("resolved BBC row in bitrate order");
        let four_duk_index = controller
            .view
            .rows
            .iter()
            .position(|row| {
                row.media_id
                    .as_ref()
                    .is_some_and(|media_id| media_id.external_id == "4duk-radio")
            })
            .expect("256 kbps comparison row");
        assert!(
            resolved_index < four_duk_index,
            "resolved 320 kbps BBC quality must participate in bitrate sorting"
        );

        controller.radio_filter_query = "aac 320 hls international".to_owned();
        controller.populate_radio();
        assert!(controller.view.rows.iter().any(|row| {
            row.media_id
                .as_ref()
                .is_some_and(|media_id| media_id.external_id == station_id)
        }));

        controller.play_queue_item(item, false);
        let second_generation = match captured_requests
            .recv_timeout(Duration::from_secs(1))
            .expect("fresh BBC manifest request")
        {
            ProviderRequest::ResolveBbcLive {
                generation,
                station_id: second_station,
            } => {
                assert_eq!(second_station, station_id);
                generation
            }
            _ => panic!("expected another BBC live request"),
        };
        assert_ne!(second_generation, first_generation);
        assert_eq!(
            playback.lock().expect("mock playback").played.len(),
            1,
            "cached quality must never replay the earlier signed manifest"
        );
    }

